const BANKING_PAY_WORKBENCH_DB_CONTRACT = 'BANKING_PAY_WORKBENCH_DB_V1';
const BANKING_PAY_CANONICAL_CORRECTION_CARRIER_VERSION =
  'BANKING_PAY_CANONICAL_CORRECTION_CARRIER_V1';
const BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_VERSION =
  'BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_V1';

async function assertBankingPayWorkbenchContract(env, entryPoint) {
  let contract = null;
  try {
    contract = unwrapRpcJsonb(
      await sbRpc(
        env,
        'pay_workbench_contract_version_get_v1',
        {},
        {
          routeClass: 'CONTROL',
          purpose: 'BANKING_PAY_WORKBENCH_CONTRACT',
          timeoutMs: 8000,
          bankingPay: true
        }
      ),
      'pay_workbench_contract_version_get_v1'
    );
  } catch (cause) {
    const error = new Error('BANKING_PAY_WORKBENCH_CONTRACT_MISMATCH');
    error.code = 'BANKING_PAY_WORKBENCH_CONTRACT_MISMATCH';
    error.status = 503;
    error.entryPoint = entryPoint;
    error.actualContract = null;
    error.cause = cause;
    console.error('[BankingPayWorkbenchContract]', JSON.stringify({
      code: error.code,
      expected_contract_version: BANKING_PAY_WORKBENCH_DB_CONTRACT,
      expected_canonical_correction_carrier_version:
        BANKING_PAY_CANONICAL_CORRECTION_CARRIER_VERSION,
      expected_targeted_family_materialisation_version:
        BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_VERSION,
      actual_contract_version: null,
      actual_canonical_correction_carrier_version: null,
      actual_targeted_family_materialisation_version: null,
      upstream_status: Number.isFinite(Number(cause?.status))
        ? Number(cause.status)
        : null,
      upstream_code:
        String(cause?.json?.code || cause?.code || '').trim() || null,
      entry_point: entryPoint,
      mutation_attempted: false,
      workbench_job_claimed: false
    }));
    throw error;
  }

  const projectionContract =
    contract && typeof contract.candidate_projection_contract === 'object'
      ? contract.candidate_projection_contract
      : null;
  const valid =
    contract
    && contract.ok === true
    && contract.contract_version === BANKING_PAY_WORKBENCH_DB_CONTRACT
    && contract.canonical_correction_carrier_version
      === BANKING_PAY_CANONICAL_CORRECTION_CARRIER_VERSION
    && contract.targeted_family_materialisation_version
      === BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_VERSION
    && projectionContract
    && projectionContract.canonical_correction_carrier_version
      === BANKING_PAY_CANONICAL_CORRECTION_CARRIER_VERSION
    && projectionContract.targeted_family_materialisation_version
      === BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_VERSION;

  if (!valid) {
    const error = new Error('BANKING_PAY_WORKBENCH_CONTRACT_MISMATCH');
    error.code = 'BANKING_PAY_WORKBENCH_CONTRACT_MISMATCH';
    error.status = 503;
    error.entryPoint = entryPoint;
    error.actualContract = contract;
    console.error('[BankingPayWorkbenchContract]', JSON.stringify({
      code: error.code,
      expected_contract_version: BANKING_PAY_WORKBENCH_DB_CONTRACT,
      expected_canonical_correction_carrier_version:
        BANKING_PAY_CANONICAL_CORRECTION_CARRIER_VERSION,
      expected_targeted_family_materialisation_version:
        BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_VERSION,
      actual_contract_version: contract?.contract_version || null,
      actual_canonical_correction_carrier_version:
        contract?.canonical_correction_carrier_version || null,
      actual_targeted_family_materialisation_version:
        contract?.targeted_family_materialisation_version || null,
      entry_point: entryPoint,
      mutation_attempted: false,
      workbench_job_claimed: false
    }));
    throw error;
  }

  return contract;
}

function bankingPayWorkbenchContractFailure(error) {
  const code = 'BANKING_PAY_WORKBENCH_CONTRACT_MISMATCH';
  const message =
    'Banking Pay is temporarily unavailable because the Worker cannot prove the required database contract.';
  return new Response(JSON.stringify({
    ok: false,
    code,
    error_code: code,
    message,
    error: {
      code,
      message,
      category: 'CONTRACT_GATE',
      retryable: true,
      action: 'RETRY_LATER',
      expected_contract_version: BANKING_PAY_WORKBENCH_DB_CONTRACT,
      expected_canonical_correction_carrier_version:
        BANKING_PAY_CANONICAL_CORRECTION_CARRIER_VERSION,
      expected_targeted_family_materialisation_version:
        BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_VERSION,
      actual_contract_version:
        error?.actualContract?.contract_version || null,
      actual_canonical_correction_carrier_version:
        error?.actualContract?.canonical_correction_carrier_version || null,
      actual_targeted_family_materialisation_version:
        error?.actualContract?.targeted_family_materialisation_version || null,
      entry_point: error?.entryPoint || null,
      mutation_attempted: false,
      workbench_job_claimed: false
    }
  }), {
    status: 503,
    headers: JSON_HEADERS
  });
}

async function handleRetiredImportMutationRoute(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  return withCORS(env, req, new Response(JSON.stringify({
    ok: false,
    contract_version: 'IMPORT_REVIEW_DB_V1',
    error: {
      code: 'IMPORT_REVIEW_HARD_CUTOVER_REQUIRED',
      message: 'This legacy import action has been retired. Reopen the import through the durable review workflow.',
      category: 'RETIRED_ROUTE',
      retryable: false,
      action: 'OPEN_IMPORT_REVIEW'
    }
  }), {
    status: 410,
    headers: { 'content-type': 'application/json; charset=utf-8' }
  }));
}

async function findImportStageReplay(env, { sourceSystem, fileKey, clientId = null, sourceEvidence } = {}) {
  const filters = [
    `source_system=eq.${encodeURIComponent(sourceSystem)}`,
    `file_r2_key=eq.${encodeURIComponent(fileKey)}`,
    'select=id,source_file_sha256,parser_version,parse_summary_json,applied_at,coverage_locked_at',
    'order=uploaded_at_utc.desc',
    'limit=2'
  ];
  if (clientId) filters.splice(2, 0, `client_id=eq.${encodeURIComponent(clientId)}`);
  const { rows } = await sbFetch(env, `${env.SUPABASE_URL}/rest/v1/hr_imports?${filters.join('&')}`);
  if (!Array.isArray(rows) || !rows.length) return null;
  const matching = rows.find((row) => (
    String(row.source_file_sha256 || '').toLowerCase() === String(sourceEvidence?.source_file_sha256 || '').toLowerCase()
    && String(row.parser_version || '') === String(sourceEvidence?.parser_version || '')
  ));
  // Replay only an unfinished staging write. Once coverage is locked (including
  // an abandoned/applied review), the operator may reimport and start afresh.
  if (matching && !matching.coverage_locked_at && !matching.applied_at) return matching;
  if (matching) return null;
  throw new Error('IMPORT_STAGE_SOURCE_CONFLICT');
}

