    const claimableCount = metricInt(drain, ['claimable_count', 'claimable_due_count']);
    const dueQueuedCount = metricInt(drain, ['due_queued_count', 'due_queued']);
    const claimed = metricInt(drain, ['claimed', 'claimed_count']);
