    const conflictLike = code.includes('STALE') || code.includes('BLOCK') || code.includes('CONFLICT') || code.includes('PENDING') || code.includes('UNKNOWN') || code.includes('PAID') || code.includes('SETTLED') || code.includes('UNSAFE');
