    break_end_iso: finalTs?.break_end_iso ?? null,
    break_minutes: finalTs?.break_minutes ?? null,
    worked_minutes: finalTs?.worked_minutes ?? null,
    actual_schedule_json: finalTs?.actual_schedule_json ?? null,
