      a = GG(a,b,c,d,wordArray[k+5],5,0xd62f105d); d = GG(d,a,b,c,wordArray[k+10],9,0x02441453); c = GG(c,d,a,b,wordArray[k+15],14,0xd8a1e681); b = GG(b,c,d,a,wordArray[k+4],20,0xe7d3fbc8);
