async function findCandidateByImportName(env, staffName, { trustNorm } = {}) {
  const enc  = encodeURIComponent;
  const norm = (s) => String(s || '').trim().toLowerCase();

  const nameNorm = norm(staffName);
  if (!nameNorm) return null;

  // 1) Candidate-level alias JSONB: candidates.nhsp_hr_name_aliases contains nameNorm
  try {
    const aliasJson = JSON.stringify([nameNorm]); // ["john smith"]
    const { rows: candRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?nhsp_hr_name_aliases=cs.${enc(aliasJson)}` +
        `&active=eq.true` +
        `&select=id` +
        `&limit=2`
    );
    // Only accept if exactly one match to avoid ambiguity
    if (candRows?.length === 1 && candRows[0]?.id) {
      return candRows[0].id;
    }
  } catch {
    // If this fails for any reason, just fall through to hr_name_mappings
  }

  // 2) hr_name_mappings: single query for all active mappings for this name
  let mapRows = [];
  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/hr_name_mappings` +
        `?hr_name_norm=eq.${enc(nameNorm)}` +
        `&active=eq.true` +
        `&select=candidate_id,hospital_or_trust`
      // no limit: table is small; this is one subrequest either way
    );
    mapRows = rows || [];
  } catch {
    return null;
  }

  if (!mapRows.length) {
    return null;
  }

  const tNorm = norm(trustNorm);

  // Prefer mappings that match this hospital_or_trust
  if (tNorm) {
    const matches = mapRows.filter((r) => norm(r.hospital_or_trust) === tNorm);
    const ids = [...new Set(matches.map((r) => r.candidate_id).filter(Boolean))];
    if (ids.length === 1) {
      return ids[0];
    }
    // if >1 candidate_id for the same site, treat as ambiguous and fall back to name-only
  }

  // Name-only fallback: if all mappings for this name point to the same candidate, use it
  const allIds = [...new Set(mapRows.map((r) => r.candidate_id).filter(Boolean))];
  if (allIds.length === 1) {
    return allIds[0];
  }

  // Ambiguous (multiple candidates for same name); require manual resolve
  return null;
}


// ───────────────────────────────────────────────────────────────────────────────
// SEARCH — Invoices (richer filters + csv/print)
// ───────────────────────────────────────────────────────────────────────────────
async function handleSearchInvoices(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const urlObj = new URL(req.url);
  const q  = (k) => urlObj.searchParams.get(k);
  const qa = (k) => urlObj.searchParams.getAll(k);
  const page     = Math.max(1, parseInt(q('page') || '1', 10));
  const pageSize = Math.max(1, Math.min(200, parseInt(q('page_size') || '50', 10)));

  const format = (q('format') || 'json').toLowerCase(); // 'json'|'csv'|'print'

  // explicit-ID selection support
  const idInExpr = q('id');
  const idsRaw   = q('ids');
  let idFilterExpr = null;
  if (idInExpr && /^in\.\(.+\)$/.test(idInExpr)) {
    idFilterExpr = idInExpr;
  } else if (idsRaw) {
    const list = idsRaw.split(',').map(s => s.trim()).filter(Boolean);
    if (list.length) idFilterExpr = `in.(${list.join(',')})`;
  }

  // Filters
  const statuses   = qa('status');
  const clientId   = q('client_id');
  const invNo      = q('invoice_no');
  const invQ       = q('q');
  const issuedFrom = q('issued_from');
  const issuedTo   = q('issued_to');
  const dueFrom    = q('due_from');
  const dueTo      = q('due_to');
  const createdFrom = q('created_from');
  const createdTo   = q('created_to');

  const orderBy = (q('order_by') || 'issued_at_utc').toLowerCase();
  const orderDir = (q('order_dir') || 'desc').toLowerCase() === 'asc' ? 'asc' : 'desc';
  const orderAllowed = new Set(['issued_at_utc','invoice_no','total_inc_vat','subtotal_ex_vat','created_at','due_at_utc','status_date_utc']);

  let url = `${env.SUPABASE_URL}/rest/v1/invoices` +
    `?select=` +
    [
      'id','invoice_no','client_id','status','status_date_utc',
      'issued_at_utc','due_at_utc','created_at',
      'total_inc_vat','subtotal_ex_vat','vat_amount',
      'on_hold_reason',
      'client:clients(name)'
    ].join(',') +
    `&limit=${pageSize}&offset=${(page-1)*pageSize}`;

  if (Array.isArray(statuses) && statuses.length) {
    const inList = statuses.map(s => String(s).toUpperCase().replace(/[(),]/g,'')).join(',');
    url += `&status=in.(${inList})`;
  }
  if (clientId) url += `&client_id=eq.${enc(clientId)}`;
  if (invNo)    url += `&invoice_no=eq.${enc(invNo)}`;
  if (invQ)     url += `&invoice_no=ilike.*${enc(invQ)}*`;
  if (issuedFrom) url += `&issued_at_utc=gte.${enc(issuedFrom)}`;
  if (issuedTo)   url += `&issued_at_utc=lte.${enc(issuedTo)}`;
  if (dueFrom)    url += `&due_at_utc=gte.${enc(dueFrom)}`;
  if (dueTo)      url += `&due_at_utc=lte.${enc(dueTo)}`;
  if (createdFrom) url += `&created_at=gte.${enc(createdFrom)}`;
  if (createdTo)   url += `&created_at=lte.${enc(createdTo)}`;

  if (idFilterExpr) url += `&id=${enc(idFilterExpr)}`;

  url += `&order=${orderAllowed.has(orderBy) ? enc(orderBy) : 'issued_at_utc'}.${orderDir}`;

  let rows = [];
  try {
    ({ rows } = await sbFetch(env, url));
  } catch (err) {
    return withCORS(env, req, ok({ error: String(err?.message || err), rows: [], page, page_size: pageSize, count: 0 }));
  }

  if (format === 'csv') {
    const header = ['InvoiceNo','Client','Status','StatusDate','IssuedAt','DueAt','CreatedAt','SubtotalExVAT','VAT','TotalIncVAT','OnHoldReason'];
    const out = [csvJoin(header)];
    for (const r of rows || []) {
      out.push(csvJoin([
        r.invoice_no || '',
        r.client?.name || '',
        r.status || '',
        r.status_date_utc || '',
        r.issued_at_utc || '',
        r.due_at_utc || '',
        r.created_at || '',
        round2(r.subtotal_ex_vat || 0).toFixed(2),
        round2(r.vat_amount || 0).toFixed(2),
        round2(r.total_inc_vat || 0).toFixed(2),
        r.on_hold_reason || ''
      ]));
    }
    return withCORS(env, req, ok({ csv: out.join('\n'), count: rows?.length || 0, page, page_size: pageSize }));
  }

  if (format === 'print') {
    const rowsHtml = (rows || []).map(r => `
      <tr>
        <td>${r.invoice_no || ''}</td>
        <td>${(r.client && r.client.name) ? r.client.name : ''}</td>
        <td>${r.status || ''}</td>
        <td>${r.status_date_utc || ''}</td>
        <td>${r.issued_at_utc || ''}</td>
        <td>${r.due_at_utc || ''}</td>
        <td>${r.created_at || ''}</td>
        <td style="text-align:right">${round2(r.subtotal_ex_vat || 0).toFixed(2)}</td>
        <td style="text-align:right">${round2(r.vat_amount || 0).toFixed(2)}</td>
        <td style="text-align:right">${round2(r.total_inc_vat || 0).toFixed(2)}</td>
        <td>${r.on_hold_reason || ''}</td>
      </tr>`).join('');
    const html = `
      <div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif">
        <h3>Invoices — Search Results</h3>
        <table width="100%" cellspacing="0" cellpadding="6" style="border-collapse:collapse">
          <thead><tr style="background:#f5f5f5">
            <th>Invoice No</th><th>Client</th><th>Status</th><th>Status Date</th><th>Issued At</th><th>Due At</th><th>Created At</th>
            <th>Subtotal ex VAT</th><th>VAT</th><th>Total inc VAT</th><th>On hold reason</th>
          </tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>`;
    return withCORS(env, req, ok({ html, count: rows?.length || 0, page, page_size: pageSize }));
  }

  return withCORS(env, req, ok({ rows, page, page_size: pageSize, count: rows?.length || 0 }));
}





// ───────────────────────────────────────────────────────────────────────────────
// SEARCH — Candidates (richer filters + csv/print)
// ───────────────────────────────────────────────────────────────────────────────




// ───────────────────────────────────────────────────────────────────────────────
// SEARCH — Clients (richer filters + csv/print)
// ───────────────────────────────────────────────────────────────────────────────


async function handleSearchClients(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const enc = encodeURIComponent;

  const urlObj = new URL(req.url);
  const q = (k) => urlObj.searchParams.get(k);
  const page = Math.max(1, parseInt(q('page') || '1', 10));
  const pageSize = Math.max(1, Math.min(200, parseInt(q('page_size') || '50', 10)));
  const format = (q('format') || 'json').toLowerCase();

  const includeCount = String(q('include_count') || 'false').toLowerCase() === 'true';

  const orderByParam = (q('order_by') || '').toLowerCase();
  const orderDirParam = (q('order_dir') || '').toLowerCase();

  const allowedSort = {
    name: 'name',
    cli_ref: 'cli_ref',
    invoice_address: 'invoice_address',
    primary_invoice_email: 'primary_invoice_email',
    ap_phone: 'ap_phone',
    vat_chargeable: 'vat_chargeable',
    payment_terms_days: 'payment_terms_days',
    mileage_charge_rate: 'mileage_charge_rate',
    ts_queries_email: 'ts_queries_email',
    created_at: 'created_at',
    updated_at: 'updated_at',
    rev: 'rev',
    client_address: 'client_address',
    contact_title: 'contact_title',
    contact_known_as: 'contact_known_as',
    contact_forename: 'contact_forename',
    contact_surname: 'contact_surname',
    contact_job_title: 'contact_job_title',
    contact_tel: 'contact_tel',
    contact_mobile: 'contact_mobile',
    contact_email: 'contact_email',
    website: 'website',
    notes: 'notes'
  };

  const defaultOrderCol = 'name';
  const orderCol = allowedSort[orderByParam] || defaultOrderCol;
  const orderDir = (orderDirParam === 'desc') ? 'desc' : 'asc';

  const spec = buildClientSummaryFilterSpec(urlObj.searchParams);

  const text = spec.q || null;
  const cliRef = spec.cli_ref || null;
  const primaryEmail = spec.primary_invoice_email || null;
  const invoiceAddr = spec.invoice_address || null;
  const postcode = spec.postcode || null;
  const apPhone = spec.ap_phone || null;
  const vatChargeable = spec.vat_chargeable || null;
  const paymentTerms = spec.payment_terms_days || null;
  const mileageRate = spec.mileage_charge_rate || null;
  const tsQueries = spec.ts_queries_email || null;
  const createdFrom = spec.created_from || null;
  const createdTo = spec.created_to || null;
  const updatedFrom = spec.updated_from || null;
  const updatedTo = spec.updated_to || null;
  const notesExact = spec.notes || null;
  const ids = Array.isArray(spec.ids) ? spec.ids.map(String) : [];

  let idFilterExpr = null;
  if (ids.length) {
    idFilterExpr = `in.(${ids.join(',')})`;
  }

  const normalizePickerRows = (value) => {
    const arr = Array.isArray(value)
      ? value
      : ((value && typeof value === 'object' && Array.isArray(value.rows)) ? value.rows : (value == null ? [] : [value]));

    return arr
      .filter((row) => row && typeof row === 'object')
      .map((row) => ({
        id: row.id == null ? null : String(row.id),
        name: row.name == null ? '' : String(row.name),
        cli_ref: row.cli_ref == null ? '' : String(row.cli_ref),
        primary_invoice_email: row.primary_invoice_email == null ? '' : String(row.primary_invoice_email),
        is_nhsp: !!row.is_nhsp,
        autoprocess_hr: !!row.autoprocess_hr,
        rev: Number.isFinite(Number(row.rev)) ? Number(row.rev) : null,
        updated_at: row.updated_at == null ? null : String(row.updated_at),
        match_rank: Number.isFinite(Number(row.match_rank)) ? Number(row.match_rank) : null
      }));
  };

  if (format === 'picker') {
    const pickerQuery = String(
      text ||
      cliRef ||
      primaryEmail ||
      apPhone
    ).trim();

    const pickerPage = Math.max(1, parseInt(q('page') || '1', 10));
    const pickerPageSize = Math.max(1, Math.min(50, parseInt(q('page_size') || '25', 10)));
    const nhspOnly = String(q('nhsp_only') || q('is_nhsp') || '').trim().toLowerCase() === 'true';
    const hrAutoOnly = String(q('hr_auto_only') || q('autoprocess_hr') || '').trim().toLowerCase() === 'true';

    if (!pickerQuery || pickerQuery.length < 2) {
      return withCORS(env, req, ok({
        rows: [],
        page: pickerPage,
        page_size: pickerPageSize,
        count: 0,
        has_more: false
      }));
    }

    try {
      const rpcLimit = Math.max(1, Math.min(100, pickerPageSize + 1));
      const rpcOffset = Math.max(0, (pickerPage - 1) * pickerPageSize);

      const rpcRowsRaw = await sbRpc(env, 'client_picker_search', {
        p_query: pickerQuery,
        p_limit: rpcLimit,
        p_offset: rpcOffset,
        p_nhsp_only: nhspOnly,
        p_hr_auto_only: hrAutoOnly
      });

      const rpcRows = normalizePickerRows(rpcRowsRaw);
      const hasMore = rpcRows.length > pickerPageSize;
      const outRows = rpcRows.slice(0, pickerPageSize);

      return withCORS(env, req, ok({
        rows: outRows,
        page: pickerPage,
        page_size: pickerPageSize,
        count: outRows.length,
        has_more: hasMore
      }));
    } catch (err) {
      const msg = String(err?.message || err || 'Client picker search failed');
      return withCORS(env, req, serverError(msg));
    }
  }

  const buildClientsApi = ({ selectClause = '*', withPaging = true, limitValue = pageSize, offsetValue = (page - 1) * pageSize, withOrder = true }) => {
    let api =
      `${env.SUPABASE_URL}/rest/v1/clients` +
      `?select=${selectClause}`;

    if (withOrder) {
      api += `&order=${enc(orderCol)}.${orderDir}`;
    }

    if (withPaging) {
      api += `&limit=${limitValue}&offset=${offsetValue}`;
    }

    if (idFilterExpr) api += `&id=${enc(idFilterExpr)}`;
    if (text) api += `&name=ilike.*${enc(text)}*`;
    if (cliRef) api += `&cli_ref=ilike.*${enc(cliRef)}*`;
    if (primaryEmail) api += `&primary_invoice_email=ilike.*${enc(primaryEmail)}*`;
    if (invoiceAddr) api += `&invoice_address=ilike.*${enc(invoiceAddr)}*`;
    if (apPhone) api += `&ap_phone=ilike.*${enc(apPhone)}*`;

    if (notesExact) {
      const escMid = String(notesExact)
        .replace(/\\/g, '\\\\')
        .replace(/\*/g, '\\*')
        .replace(/%/g, '\\%')
        .replace(/_/g, '\\_');
      api += `&notes=ilike.*${enc(escMid)}*`;
    }

    if (vatChargeable === 'true') api += `&vat_chargeable=eq.true`;
    if (vatChargeable === 'false') api += `&vat_chargeable=eq.false`;

    if (paymentTerms) api += `&payment_terms_days=eq.${enc(paymentTerms)}`;
    if (mileageRate) api += `&mileage_charge_rate=eq.${enc(mileageRate)}`;
    if (tsQueries) api += `&ts_queries_email=ilike.*${enc(tsQueries)}*`;

    if (createdFrom) api += `&created_at=gte.${enc(createdFrom)}`;
    if (createdTo) api += `&created_at=lte.${enc(createdTo)}`;
    if (updatedFrom) api += `&updated_at=gte.${enc(updatedFrom)}`;
    if (updatedTo) api += `&updated_at=lte.${enc(updatedTo)}`;

    return api;
  };

  if (format === 'membership') {
    const idsOut = [];
    const seen = new Set();
    let offset = 0;
    const batchSize = 1000;

    try {
      while (true) {
        const api = buildClientsApi({
          selectClause: 'id',
          withPaging: true,
          limitValue: batchSize,
          offsetValue: offset,
          withOrder: false
        });

        const { rows } = await sbFetch(env, api, false);
        const batch = Array.isArray(rows) ? rows : [];

        for (const row of batch) {
          const id = row && row.id ? String(row.id).trim() : '';
          if (!id || seen.has(id)) continue;
          seen.add(id);
          idsOut.push(id);
        }

        if (batch.length < batchSize) break;
        offset += batchSize;
      }
    } catch (err) {
      return withCORS(env, req, serverError(`Supabase fetch failed: ${String(err?.message || err)}`));
    }

    return withCORS(env, req, ok({ ids: idsOut, count: idsOut.length }));
  }

  const api = buildClientsApi({
    selectClause: '*',
    withPaging: true,
    limitValue: pageSize,
    offsetValue: (page - 1) * pageSize,
    withOrder: true
  });

  let rows = [];
  let total = undefined;
  try {
    const res = await sbFetch(env, api, includeCount);
    rows = res?.rows || [];
    total = res?.total;
  } catch (err) {
    return withCORS(env, req, ok({ error: String(err?.message || err), rows: [], page, page_size: pageSize, count: 0 }));
  }

  const respCount = includeCount ? (typeof total === 'number' ? total : (rows?.length || 0)) : (rows?.length || 0);

  if (format === 'csv') {
    const header = [
      'ClientId',
      'Name',
      'ClientRef',
      'InvoiceAddress',
      'Postcode',
      'VATChargeable',
      'PaymentTermsDays',
      'PrimaryInvoiceEmail',
      'APPhone',
      'MileageChargeRate',
      'TSQueriesEmail',
      'CreatedAt',
      'UpdatedAt'
    ];
    const out = [csvJoin(header)];
    for (const r of rows || []) {
      out.push(csvJoin([
        r.id,
        r.name || '',
        r.cli_ref || '',
        r.invoice_address || '',
        '',
        r.vat_chargeable ? 'Y' : 'N',
        Number(r.payment_terms_days ?? ''),
        r.primary_invoice_email || '',
        r.ap_phone || '',
        r.mileage_charge_rate != null ? String(r.mileage_charge_rate) : '',
        r.ts_queries_email || '',
        r.created_at || '',
        r.updated_at || ''
      ]));
    }
    return withCORS(env, req, ok({ csv: out.join('\n'), count: respCount, page, page_size: pageSize }));
  }

  if (format === 'print') {
    const rowsHtml = (rows || []).map(r => `
      <tr>
        <td>${r.name || ''}</td>
        <td>${r.cli_ref || ''}</td>
        <td>${r.invoice_address || ''}</td>
        <td></td>
        <td>${r.vat_chargeable ? 'Y' : 'N'}</td>
        <td>${Number(r.payment_terms_days ?? '')}</td>
        <td>${r.primary_invoice_email || ''}</td>
        <td>${r.ap_phone || ''}</td>
        <td>${r.mileage_charge_rate != null ? String(r.mileage_charge_rate) : ''}</td>
        <td>${r.ts_queries_email || ''}</td>
        <td>${r.created_at || ''}</td>
        <td>${r.updated_at || ''}</td>
      </tr>`).join('');
    const html = `
      <div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif">
        <h3>Clients — Search Results</h3>
        <table width="100%" cellspacing="0" cellpadding="6" style="border-collapse:collapse">
          <thead><tr style="background:#f5f5f5">
            <th>Name</th><th>Client Ref</th><th>Invoice Address</th><th>Postcode</th>
            <th>VAT Chargeable</th><th>Payment Terms (days)</th>
            <th>Primary Invoice Email</th><th>A/P Phone</th>
            <th>Mileage Charge Rate</th><th>TS Queries Email</th>
            <th>Created At</th><th>Updated At</th>
          </tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>`;
    return withCORS(env, req, ok({ html, count: respCount, page, page_size: pageSize }));
  }

  return withCORS(env, req, ok({ rows, page, page_size: pageSize, count: respCount }));
}

// ───────────────────────────────────────────────────────────────────────────────
// SEARCH — Umbrellas (richer filters + csv/print)
// ───────────────────────────────────────────────────────────────────────────────


async function handleSearchUmbrellas(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const enc = encodeURIComponent;

  const urlObj = new URL(req.url);
  const q = (k) => urlObj.searchParams.get(k);
  const page = Math.max(1, parseInt(q('page') || '1', 10));
  const pageSize = Math.max(1, Math.min(200, parseInt(q('page_size') || '50', 10)));
  const format = (q('format') || 'json').toLowerCase();

  const includeCount = String(q('include_count') || 'false').toLowerCase() === 'true';

  const orderByParam = (q('order_by') || '').toLowerCase();
  const orderDirParam = (q('order_dir') || '').toLowerCase();

  const allowedSort = {
    name: 'name',
    enabled: 'enabled',
    vat_chargeable: 'vat_chargeable',
    remittance_email: 'remittance_email',
    bank_name: 'bank_name',
    sort_code: 'sort_code',
    account_number: 'account_number',
    created_at: 'created_at',
    updated_at: 'updated_at',
    postcode: 'postcode',
    town_city: 'town_city',
    company_number: 'company_number',
    revolut_counterparty_id: 'revolut_counterparty_id',
    revolut_counterparty_account_id: 'revolut_counterparty_account_id'
  };

  const defaultOrderCol = 'name';
  const orderCol = allowedSort[orderByParam] || defaultOrderCol;
  const orderDir = (orderDirParam === 'desc') ? 'desc' : 'asc';

  const spec = buildUmbrellaSummaryFilterSpec(urlObj.searchParams);

  const text = spec.q || null;
  const bankName = spec.bank_name || null;
  const sortCode = spec.sort_code || null;
  const accountNo = spec.account_number || null;
  const enabled = spec.enabled || null;
  const vatChargeable = spec.vat_chargeable || null;
  const createdFrom = spec.created_from || null;
  const createdTo = spec.created_to || null;
  const ids = Array.isArray(spec.ids) ? spec.ids.map(String) : [];

  let idFilterExpr = null;
  if (ids.length) {
    idFilterExpr = `in.(${ids.join(',')})`;
  }

  const buildUmbrellasApi = ({ selectClause = '*', withPaging = true, limitValue = pageSize, offsetValue = (page - 1) * pageSize, withOrder = true }) => {
    let api =
      `${env.SUPABASE_URL}/rest/v1/umbrellas` +
      `?select=${selectClause}`;

    if (withOrder) {
      api += `&order=${enc(orderCol)}.${orderDir}`;
    }

    if (withPaging) {
      api += `&limit=${limitValue}&offset=${offsetValue}`;
    }

    if (idFilterExpr) api += `&id=${enc(idFilterExpr)}`;

    if (text) {
      const raw = String(text || '').trim();
      if (raw) {
        const expr = `(name.ilike.*${raw}*,remittance_email.ilike.*${raw}*)`;
        api += `&or=${enc(expr)}`;
      }
    }

    if (bankName) api += `&bank_name=ilike.*${enc(bankName)}*`;
    if (sortCode) api += `&sort_code=ilike.*${enc(sortCode)}*`;
    if (accountNo) api += `&account_number=ilike.*${enc(accountNo)}*`;
    if (enabled === 'true') api += `&enabled=eq.true`;
    if (enabled === 'false') api += `&enabled=eq.false`;
    if (vatChargeable === 'true') api += `&vat_chargeable=eq.true`;
    if (vatChargeable === 'false') api += `&vat_chargeable=eq.false`;
    if (createdFrom) api += `&created_at=gte.${enc(createdFrom)}`;
    if (createdTo) api += `&created_at=lte.${enc(createdTo)}`;

    return api;
  };

  if (format === 'membership') {
    const idsOut = [];
    const seen = new Set();
    let offset = 0;
    const batchSize = 1000;

    try {
      while (true) {
        const api = buildUmbrellasApi({
          selectClause: 'id',
          withPaging: true,
          limitValue: batchSize,
          offsetValue: offset,
          withOrder: false
        });

        const { rows } = await sbFetch(env, api, false);
        const batch = Array.isArray(rows) ? rows : [];

        for (const row of batch) {
          const id = row && row.id ? String(row.id).trim() : '';
          if (!id || seen.has(id)) continue;
          seen.add(id);
          idsOut.push(id);
        }

        if (batch.length < batchSize) break;
        offset += batchSize;
      }
    } catch (err) {
      return withCORS(env, req, serverError(`Supabase fetch failed: ${String(err?.message || err)}`));
    }

    return withCORS(env, req, ok({ ids: idsOut, count: idsOut.length }));
  }

  const api = buildUmbrellasApi({
    selectClause: '*',
    withPaging: true,
    limitValue: pageSize,
    offsetValue: (page - 1) * pageSize,
    withOrder: true
  });

  let rows = [];
  let total = undefined;
  try {
    const res = await sbFetch(env, api, includeCount);
    rows = res?.rows || [];
    total = res?.total;
  } catch (err) {
    return withCORS(env, req, ok({
      error: String(err?.message || err),
      rows: [],
      page,
      page_size: pageSize,
      count: 0
    }));
  }

  const respCount =
    includeCount
      ? (typeof total === 'number' ? total : (rows?.length || 0))
      : (rows?.length || 0);

  if (format === 'csv') {
    const header = ['UmbrellaId','Name','Enabled','VATChargeable','Bank','SortCode','AccountNumber','CreatedAt'];
    const out = [csvJoin(header)];
    for (const r of rows || []) {
      out.push(csvJoin([
        r.id,
        r.name || '',
        r.enabled ? 'Y' : 'N',
        r.vat_chargeable ? 'Y' : 'N',
        r.bank_name || '',
        r.sort_code || '',
        r.account_number || '',
        r.created_at || ''
      ]));
    }
    return withCORS(env, req, ok({
      csv: out.join('\n'),
      count: respCount,
      page,
      page_size: pageSize
    }));
  }

  if (format === 'print') {
    const rowsHtml = (rows || []).map(r => `
      <tr>
        <td>${r.name || ''}</td>
        <td>${r.enabled ? 'Y' : 'N'}</td>
        <td>${r.vat_chargeable ? 'Y' : 'N'}</td>
        <td>${r.bank_name || ''}</td>
        <td>${r.sort_code || ''}</td>
        <td>${r.account_number || ''}</td>
        <td>${r.created_at || ''}</td>
      </tr>`).join('');
    const html = `
      <div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif">
        <h3>Umbrellas — Search Results</h3>
        <table width="100%" cellspacing="0" cellpadding="6" style="border-collapse:collapse">
          <thead><tr style="background:#f5f5f5">
            <th>Name</th><th>Enabled</th><th>VAT Chargeable</th>
            <th>Bank</th><th>Sort code</th><th>Account number</th><th>Created At</th>
          </tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>`;
    return withCORS(env, req, ok({
      html,
      count: respCount,
      page,
      page_size: pageSize
    }));
  }

  return withCORS(env, req, ok({
    rows,
    page,
    page_size: pageSize,
    count: respCount
  }));
}



