// ENV expected (Option A: Cloudflare Pages frontend + Worker API):
// - SUPABASE_URL
// - SUPABASE_SERVICE_ROLE_KEY
// - ALLOWED_ORIGINS                 (CSV of exact origins for CORS, e.g. "https://tms.example.com")
// - SESSION_TOKEN_SECRET            (HMAC secret for access/refresh tokens)
// - COOKIE_NAME                     (default 'ctms_refresh')
// - COOKIE_DOMAIN                   (e.g. '.example.com' for same-site subdomains)
// - COOKIE_SAME_SITE                ('Lax' recommended for same-site; 'None' if truly cross-site)
// - ACCESS_TTL_SECONDS              (default 900 = 15m)
// - REFRESH_TTL_SECONDS             (default 1209600 = 14d)
// - PASSWORD_RESET_TTL_SECONDS      (default 3600)
// - UPLOAD_TOKEN_SECRET             (HMAC secret for upload/download token mint/verify)
// Bindings:
// - SESSIONS (KV namespace)         (KV for refresh sessions)
// - R2 (bucket for signatures)

const AUTH = {
  USERS_TABLE: 'tms_users',
  RESETS_TABLE: 'tms_password_resets',
};

function pickCookieSameSite(env) {
  const v = String(env.COOKIE_SAME_SITE || 'Lax');
  return (v === 'None' || v === 'Lax' || v === 'Strict') ? v : 'Lax';
}
function pickCookiePartitioned(env) {
  return String(env.COOKIE_PARTITIONED || '').trim().toLowerCase() === 'true';
}
function cookieName(env){ return String(env.COOKIE_NAME || 'ctms_refresh'); }

function setCookie(headers, name, value, { maxAgeSec, domain, sameSite='Lax', partitioned=false, secure=true, httpOnly=true, path='/' } = {}) {
  const parts = [`${name}=${value || ''}`];
  if (path) parts.push(`Path=${path}`);
  if (domain) parts.push(`Domain=${domain}`);
  if (Number.isFinite(maxAgeSec)) parts.push(`Max-Age=${Math.max(0, maxAgeSec|0)}`);
  if (sameSite) parts.push(`SameSite=${sameSite}`);
  if (secure) parts.push('Secure');
  if (httpOnly) parts.push('HttpOnly');
  if (partitioned) parts.push('Partitioned');
  headers.append('Set-Cookie', parts.join('; '));
}
function parseCookies(req) {
  const raw = req.headers.get('cookie') || '';
  const out = {};
  raw.split(';').map(s => s.trim()).filter(Boolean).forEach(p=>{
    const i = p.indexOf('=');
    const k = i>=0 ? p.slice(0,i).trim() : p;
    const v = i>=0 ? p.slice(i+1) : '';
    out[k] = v;
  });
  return out;
}

// ── Password hashing (PBKDF2-SHA256) ─────────────────────────
const MAX_PBKDF2_ITER = 100000; // Cloudflare limit

async function pbkdf2Hash(password, iterations = 100000) {
  const iters = Math.min(Number(iterations) || 100000, MAX_PBKDF2_ITER);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), { name:'PBKDF2' }, false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name:'PBKDF2', hash:'SHA-256', salt, iterations: iters }, key, 256);
  const hashB64 = bufToBase64Url(bits);
  const saltB64 = bufToBase64Url(salt);
  return `pbkdf2:sha256$${iters}$${saltB64}$${hashB64}`;
}

async function pbkdf2Verify(password, stored) {
  // format: pbkdf2:sha256$ITER$SALT$HASH
  const m = /^pbkdf2:sha256\$(\d+)\$([A-Za-z0-9\-_]+)\$([A-Za-z0-9\-_]+)$/.exec(String(stored||''));
  if (!m) return false;
  const iterations = parseInt(m[1],10);
  const salt = base64UrlToUint8(m[2]);
  const want = base64UrlToUint8(m[3]);
  if (!Number.isFinite(iterations) || iterations <= 0 || iterations > MAX_PBKDF2_ITER) {
    // Iteration count not supported on this platform → treat as mismatch (avoids 500)
    console.warn('PBKDF2 iteration count not supported:', iterations);
    return false;
  }
  try {
    const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), { name:'PBKDF2' }, false, ['deriveBits']);
    const bits = await crypto.subtle.deriveBits({ name:'PBKDF2', hash:'SHA-256', salt, iterations }, key, want.byteLength*8);
    const got = new Uint8Array(bits);
    if (got.byteLength !== want.byteLength) return false;
    let diff = 0;
    for (let i=0;i<got.byteLength;i++) diff |= (got[i]^want[i]);
    return diff === 0;
  } catch (e) {
    console.warn('PBKDF2 verify failed:', e);
    return false;
  }
}

// â”€â”€ Supabase helpers for users / resets â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function sbAuthHeaders(env){
  const k = env.SUPABASE_SERVICE_ROLE_KEY;
  return { 'apikey': k, 'Authorization': `Bearer ${k}`, 'Content-Type': 'application/json' };
}
async function sbGetUserByEmail(env, email) {
  const url = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?email=eq.${encodeURIComponent(email)}&select=id,email,role,is_active,password_hash,session_version`;
  const res = await fetch(url, { headers: sbAuthHeaders(env) });
  const json = await res.json().catch(()=>[]);
  return Array.isArray(json) && json[0] ? json[0] : null;
}
async function sbGetUserById(env, id) {
  const url = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?id=eq.${encodeURIComponent(id)}&select=id,email,role,is_active,password_hash,session_version`;
  const res = await fetch(url, { headers: sbAuthHeaders(env) });
  const json = await res.json().catch(()=>[]);
  return Array.isArray(json) && json[0] ? json[0] : null;
}

async function sbUpdateUserPassword(env, user_id, newHash) {
  const url = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?id=eq.${encodeURIComponent(user_id)}`;

  // Update password hash
  const res = await fetch(url, {
    method: 'PATCH',
    headers: { ...sbAuthHeaders(env), 'Prefer': 'return=representation' },
    body: JSON.stringify({ password_hash: newHash })
  });
  if (!res.ok) throw new Error(`password update failed ${res.status}`);

  // bump session_version:
  const current = await sbGetUserById(env, user_id);
  const nextSv = (current && Number.isFinite(Number(current.session_version)))
    ? (Math.trunc(Number(current.session_version)) + 1)
    : 2;

  const svRes = await fetch(url, {
    method: 'PATCH',
    headers: { ...sbAuthHeaders(env), 'Prefer': 'return=representation' },
    body: JSON.stringify({ session_version: nextSv })
  });
  if (!svRes.ok) throw new Error(`session_version bump failed ${svRes.status}`);

  const j = await svRes.json().catch(() => []);
  const updated = Array.isArray(j) && j[0] ? j[0] : null;

  // ✅ Clear 2FA trust + challenges (strict; migrations required)
  const enc = encodeURIComponent;

  const delTrust = await fetch(
    `${env.SUPABASE_URL}/rest/v1/tms_user_2fa_trust?user_id=eq.${enc(user_id)}`,
    { method: 'DELETE', headers: sbAuthHeaders(env) }
  );
  if (!delTrust.ok) {
    const t = await delTrust.text().catch(() => '');
    throw new Error(`2FA trust delete failed (${delTrust.status}) ${t || ''}`.trim());
  }

  const delChallenges = await fetch(
    `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges?user_id=eq.${enc(user_id)}`,
    { method: 'DELETE', headers: sbAuthHeaders(env) }
  );
  if (!delChallenges.ok) {
    const t = await delChallenges.text().catch(() => '');
    throw new Error(`2FA challenges delete failed (${delChallenges.status}) ${t || ''}`.trim());
  }

  return updated;
}

// NOTE: There is currently no separate in-file helper exposing pay_export_bank_csv supported column keys.
// Keep this set aligned with the current Banking CSV internal keys accepted by CSV settings/export paths.
const BANKING_PAY_CSV_SUPPORTED_COLUMN_KEYS = new Set([
  'payment_reference',
  'payee_name',
  'sort_code',
  'account_number',
  'account_type',
  'amount',
  'currency',
  'pay_channel',
  'rail_provider',
  'rail_env',
  'request_id',
  'transfer_group_key',
  'candidate_id',
  'umbrella_id'
]);

const normalizePayExportCsvFormatJson = (raw) => {
  // settings_defaults.pay_export_csv_format_json is NOT NULL with default {} in DB contract.
  // Treat null/empty-parsed input as reset-to-default-object.
  if (raw === null || raw === undefined) return {};
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('pay_export_csv_format_json must be a JSON object (or null)');
  }

  const allowedTopLevel = new Set([
    'include_header',
    'delimiter',
    'line_ending',
    'quote_mode',
    'bom',
    'sort_code_format',
    'account_number_format',
    'amount_decimals',
    'empty_value',
    'headers'
  ]);

  for (const k of Object.keys(raw)) {
    if (!allowedTopLevel.has(k)) {
      throw new Error(`pay_export_csv_format_json.${k} is not supported`);
    }
  }

  const out = {};

  if (Object.prototype.hasOwnProperty.call(raw, 'include_header')) {
    if (typeof raw.include_header !== 'boolean') throw new Error('pay_export_csv_format_json.include_header must be boolean');
    out.include_header = raw.include_header;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'delimiter')) {
    const v = String(raw.delimiter ?? '');
    if (!new Set([',', ';', '\t', '|']).has(v)) throw new Error('pay_export_csv_format_json.delimiter must be one of ",", ";", "\\t", "|"');
    out.delimiter = v;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'line_ending')) {
    const v = String(raw.line_ending ?? '').trim().toUpperCase();
    if (!new Set(['LF', 'CRLF']).has(v)) throw new Error('pay_export_csv_format_json.line_ending must be LF or CRLF');
    out.line_ending = v;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'quote_mode')) {
    const v = String(raw.quote_mode ?? '').trim().toUpperCase();
    if (!new Set(['MINIMAL', 'ALL']).has(v)) throw new Error('pay_export_csv_format_json.quote_mode must be MINIMAL or ALL');
    out.quote_mode = v;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'bom')) {
    if (typeof raw.bom !== 'boolean') throw new Error('pay_export_csv_format_json.bom must be boolean');
    out.bom = raw.bom;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'sort_code_format')) {
    const v = String(raw.sort_code_format ?? '').trim().toUpperCase();
    if (!new Set(['AS_STORED', 'DIGITS', 'HYPHENATED']).has(v)) {
      throw new Error('pay_export_csv_format_json.sort_code_format must be AS_STORED, DIGITS, or HYPHENATED');
    }
    out.sort_code_format = v;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'account_number_format')) {
    const v = String(raw.account_number_format ?? '').trim().toUpperCase();
    if (!new Set(['AS_STORED', 'DIGITS']).has(v)) {
      throw new Error('pay_export_csv_format_json.account_number_format must be AS_STORED or DIGITS');
    }
    out.account_number_format = v;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'amount_decimals')) {
    const n = Number(raw.amount_decimals);
    const v = Number.isFinite(n) ? Math.trunc(n) : NaN;
    if (!Number.isFinite(v) || n !== v || v < 0 || v > 4) {
      throw new Error('pay_export_csv_format_json.amount_decimals must be an integer between 0 and 4');
    }
    out.amount_decimals = v;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'empty_value')) {
    if (typeof raw.empty_value !== 'string') throw new Error('pay_export_csv_format_json.empty_value must be a string');
    const v = raw.empty_value.trim();
    if (v.length > 50) throw new Error('pay_export_csv_format_json.empty_value max length is 50');
    out.empty_value = v;
  }

  if (Object.prototype.hasOwnProperty.call(raw, 'headers')) {
    const headersRaw = raw.headers;
    if (headersRaw == null) {
      out.headers = {};
    } else if (!headersRaw || typeof headersRaw !== 'object' || Array.isArray(headersRaw)) {
      throw new Error('pay_export_csv_format_json.headers must be an object');
    } else {
      const headersOut = {};
      for (const [keyRaw, valueRaw] of Object.entries(headersRaw)) {
        const key = String(keyRaw || '').trim();
        if (!BANKING_PAY_CSV_SUPPORTED_COLUMN_KEYS.has(key)) {
          throw new Error(`pay_export_csv_format_json.headers contains unsupported key: ${key}`);
        }
        if (typeof valueRaw !== 'string') {
          throw new Error(`pay_export_csv_format_json.headers.${key} must be a string`);
        }
        const value = valueRaw.trim();
        if (!value) continue;
        if (value.length > 120) {
          throw new Error(`pay_export_csv_format_json.headers.${key} max length is 120`);
        }
        headersOut[key] = value;
      }
      out.headers = headersOut;
    }
  }

  return out;
};

async function handleGetSettings(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized('Unauthorized');

  try {
    const select =
      [
        'id',

        // Agency branding
        'agency_name',
        'agency_logo',

        // Timesheet PDF text blocks
        'timesheet_header_json',
        'timesheet_footer_json',

        // ✅ Remittances (new settings tab)
        'remittance_includes_json',
        'remittance_header_message',
        'remittance_footer_message',

        // ✅ NEW: remittance detailed default + candidate umbrella-copy default
        'remittances_detailed_breakdown',
        'remittance_receive_when_umbrella_paid',

        // ✅ PAYE remittances gate
        'paye_remittances_enabled',

        // ✅ NEW: remittance test routing (send all remittances to this email when payroll_testing=true)
        'remittance_test_recipient_email',

        // ✅ NEW: payment authoriser quantity
        'payment_authoriser_quantity',

        // ✅ NEW: payment correction/remittance timing settings
        'payment_remittance_send_timing',
        'payment_return_auto_reverse_timesheets',
        'payment_return_admin_recipient_role',
        'payment_return_admin_notice_quiet_minutes',
        'payment_return_admin_notice_max_wait_minutes',
        'banking_pay_auto_unwind_terminal_no_money',

        // ✅ NEW: pay eligibility window (Option A)
        'pay_eligibility_months_back',
        // NOTE: pay_eligibility_weeks_ahead is deprecated (cutoff date controls upper bound); do not expose.

        // ✅ NEW: configurable export CSV columns/order
        'pay_export_csv_columns_json',
        'pay_export_csv_format_json',

        // Global shift patterns, timezone, and Banking Pay official weekday
        'timezone_id',
        'banking_pay_official_pay_weekday',
        'day_start','day_end',
        'night_start','night_end',
        'sat_start','sat_end',
        'sun_start','sun_end',
        'bh_start','bh_end',

        // BH calendar config
        'bh_source','bh_list','bh_feed_url',

        // Global policy flags
        'ts_reference_required',
        'reversal_complete_financials_date',
        'reversal_replacement_financials_date',
        'updated_at',

        // ✅ Adaptability config
        'import_config_json',

        // Bank details still live on settings_defaults
        'bank_name','bank_sort_code','bank_account_number','vat_registration_number',

        // ✅ Banking rail defaults (for UI preselect)
        'rail_default_funding_account_ref',

        // ✅ NEW: payroll testing mode flag (simulate payments; no real bank payments)
        'payroll_testing',

        // ✅ NEW: comms adaptors config (WATI/ClickSend + limits)
        'comms_adaptors_json',

        // Email settings (global)
        'finance_email',
        'finance_email_settings',
        'system_email',
        'system_emails',
        'max_attachments_per_email'
      ].join(',');

    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/settings_defaults?id=eq.1&select=${select}`
    );

    // Finance windows list (new) — SQL-first RPC, single call
    let finance_windows = [];
    try {
      const fw = await sbRpc(env, 'settings_finance_list', {});
      finance_windows = Array.isArray(fw) ? fw : [];
    } catch {
      finance_windows = [];
    }

    const src = (rows && rows.length)
      ? rows
      : (await sbFetch(env, `${env.SUPABASE_URL}/rest/v1/settings_defaults?select=${select}&limit=1`)).rows;

    if (!src || !src.length) return notFound("settings_defaults not found");

    const settings = { ...src[0] };
    delete settings.id;

    // ✅ Redact webhook URLs (do not expose secrets)
    const redactWebhook = (obj) => {
      if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return obj;
      const out = { ...obj };
      const wasSet = (typeof out.webhook_url === 'string') && out.webhook_url.trim().length > 0;
      if ('webhook_url' in out) out.webhook_url = '';
      delete out.webhook_url_redacted;
      out.webhook_url_set = !!wasSet;
      return out;
    };

    settings.finance_email_settings = redactWebhook(settings.finance_email_settings);
    settings.system_emails = redactWebhook(settings.system_emails);

    let banking_webhook_status_summary = [];
    try {
      const webhookRes = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/bank_provider_webhook_configs?select=id,provider_key,rail_env,webhook_public_id,provider_webhook_id,event_types,status,last_verified_at_utc,last_event_at_utc,last_error_at_utc,last_error,last_failed_event_sync_at_utc,old_secret_expires_at_utc,signing_secret_ref,signing_secret_encrypted,old_signing_secret_encrypted,meta_json,updated_at_utc&order=provider_key.asc,rail_env.asc,webhook_public_id.asc&limit=100`,
        false
      );
      const webhookRows = Array.isArray(webhookRes.rows) ? webhookRes.rows : [];
      const unmatchedByConfigId = new Map();
      const unmatchedByProviderEnv = new Map();
      try {
        const receiptRes = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/bank_provider_webhook_receipts?select=webhook_config_id,provider_key,rail_env,status,signature_valid&status=eq.UNMATCHED_REVIEW_REQUIRED&signature_valid=eq.true&limit=10000`,
          false
        );
        const receiptRows = Array.isArray(receiptRes.rows) ? receiptRes.rows : [];
        for (const receiptRow of receiptRows) {
          const configId = receiptRow.webhook_config_id ? String(receiptRow.webhook_config_id) : '';
          const providerEnvKey = `${String(receiptRow.provider_key || '').trim().toUpperCase()}|${String(receiptRow.rail_env || '').trim().toUpperCase()}`;
          if (configId) unmatchedByConfigId.set(configId, (unmatchedByConfigId.get(configId) || 0) + 1);
          if (providerEnvKey !== '|') unmatchedByProviderEnv.set(providerEnvKey, (unmatchedByProviderEnv.get(providerEnvKey) || 0) + 1);
        }
      } catch {}

      const nowMs = Date.now();
      banking_webhook_status_summary = webhookRows.map((row) => {
        const meta = (row.meta_json && typeof row.meta_json === 'object' && !Array.isArray(row.meta_json)) ? row.meta_json : {};
        const secretConfigured = !!String(row.signing_secret_ref || '').trim() || !!String(row.signing_secret_encrypted || '').trim();
        const oldSecretExpiresMs = row.old_secret_expires_at_utc ? Date.parse(String(row.old_secret_expires_at_utc)) : NaN;
        const oldSecretConfigured = !!String(row.old_signing_secret_encrypted || '').trim()
          || !!String(meta.old_signing_secret_ref || meta.oldSigningSecretRef || meta.old_secret_ref || '').trim();
        const oldSecretOverlapActive = oldSecretConfigured && Number.isFinite(oldSecretExpiresMs) && oldSecretExpiresMs > nowMs;
        const providerEnvKey = `${String(row.provider_key || '').trim().toUpperCase()}|${String(row.rail_env || '').trim().toUpperCase()}`;
        const unmatchedVerifiedWebhookCount = (row.id && unmatchedByConfigId.get(String(row.id))) || unmatchedByProviderEnv.get(providerEnvKey) || 0;
        const lastError = row.last_error || null;
        const failedReplaySyncState = row.last_failed_event_sync_at_utc
          ? (lastError && String(lastError).toUpperCase().includes('FAILED_WEBHOOK_REPLAY') ? 'ERROR' : 'SYNCED')
          : 'NEVER_SYNCED';
        return {
          id: row.id || null,
          provider: row.provider_key || null,
          provider_key: row.provider_key || null,
          rail_environment: row.rail_env || null,
          rail_env: row.rail_env || null,
          webhook_public_id: row.webhook_public_id || null,
          provider_webhook_id_set: !!String(row.provider_webhook_id || '').trim(),
          configured_event_types: Array.isArray(row.event_types) ? row.event_types : [],
          event_types: Array.isArray(row.event_types) ? row.event_types : [],
          status: row.status || null,
          active: row.status === 'ACTIVE' || row.status === 'ROTATING_SECRET',
          last_verified_at_utc: row.last_verified_at_utc || null,
          last_event_at_utc: row.last_event_at_utc || null,
          last_error_at_utc: row.last_error_at_utc || null,
          last_error: lastError,
          failed_replay_sync_state: failedReplaySyncState,
          last_failed_event_sync_at_utc: row.last_failed_event_sync_at_utc || null,
          unmatched_verified_webhook_count: unmatchedVerifiedWebhookCount,
          secret_configured: secretConfigured,
          signing_secret_configured: secretConfigured,
          old_secret_configured: oldSecretConfigured,
          old_secret_overlap_active: oldSecretOverlapActive,
          old_secret_expires_at_utc: oldSecretConfigured ? (row.old_secret_expires_at_utc || null) : null,
          updated_at_utc: row.updated_at_utc || null
        };
      });
    } catch {
      banking_webhook_status_summary = [];
    }

    const banking_alert_preference_options = {
      allowed_alert_kinds: [
        'PROVIDER_OUTAGE_RETRY_LATER',
        'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
        'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
        'AUTO_UNWIND_PROGRESS',
        'WHOLE_BATCH_CANCELLATION_PROGRESS',
        'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
        'PAID_SETTLED_RECOVERY_REQUIRED',
        'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
        'WEBHOOK_UNMATCHED_REVIEW_REQUIRED',
        'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
        'BATCH_SCHEDULED_SUCCESS',
        'BATCH_SETTLED_SUCCESS'
      ],
      allowed_failure_reason_groups: [
        'INSUFFICIENT_FUNDS',
        'UNKNOWN_RECIPIENT',
        'INVALID_ACCOUNT',
        'ACCOUNT_CLOSED',
        'BANK_REJECTED',
        'PROVIDER_OUTAGE',
        'PROVIDER_UNKNOWN',
        'COMPLIANCE_REVIEW',
        'DUPLICATE_RISK',
        'PAID_RECOVERY_REQUIRED',
        'MANUAL_ADJUSTMENT_BLOCKER',
        'WEBHOOK_UNMATCHED',
        'PROVIDER_FAILED_UNSPECIFIED'
      ],
      severity_options: ['INFO','PROGRESS','ACTION_REQUIRED','CRITICAL'],
      defaults: {
        enabled: true,
        alert_kind_allowlist: null,
        alert_kind_blocklist: [],
        failure_reason_allowlist: null,
        failure_reason_blocklist: [],
        include_action_required: true,
        include_progress_alerts: true,
        include_informational_alerts: false,
        include_success_alerts: true,
        severity_min: 'ACTION_REQUIRED'
      }
    };


    return withCORS(env, req, ok({
      settings,
      finance_windows,
      banking_webhook_status_summary,
      banking_alert_preference_options
    }));
  } catch (e) {
    return withCORS(env, req, serverError("Failed to fetch settings_defaults"));
  }
}







async function handleUpdateSettings(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized('Unauthorized');

  const data = await parseJSONBody(req);
  if (!data) return withCORS(env, req, badRequest("Invalid JSON"));

  const hasImportFinancialPolicy = Object.prototype.hasOwnProperty.call(data, 'reversal_complete_financials_date')
    || Object.prototype.hasOwnProperty.call(data, 'reversal_replacement_financials_date');
  if (hasImportFinancialPolicy) {
    const allowedPolicyKeys = new Set([
      'reversal_complete_financials_date', 'reversal_replacement_financials_date',
      'expected_updated_at', 'request_key'
    ]);
    const unsupported = Object.keys(data).filter((key) => !allowedPolicyKeys.has(key));
    if (unsupported.length) {
      return withCORS(env, req, badRequest('Import financial-date settings must be saved separately from unrelated global settings.'));
    }
    const reversal = String(data.reversal_complete_financials_date || '').trim().toUpperCase();
    const replacement = String(data.reversal_replacement_financials_date || '').trim().toUpperCase();
    if (!['PAID_DATE', 'NOW'].includes(reversal) || !['PAID_DATE', 'NOW'].includes(replacement)) {
      return withCORS(env, req, badRequest('Both import financial-date settings must be PAID_DATE or NOW.'));
    }
    if (!data.expected_updated_at || String(data.request_key || '').trim().length < 16) {
      return withCORS(env, req, badRequest('expected_updated_at and a stable request_key are required.'));
    }
    try {
      const raw = await sbRpc(env, 'settings_defaults_import_financial_policy_update_v1', {
        p_expected_updated_at: data.expected_updated_at,
        p_reversal_complete_financials_date: reversal,
        p_reversal_replacement_financials_date: replacement,
        p_actor_user_id: user.id,
        p_request_key: String(data.request_key).trim()
      }, { timeoutMs: 15000 });
      return withCORS(env, req, ok(unwrapRpcJsonb(raw, 'settings_defaults_import_financial_policy_update_v1')));
    } catch (error) {
      const code = String(error?.json?.message || error?.message || '').match(/[A-Z][A-Z0-9_]{4,}/)?.[0] || 'SETTINGS_UPDATE_FAILED';
      return withCORS(env, req, new Response(JSON.stringify({
        ok: false,
        error_code: code,
        message: /CONFLICT|STALE/.test(code) ? 'Global settings changed. Reload and try again.' : 'The global import financial-date settings were not changed.'
      }), { status: /CONFLICT|STALE/.test(code) ? 409 : 400, headers: JSON_HEADERS }));
    }
  }

  const forbiddenBankWebhookSettingKeys = [
    'bank_provider_webhook_signing_secret',
    'bank_provider_webhook_signing_secret_ref',
    'bank_provider_webhook_signing_secret_encrypted',
    'signing_secret',
    'signing_secret_ref',
    'signing_secret_encrypted',
    'old_signing_secret_encrypted',
    'webhook_signing_secret'
  ];
  for (const key of forbiddenBankWebhookSettingKeys) {
    if (Object.prototype.hasOwnProperty.call(data, key)) {
      return withCORS(env, req, badRequest('Bank provider webhook secrets cannot be updated through generic settings.'));
    }
  }
  const forbiddenAlertPreferenceSettingKeys = [
    'banking_alert_user_preferences',
    'alert_kind_allowlist',
    'alert_kind_blocklist',
    'failure_reason_allowlist',
    'failure_reason_blocklist',
    'include_action_required',
    'include_progress_alerts',
    'include_informational_alerts',
    'include_success_alerts',
    'muted_provider_keys',
    'muted_pay_batch_ids',
    'snoozed_until_utc'
  ];
  for (const key of forbiddenAlertPreferenceSettingKeys) {
    if (Object.prototype.hasOwnProperty.call(data, key)) {
      return withCORS(env, req, badRequest('Banking Alert preferences must be updated through the alert preferences endpoint.'));
    }
  }

  const allowed = [
    'timezone_id',
    'banking_pay_official_pay_weekday',
    'day_start','day_end','night_start','night_end',
    'sat_start','sat_end','sun_start','sun_end',
    'bh_start','bh_end',
    'bh_source','bh_list','bh_feed_url',

    'bank_name','bank_sort_code','bank_account_number','vat_registration_number',
    'ts_reference_required',

    // ✅ Adaptability config
    'import_config_json',

    // ✅ Banking rail default (UI preselect only; batches still store funding_account_ref on the batch)
    'rail_default_funding_account_ref',

    // ✅ NEW: configurable export CSV columns/order
    'pay_export_csv_columns_json',
    'pay_export_csv_format_json',

    // ✅ NEW: payroll testing mode flag (simulate payments; no real bank payments)
    'payroll_testing',

    // ✅ PAYE remittances gate (default for PAYE candidate remittances when candidate override disabled)
    'paye_remittances_enabled',

    // ✅ NEW: candidate umbrella-copy default when candidate override disabled
    'remittance_receive_when_umbrella_paid',

    // ✅ NEW: detailed remittances default
    'remittances_detailed_breakdown',

    // ✅ NEW: remittance test routing (send all remittances to this email when payroll_testing=true)
    'remittance_test_recipient_email',

    // ✅ NEW: payment authoriser quantity
    'payment_authoriser_quantity',

    // ✅ NEW: payment correction/remittance timing settings
    'payment_remittance_send_timing',
    'payment_return_auto_reverse_timesheets',
    'payment_return_admin_recipient_role',
    'payment_return_admin_notice_quiet_minutes',
    'payment_return_admin_notice_max_wait_minutes',
    'banking_pay_auto_unwind_terminal_no_money',

    // ✅ NEW: pay eligibility window (Option A)
    'pay_eligibility_months_back',
    // NOTE: pay_eligibility_weeks_ahead is deprecated (cutoff date controls upper bound); ignore updates.

    // ✅ Remittances (new settings tab)
    'remittance_includes_json',
    'remittance_header_message',
    'remittance_footer_message',

    // ✅ NEW: comms adaptors config (WATI/ClickSend + limits)
    'comms_adaptors_json',

    // Email settings
    'finance_email',
    'finance_email_settings',
    'system_email',
    'system_emails',
    'max_attachments_per_email'
  ];

  const payload = { updated_at: new Date().toISOString() };

  // If we need to merge webhook_url without exposing it, fetch current values once
  const needsWebhookMerge = ('finance_email_settings' in data) || ('system_emails' in data);

  // If we need to validate default funding account ref, fetch rail defaults once
  const needsRailFundingValidation = ('rail_default_funding_account_ref' in data);

  // If quiet/max settings are updated independently, fetch current values to validate the combined pair.
  const needsPaymentCorrectionTimingValidation =
    ('payment_return_admin_notice_quiet_minutes' in data) ||
    ('payment_return_admin_notice_max_wait_minutes' in data);

  let currentEmailSettings = null;
  let currentRailDefaults = null;
  let currentPaymentCorrectionSettings = null;

  if (needsWebhookMerge || needsRailFundingValidation || needsPaymentCorrectionTimingValidation) {
    try {
      const selParts = [];
      if (needsWebhookMerge) selParts.push('finance_email_settings', 'system_emails');
      if (needsRailFundingValidation) selParts.push('rail_provider_default', 'rail_env_default');
      if (needsPaymentCorrectionTimingValidation) {
        selParts.push(
          'payment_return_admin_notice_quiet_minutes',
          'payment_return_admin_notice_max_wait_minutes'
        );
      }
      const sel = selParts.join(',');

      const { rows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/settings_defaults?id=eq.1&select=${sel}`
      );

      const row0 = (rows && rows[0]) ? rows[0] : {};

      if (needsWebhookMerge) {
        currentEmailSettings = {
          finance_email_settings: row0.finance_email_settings || {},
          system_emails: row0.system_emails || {}
        };
      }

      if (needsRailFundingValidation) {
        currentRailDefaults = {
          rail_provider_default: row0.rail_provider_default,
          rail_env_default: row0.rail_env_default
        };
      }

      if (needsPaymentCorrectionTimingValidation) {
        currentPaymentCorrectionSettings = {
          payment_return_admin_notice_quiet_minutes: row0.payment_return_admin_notice_quiet_minutes,
          payment_return_admin_notice_max_wait_minutes: row0.payment_return_admin_notice_max_wait_minutes
        };
      }
    } catch {
      if (needsWebhookMerge) currentEmailSettings = { finance_email_settings: {}, system_emails: {} };
      if (needsRailFundingValidation) currentRailDefaults = { rail_provider_default: null, rail_env_default: null };
      if (needsPaymentCorrectionTimingValidation) {
        currentPaymentCorrectionSettings = {
          payment_return_admin_notice_quiet_minutes: 10,
          payment_return_admin_notice_max_wait_minutes: 60
        };
      }
    }
  }

  const mergeWebhookSettings = (existingRaw, incomingRaw) => {
    const existing = (existingRaw && typeof existingRaw === 'object' && !Array.isArray(existingRaw)) ? existingRaw : {};
    const incoming = (incomingRaw && typeof incomingRaw === 'object' && !Array.isArray(incomingRaw)) ? incomingRaw : {};

    // strip non-persisted UI hints
    const cleanIncoming = { ...incoming };
    delete cleanIncoming.webhook_url_set;
    delete cleanIncoming.webhook_url_redacted;

    const out = { ...existing };

    // headers: if present in incoming, replace (allow null to clear)
    if ('headers' in cleanIncoming) {
      const h = cleanIncoming.headers;
      if (h == null) out.headers = {};
      else if (typeof h === 'object' && !Array.isArray(h)) out.headers = h;
      else throw new Error('invalid_headers');
    }

    // webhook_url: only overwrite when a non-empty real value is supplied
    if ('webhook_url' in cleanIncoming) {
      const w = cleanIncoming.webhook_url;
      if (w == null) {
        // keep existing
      } else if (typeof w === 'string') {
        const v = w.trim();
        if (v && v !== '[REDACTED]') out.webhook_url = v;
      } else {
        throw new Error('invalid_webhook_url');
      }
    }

    return out;
  };

  const isPlainObj = (x) => !!(x && typeof x === 'object' && !Array.isArray(x));

  const normalizeTextOrNull = (raw) => {
    if (raw === null || raw === undefined) return null;
    const s = String(raw);
    const t = s.trim();
    return t.length ? s : null;
  };

  const validateRemittanceIncludesJson = (obj) => {
    if (obj == null) return null;
    if (!isPlainObj(obj)) throw new Error('remittance_includes_json_not_object');

    const weekly = obj.weekly;
    const daily = obj.daily;

    if (!isPlainObj(weekly) || !isPlainObj(daily)) throw new Error('remittance_includes_json_missing_scopes');

    if ('include_item_types' in weekly && !isPlainObj(weekly.include_item_types)) throw new Error('remittance_includes_json_weekly_item_types');
    if ('include_fields' in weekly && !isPlainObj(weekly.include_fields)) throw new Error('remittance_includes_json_weekly_fields');

    if ('include_item_types' in daily && !isPlainObj(daily.include_item_types)) throw new Error('remittance_includes_json_daily_item_types');
    if ('include_fields' in daily && !isPlainObj(daily.include_fields)) throw new Error('remittance_includes_json_daily_fields');

    if ('defaults' in obj && obj.defaults != null && !isPlainObj(obj.defaults)) throw new Error('remittance_includes_json_defaults');

    return obj;
  };

  const MAX_REM_MSG_LEN = 2000;

  const parseStrictBoolean = (raw, fieldName) => {
    if (typeof raw === 'boolean') return raw;
    if (typeof raw === 'string') {
      const t = raw.trim().toLowerCase();
      if (t === 'true') return true;
      if (t === 'false') return false;
    }
    throw new Error(`${fieldName} must be boolean`);
  };

  const parseStrictInteger = (raw, fieldName) => {
    const n = Number(raw);
    const v = Number.isFinite(n) ? Math.trunc(n) : NaN;
    if (!Number.isFinite(v)) throw new Error(`${fieldName} must be an integer`);
    return v;
  };

  for (const k of allowed) {
    if (!(k in data)) continue;

    if (k === 'payment_remittance_send_timing') {
      const v = String(data.payment_remittance_send_timing || '').trim().toUpperCase();
      if (!['ON_EXECUTION', 'ON_PAYMENT_CONFIRMED'].includes(v)) {
        return withCORS(env, req, badRequest('payment_remittance_send_timing must be ON_EXECUTION or ON_PAYMENT_CONFIRMED'));
      }
      payload.payment_remittance_send_timing = v;
      continue;
    }

    if (k === 'payment_return_auto_reverse_timesheets') {
      try {
        payload.payment_return_auto_reverse_timesheets = parseStrictBoolean(data.payment_return_auto_reverse_timesheets, 'payment_return_auto_reverse_timesheets');
      } catch (e) {
        return withCORS(env, req, badRequest(String(e?.message || e)));
      }
      continue;
    }

    if (k === 'payment_return_admin_recipient_role') {
      if (typeof data.payment_return_admin_recipient_role !== 'string') {
        return withCORS(env, req, badRequest('payment_return_admin_recipient_role must be a non-empty string'));
      }
      const v = data.payment_return_admin_recipient_role.trim();
      if (!v) {
        return withCORS(env, req, badRequest('payment_return_admin_recipient_role must be a non-empty string'));
      }
      payload.payment_return_admin_recipient_role = v;
      continue;
    }

    if (k === 'payment_return_admin_notice_quiet_minutes') {
      let v;
      try {
        v = parseStrictInteger(data.payment_return_admin_notice_quiet_minutes, 'payment_return_admin_notice_quiet_minutes');
      } catch (e) {
        return withCORS(env, req, badRequest(String(e?.message || e)));
      }
      if (!(v >= 0 && v <= 1440)) {
        return withCORS(env, req, badRequest('payment_return_admin_notice_quiet_minutes must be an integer between 0 and 1440'));
      }
      payload.payment_return_admin_notice_quiet_minutes = v;
      continue;
    }

    if (k === 'payment_return_admin_notice_max_wait_minutes') {
      let v;
      try {
        v = parseStrictInteger(data.payment_return_admin_notice_max_wait_minutes, 'payment_return_admin_notice_max_wait_minutes');
      } catch (e) {
        return withCORS(env, req, badRequest(String(e?.message || e)));
      }
      if (!(v >= 0 && v <= 1440)) {
        return withCORS(env, req, badRequest('payment_return_admin_notice_max_wait_minutes must be an integer between 0 and 1440'));
      }
      payload.payment_return_admin_notice_max_wait_minutes = v;
      continue;
    }

    if (k === 'banking_pay_auto_unwind_terminal_no_money') {
      try {
        payload.banking_pay_auto_unwind_terminal_no_money = parseStrictBoolean(data.banking_pay_auto_unwind_terminal_no_money, 'banking_pay_auto_unwind_terminal_no_money');
      } catch (e) {
        return withCORS(env, req, badRequest(String(e?.message || e)));
      }
      continue;
    }

    if (k === 'comms_adaptors_json') {
      const raw = data.comms_adaptors_json;
      let parsed = null;

      if (raw == null) {
        parsed = {};
      } else if (isPlainObj(raw)) {
        parsed = raw;
      } else if (typeof raw === 'string') {
        parsed = _safeJsonParseMaybe(raw, null);
      }

      if (!isPlainObj(parsed)) {
        return withCORS(env, req, badRequest('comms_adaptors_json must be a JSON object (or a JSON string that parses to an object).'));
      }

      payload.comms_adaptors_json = parsed;
      continue;
    }

    if (k === 'import_config_json') {
      const raw = data.import_config_json;
      let parsed = null;

      if (raw && typeof raw === 'object') {
        parsed = raw;
      } else if (typeof raw === 'string') {
        parsed = _safeJsonParseMaybe(raw, null);
      } else if (raw == null) {
        parsed = {};
      }

      if (!parsed || typeof parsed !== 'object') {
        return withCORS(env, req, badRequest("import_config_json must be a JSON object (or a JSON string that parses to an object)."));
      }

      payload.import_config_json = parsed;
      continue;
    }

    if (k === 'pay_export_csv_columns_json') {
      const raw = data.pay_export_csv_columns_json;
      let parsed = null;

      if (raw == null) {
        payload.pay_export_csv_columns_json = null;
        continue;
      } else if (Array.isArray(raw)) {
        parsed = raw;
      } else if (typeof raw === 'string') {
        parsed = _safeJsonParseMaybe(raw, null);
      }

      if (!Array.isArray(parsed)) {
        return withCORS(env, req, badRequest('pay_export_csv_columns_json must be a JSON array (or null)'));
      }

      // Validate: must be an array of non-empty strings (duplicates are allowed here but will be rejected by export RPC)
      for (const it of parsed) {
        const s = (it === null || it === undefined) ? '' : String(it).trim();
        if (!s) {
          return withCORS(env, req, badRequest('pay_export_csv_columns_json must contain only non-empty strings'));
        }
      }

      payload.pay_export_csv_columns_json = parsed.map((it) => String(it).trim());
      continue;
    }

    if (k === 'pay_export_csv_format_json') {
      const raw = data.pay_export_csv_format_json;
      let parsed = null;

      if (raw == null) {
        payload.pay_export_csv_format_json = {};
        continue;
      } else if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
        parsed = raw;
      } else if (typeof raw === 'string') {
        try {
          parsed = JSON.parse(raw);
        } catch {
          return withCORS(env, req, badRequest('pay_export_csv_format_json must be valid JSON object or null'));
        }
      }

      try {
        payload.pay_export_csv_format_json = normalizePayExportCsvFormatJson(parsed);
      } catch (e) {
        return withCORS(env, req, badRequest(String(e?.message || e || 'pay_export_csv_format_json invalid')));
      }
      continue;
    }

    if (k === 'remittance_includes_json') {
      const raw = data.remittance_includes_json;
      let parsed = null;

      if (raw == null) {
        parsed = null;
      } else if (isPlainObj(raw)) {
        parsed = raw;
      } else if (typeof raw === 'string') {
        parsed = _safeJsonParseMaybe(raw, null);
      }

      try {
        payload.remittance_includes_json = validateRemittanceIncludesJson(parsed);
      } catch (e) {
        const msg = String(e?.message || e || '');
        const err =
          (msg === 'remittance_includes_json_not_object') ? 'remittance_includes_json must be a JSON object (or null)' :
          (msg === 'remittance_includes_json_missing_scopes') ? 'remittance_includes_json must include weekly and daily objects' :
          (msg === 'remittance_includes_json_weekly_item_types') ? 'remittance_includes_json.weekly.include_item_types must be an object' :
          (msg === 'remittance_includes_json_weekly_fields') ? 'remittance_includes_json.weekly.include_fields must be an object' :
          (msg === 'remittance_includes_json_daily_item_types') ? 'remittance_includes_json.daily.include_item_types must be an object' :
          (msg === 'remittance_includes_json_daily_fields') ? 'remittance_includes_json.daily.include_fields must be an object' :
          (msg === 'remittance_includes_json_defaults') ? 'remittance_includes_json.defaults must be an object' :
          'remittance_includes_json invalid';
        return withCORS(env, req, badRequest(err));
      }
      continue;
    }

    if (k === 'remittance_header_message') {
      const v = normalizeTextOrNull(data.remittance_header_message);
      if (v != null && v.length > MAX_REM_MSG_LEN) {
        return withCORS(env, req, badRequest(`remittance_header_message too long (max ${MAX_REM_MSG_LEN})`));
      }
      payload.remittance_header_message = v;
      continue;
    }

    if (k === 'remittance_footer_message') {
      const v = normalizeTextOrNull(data.remittance_footer_message);
      if (v != null && v.length > MAX_REM_MSG_LEN) {
        return withCORS(env, req, badRequest(`remittance_footer_message too long (max ${MAX_REM_MSG_LEN})`));
      }
      payload.remittance_footer_message = v;
      continue;
    }

    if (k === 'finance_email_settings') {
      const raw = data.finance_email_settings;
      let parsed = null;

      if (raw && typeof raw === 'object') parsed = raw;
      else if (typeof raw === 'string') parsed = _safeJsonParseMaybe(raw, null);
      else if (raw == null) parsed = {};
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return withCORS(env, req, badRequest("finance_email_settings must be a JSON object (or a JSON string that parses to an object)."));
      }

      try {
        payload.finance_email_settings = mergeWebhookSettings(currentEmailSettings?.finance_email_settings, parsed);
      } catch (e) {
        const msg = (String(e?.message || e) === 'invalid_headers') ? 'finance_email_settings.headers must be an object' :
                    (String(e?.message || e) === 'invalid_webhook_url') ? 'finance_email_settings.webhook_url must be a string' :
                    'finance_email_settings invalid';
        return withCORS(env, req, badRequest(msg));
      }
      continue;
    }

    if (k === 'system_emails') {
      const raw = data.system_emails;
      let parsed = null;

      if (raw && typeof raw === 'object') parsed = raw;
      else if (typeof raw === 'string') parsed = _safeJsonParseMaybe(raw, null);
      else if (raw == null) parsed = {};
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return withCORS(env, req, badRequest("system_emails must be a JSON object (or a JSON string that parses to an object)."));
      }

      try {
        payload.system_emails = mergeWebhookSettings(currentEmailSettings?.system_emails, parsed);
      } catch (e) {
        const msg = (String(e?.message || e) === 'invalid_headers') ? 'system_emails.headers must be an object' :
                    (String(e?.message || e) === 'invalid_webhook_url') ? 'system_emails.webhook_url must be a string' :
                    'system_emails invalid';
        return withCORS(env, req, badRequest(msg));
      }
      continue;
    }

    if (k === 'max_attachments_per_email') {
      const n = Number(data.max_attachments_per_email);
      const v = Number.isFinite(n) ? Math.trunc(n) : NaN;

      if (!(v >= 1 && v <= 100)) {
        return withCORS(env, req, badRequest("max_attachments_per_email must be an integer between 1 and 100."));
      }

      payload.max_attachments_per_email = v;
      continue;
    }

    if (k === 'finance_email') {
      const v = (data.finance_email == null) ? null : String(data.finance_email).trim();
      payload.finance_email = v && v.length ? v : null;
      continue;
    }

    if (k === 'system_email') {
      const v0 = (data.system_email == null) ? null : String(data.system_email).trim();
      if (v0 && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v0)) {
        return withCORS(env, req, badRequest('invalid_system_email'));
      }
      payload.system_email = v0 && v0.length ? v0 : null;
      continue;
    }

    if (k === 'payroll_testing') {
      const raw = data.payroll_testing;

      let v = null;
      if (typeof raw === 'boolean') {
        v = raw;
      } else if (typeof raw === 'string') {
        const t = raw.trim().toLowerCase();
        if (t === 'true') v = true;
        else if (t === 'false') v = false;
      }

      if (v === null) {
        return withCORS(env, req, badRequest('payroll_testing must be boolean'));
      }

      payload.payroll_testing = v;
      continue;
    }

    if (k === 'paye_remittances_enabled') {
      const raw = data.paye_remittances_enabled;

      let v = null;
      if (typeof raw === 'boolean') {
        v = raw;
      } else if (typeof raw === 'string') {
        const t = raw.trim().toLowerCase();
        if (t === 'true') v = true;
        else if (t === 'false') v = false;
      }

      if (v === null) {
        return withCORS(env, req, badRequest('paye_remittances_enabled must be boolean'));
      }

      payload.paye_remittances_enabled = v;
      continue;
    }

    if (k === 'remittances_detailed_breakdown') {
      const raw = data.remittances_detailed_breakdown;

      let v = null;
      if (typeof raw === 'boolean') {
        v = raw;
      } else if (typeof raw === 'string') {
        const t = raw.trim().toLowerCase();
        if (t === 'true') v = true;
        else if (t === 'false') v = false;
      }

      if (v === null) {
        return withCORS(env, req, badRequest('remittances_detailed_breakdown must be boolean'));
      }

      payload.remittances_detailed_breakdown = v;
      continue;
    }

    if (k === 'remittance_receive_when_umbrella_paid') {
      const raw = data.remittance_receive_when_umbrella_paid;

      let v = null;
      if (typeof raw === 'boolean') {
        v = raw;
      } else if (typeof raw === 'string') {
        const t = raw.trim().toLowerCase();
        if (t === 'true') v = true;
        else if (t === 'false') v = false;
      }

      if (v === null) {
        return withCORS(env, req, badRequest('remittance_receive_when_umbrella_paid must be boolean'));
      }

      payload.remittance_receive_when_umbrella_paid = v;
      continue;
    }

    if (k === 'remittance_test_recipient_email') {
      const v0 = (data.remittance_test_recipient_email == null) ? null : String(data.remittance_test_recipient_email).trim();
      if (!v0) {
        payload.remittance_test_recipient_email = null;
        continue;
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+\.[^\s@]+$/.test(v0)) {
        // keep existing error code format as-is
        return withCORS(env, req, badRequest('invalid_remittance_test_recipient_email'));
      }
      payload.remittance_test_recipient_email = v0;
      continue;
    }

    if (k === 'banking_pay_official_pay_weekday') {
      const weekday = parseStrictInteger(data[k], 'banking_pay_official_pay_weekday');
      if (weekday < 0 || weekday > 6) {
        return withCORS(env, req, badRequest('banking_pay_official_pay_weekday must be an integer from 0 (Sunday) to 6 (Saturday)'));
      }
      payload[k] = weekday;
      continue;
    }

    if (k === 'payment_authoriser_quantity') {
      const raw = data.payment_authoriser_quantity;
      const n = Number(raw);
      const v = Number.isFinite(n) ? Math.trunc(n) : NaN;
      if (!(v >= 1 && v <= 10)) {
        return withCORS(env, req, badRequest('payment_authoriser_quantity must be an integer between 1 and 10'));
      }
      payload.payment_authoriser_quantity = v;
      continue;
    }

    if (k === 'pay_eligibility_months_back') {
      const raw = data.pay_eligibility_months_back;
      const n = Number(raw);
      const v = Number.isFinite(n) ? Math.trunc(n) : NaN;
      if (!(v >= 0 && v <= 120)) {
        return withCORS(env, req, badRequest('pay_eligibility_months_back must be an integer between 0 and 120'));
      }
      payload.pay_eligibility_months_back = v;
      continue;
    }

    if (k === 'rail_default_funding_account_ref') {
      const v0 = (data.rail_default_funding_account_ref === null || data.rail_default_funding_account_ref === undefined)
        ? null
        : (String(data.rail_default_funding_account_ref).trim() || null);

      // Allow clearing
      if (v0 == null) {
        payload.rail_default_funding_account_ref = null;
        continue;
      }

      // Validate against current rail adapter
      const provider = String(currentRailDefaults?.rail_provider_default || 'CSV').trim().toUpperCase();
      const railEnv = String(currentRailDefaults?.rail_env_default || 'PROD').trim().toUpperCase();

      const adapter = getRailAdapter(provider);
      if (!adapter || typeof adapter.validateFundingAccountRef !== 'function') {
        return withCORS(env, req, badRequest('FUNDING_ACCOUNT_REF_NOT_SUPPORTED_FOR_THIS_RAIL'));
      }

      // ✅ OPTION (1): Only validate if the rail is configured/available. If not available, allow saving without validation
      // to avoid wedging Global Settings when Revolut OAuth/redirect config is incomplete.
      if (typeof adapter.capabilities === 'function') {
        let caps = null;
        try {
          caps = await adapter.capabilities(env);
        } catch (e) {
          caps = { available: false, reason: (e && e.message) ? String(e.message) : 'CAPABILITIES_FAILED' };
        }

        if (caps && typeof caps === 'object' && caps.available === false) {
          payload.rail_default_funding_account_ref = v0;
          continue;
        }
      }

      let vres = null;
      try {
        vres = await adapter.validateFundingAccountRef(env, { rail_env: railEnv, funding_account_ref: v0 });
      } catch (e) {
        const msg = (e && e.message) ? String(e.message) : String(e || 'FUNDING_ACCOUNT_VALIDATE_FAILED');
        return withCORS(env, req, badRequest(msg));
      }

      const valid = !!(vres && typeof vres === 'object' && vres.valid === true);
      if (!valid) {
        const reason = (vres && typeof vres === 'object' && vres.reason) ? String(vres.reason) : 'FUNDING_ACCOUNT_REF_INVALID';
        return withCORS(env, req, badRequest(reason));
      }

      const acct = (vres && typeof vres === 'object') ? (vres.account || null) : null;
      const ccy = (acct && acct.currency !== undefined && acct.currency !== null) ? String(acct.currency).trim().toUpperCase() : null;
      if (ccy && ccy !== 'GBP') {
        return withCORS(env, req, badRequest('FUNDING_ACCOUNT_REF_MUST_BE_GBP'));
      }

      payload.rail_default_funding_account_ref = v0;
      continue;
    }

    // Normal field passthrough
    payload[k] = data[k];
  }

  if (
    ('payment_return_admin_notice_quiet_minutes' in payload) ||
    ('payment_return_admin_notice_max_wait_minutes' in payload)
  ) {
    const quiet = ('payment_return_admin_notice_quiet_minutes' in payload)
      ? payload.payment_return_admin_notice_quiet_minutes
      : (() => {
          const n = Number(currentPaymentCorrectionSettings?.payment_return_admin_notice_quiet_minutes);
          const v = Number.isFinite(n) ? Math.trunc(n) : 10;
          return (v >= 0 && v <= 1440) ? v : 10;
        })();

    const maxWait = ('payment_return_admin_notice_max_wait_minutes' in payload)
      ? payload.payment_return_admin_notice_max_wait_minutes
      : (() => {
          const n = Number(currentPaymentCorrectionSettings?.payment_return_admin_notice_max_wait_minutes);
          const v = Number.isFinite(n) ? Math.trunc(n) : 60;
          return (v >= 0 && v <= 1440) ? v : 60;
        })();

    if (maxWait < quiet) {
      return withCORS(env, req, badRequest('payment_return_admin_notice_max_wait_minutes must be greater than or equal to payment_return_admin_notice_quiet_minutes'));
    }
  }

  try {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/settings_defaults?id=eq.1`, {
      method: "PATCH",
      headers: { ...sbHeaders(env), "Prefer": "return=representation" },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      const err = await res.text();
      return withCORS(env, req, badRequest(`Update failed: ${err}`));
    }

    const json = await res.json().catch(() => ({}));
    const settings = Array.isArray(json) ? json[0] : json;
    delete settings.id;

    // Bust TTL cache so next loadSettingsDefaults fetches fresh values
    __SETTINGS_DEFAULTS_CACHE = { ts: 0, value: null };

    // Redact webhook URLs in response
    const redactWebhook = (obj) => {
      if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return obj;
      const out = { ...obj };
      const wasSet = (typeof out.webhook_url === 'string') && out.webhook_url.trim().length > 0;
      if ('webhook_url' in out) out.webhook_url = '';
      delete out.webhook_url_redacted;
      out.webhook_url_set = !!wasSet;
      return out;
    };
    settings.finance_email_settings = redactWebhook(settings.finance_email_settings);
    settings.system_emails = redactWebhook(settings.system_emails);

    return withCORS(env, req, ok({ settings }));
  } catch {
    return withCORS(env, req, serverError("Failed to update settings_defaults"));
  }
}
async function resolveBankingPayOfficialDateContext(env, options = {}) {
  const trimStr = (value) => String(value == null ? '' : value).trim();
  const safeObject = (value) => (value && typeof value === 'object' && !Array.isArray(value)) ? value : {};
  const isoDateRe = /^\d{4}-\d{2}-\d{2}$/;
  const asOfUtcRaw = trimStr(options.as_of_utc ?? options.asOfUtc);
  let asOfUtc = null;

  if (asOfUtcRaw) {
    const parsed = Date.parse(asOfUtcRaw);
    if (!Number.isFinite(parsed)) {
      const error = new Error('The Banking Pay date context could not be resolved because the supplied as-of timestamp is invalid.');
      error.code = 'BANKING_PAY_DATE_CONTEXT_AS_OF_INVALID';
      throw error;
    }
    asOfUtc = new Date(parsed).toISOString();
  }

  const rpcResult = await sbRpc(env, 'pay_banking_official_date_context_v1', {
    p_as_of_utc: asOfUtc
  }, {
    routeClass: 'DISPLAY',
    purpose: 'BANKING_PAY_OFFICIAL_DATE_CONTEXT',
    timeoutMs: 8000
  });

  let payload = rpcResult;
  if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') {
    payload = payload[0];
  }
  if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'pay_banking_official_date_context_v1')) {
    payload = payload.pay_banking_official_date_context_v1;
  }
  if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') {
    payload = payload[0];
  }

  const context = safeObject(payload);
  const timezoneId = trimStr(context.timezone_id);
  const businessDateField = trimStr(context.business_date);
  const londonCurrentDateField = trimStr(context.london_current_date);
  const businessDate = businessDateField || londonCurrentDateField;
  const currentOfficialPayDate = trimStr(context.current_official_pay_date);
  const nextOfficialPayDate = trimStr(context.next_official_pay_date);
  const followingOfficialPayDate = trimStr(context.following_official_pay_date);
  const currentPayWeekStart = trimStr(context.current_pay_week_start);
  const currentPayWeekEnd = trimStr(context.current_pay_week_end);
  const currentPayWeekKey = trimStr(context.current_pay_week_key || currentOfficialPayDate);
  const configurationFingerprint = trimStr(context.configuration_fingerprint);
  const officialWeekday = Number(context.official_pay_weekday);

  if (
    context.ok !== true ||
    timezoneId !== 'Europe/London' ||
    !isoDateRe.test(businessDate) ||
    (businessDateField && !isoDateRe.test(businessDateField)) ||
    (londonCurrentDateField && !isoDateRe.test(londonCurrentDateField)) ||
    (businessDateField && londonCurrentDateField && businessDateField !== londonCurrentDateField) ||
    !isoDateRe.test(currentOfficialPayDate) ||
    !isoDateRe.test(nextOfficialPayDate) ||
    !isoDateRe.test(followingOfficialPayDate) ||
    !isoDateRe.test(currentPayWeekStart) ||
    !isoDateRe.test(currentPayWeekEnd) ||
    !isoDateRe.test(currentPayWeekKey) ||
    !configurationFingerprint ||
    !Number.isInteger(officialWeekday) ||
    officialWeekday < 0 ||
    officialWeekday > 6
  ) {
    const error = new Error('The authoritative Banking Pay date context returned an invalid result.');
    error.code = 'BANKING_PAY_DATE_CONTEXT_INVALID';
    error.context = context;
    throw error;
  }

  const businessTime = Date.parse(`${businessDate}T00:00:00Z`);
  const currentPayTime = Date.parse(`${currentOfficialPayDate}T00:00:00Z`);
  const nextPayTime = Date.parse(`${nextOfficialPayDate}T00:00:00Z`);
  const followingPayTime = Date.parse(`${followingOfficialPayDate}T00:00:00Z`);
  const weekStartTime = Date.parse(`${currentPayWeekStart}T00:00:00Z`);
  const weekEndTime = Date.parse(`${currentPayWeekEnd}T00:00:00Z`);

  if (
    !Number.isFinite(businessTime) ||
    !Number.isFinite(currentPayTime) ||
    !Number.isFinite(nextPayTime) ||
    !Number.isFinite(followingPayTime) ||
    !Number.isFinite(weekStartTime) ||
    !Number.isFinite(weekEndTime) ||
    currentPayTime < businessTime ||
    nextPayTime !== currentPayTime ||
    followingPayTime !== currentPayTime + (7 * 24 * 60 * 60 * 1000) ||
    weekEndTime !== currentPayTime ||
    weekStartTime !== weekEndTime - (6 * 24 * 60 * 60 * 1000) ||
    currentPayWeekKey !== currentOfficialPayDate ||
    new Date(currentPayTime).getUTCDay() !== officialWeekday
  ) {
    const error = new Error('The authoritative Banking Pay date context is internally inconsistent.');
    error.code = 'BANKING_PAY_DATE_CONTEXT_INCONSISTENT';
    error.context = context;
    throw error;
  }

  return {
    ...context,
    ok: true,
    timezone_id: timezoneId,
    timezoneId,
    london_current_date: businessDate,
    business_date: businessDate,
    businessDate,
    current_official_pay_date: currentOfficialPayDate,
    currentOfficialPayDate,
    next_official_pay_date: nextOfficialPayDate,
    nextOfficialPayDate,
    following_official_pay_date: followingOfficialPayDate,
    followingOfficialPayDate,
    current_pay_week_start: currentPayWeekStart,
    currentPayWeekStart,
    current_pay_week_end: currentPayWeekEnd,
    currentPayWeekEnd,
    current_pay_week_key: currentPayWeekKey,
    currentPayWeekKey,
    official_pay_weekday: officialWeekday,
    officialPayWeekday: officialWeekday,
    configuration_fingerprint: configurationFingerprint,
    configurationFingerprint
  };
}

async function handleAuthReauthVerify(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;

  const u = await requireUser(env, req); // any logged-in user
  if (!u) return unauthorized('Unauthorized');

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const challengeId = String(body.challenge_id || body.challengeId || '').trim();
  const code = String(body.code || '').trim();

  if (!challengeId) return badRequest('challenge_id_required');
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(challengeId)) {
    return badRequest('invalid_challenge_id');
  }
  if (!/^\d{6}$/.test(code)) return badRequest('invalid_code_format');

  const allowedPurposes = new Set(['PAYMENT_SCHEDULE', 'PAYE_SAME_WEEK_OVERRIDE', 'PAYMENT_REVERSAL']);
  const requestedPurposeRaw = (body.purpose !== undefined && body.purpose !== null)
    ? body.purpose
    : ((body.reauth_purpose !== undefined && body.reauth_purpose !== null) ? body.reauth_purpose : null);
  const requestedPurpose = requestedPurposeRaw === null ? null : String(requestedPurposeRaw || '').trim().toUpperCase();

  if (requestedPurpose && !allowedPurposes.has(requestedPurpose)) {
    return badRequest('invalid_reauth_purpose');
  }

  // Load auth policy (reuse same policy source as login 2FA)
  let authEffective = null;
  try {
    const s = await loadSettingsDefaults(env);
    authEffective = (s && s.importConfig && s.importConfig.auth_effective && typeof s.importConfig.auth_effective === 'object')
      ? s.importConfig.auth_effective
      : null;
  } catch { authEffective = null; }

  const tfaMaxAttempts = (authEffective && Number.isFinite(Number(authEffective.tfa_max_attempts)))
    ? Math.max(1, Math.trunc(Number(authEffective.tfa_max_attempts)))
    : 10;

  const ip = getClientIp(req);
  const ipKey = (ip && String(ip).trim()) ? String(ip).trim() : 'UNKNOWN';

  let ch;
  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges` +
        `?id=eq.${encodeURIComponent(challengeId)}` +
        `&select=id,user_id,ip_address,code_salt,code_hash,expires_at_utc,used_at_utc,attempt_count,purpose` +
        `&limit=1`
    );
    ch = (rows && rows[0]) ? rows[0] : null;
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  if (!ch) return badRequest('invalid_challenge');

  const challengePurpose = String(ch.purpose || 'PAYMENT_SCHEDULE').trim().toUpperCase();
  if (!allowedPurposes.has(challengePurpose)) {
    return badRequest('invalid_challenge_purpose');
  }

  if (requestedPurpose && requestedPurpose !== challengePurpose) {
    return unauthorized('Invalid code');
  }

  // Must match current logged-in user
  if (String(ch.user_id || '').trim() !== String(u.id || '').trim()) {
    return unauthorized('Invalid code');
  }

  // Same IP enforcement
  if (String(ch.ip_address || '').trim() !== ipKey) {
    return unauthorized('Invalid code');
  }

  if (ch.used_at_utc) return badRequest('invalid_or_expired_code');

  const expMs = Date.parse(String(ch.expires_at_utc || ''));
  if (!Number.isFinite(expMs) || expMs < Date.now()) return badRequest('invalid_or_expired_code');

  const attempts = Number(ch.attempt_count ?? 0) || 0;
  if (attempts >= tfaMaxAttempts) return badRequest('max_attempts_exceeded');

  // Verify hash
  let wantHash = '';
  try {
    wantHash = await hash2faCode(ch.code_salt, code);
  } catch (e) {
    return serverError(`2FA hash failed: ${e?.message || e}`);
  }

  const storedHash = String(ch.code_hash || '');
  const match = timingSafeEqualStr(storedHash, wantHash);

  if (!match) {
    // increment attempt_count
    try {
      await sbPatch2faChallengeById(env, challengeId, { attempt_count: attempts + 1 });
    } catch (e) {
      return serverError(e?.message || String(e));
    }
    return unauthorized('Invalid code');
  }

  const nowIso = new Date().toISOString();

  // Mark challenge used
  try {
    await sbPatch2faChallengeById(env, challengeId, { used_at_utc: nowIso });
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  // Upsert trust row (same IP) — best-effort
  try {
    await sbUpsert2faTrust(env, ch.user_id, ipKey, { verifiedAtIso: nowIso, lastUsedAtIso: nowIso });
  } catch {}

  // Mint short-lived reauth token, bound to the challenge purpose.
  const ttlSec = 300; // 5 minutes
  const exp = Math.floor(Date.now() / 1000) + ttlSec;
  const iat = Math.floor(Date.now() / 1000);
  const payload = {
    typ: 'reauth',
    sub: String(u.id),
    purpose: challengePurpose,
    iat,
    exp
  };

  let token;
  try {
    token = await createToken(sessionSecret(env), payload);
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  return new Response(JSON.stringify({
    ok: true,
    purpose: challengePurpose,
    reauth_token: token,
    expires_in: ttlSec
  }), { status: 200, headers: JSON_HEADERS });
}


async function verifyPaymentReversalReauth(env, user, token) {
  const reauthToken = String(token || '').trim();
  if (!reauthToken) {
    return {
      ok: false,
      response: badRequest('reauth_token is required'),
      error: 'reauth_token is required'
    };
  }

  const currentUserId = String(user?.id || '').trim();
  if (!currentUserId) {
    return {
      ok: false,
      response: unauthorized('Invalid reauth_token'),
      error: 'Invalid reauth_token'
    };
  }

  let verifiedToken;
  try {
    verifiedToken = await verifyToken(sessionSecret(env), reauthToken);
  } catch (e) {
    return {
      ok: false,
      response: unauthorized('Invalid reauth_token'),
      error: String(e?.message || e || 'Invalid reauth_token')
    };
  }

  if (!verifiedToken || verifiedToken.ok !== true) {
    return {
      ok: false,
      response: unauthorized('Invalid reauth_token'),
      error: String(verifiedToken?.error || 'Invalid reauth_token')
    };
  }

  const payload = (verifiedToken && verifiedToken.payload && typeof verifiedToken.payload === 'object') ? verifiedToken.payload : {};
  const typ = String(payload.typ || '').trim();
  const purpose = String(payload.purpose || '').trim().toUpperCase();
  const sub = String(payload.sub || '').trim();
  const exp = Number(payload.exp);
  const nowUnix = Math.floor(Date.now() / 1000);

  if (typ !== 'reauth') {
    return {
      ok: false,
      response: unauthorized('Invalid reauth_token'),
      error: 'Invalid reauth_token'
    };
  }

  if (purpose !== 'PAYMENT_REVERSAL') {
    return {
      ok: false,
      response: unauthorized('Invalid reauth_token'),
      error: 'Invalid reauth_token'
    };
  }

  if (sub !== currentUserId) {
    return {
      ok: false,
      response: unauthorized('Invalid reauth_token'),
      error: 'Invalid reauth_token'
    };
  }

  if (!Number.isFinite(exp) || nowUnix > exp) {
    return {
      ok: false,
      response: unauthorized('Invalid reauth_token'),
      error: 'Invalid reauth_token'
    };
  }

  return {
    ok: true,
    verified_by_user_id: currentUserId,
    verified_at_utc: new Date().toISOString()
  };
}




async function handleAuthReauthStart(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;

  const u = await requireUser(env, req); // any logged-in user
  if (!u) return unauthorized('Unauthorized');

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const password = String(body.password || '').trim();
  if (!password) return badRequest('password_required');

  const requestedPurpose = String(body.purpose || 'PAYMENT_SCHEDULE').trim().toUpperCase();
  const allowedPurposes = new Set(['PAYMENT_SCHEDULE', 'PAYE_SAME_WEEK_OVERRIDE', 'PAYMENT_REVERSAL']);
  if (!allowedPurposes.has(requestedPurpose)) return badRequest('invalid_reauth_purpose');
  const requestedExecutionMode = String(body.execution_mode || body.executionMode || '').trim().toUpperCase();

  // Verify current password against stored hash
  const userRow = await sbGetUserById(env, u.id); // includes password_hash
  if (!userRow || userRow.is_active !== true) return unauthorized('Unauthorized');

  const okPw = await pbkdf2Verify(password, userRow.password_hash || '');
  if (!okPw) return unauthorized('Invalid credentials');

  const testCsvBypass = evaluateTestCsvExecutionBypass({
    env,
    user: userRow,
    purpose: requestedPurpose,
    executionMode: requestedExecutionMode
  });
  if (testCsvBypass.allowed) {
    const ttlSec = 300;
    const nowUnix = Math.floor(Date.now() / 1000);
    const payload = {
      typ: 'reauth',
      sub: String(userRow.id),
      purpose: 'PAYMENT_SCHEDULE',
      test_csv_execution_only: true,
      iat: nowUnix,
      exp: nowUnix + ttlSec
    };
    let token;
    try {
      token = await createToken(sessionSecret(env), payload);
    } catch (e) {
      return serverError(e?.message || String(e));
    }
    try {
      console.warn('[security] TEST-only CSV settlement 2FA override used after password verification.');
    } catch {}
    return new Response(JSON.stringify({
      ok: true,
      tfa_required: false,
      purpose: 'PAYMENT_SCHEDULE',
      execution_mode: 'CSV_SETTLEMENT',
      reauth_token: token,
      expires_in: ttlSec,
      test_csv_execution_bypass: true
    }), { status: 200, headers: JSON_HEADERS });
  }

  const testSameWeekPayeBypass = evaluateTestSameWeekPayeOverrideBypass({
    env,
    user: userRow,
    purpose: requestedPurpose
  });
  if (testSameWeekPayeBypass.allowed) {
    const ttlSec = 300;
    const nowUnix = Math.floor(Date.now() / 1000);
    const payload = {
      typ: 'reauth',
      sub: String(userRow.id),
      purpose: 'PAYE_SAME_WEEK_OVERRIDE',
      test_same_week_paye_override_only: true,
      iat: nowUnix,
      exp: nowUnix + ttlSec
    };
    let token;
    try {
      token = await createToken(sessionSecret(env), payload);
    } catch (e) {
      return serverError(e?.message || String(e));
    }
    try {
      console.warn('[security] TEST-only same-week PAYE draft 2FA override used after password verification.');
    } catch {}
    return new Response(JSON.stringify({
      ok: true,
      tfa_required: false,
      purpose: 'PAYE_SAME_WEEK_OVERRIDE',
      reauth_token: token,
      expires_in: ttlSec,
      test_same_week_paye_override_bypass: true
    }), { status: 200, headers: JSON_HEADERS });
  }

  // Load auth policy (reuse same policy source as login 2FA)
  let authEffective = null;
  try {
    const s = await loadSettingsDefaults(env);
    authEffective = (s && s.importConfig && s.importConfig.auth_effective && typeof s.importConfig.auth_effective === 'object')
      ? s.importConfig.auth_effective
      : null;
  } catch { authEffective = null; }

  const tfaCodeTtlSec = (authEffective && Number.isFinite(Number(authEffective.tfa_code_ttl_seconds)))
    ? Math.max(30, Math.trunc(Number(authEffective.tfa_code_ttl_seconds)))
    : 300;

  const ip = getClientIp(req);
  const ipKey = (ip && String(ip).trim()) ? String(ip).trim() : 'UNKNOWN';

  const nowIso = new Date().toISOString();
  const expiresAtIso = new Date(Date.now() + (tfaCodeTtlSec * 1000)).toISOString();

  const code = genSixDigitCode();
  const salt = bufToBase64Url(crypto.getRandomValues(new Uint8Array(16)));
  const codeHash = await hash2faCode(salt, code);

  // Insert challenge row (same table as login 2FA), binding it to the requested reauth purpose.
  let challengeId = null;
  try {
    const challengeRes = await fetch(`${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges`, {
      method: 'POST',
      headers: { ...sbAuthHeaders(env), Prefer: 'return=representation' },
      body: JSON.stringify({
        user_id: String(userRow.id),
        ip_address: String(ipKey),
        code_salt: String(salt),
        code_hash: String(codeHash),
        expires_at_utc: String(expiresAtIso),
        purpose: requestedPurpose
      })
    });

    if (!challengeRes.ok) {
      const t = await challengeRes.text().catch(() => '');
      return serverError(`2FA challenge insert failed (${challengeRes.status}) ${t || ''}`.trim());
    }

    const challengeRows = await challengeRes.json().catch(() => []);
    const challengeRow = Array.isArray(challengeRows) ? challengeRows[0] : challengeRows;
    challengeId = challengeRow && challengeRow.id ? String(challengeRow.id) : null;
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  if (!challengeId) return serverError('2FA challenge id missing after insert');

  // Resolve system replyTo email (optional)
  let replyTo = null;
  try {
    const s = await loadSettingsDefaults(env);
    if (s && s.system_email && String(s.system_email).trim()) replyTo = String(s.system_email).trim();
  } catch {}

  // Send code email via SYSTEM channel
  const mins = Math.max(1, Math.round(tfaCodeTtlSec / 60));
  const subject = 'CloudTMS payment verification code';
  const bodyText =
    `Your CloudTMS payment verification code is: ${code}\n\n` +
    `It expires in ${mins} minute${mins === 1 ? '' : 's'}.\n\n` +
    `If you did not request this code, you can ignore this email.`;

  const htmlBody =
    `<p>Your CloudTMS payment verification code is:</p>` +
    `<p style="font-size:22px;font-weight:700;letter-spacing:2px;">${code}</p>` +
    `<p>This code expires in ${mins} minute${mins === 1 ? '' : 's'}.</p>` +
    `<p>If you did not request this code, you can ignore this email.</p>`;

  const emailPayload = {
    to: String(userRow.email || '').trim(),
    subject,
    htmlBody,
    textBody: bodyText,
    attachmentsV2: [],
    meta: { kind: 'PAYMENT_REAUTH_2FA', purpose: requestedPurpose, user_id: String(userRow.id), challenge_id: String(challengeId), ip: ipKey, issued_at_utc: nowIso }
  };
  if (replyTo) emailPayload.replyTo = replyTo;

  let pa;
  try {
    pa = await postToPowerAutomate(env, emailPayload, 'system');
  } catch (e) {
    pa = { ok: false, status: 0, body: e?.message || String(e) };
  }

  if (!pa || pa.ok !== true) {
    // Best-effort: delete the challenge so we don't accumulate unusable rows
    try {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges?id=eq.${encodeURIComponent(challengeId)}`,
        { method: 'DELETE', headers: sbAuthHeaders(env) }
      ).catch(() => {});
    } catch {}

    return serverError(`2FA email send failed (${pa?.status || 0}) ${pa?.body || ''}`.trim());
  }

  return new Response(JSON.stringify({
    ok: true,
    tfa_required: true,
    purpose: requestedPurpose,
    challenge_id: challengeId,
    expires_in: tfaCodeTtlSec
  }), { status: 200, headers: JSON_HEADERS });
}


function getClientIp(req) {
  const h = req && req.headers;
  if (!h || typeof h.get !== 'function') return null;

  const cf = h.get('cf-connecting-ip');
  if (cf && String(cf).trim()) return String(cf).trim();

  const xff = h.get('x-forwarded-for');
  if (xff && String(xff).trim()) {
    const first = String(xff).split(',')[0];
    if (first && String(first).trim()) return String(first).trim();
  }

  const xr = h.get('x-real-ip');
  if (xr && String(xr).trim()) return String(xr).trim();

  return null;
}

function genSixDigitCode() {
  const rnd = crypto.getRandomValues(new Uint32Array(1))[0] >>> 0;
  return String(rnd % 1000000).padStart(6, '0');
}

async function hash2faCode(codeSalt, code) {
  return sha256Hex(`${String(codeSalt || '')}:${String(code || '')}`);
}

function timingSafeEqualStr(a, b) {
  const sa = String(a ?? '');
  const sb = String(b ?? '');
  if (sa.length !== sb.length) return false;
  let diff = 0;
  for (let i = 0; i < sa.length; i++) diff |= (sa.charCodeAt(i) ^ sb.charCodeAt(i));
  return diff === 0;
}

// --- 2FA challenge helpers ---
async function sbInsert2faChallenge(env, { user_id, ip_address, code_salt, code_hash, expires_at_utc }) {
  const url = `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges`;
  const res = await fetch(url, {
    method: 'POST',
    headers: { ...sbAuthHeaders(env), Prefer: 'return=representation' },
    body: JSON.stringify({
      user_id: String(user_id),
      ip_address: String(ip_address),
      code_salt: String(code_salt),
      code_hash: String(code_hash),
      expires_at_utc: String(expires_at_utc)
    })
  });
  if (!res.ok) {
    const t = await res.text().catch(() => '');
    throw new Error(`2FA challenge insert failed (${res.status}) ${t || ''}`.trim());
  }
  const arr = await res.json().catch(() => []);
  const row = Array.isArray(arr) ? arr[0] : arr;
  const id = row && row.id ? String(row.id) : null;
  if (!id) throw new Error('2FA challenge insert returned no id');
  return id;
}

async function sbGet2faChallengeById(env, challengeId) {
  const enc = encodeURIComponent;
  const url =
    `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges` +
    `?id=eq.${enc(challengeId)}` +
    `&select=id,user_id,ip_address,code_salt,code_hash,expires_at_utc,used_at_utc,attempt_count,resend_count,last_sent_at_utc`;
  const res = await fetch(url, { headers: sbAuthHeaders(env) });
  if (!res.ok) {
    const t = await res.text().catch(() => '');
    throw new Error(`2FA challenge read failed (${res.status}) ${t || ''}`.trim());
  }
  const arr = await res.json().catch(() => []);
  return Array.isArray(arr) && arr[0] ? arr[0] : null;
}

async function sbPatch2faChallengeById(env, challengeId, patch) {
  const enc = encodeURIComponent;
  const url = `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges?id=eq.${enc(challengeId)}`;
  const res = await fetch(url, {
    method: 'PATCH',
    headers: { ...sbAuthHeaders(env), Prefer: 'return=representation' },
    body: JSON.stringify(patch || {})
  });
  if (!res.ok) {
    const t = await res.text().catch(() => '');
    throw new Error(`2FA challenge update failed (${res.status}) ${t || ''}`.trim());
  }
  const arr = await res.json().catch(() => []);
  return Array.isArray(arr) && arr[0] ? arr[0] : null;
}

// --- 2FA trust helpers ---
async function sbGet2faTrustByUserIp(env, userId, ipAddress) {
  const enc = encodeURIComponent;
  const url =
    `${env.SUPABASE_URL}/rest/v1/tms_user_2fa_trust` +
    `?user_id=eq.${enc(userId)}` +
    `&ip_address=eq.${enc(ipAddress)}` +
    `&select=id,user_id,ip_address,verified_at_utc,last_used_at_utc,updated_at` +
    `&limit=1`;
  const res = await fetch(url, { headers: sbAuthHeaders(env) });
  if (!res.ok) {
    const t = await res.text().catch(() => '');
    throw new Error(`2FA trust read failed (${res.status}) ${t || ''}`.trim());
  }
  const arr = await res.json().catch(() => []);
  return Array.isArray(arr) && arr[0] ? arr[0] : null;
}

async function sbUpsert2faTrust(env, userId, ipAddress, { verifiedAtIso = null, lastUsedAtIso = null } = {}) {
  const url =
    `${env.SUPABASE_URL}/rest/v1/tms_user_2fa_trust` +
    `?on_conflict=user_id,ip_address`;
  const nowIso = new Date().toISOString();
  const row = {
    user_id: String(userId),
    ip_address: String(ipAddress),
    verified_at_utc: verifiedAtIso || nowIso,
    updated_at: nowIso
  };
  if (lastUsedAtIso) row.last_used_at_utc = String(lastUsedAtIso);

  const res = await fetch(url, {
    method: 'POST',
    headers: { ...sbAuthHeaders(env), Prefer: 'resolution=merge-duplicates,return=minimal' },
    body: JSON.stringify(row)
  });
  if (!res.ok) {
    const t = await res.text().catch(() => '');
    throw new Error(`2FA trust upsert failed (${res.status}) ${t || ''}`.trim());
  }
  return true;
}


// ====================== NEW BACKEND HANDLERS ======================

async function handleAuth2faVerify(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const challengeId = String(body.challenge_id || body.challengeId || '').trim();
  const code = String(body.code || '').trim();

  if (!challengeId) return badRequest('challenge_id_required');
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(challengeId)) {
    return badRequest('invalid_challenge_id');
  }
  if (!/^\d{6}$/.test(code)) return badRequest('invalid_code_format');

  // Load auth policy
  let authEffective = null;
  try {
    const s = await loadSettingsDefaults(env);
    authEffective = (s && s.importConfig && s.importConfig.auth_effective && typeof s.importConfig.auth_effective === 'object')
      ? s.importConfig.auth_effective
      : null;
  } catch { authEffective = null; }

  const tfaMaxAttempts = (authEffective && Number.isFinite(Number(authEffective.tfa_max_attempts)))
    ? Math.max(1, Math.trunc(Number(authEffective.tfa_max_attempts)))
    : 10;

  const idleLogoutSec = (authEffective && Number.isFinite(Number(authEffective.idle_logout_seconds)))
    ? Math.max(60, Math.trunc(Number(authEffective.idle_logout_seconds)))
    : (2 * 60 * 60);

  const idleWarnSec = (() => {
    const v = (authEffective && Number.isFinite(Number(authEffective.idle_warning_seconds)))
      ? Math.max(1, Math.trunc(Number(authEffective.idle_warning_seconds)))
      : (5 * 60);
    return (v >= idleLogoutSec) ? Math.max(1, Math.min(300, idleLogoutSec - 1)) : v;
  })();

  const policy = { idle_logout_seconds: idleLogoutSec, idle_warning_seconds: idleWarnSec };

  const ip = getClientIp(req);
  const ipKey = (ip && String(ip).trim()) ? String(ip).trim() : 'UNKNOWN';

  let ch;
  try {
    ch = await sbGet2faChallengeById(env, challengeId);
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  if (!ch) return badRequest('invalid_challenge');

  // Same IP enforcement
  if (String(ch.ip_address || '').trim() !== ipKey) {
    return unauthorized('Invalid code');
  }

  if (ch.used_at_utc) return badRequest('invalid_or_expired_code');

  const expMs = Date.parse(String(ch.expires_at_utc || ''));
  if (!Number.isFinite(expMs) || expMs < Date.now()) return badRequest('invalid_or_expired_code');

  const attempts = Number(ch.attempt_count ?? 0) || 0;
  if (attempts >= tfaMaxAttempts) return badRequest('max_attempts_exceeded');

  // Verify hash
  let wantHash = '';
  try {
    wantHash = await hash2faCode(ch.code_salt, code);
  } catch (e) {
    return serverError(`2FA hash failed: ${e?.message || e}`);
  }

  const storedHash = String(ch.code_hash || '');
  const match = timingSafeEqualStr(storedHash, wantHash);

  if (!match) {
    // increment attempt_count
    try {
      await sbPatch2faChallengeById(env, challengeId, { attempt_count: attempts + 1 });
    } catch (e) {
      return serverError(e?.message || String(e));
    }
    return unauthorized('Invalid code');
  }

  const nowIso = new Date().toISOString();

  // Mark challenge used
  try {
    await sbPatch2faChallengeById(env, challengeId, { used_at_utc: nowIso });
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  // Upsert trust row (same IP)
  try {
    await sbUpsert2faTrust(env, ch.user_id, ipKey, { verifiedAtIso: nowIso, lastUsedAtIso: nowIso });
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  // Issue tokens + refresh cookie
  const user = await sbGetUserById(env, ch.user_id);
  if (!user || user.is_active !== true) return unauthorized('Unauthorized');

  const sid = bufToBase64Url(crypto.getRandomValues(new Uint8Array(16)));
  const sv = user.session_version | 0 || 1;

  const refresh = await mintRefreshToken(env, { sid, sv });
  const access = await mintAccessToken(env, { user_id: user.id, email: user.email, role: user.role, sv, sid });

  await kvPutSession(env, sid, { user_id: user.id, sv, exp: refresh.exp }, refreshTtl(env));

  const headers = new Headers(JSON_HEADERS);
  setCookie(headers, cookieName(env), refresh.token, {
    maxAgeSec: refreshTtl(env),
    domain: env.COOKIE_DOMAIN || undefined,
    sameSite: pickCookieSameSite(env),
    partitioned: pickCookiePartitioned(env),
    secure: true,
    httpOnly: true,
    path: '/'
  });

  // Best-effort: stamp last_login_at_utc (login complete)
  try {
    const url = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?id=eq.${encodeURIComponent(user.id)}`;
    await fetch(url, {
      method: 'PATCH',
      headers: { ...sbAuthHeaders(env), Prefer: 'return=minimal' },
      body: JSON.stringify({ last_login_at_utc: nowIso, updated_at: nowIso })
    }).catch(() => {});
  } catch {}

  return new Response(JSON.stringify({
    ok: true,
    access_token: access.token,
    expires_in: accessTtl(env),
    user: { id: user.id, email: user.email, role: user.role },
    policy
  }), { status: 200, headers });
}

async function handleAuth2faResend(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const challengeId = String(body.challenge_id || body.challengeId || '').trim();
  if (!challengeId) return badRequest('challenge_id_required');
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(challengeId)) {
    return badRequest('invalid_challenge_id');
  }

  // Load auth policy
  let authEffective = null;
  try {
    const s = await loadSettingsDefaults(env);
    authEffective = (s && s.importConfig && s.importConfig.auth_effective && typeof s.importConfig.auth_effective === 'object')
      ? s.importConfig.auth_effective
      : null;
  } catch { authEffective = null; }

  const tfaCodeTtlSec = (authEffective && Number.isFinite(Number(authEffective.tfa_code_ttl_seconds)))
    ? Math.max(30, Math.trunc(Number(authEffective.tfa_code_ttl_seconds)))
    : 300;

  const resendCooldownSec = (authEffective && Number.isFinite(Number(authEffective.tfa_resend_cooldown_seconds)))
    ? Math.max(0, Math.trunc(Number(authEffective.tfa_resend_cooldown_seconds)))
    : 30;

  const maxResends = (authEffective && Number.isFinite(Number(authEffective.tfa_max_resends)))
    ? Math.max(0, Math.trunc(Number(authEffective.tfa_max_resends)))
    : 5;

  const ip = getClientIp(req);
  const ipKey = (ip && String(ip).trim()) ? String(ip).trim() : 'UNKNOWN';

  let ch;
  try {
    ch = await sbGet2faChallengeById(env, challengeId);
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  if (!ch) return badRequest('invalid_challenge');

  // Same IP enforcement
  if (String(ch.ip_address || '').trim() !== ipKey) {
    return unauthorized('Invalid challenge');
  }

  if (ch.used_at_utc) return badRequest('invalid_challenge');

  const resendCount = Number(ch.resend_count ?? 0) || 0;
  if (resendCount >= maxResends) return badRequest('max_resends_exceeded');

  const lastSentMs = Date.parse(String(ch.last_sent_at_utc || ''));
  if (Number.isFinite(lastSentMs) && resendCooldownSec > 0) {
    const ageSec = (Date.now() - lastSentMs) / 1000;
    if (ageSec < resendCooldownSec) {
      return badRequest('resend_cooldown', { retry_after_seconds: Math.ceil(resendCooldownSec - ageSec) });
    }
  }

  const user = await sbGetUserById(env, ch.user_id);
  if (!user || user.is_active !== true) return badRequest('invalid_challenge');

  const nowIso = new Date().toISOString();
  const expiresAtIso = new Date(Date.now() + (tfaCodeTtlSec * 1000)).toISOString();

  const newCode = genSixDigitCode();
  const newSalt = bufToBase64Url(crypto.getRandomValues(new Uint8Array(16)));
  const newHash = await hash2faCode(newSalt, newCode);

  // Patch challenge with new code, but keep a rollback snapshot
  const rollback = {
    code_salt: ch.code_salt,
    code_hash: ch.code_hash,
    expires_at_utc: ch.expires_at_utc,
    attempt_count: Number(ch.attempt_count ?? 0) || 0,
    resend_count: resendCount,
    last_sent_at_utc: ch.last_sent_at_utc
  };

  try {
    await sbPatch2faChallengeById(env, challengeId, {
      code_salt: newSalt,
      code_hash: newHash,
      expires_at_utc: expiresAtIso,
      attempt_count: 0,
      resend_count: resendCount + 1,
      last_sent_at_utc: nowIso
    });
  } catch (e) {
    return serverError(e?.message || String(e));
  }

  // Resolve replyTo (optional)
  let replyTo = null;
  try {
    const s = await loadSettingsDefaults(env);
    if (s && s.system_email && String(s.system_email).trim()) replyTo = String(s.system_email).trim();
  } catch {}

  const mins = Math.max(1, Math.round(tfaCodeTtlSec / 60));
  const subject = 'CloudTMS sign-in verification code';
  const bodyText =
    `Your CloudTMS verification code is: ${newCode}\n\n` +
    `It expires in ${mins} minute${mins === 1 ? '' : 's'}.\n\n` +
    `If you did not request this code, you can ignore this email.`;

  const htmlBody =
    `<p>Your CloudTMS verification code is:</p>` +
    `<p style="font-size:22px;font-weight:700;letter-spacing:2px;">${newCode}</p>` +
    `<p>This code expires in ${mins} minute${mins === 1 ? '' : 's'}.</p>` +
    `<p>If you did not request this code, you can ignore this email.</p>`;

  const emailPayload = {
    to: String(user.email || '').trim(),
    subject,
    htmlBody,
    body: bodyText,
    attachmentsV2: [],
    metadata: { kind: '2FA_RESEND', user_id: String(user.id), challenge_id: String(challengeId), ip: ipKey, issued_at_utc: nowIso }
  };
  if (replyTo) emailPayload.replyTo = replyTo;

  let pa;
  try {
    pa = await postToPowerAutomate(env, emailPayload, 'system');
  } catch (e) {
    pa = { ok: false, status: 0, body: e?.message || String(e) };
  }

  if (!pa || pa.ok !== true) {
    // Roll back challenge update so user isn't stuck behind cooldown for an email they didn't receive
    try {
      await sbPatch2faChallengeById(env, challengeId, rollback);
    } catch {}
    return serverError(`2FA email send failed (${pa?.status || 0}) ${pa?.body || ''}`.trim());
  }

  return new Response(JSON.stringify({
    ok: true,
    challenge_id: challengeId,
    expires_in: tfaCodeTtlSec,
    resend_cooldown_seconds: resendCooldownSec
  }), { status: 200, headers: JSON_HEADERS });
}
async function sbInsertResetToken(env, user_id, ttlSec) {
  const token = bufToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
  const expires_at = new Date(Date.now() + (ttlSec*1000)).toISOString();
  const url = `${env.SUPABASE_URL}/rest/v1/${AUTH.RESETS_TABLE}`;
  const row = { user_id, token, expires_at, used_at: null };
  const res = await fetch(url, { method:'POST', headers: { ...sbAuthHeaders(env), 'Prefer':'return=representation' }, body: JSON.stringify(row) });
  if (!res.ok) throw new Error(`insert reset token failed ${res.status}`);
  return token;
}
async function sbConsumeResetToken(env, token) {
  const selUrl = `${env.SUPABASE_URL}/rest/v1/${AUTH.RESETS_TABLE}?token=eq.${encodeURIComponent(token)}&select=id,user_id,expires_at,used_at`;
  const r = await fetch(selUrl, { headers: sbAuthHeaders(env) });
  const arr = await r.json().catch(()=>[]);
  const row = Array.isArray(arr) ? arr[0] : null;
  if (!row) return { ok:false, error:'INVALID_OR_EXPIRED_RESET' };
  if (row.used_at) return { ok:false, error:'INVALID_OR_EXPIRED_RESET' };
  if (new Date(row.expires_at).getTime() < Date.now()) return { ok:false, error:'INVALID_OR_EXPIRED_RESET' };
  const updUrl = `${env.SUPABASE_URL}/rest/v1/${AUTH.RESETS_TABLE}?id=eq.${encodeURIComponent(row.id)}`;
  const u = await fetch(updUrl, { method:'PATCH', headers: { ...sbAuthHeaders(env), 'Prefer':'return=representation' }, body: JSON.stringify({ used_at: new Date().toISOString() }) });
  if (!u.ok) return { ok:false, error:'RESET_CONSUME_FAILED' };
  return { ok:true, user_id: row.user_id };
}

// â”€â”€ Access/Refresh tokens (HMAC) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function accessTtl(env){ return parseInt(env.ACCESS_TTL_SECONDS || '900', 10) || 900; }          // 15m
function refreshTtl(env){ return parseInt(env.REFRESH_TTL_SECONDS || '1209600', 10) || 1209600; } // 14d
function resetTtl(env){ return parseInt(env.PASSWORD_RESET_TTL_SECONDS || '3600', 10) || 3600; }   // 60m
function sessionSecret(env){ return String(env.SESSION_TOKEN_SECRET); }

async function mintAccessToken(env, { user_id, email, role, sv, sid }) {
  const exp = Math.floor(Date.now()/1000) + accessTtl(env);
  const payload = { typ:'access', sub:user_id, email, role, sv, sid, iat: Math.floor(Date.now()/1000), exp };
  const token = await createToken(sessionSecret(env), payload);
  return { token, exp };
}
async function mintRefreshToken(env, { sid, sv }) {
  const exp = Math.floor(Date.now()/1000) + refreshTtl(env);
  const payload = { typ:'refresh', sid, sv, iat: Math.floor(Date.now()/1000), exp };
  const token = await createToken(sessionSecret(env), payload);
  return { token, exp };
}

// Bearer access-token guard for /api/* routes
async function requireUser(env, req, allowedRoles = []) {
  const hdr = req.headers.get('authorization') || '';
  const m = hdr.match(/^Bearer\s+(.+)$/i);
  if (!m) return null;

  const ver = await verifyToken(sessionSecret(env), m[1]);
  if (!ver.ok) return null;

  const p = ver.payload || {};
  if (p.typ !== 'access' || !p.sub) return null;

  // Ensure the user still exists, is active, and session_version matches
  const user = await sbGetUserById(env, p.sub);
  if (!user || user.is_active !== true) return null;
  if ((user.session_version|0) !== (p.sv|0)) return null;

  if (Array.isArray(allowedRoles) && allowedRoles.length && !allowedRoles.includes(user.role)) return null;
  return { id: user.id, email: user.email, role: user.role, sv: user.session_version|0, sid: p.sid };
}

// KV session helpers (store sid → { user_id, sv, exp })
async function kvPutSession(env, sid, data, ttlSec) {

  await env.SESSIONS.put(`sid:${sid}`, JSON.stringify(data), { expirationTtl: ttlSec });
}
async function kvGetSession(env, sid) {
  const t = await env.SESSIONS.get(`sid:${sid}`);
  return t ? JSON.parse(t) : null;
}
async function kvDelSession(env, sid) {
  await env.SESSIONS.delete(`sid:${sid}`);
}

// â”€â”€ Auth handlers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

async function handleAuthLogout(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;
  const cookies = parseCookies(req);
  const raw = cookies[cookieName(env)];
  if (raw) {
    const ver = await verifyToken(sessionSecret(env), raw);
    if (ver.ok && ver.payload && ver.payload.sid) {
      await kvDelSession(env, ver.payload.sid);
    }
  }
  const headers = new Headers(JSON_HEADERS);
  setCookie(headers, cookieName(env), '', {
    maxAgeSec: 0,
    domain: env.COOKIE_DOMAIN || undefined,
    sameSite: pickCookieSameSite(env),
    partitioned: pickCookiePartitioned(env),
    secure: true,
    httpOnly: true,
    path: '/'
  });
  return new Response(JSON.stringify({ ok:true }), { status:200, headers });
}

// ---------------------- UK timezone check ----------------------
async function handleUKTimeCheck(env, req) {
  const body = await parseJSONBody(req);
  if (!body) return withCORS(env, req, badRequest('invalid_json'));

  const phone_tz = String(body.phone_tz || '');
  const phone_epoch_ms = Number(body.phone_epoch_ms);
  const tolerance_ms = Math.max(0, Number(env.UK_TZ_SKEW_MS ?? 180000));

  const broker_epoch_ms = Date.now();
  const broker_tz = 'Europe/London';

  const tzOk = phone_tz === broker_tz;
  const skew_ms = Number.isFinite(phone_epoch_ms)
    ? Math.abs(broker_epoch_ms - phone_epoch_ms)
    : NaN;
  const skewOk = Number.isFinite(skew_ms) && skew_ms <= tolerance_ms;

  const valid = tzOk && skewOk;
  const reason = valid
    ? 'ok'
    : (!tzOk ? 'tz_mismatch' : (!Number.isFinite(skew_ms) ? 'invalid_phone_epoch' : 'clock_skew'));

  return withCORS(env, req, ok({
    valid,
    reason,
    tolerance_ms,
    skew_ms,
    broker_epoch_ms,
    broker_tz,
  }));
}

// ---------------------- Query builder for list ----------------------
function buildTimesheetsQuery(env, q) {
  const url = new URL(`${env.SUPABASE_URL}/rest/v1/timesheets`);
  url.searchParams.set("select", "*");

  const add = (k, v) => url.searchParams.set(k, v);

  if (q.booking_id) add("booking_id", `eq.${q.booking_id}`);
  if (q.booking_ids && q.booking_ids.length) add("booking_id", `in.(${q.booking_ids.map(encodeURIComponent).join(",")})`);

  if (q.candidate_id) add("occupant_key_norm", `eq.${q.candidate_id}`);
  if (q.candidate_ids && q.candidate_ids.length) add("occupant_key_norm", `in.(${q.candidate_ids.map(encodeURIComponent).join(",")})`);

  if (q.week_ending) add("week_ending_date", `eq.${q.week_ending}`);
  if (q.week_endings && q.week_endings.length) add("week_ending_date", `in.(${q.week_endings.map(encodeURIComponent).join(",")})`);

  if (q.status) add("status", `eq.${q.status}`);
  if (q.statuses && q.statuses.length) add("status", `in.(${q.statuses.map(encodeURIComponent).join(",")})`);

  if (q.job_title) add("job_title_norm", `eq.${q.job_title}`);
  if (q.job_titles && q.job_titles.length) add("job_title_norm", `in.(${q.job_titles.map(encodeURIComponent).join(",")})`);

  const hospMode = q.hospital_match || "contains";
  if (q.hospital) {
    if (hospMode === "exact") add("hospital_norm", `eq.${q.hospital.toLowerCase()}`);
    else if (hospMode === "prefix") add("hospital_norm", `like.${q.hospital.toLowerCase()}%`);
    else add("hospital_norm", `like.%${q.hospital.toLowerCase()}%`);
  }
  const wardMode = q.ward_match || "contains";
  if (q.ward) {
    if (wardMode === "exact") add("ward_norm", `eq.${q.ward.toLowerCase()}`);
    else if (wardMode === "prefix") add("ward_norm", `like.${q.ward.toLowerCase()}%`);
    else add("ward_norm", `like.%${q.ward.toLowerCase()}%`);
  }

  if (q.version) add("version", `eq.${q.version}`);
  else if (String(q.current_only ?? "true").toLowerCase() !== "false") add("is_current", "eq.true");

  if (q.sort) {
    const col = q.sort;
    const ord = q.order === "asc" ? "asc" : "desc";
    url.searchParams.set("order", `${col}.${ord}`);
  }
  const limit = Math.min(parseInt(q.limit || "50", 10) || 50, 200);
  const offset = parseInt(q.offset || "0", 10) || 0;
  url.searchParams.set("limit", String(limit));
  url.searchParams.set("offset", String(offset));

  return url.toString();
}

// ---------------------- Upload/submit/presign ----------------------
async function handlePresign(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;

  const body = await parseJSONBody(req);
  if (!body) return withCORS(env, req, badRequest("Invalid JSON"));

  const {
    occupant_key: candidate_id,
    date_start_local,  // YYYY-MM-DD (local)
    hospital,
    ward,
    job_title,
    shift_label = "",
    resubmission_of,
  } = body;

  if (!candidate_id || !date_start_local || !hospital || !ward || !job_title) {
    return withCORS(env, req, badRequest("Missing required fields"));
  }

  const booking_id = resubmission_of || await makeBookingId(candidate_id, date_start_local, hospital, ward, job_title, shift_label);
  const week_ending_date = weekEndingSunday(date_start_local);
  const weCompact = week_ending_date.replace(/-/g, "");

  const maxV = await sbMaxVersion(env, booking_id);
  const version = maxV > 0 ? maxV + 1 : 1;

   const nurseKey = `Signatures/we=${weCompact}/${booking_id}/v${version}/nurse.png`;
  const authKey  = `Signatures/we=${weCompact}/${booking_id}/v${version}/authoriser.png`;


  const maxBytes = parseInt(env.UPLOAD_MAX_BYTES || "300000", 10);
  const expiresSec = parseInt(env.PRESIGN_EXPIRES_SECONDS || "600", 10);
  const exp = Math.floor(Date.now() / 1000) + expiresSec;
  const secret = env.UPLOAD_TOKEN_SECRET;

  const nurseToken = await createToken(secret, { typ: "upload", booking_id, version, role: "nurse", key: nurseKey, exp });
  const authToken  = await createToken(secret, { typ: "upload", booking_id, version, role: "authoriser", key: authKey, exp });

  const uploadBase = new URL(req.url);
  uploadBase.pathname = "/upload";
  const mkUrl = (key, token, role) => {
    const u = new URL(uploadBase);
    u.searchParams.set("key", key);
    u.searchParams.set("booking_id", booking_id);
    u.searchParams.set("version", String(version));
    u.searchParams.set("role", role);
    u.searchParams.set("token", token);
    return u.toString();
  };

  return withCORS(env, req, ok({
    booking_id,
    version,
    week_ending_date,
    upload: {
      content_type: "image/png",
      max_bytes: maxBytes,
      expires_at: new Date(exp * 1000).toISOString(),
      nurse: { key: nurseKey, put_url: mkUrl(nurseKey, nurseToken, "nurse"), token: nurseToken },
      authoriser: { key: authKey, put_url: mkUrl(authKey, authToken, "authoriser"), token: authToken },
    },
  }));
}

async function handleUpload(env, req, url) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;

  const key = url.searchParams.get("key") || "";
  const booking_id = url.searchParams.get("booking_id") || "";
  const role = url.searchParams.get("role") || "";
  const token = url.searchParams.get("token") || "";

  const secret = env.UPLOAD_TOKEN_SECRET;
  const ver = await verifyToken(secret, token);
  if (!ver.ok) return withCORS(env, req, unauthorized("Invalid token"));
  const p = ver.payload;
  if (p.typ !== "upload" || p.booking_id !== booking_id || p.role !== role || p.key !== key) {
    return withCORS(env, req, unauthorized("Token mismatch"));
  }

  const keyOk = /^Signatures\/we=\d{8}\/bk_[a-f0-9]{16}(?:\/v\d+)?\/(nurse|authoriser)\.png$/.test(key);
  if (!keyOk) return withCORS(env, req, badRequest("Invalid key"));


  const ct = req.headers.get("content-type") || "";
  if (!isPng(ct)) return withCORS(env, req, unsupported("Only image/png allowed"));

  const maxBytes = parseInt(env.UPLOAD_MAX_BYTES || "300000", 10);
  const contentLength = parseInt(req.headers.get("content-length") || "0", 10);
  if (contentLength > maxBytes) return withCORS(env, req, tooLarge(`Max ${maxBytes} bytes`));

  const requireMd5 = String(env.REQUIRE_MD5 || "false").toLowerCase() === "true";
  const md5 = req.headers.get("content-md5");
  if (requireMd5 && !md5) return withCORS(env, req, badRequest("Content-MD5 required"));

  const we = (key.match(/^Signatures\/we=(\d{8})\//) || [])[1];
  const versionMatch = key.match(/\/v(\d+)\//);
  const version = versionMatch ? parseInt(versionMatch[1], 10) : 1;
  const week_ending_date = we ? `${we.slice(0,4)}-${we.slice(4,6)}-${we.slice(6,8)}` : undefined;

  const putRes = await r2Put(env, key, req.body, {
    httpMetadata: { contentType: "image/png" },
    customMetadata: {
      bookingid: booking_id,
      weekending: week_ending_date || "",
      role,
      version: String(version),
    },
  });
  const size = contentLength || undefined;
  return withCORS(env, req, ok({ ok: true, role, key, etag: putRes?.etag, size, version }));
}

async function handleSummaryMembership(env, req, section) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }

  const trimStr = (v) => String(v == null ? '' : v).trim();
  const clonePlain = (value) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    try {
      return JSON.parse(JSON.stringify(value));
    } catch {
      const out = {};
      Object.keys(value).forEach((key) => {
        out[key] = value[key];
      });
      return out;
    }
  };
  const normalizeValue = (value) => {
    if (value === undefined) return undefined;
    if (value === null) return null;

    if (Array.isArray(value)) {
      const arr = value
        .map(normalizeValue)
        .filter(v => v !== undefined)
        .map(v => (v && typeof v === 'object') ? JSON.parse(JSON.stringify(v)) : v);

      return arr.sort((a, b) => {
        const aa = JSON.stringify(a);
        const bb = JSON.stringify(b);
        if (aa < bb) return -1;
        if (aa > bb) return 1;
        return 0;
      });
    }

    if (value && typeof value === 'object') {
      const out = {};
      Object.keys(value).sort().forEach((key) => {
        const v = normalizeValue(value[key]);
        if (v !== undefined) out[key] = v;
      });
      return out;
    }

    if (typeof value === 'number' && !Number.isFinite(value)) return null;
    return value;
  };
  const normalizeIdArray = (arr) => Array.from(new Set(
    (Array.isArray(arr) ? arr : [])
      .map(v => trimStr(v))
      .filter(Boolean)
  ));
  const buildQueryString = (params) => {
    const usp = new URLSearchParams();
    Object.entries(params || {}).forEach(([key, value]) => {
      if (value == null) return;

      if (Array.isArray(value)) {
        if (key === 'ids') {
          const csv = value.map(v => trimStr(v)).filter(Boolean).join(',');
          if (csv) usp.set(key, csv);
          return;
        }
        value.forEach((vv) => {
          const s = trimStr(vv);
          if (!s) return;
          usp.append(key, s);
        });
        return;
      }

      const s = trimStr(value);
      if (!s) return;
      usp.set(key, s);
    });
    return usp.toString();
  };
  const invokeJsonHandler = async (path, params) => {
    const base = new URL(req.url);
    const qs = buildQueryString(params || {});
    const internalReq = new Request(`${base.origin}${path}${qs ? `?${qs}` : ''}`, {
      method: 'GET',
      headers: req.headers
    });

    let resp = null;
    if (path === '/api/search/candidates') resp = await handleSearchCandidates(env, internalReq);
    else if (path === '/api/search/clients') resp = await handleSearchClients(env, internalReq);
    else if (path === '/api/search/umbrellas') resp = await handleSearchUmbrellas(env, internalReq);
    else if (path === '/api/contracts') resp = await handleContractsList(env, internalReq);
    else if (path === '/api/timesheets/summary') resp = await handleTimesheetsSummary(env, internalReq);
    else if (path === '/api/invoices') resp = await handleListInvoices(env, internalReq);
    else throw new Error(`Unsupported summary membership path: ${path}`);

    let payload = null;
    try { payload = await resp.clone().json(); } catch { payload = null; }

    if (!resp.ok) {
      const msg =
        (payload && typeof payload === 'object' && (payload.error || payload.message))
          ? String(payload.error || payload.message)
          : `Internal handler failed (${resp.status})`;
      throw new Error(msg);
    }

    if (payload && typeof payload === 'object' && !Array.isArray(payload) && (payload.error || payload.message)) {
      throw new Error(String(payload.error || payload.message));
    }

    return payload;
  };

  const allowedSections = new Set(['candidates', 'clients', 'umbrellas', 'contracts', 'timesheets', 'invoices']);
  const rawSection =
    trimStr(section) ||
    trimStr(body && (body.section || body.entity || body.context_kind)) ||
    (() => {
      try {
        const parts = new URL(req.url).pathname.split('/').filter(Boolean);
        return trimStr(parts[parts.length - 1]);
      } catch {
        return '';
      }
    })();

  const sectionKey = rawSection.toLowerCase();
  if (!allowedSections.has(sectionKey)) {
    return withCORS(env, req, badRequest('invalid_section'));
  }

  const rawFilters = clonePlain(
    (body && body.effective_filters && typeof body.effective_filters === 'object' && !Array.isArray(body.effective_filters))
      ? body.effective_filters
      : ((body && body.filters && typeof body.filters === 'object' && !Array.isArray(body.filters))
          ? body.filters
          : {})
  );

  let effectiveFilters = clonePlain(rawFilters);
  if (sectionKey === 'candidates') effectiveFilters = buildCandidateSummaryFilterSpec(rawFilters);
  if (sectionKey === 'clients') effectiveFilters = buildClientSummaryFilterSpec(rawFilters);
  if (sectionKey === 'umbrellas') effectiveFilters = buildUmbrellaSummaryFilterSpec(rawFilters);
  if (sectionKey === 'contracts') effectiveFilters = buildContractSummaryFilterSpec(rawFilters);
  if (sectionKey === 'timesheets') effectiveFilters = buildTimesheetSummaryFilterSpec(rawFilters);
  if (sectionKey === 'invoices') effectiveFilters = buildInvoiceSummaryFilterSpec(rawFilters);

  if (Object.prototype.hasOwnProperty.call(effectiveFilters, 'ids')) {
    effectiveFilters.ids = normalizeIdArray(effectiveFilters.ids);
    if (!effectiveFilters.ids.length) delete effectiveFilters.ids;
  }

  const truthy = (value) => {
    if (value === true) return true;
    if (value === false || value == null) return false;
    const s = trimStr(value).toLowerCase();
    return ['1', 'true', 'yes', 'y', 'on', 'ids', 'full', 'full_ids'].includes(s);
  };

  const membershipMode = trimStr(
    (body && (body.membership_mode || body.membershipMode || body.mode)) ||
    rawFilters.membership_mode ||
    rawFilters.membershipMode ||
    effectiveFilters.membership_mode ||
    effectiveFilters.membershipMode ||
    ''
  ).toLowerCase();

  const explicitFullMembership = !!(
    truthy(body && (body.include_ids || body.includeIds)) ||
    truthy(body && (body.explicit_full_membership || body.explicitFullMembership)) ||
    truthy(body && (body.force_full_membership || body.forceFullMembership)) ||
    truthy(rawFilters.include_ids || rawFilters.includeIds) ||
    truthy(rawFilters.explicit_full_membership || rawFilters.explicitFullMembership) ||
    truthy(rawFilters.force_full_membership || rawFilters.forceFullMembership) ||
    truthy(effectiveFilters.include_ids || effectiveFilters.includeIds) ||
    truthy(effectiveFilters.explicit_full_membership || effectiveFilters.explicitFullMembership) ||
    truthy(effectiveFilters.force_full_membership || effectiveFilters.forceFullMembership) ||
    ['ids', 'full', 'full_ids', 'membership_ids'].includes(membershipMode)
  );

  const payBatchIdForTimesheets = sectionKey === 'timesheets'
    ? trimStr(
        effectiveFilters.pay_batch_id ||
        effectiveFilters.payBatchId ||
        effectiveFilters.batch_id ||
        effectiveFilters.batchId ||
        ''
      )
    : '';

  const datasetKey = JSON.stringify({
    section: sectionKey,
    filters: normalizeValue(effectiveFilters) || {}
  });

  try {
    if (sectionKey === 'candidates') {
      const rpcRows = await sbRpcAllRows(env, 'candidate_list_ids', {
        p_filters: clonePlain(effectiveFilters)
      }, {
        pageSize: 1000
      });

      const rowIds = normalizeIdArray(
        (Array.isArray(rpcRows) ? rpcRows : [])
          .map((row) => {
            if (row && typeof row === 'object') return row.id ?? row.candidate_id ?? '';
            return row == null ? '' : row;
          })
      );

      const totalCount = rowIds.length;

      return withCORS(env, req, ok({
        section: sectionKey,
        dataset_key: datasetKey,
        row_ids: rowIds,
        ids: rowIds.slice(),
        total_count: totalCount,
        total: totalCount
      }));
    }

    const pathMap = {
      candidates: '/api/search/candidates',
      clients: '/api/search/clients',
      umbrellas: '/api/search/umbrellas',
      contracts: '/api/contracts',
      timesheets: '/api/timesheets/summary',
      invoices: '/api/invoices'
    };

    const membershipParams = {
      ...clonePlain(effectiveFilters),
      format: 'membership'
    };

    if (sectionKey === 'timesheets' && payBatchIdForTimesheets) {
      membershipParams.include_ids = explicitFullMembership ? 'true' : 'false';
      membershipParams.includeIds = explicitFullMembership ? 'true' : 'false';
      membershipParams.membership_mode = explicitFullMembership ? 'ids' : 'deferred';
      membershipParams.explicit_full_membership = explicitFullMembership ? 'true' : 'false';
    }

    const payload = await invokeJsonHandler(pathMap[sectionKey], membershipParams);

    const payloadDeferred = !!(
      sectionKey === 'timesheets' &&
      payBatchIdForTimesheets &&
      !explicitFullMembership &&
      payload &&
      typeof payload === 'object' &&
      !Array.isArray(payload) &&
      (
        payload.membership_deferred === true ||
        payload.deferred === true ||
        payload.ids_deferred === true
      )
    );

    const rowIds = payloadDeferred
      ? []
      : normalizeIdArray(
          Array.isArray(payload && payload.row_ids)
            ? payload.row_ids
            : (Array.isArray(payload && payload.ids) ? payload.ids : [])
        );

    const countRaw = Number(payload && (payload.total_count ?? payload.total ?? payload.count ?? rowIds.length));
    const totalCount = Number.isFinite(countRaw) ? countRaw : rowIds.length;

    return withCORS(env, req, ok({
      section: sectionKey,
      dataset_key: datasetKey,
      row_ids: rowIds,
      ids: rowIds.slice(),
      total_count: totalCount,
      total: totalCount,
      count: totalCount,
      membership_deferred: payloadDeferred,
      deferred: payloadDeferred,
      ids_deferred: payloadDeferred
    }));
  } catch (e) {
    return withCORS(env, req, serverError(String(e?.message || e || 'SUMMARY_MEMBERSHIP_FAILED')));
  }
}

async function handleSubmit(env, req) {
  const pre = preflightIfNeeded(env, req);
  if (pre) return pre;

  const body = await parseJSONBody(req);
  if (!body) return withCORS(env, req, badRequest("Invalid JSON"));

  const required = [
    "booking_id", "scheduled_start_iso", "scheduled_end_iso",
    "worked_start_iso", "worked_end_iso",
    "break_start_iso", "break_end_iso",
    "auth_name", "auth_job_title", "nurse_key", "authoriser_key", "idempotency_key"
  ];
  for (const k of required) if (!body[k]) return withCORS(env, req, badRequest(`Missing ${k}`));

  if (!isEligibleWindow(body.worked_end_iso)) {
    return withCORS(env, req, new Response(JSON.stringify({
      error: "Shift not in eligible window (must be ongoing or ended ≤ 4h)",
      code: "INELIGIBLE"
    }), { status: 422, headers: JSON_HEADERS }));
  }

  const nurseHead = await r2Head(env, body.nurse_key);
  const authHead  = await r2Head(env, body.authoriser_key);
  if (!nurseHead || !authHead) return withCORS(env, req, badRequest("Signatures not uploaded"));
  let nurseSha256;
  let authoriserSha256;
  try {
    [nurseSha256, authoriserSha256] = await Promise.all([
      r2ObjectSha256Hex(env, body.nurse_key),
      r2ObjectSha256Hex(env, body.authoriser_key)
    ]);
  } catch {
    return withCORS(env, req, badRequest('Signatures could not be verified'));
  }

  const worked_date_local = londonDate(body.worked_start_iso);
  const week_ending_date  = weekEndingSunday(worked_date_local);
  const break_minutes     = minutesBetween(body.break_start_iso, body.break_end_iso);
  const worked_minutes    = minutesBetween(body.worked_start_iso, body.worked_end_iso);
  const break_expected    = parseInt(env.BREAK_EXPECTED_MINUTES || "60", 10);

  let version = parseInt(body.version || "0", 10);
  if (!version || Number.isNaN(version)) {
    const m = body.nurse_key.match(/\/v(\d+)\//) || body.authoriser_key.match(/\/v(\d+)\//);
    version = m ? parseInt(m[1], 10) : 1;
  }

  const current = await sbGetTimesheetCurrent(env, body.booking_id);
  if (current && current.is_current === true) {
    const maxV = await sbMaxVersion(env, body.booking_id);
    if (maxV >= 1) {
      return withCORS(env, req, conflict("A current timesheet exists for this booking. Revoke before resubmitting."));
    }
  }

  const authorised_at_server = new Date().toISOString();

  const row = {
    booking_id: body.booking_id,
    version,
    is_current: true,

    // ✅ Explicitly classify this as DAILY + ELECTRONIC (so admin UI + routes behave correctly)
    sheet_scope: "DAILY",
    submission_mode: "ELECTRONIC",

    occupant_key_norm: (body.candidate_id || body.occupant_key || "").toLowerCase(),
    hospital_norm: (body.hospital || "").toLowerCase(),
    ward_norm: (body.ward || "").toLowerCase(),
    job_title_norm: (body.job_title || "").toLowerCase(),
    shift_label_norm: (body.shift_label || "").toLowerCase() || null,

    scheduled_start_iso: body.scheduled_start_iso,
    scheduled_end_iso: body.scheduled_end_iso,
    worked_start_iso: body.worked_start_iso,
    worked_end_iso: body.worked_end_iso,
    break_start_iso: body.break_start_iso,
    break_end_iso: body.break_end_iso,
    break_minutes,
    worked_minutes,

    week_ending_date,

    auth_name: body.auth_name,
    auth_job_title: body.auth_job_title,
    authorised_at_server,

    r2_nurse_key: body.nurse_key,
    r2_auth_key: body.authoriser_key,
    img_sha256_nurse: nurseSha256,
    img_sha256_auth: authoriserSha256,

    // ✅ MUST match timesheet_status_enum (no "SUBMITTED" in your DB enum)
    status: "RECEIVED",

    idempotency_key: body.idempotency_key,
    client_hash: body.client_hash || null,
    client_ua: body.client_user_agent || req.headers.get("user-agent") || "",

    // ✅ Keep NOT NULL safe + avoid default QR “PENDING” making it look like QR
    qr_payload_json: {},
    qr_status: null,
    qr_token: null,
    qr_generated_at: null,
    qr_scanned_at: null,
    qr_scan_info_json: null,
    qr_r2_key: null
  };

  let ts;
  try {
    ts = await sbUpsertTimesheet(env, row);
  } catch (e) {
    return withCORS(env, req, serverError(`DB upsert failed: ${e.message}`));
  }

  const ts_id = ts?.timesheet_id || null;

  // ─────────────────────────────────────────────────────────────
  // ✅ TIMESHEET TAB AUDIT (minimal + meaningful)
  // Action: TIMESHEET_CREATED (source: daily electronic submit)
  // ─────────────────────────────────────────────────────────────
  try {
    // Actor is not a tms_user here (public submit), so label as mobile submitter.
    const auditActor = {
      id: null,
      display_name: (body.occupant_key || body.candidate_id || "Mobile submit"),
      email: null,
      role: "mobile"
    };

    if (ts_id) {
      await writeAudit(
        env,
        auditActor,
        "TIMESHEET_CREATED",
        {
          source: "DAILY_ELECTRONIC_SUBMIT",
          timesheet_id: ts_id,
          booking_id: body.booking_id,
          sheet_scope: "DAILY",
          submission_mode: "ELECTRONIC",
          version,
          week_ending_date,
          worked_start_iso: body.worked_start_iso,
          worked_end_iso: body.worked_end_iso,
          break_minutes,
          authorised_at_server,
          idempotency_key: body.idempotency_key
        },
        {
          entity: "timesheets",
          subject_id: ts_id,
          correlation_id: body.idempotency_key,
          req
        }
      );
    }
  } catch {
    // best-effort
  }

  return withCORS(env, req, ok({
    ok: true,
    timesheet_id: ts_id,
    status: "RECEIVED",
    break_ok: break_minutes === break_expected,
    version
  }));
}

// ---------------------- Revoke flows ----------------------
async function handleRevoke(env, req) {
  const body = await parseJSONBody(req);
  if (!body) return badRequest("Invalid JSON");
  const { booking_id, reason = null, actor = "candidate" } = body;
  if (!booking_id) return badRequest("booking_id required");

  const current = await sbGetTimesheetCurrent(env, booking_id);
  if (!current) return notFound("No current timesheet to revoke");

  const url = `${env.SUPABASE_URL}/rest/v1/timesheets?booking_id=eq.${encodeURIComponent(booking_id)}&is_current=eq.true`;
  const patch = {
    is_current: false,
    status: "REVOKED",
    revoked_at: new Date().toISOString(),
    revoked_reason: reason,
    revoked_by: actor,
  };
  const res = await fetch(url, {
    method: "PATCH",
    headers: { ...sbHeaders(env), "Prefer": "return=representation" },
    body: JSON.stringify(patch),
  });
  if (!res.ok) {
    const t = await res.text().catch(() => "");
    return serverError(`Revoke failed: ${res.status} ${t}`);
  }
  const json = await res.json().catch(() => []);
  const revoked = Array.isArray(json) ? json[0] : json;

  const next_version = (await sbMaxVersion(env, booking_id)) + 1;
  return ok({ ok: true, booking_id, current_revoked: true, timesheet_id: revoked?.timesheet_id || null, next_version });
}

async function handleRevokeAndPresign(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;
  const body = await parseJSONBody(req);
  if (!body) return withCORS(env, req, badRequest("Invalid JSON"));
  const { booking_id, reason = null, actor = "candidate" } = body;
  if (!booking_id) return withCORS(env, req, badRequest("booking_id required"));

  const current = await sbGetTimesheetCurrent(env, booking_id);
  if (!current) return withCORS(env, req, notFound("No current timesheet to revoke"));

  const url = `${env.SUPABASE_URL}/rest/v1/timesheets?booking_id=eq.${encodeURIComponent(booking_id)}&is_current=eq.true`;
  const patch = { is_current: false, status: "REVOKED", revoked_at: new Date().toISOString(), revoked_reason: reason, revoked_by: actor };
  const res = await fetch(url, { method: "PATCH", headers: { ...sbHeaders(env), "Prefer": "return=representation" }, body: JSON.stringify(patch) });
  if (!res.ok) {
    const t = await res.text().catch(() => "");
    return withCORS(env, req, serverError(`Revoke failed: ${res.status} ${t}`));
  }

  const next_version = (await sbMaxVersion(env, booking_id)) + 1;
  const week_ending_date = current.week_ending_date;
  const weCompact = week_ending_date.replace(/-/g, "");
   const nurseKey = `Signatures/we=${weCompact}/${booking_id}/v${next_version}/nurse.png`;
  const authKey  = `Signatures/we=${weCompact}/${booking_id}/v${next_version}/authoriser.png`;


  const maxBytes = parseInt(env.UPLOAD_MAX_BYTES || "300000", 10);
  const expiresSec = parseInt(env.PRESIGN_EXPIRES_SECONDS || "600", 10);
  const exp = Math.floor(Date.now() / 1000) + expiresSec;
  const secret = env.UPLOAD_TOKEN_SECRET;
  const nurseToken = await createToken(secret, { typ: "upload", booking_id, version: next_version, role: "nurse", key: nurseKey, exp });
  const authToken  = await createToken(secret, { typ: "upload", booking_id, version: next_version, role: "authoriser", key: authKey, exp });

  const base = new URL(req.url); base.pathname = "/upload";
  const mkUrl = (key, token, role) => {
    const u = new URL(base);
    u.searchParams.set("key", key);
    u.searchParams.set("booking_id", booking_id);
    u.searchParams.set("version", String(next_version));
    u.searchParams.set("role", role);
    u.searchParams.set("token", token);
    return u.toString();
  };

  return withCORS(env, req, ok({
    ok: true,
    booking_id,
    version: next_version,
    week_ending_date,
    upload: {
      content_type: "image/png",
      max_bytes: maxBytes,
      expires_at: new Date(exp * 1000).toISOString(),
      nurse: { key: nurseKey, put_url: mkUrl(nurseKey, nurseToken, "nurse"), token: nurseToken },
      authoriser: { key: authKey, put_url: mkUrl(authKey, authToken, "authoriser"), token: authToken },
    },
  }));
}

// ---------------------- Reads ----------------------
async function handleGetOne(env, req, booking_id, url) {
  const version = url.searchParams.get("version");
  const currentOnly = String(url.searchParams.get("current_only") ?? "true").toLowerCase() !== "false";

  let row = null;
  if (version) row = await sbGetTimesheetByVersion(env, booking_id, parseInt(version, 10));
  else if (currentOnly) row = await sbGetTimesheetCurrent(env, booking_id);
  else {
    const u = `${env.SUPABASE_URL}/rest/v1/timesheets?booking_id=eq.${encodeURIComponent(booking_id)}&select=*&order=version.desc&limit=10`;
    const { rows } = await sbFetch(env, u);
    row = rows;
  }
  if (!row || (Array.isArray(row) && !row.length)) return withCORS(env, req, notFound("Timesheet not found"));
  return withCORS(env, req, ok(row));
}

// ─────────────────────────────────────────────────────────────────────────────
// Timesheets: list with optional sign keys/urls
// ─────────────────────────────────────────────────────────────────────────────
async function handleList(env, req, url) {
  // Admin-only (exposes keys/URLs when requested)
  const user = await requireUser(env, req, ["admin"]);
  if (!user) return withCORS(env, req, unauthorized());

  const q = Object.fromEntries(url.searchParams.entries());
  const sbUrl = buildTimesheetsQuery(env, q);

  const includeCount = String(q.include_count ?? "false").toLowerCase() === "true";
  const { rows, total } = await sbFetch(env, sbUrl, includeCount);

  const include = new Set(String(q.include || "").split(",").map(s => s.trim()).filter(Boolean));
  const sign_which = String(q.sign_which || "both").toLowerCase();

  // Clamp expiry: 60s–900s, default 180s
  const expReq = parseInt(q.sign_expires_seconds || "180", 10);
  const sign_exp = Math.max(60, Math.min(Number.isFinite(expReq) ? expReq : 180, 900));

  const secret = env.UPLOAD_TOKEN_SECRET;
  if (!secret && include.has("sign_urls")) {
    return withCORS(env, req, serverError("UPLOAD_TOKEN_SECRET not configured"));
  }

  const items = await Promise.all(
    rows.map(async (r) => {
      const have = { nurse: !!r.r2_nurse_key, authoriser: !!r.r2_auth_key };
      const out = { ...r, signatures: { have } };

      if (include.has("sign_keys")) {
        out.signatures.keys = {
          nurse: r.r2_nurse_key || null,
          authoriser: r.r2_auth_key || null
        };
      }

      if (include.has("sign_urls")) {
        const addUrl = async (which, key) => {
          if (!key) return null;
          const exp = Math.floor(Date.now() / 1000) + sign_exp;
          const token = await createToken(secret, {
            typ: "dl",
            booking_id: r.booking_id,
            role: which,
            key,
            exp,
          });
          const u = new URL(req.url);
          u.pathname = "/signatures/get";
          u.search = "";
          u.searchParams.set("key", key);
          u.searchParams.set("booking_id", r.booking_id);
          u.searchParams.set("role", which);
          u.searchParams.set("token", token);
          return u.toString();
        };

        const urls = {};
        if (sign_which === "both" || sign_which === "nurse") {
          urls.nurse = await addUrl("nurse", r.r2_nurse_key);
        }
        if (sign_which === "both" || sign_which === "authoriser") {
          urls.authoriser = await addUrl("authoriser", r.r2_auth_key);
        }
        out.signatures.urls = urls;
      }

      return out;
    })
  );

  const resp = includeCount ? { items, count: total ?? undefined } : { items };
  return withCORS(env, req, ok(resp));
}

async function handleQuery(env, req) {
  const body = await parseJSONBody(req);
  if (!body) return badRequest("Invalid JSON");
  const q = { ...body };
  if (Array.isArray(q.booking_ids) && q.booking_ids.length > 0) q.booking_ids = q.booking_ids.slice(0, 500);
  const sbUrl = buildTimesheetsQuery(env, q);
  const { rows } = await sbFetch(env, sbUrl, !!q.include_count);
  return ok({ items: rows });
}

async function handleAuthorisedStatus(env, req) {
  const body = await parseJSONBody(req);
  if (!body || !Array.isArray(body.booking_ids) || !body.booking_ids.length) return badRequest("booking_ids array required");
  const ids = body.booking_ids.slice(0, 1000);
  const url = `${env.SUPABASE_URL}/rest/v1/timesheets?booking_id=in.(${ids.map(encodeURIComponent).join(",")})&select=booking_id,authorised_at_server`;
  const { rows } = await sbFetch(env, url);
  const map = {};
  for (const r of rows) map[r.booking_id] = !!r.authorised_at_server;
  for (const id of ids) if (!(id in map)) map[id] = false;
  return ok({ statuses: map });
}

// ---------------------- Signatures: presign GET + proxy GET ----------------------
async function handleSignPresignGet(env, req) {
  try {
    const body = await parseJSONBody(req);
    if (!body) return withCORS(env, req, badRequest("Invalid JSON"));

    const {
      booking_id,
      which = "nurse",
      version = null,
      expires_seconds = 180
    } = body;

    if (!booking_id || !["nurse", "authoriser"].includes(which)) {
      return withCORS(env, req, badRequest("booking_id and which required"));
    }

    const row = version
      ? await sbGetTimesheetByVersion(env, booking_id, parseInt(version, 10))
      : await sbGetTimesheetCurrent(env, booking_id);

    if (!row) return withCORS(env, req, notFound("Timesheet not found"));

    const keyRaw = (which === "nurse" ? row.r2_nurse_key : row.r2_auth_key);
    if (!keyRaw) return withCORS(env, req, notFound("Signature not found"));

    // ✅ IMPORTANT: normalise leading slash
    const key = String(keyRaw).trim().replace(/^\/+/, "");
    if (!key) return withCORS(env, req, notFound("Signature not found"));

    const exp = Math.min(parseInt(expires_seconds, 10) || 180, 900);
    const tokenExp = Math.floor(Date.now() / 1000) + exp;

    const secret = env.UPLOAD_TOKEN_SECRET;
    const token = await createToken(secret, {
      typ: "dl",
      booking_id,
      role: which,
      key,
      exp: tokenExp
    });

    const u = new URL(req.url);
    u.pathname = "/signatures/get";
    u.search = "";
    u.searchParams.set("key", key);
    u.searchParams.set("booking_id", booking_id);
    u.searchParams.set("role", which);
    u.searchParams.set("token", token);

    return withCORS(env, req, ok({
      booking_id,
      which,
      get_url: u.toString(),
      expires_at: new Date(tokenExp * 1000).toISOString()
    }));
  } catch (e) {
    // ensure errors still return CORS
    return withCORS(env, req, serverError(e?.message || "Failed to presign signature"));
  }
}
async function handleSignPresignGetBatch(env, req) {
  try {
    const body = await parseJSONBody(req);
    if (!body || !Array.isArray(body.items) || !body.items.length) {
      return withCORS(env, req, badRequest("items array required"));
    }

    const items = body.items.slice(0, 100);
    const exp = Math.min(parseInt(body.expires_seconds || "300", 10) || 300, 900);
    const secret = env.UPLOAD_TOKEN_SECRET;

    const out = [];
    const not_found = [];

    for (const it of items) {
      const booking_id = it?.booking_id;
      const which = it?.which || "nurse";
      const version = it?.version != null ? parseInt(it.version, 10) : null;

      if (!booking_id || !["nurse", "authoriser"].includes(which)) continue;

      const row = (Number.isFinite(version) && version != null)
        ? await sbGetTimesheetByVersion(env, booking_id, version)
        : await sbGetTimesheetCurrent(env, booking_id);

      if (!row) { not_found.push(booking_id); continue; }

      const keyRaw = (which === "nurse" ? row.r2_nurse_key : row.r2_auth_key);
      if (!keyRaw) { not_found.push(booking_id); continue; }

      // ✅ IMPORTANT: normalise leading slash (R2 keys must not start with "/")
      const key = String(keyRaw).trim().replace(/^\/+/, "");
      if (!key) { not_found.push(booking_id); continue; }

      const tokenExp = Math.floor(Date.now() / 1000) + exp;
      const token = await createToken(secret, { typ: "dl", booking_id, role: which, key, exp: tokenExp });

      const u = new URL(req.url);
      u.pathname = "/signatures/get";
      u.search = "";
      u.searchParams.set("key", key);
      u.searchParams.set("booking_id", booking_id);
      u.searchParams.set("role", which);
      u.searchParams.set("token", token);

      out.push({
        booking_id,
        which,
        version: row.version,
        get_url: u.toString(),
        expires_at: new Date(tokenExp * 1000).toISOString()
      });
    }

    return withCORS(env, req, ok({ links: out, not_found }));
  } catch (e) {
    return withCORS(env, req, serverError(e?.message || "Failed to presign signature batch"));
  }
}


// ====================== CLIENTS ======================
/**
 * @openapi
 * /api/clients:
 *   get:
 *     summary: List clients
 *     tags: [Clients]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: query
 *         name: include_count
 *         schema: { type: boolean }
 *       - in: query
 *         name: limit
 *         schema: { type: integer, minimum: 1, maximum: 200 }
 *       - in: query
 *         name: offset
 *         schema: { type: integer, minimum: 0 }
 *     responses:
 *       200:
 *         description: List of clients
 *   post:
 *     summary: Create client
 *     tags: [Clients]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *     responses:
 *       200:
 *         description: Created client
 */
async function handleListClients(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const params = new URL(req.url).searchParams;
  const includeCount = params.get('include_count') === 'true';

  // Support page/page_size and legacy limit/offset
  const pageRaw      = parseInt(params.get('page') || '1', 10);
  const pageSizeRaw  = params.get('page_size');
  const legacyLimit  = parseInt(params.get('limit')  || '50', 10);
  const legacyOffset = parseInt(params.get('offset') || '0',  10);

  const page     = Math.max(1, isNaN(pageRaw) ? 1 : pageRaw);
  const pageSize = pageSizeRaw != null ? Math.max(1, Math.min(200, parseInt(pageSizeRaw, 10) || 50)) : null;
  const limit    = pageSize != null ? pageSize : Math.max(1, Math.min(200, isNaN(legacyLimit) ? 50 : legacyLimit));
  const offset   = pageSize != null ? (page - 1) * limit : Math.max(0, isNaN(legacyOffset) ? 0 : legacyOffset);

  const url = new URL(`${env.SUPABASE_URL}/rest/v1/clients`);
  url.searchParams.set('select', '*');      // include all columns (e.g., ts_queries_email)
  url.searchParams.set('order',  'name.asc');
  url.searchParams.set('limit',  String(limit));
  url.searchParams.set('offset', String(offset));

  try {
    const { rows, total } = await sbFetch(env, url.toString(), includeCount);
    const resp = includeCount ? { items: rows, count: total ?? undefined } : { items: rows };
    return withCORS(env, req, ok(resp));
  } catch {
    return withCORS(env, req, serverError('Failed to list clients'));
  }
}

/**
 * @openapi
 * /api/rates/candidate-overrides/overlap-exists:
 *   get:
 *     summary: Check if any candidate override overlaps a client rate window
 *     tags: [Rates]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: query
 *         name: client_id
 *         required: true
 *         schema: { type: string, format: uuid }
 *       - in: query
 *         name: role
 *         required: true
 *         schema: { type: string }
 *       - in: query
 *         name: band
 *         required: false
 *         schema:
 *           type: string
 *           nullable: true
 *         description: Use empty string to match NULL band
 *       - in: query
 *         name: from
 *         required: true
 *         schema: { type: string, format: date }
 *         description: Client window date_from (YYYY-MM-DD)
 *       - in: query
 *         name: to
 *         required: false
 *         schema: { type: string, format: date, nullable: true }
 *         description: Client window date_to (YYYY-MM-DD). Omit for open-ended.
 *       - in: query
 *         name: exclude_id
 *         required: false
 *         schema: { type: string, format: uuid }
 *         description: Override id to exclude (useful when editing an existing override)
 *     responses:
 *       200:
 *         description: Overlap summary
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 exists: { type: boolean }
 *                 count:  { type: integer }
 *                 sample_id: { type: string, nullable: true }
 */

 async function handleCandidateOverrideOverlapExists(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const urlObj   = new URL(req.url);
  const enc      = (s) => encodeURIComponent(String(s ?? ''));
  const clientId = urlObj.searchParams.get('client_id');
  const role     = urlObj.searchParams.get('role');
  const bandRaw  = urlObj.searchParams.get('band');       // '' (empty) means NULL band
  const from     = urlObj.searchParams.get('from');       // YYYY-MM-DD
  const to       = urlObj.searchParams.get('to');         // YYYY-MM-DD or null
  const exclude  = urlObj.searchParams.get('exclude_id'); // optional

  if (!clientId || !role || !from) {
    return withCORS(env, req, badRequest('client_id, role and from are required'));
  }

  // Open-ended end bound if not supplied (use a far-future date to simplify filters)
  const toEff = to || '9999-12-31';

  // Build PostgREST query over rates_candidate_overrides with overlap logic:
  // Overlap iff (override.date_from <= toEff) AND (override.date_to IS NULL OR override.date_to >= from)
  // Match same (client_id, role, band|NULL). We don’t filter by rate_type — both PAYE/UMBRELLA are relevant.
  let q =
    `${env.SUPABASE_URL}/rest/v1/rates_candidate_overrides` +
    `?select=id` +
    `&client_id=eq.${enc(clientId)}` +
    `&role=eq.${enc(role)}` +
    `&date_from=lte.${enc(toEff)}` +
    `&or=(date_to.is.null,date_to.gte.${enc(from)})` +
    `&limit=1`; // fast existence check

  if (bandRaw === '' || String(bandRaw).toLowerCase() === 'null') {
    q += `&band=is.null`;
  } else if (bandRaw != null) {
    q += `&band=eq.${enc(bandRaw)}`;
  } else {
    // no band param -> accept both NULL and non-NULL? For client windows we normally know band; if truly unknown, omit.
  }

  if (exclude) {
    q += `&id=neq.${enc(exclude)}`;
  }

  // Ask sbFetch for total via Content-Range by passing includeCount=true
  const { rows, total } = await sbFetch(env, q, true);
  const exists = (typeof total === 'number' ? total : (rows?.length || 0)) > 0;

  return withCORS(env, req, ok({
    exists,
    count: typeof total === 'number' ? total : (rows?.length || 0),
    sample_id: rows?.[0]?.id || null
  }));
}


async function handleGetClient(env, req, clientId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const enc = encodeURIComponent;

  try {
    // Client (explicit select=* so ts_queries_email etc always present)
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/clients?id=eq.${enc(clientId)}&select=*&limit=1`
    );
    if (!rows.length) return withCORS(env, req, notFound("Client not found"));
    const client = rows[0];

    // Latest client_settings
    const { rows: csRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/client_settings` +
      `?client_id=eq.${enc(clientId)}` +
      `&select=` +
        [
          'id','client_id',
          'vat_rate_pct','holiday_pay_pct','erni_pct',
          'apply_holiday_to','apply_erni_to','margin_includes',
          'effective_from',
          'timezone_id',
          'day_start','day_end','night_start','night_end','sat_start','sat_end','sun_start','sun_end','bh_start','bh_end',
          'bh_source','bh_list','bh_feed_url',
          'hr_validation_required',
          'ts_reference_required','pay_reference_required','invoice_reference_required',
          'default_submission_mode',
          'week_ending_weekday',
          'is_nhsp','self_bill_no_invoices_sent','daily_calc_of_invoices',
          'no_timesheet_required','group_nightsat_sunbh',
          'auto_invoice_default',
          'requires_hr','autoprocess_hr','hr_attach_to_invoice','ts_attach_to_invoice',

          // ✅ NEW: client comms opt-ins (DB-backed)
          'opt_in_email','opt_in_sms','opt_in_whatsapp',

          // invoicing settings required by UI
          'invoice_consolidation_mode',
          'reference_number_required_to_issue_invoice',

          // manual adjustment email routing
          'send_manual_invoices_to_different_email',
          'manual_invoices_alt_email_address',

          // Import-authoritative correction financial-date policy overrides
          'reversal_complete_financials_date',
          'reversal_replacement_financials_date',

          'created_at','updated_at'
        ].join(',') +
      `&order=effective_from.desc,created_at.desc&limit=1`
    );

    const client_settings = csRows?.[0] || null;
    let import_financial_policy = null;
    try {
      const { rows: defaultsRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/settings_defaults?id=eq.1&select=reversal_complete_financials_date,reversal_replacement_financials_date,updated_at&limit=1`
      );
      const defaults = defaultsRows?.[0] || {};
      const eligible = client_settings?.is_nhsp === true
        || (client_settings?.autoprocess_hr === true && client_settings?.no_timesheet_required === true);
      import_financial_policy = {
        eligible,
        client_settings_updated_at: client_settings?.updated_at || null,
        client_rev: client.rev ?? null,
        reversal_complete_financials_date: {
          override: eligible ? (client_settings?.reversal_complete_financials_date ?? null) : null,
          effective: eligible
            ? (client_settings?.reversal_complete_financials_date ?? defaults.reversal_complete_financials_date ?? null)
            : null,
          source: eligible && client_settings?.reversal_complete_financials_date != null ? 'CLIENT' : (eligible ? 'GLOBAL' : 'NOT_ELIGIBLE')
        },
        reversal_replacement_financials_date: {
          override: eligible ? (client_settings?.reversal_replacement_financials_date ?? null) : null,
          effective: eligible
            ? (client_settings?.reversal_replacement_financials_date ?? defaults.reversal_replacement_financials_date ?? null)
            : null,
          source: eligible && client_settings?.reversal_replacement_financials_date != null ? 'CLIENT' : (eligible ? 'GLOBAL' : 'NOT_ELIGIBLE')
        },
        global_settings_updated_at: defaults.updated_at || null
      };
    } catch {
      import_financial_policy = {
        eligible: false,
        configuration_error: 'IMPORT_FINANCIAL_POLICY_UNAVAILABLE'
      };
    }

    // has_e_history (client-level) for Client modal E-History tab enablement
    let has_e_history = false;
    try {
      // Option B: smaller existence check via v_legacy_client_candidates
      const { rows: histRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_legacy_client_candidates` +
          `?client_id=eq.${enc(clientId)}` +
          `&select=client_id` +
          `&limit=1`
      );
      has_e_history = Array.isArray(histRows) && histRows.length > 0;
    } catch (e) {
      console.error('handleGetClient: legacy history existence check failed', {
        client_id: clientId,
        err: e?.message || String(e)
      });
      has_e_history = false;
    }

    return withCORS(env, req, ok({ client, client_settings, import_financial_policy, has_e_history }));
  } catch (e) {
    console.error('handleGetClient failed', {
      client_id: clientId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError("Failed to fetch client"));
  }
}

async function handleCreateClient(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const data = await parseJSONBody(req);
  if (!data) return withCORS(env, req, badRequest("Invalid JSON"));

  // Client and initial settings share one idempotent database transaction.
  try {
    const payload = await createClientWithSettingsAtomic(env, user, data);
    return withCORS(env, req, ok(payload));
  } catch (error) {
    const code = String(error?.json?.message || error?.message || 'CLIENT_CREATE_FAILED').match(/CLIENT_[A-Z0-9_]+/)?.[0] || 'CLIENT_CREATE_FAILED';
    const status = /CONFLICT|LOCK_BUSY/.test(code) ? 409 : 400;
    return withCORS(env, req, new Response(JSON.stringify({
      ok: false,
      error_code: code,
      message: code === 'CLIENT_CREATE_FAILED'
        ? 'Client creation failed safely.'
        : 'The client or initial settings did not pass server validation.'
    }), { status, headers: JSON_HEADERS }));
  }
}

async function handleUpdateClient(env, req, clientId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const raw = await parseJSONBody(req);
  if (!raw) return withCORS(env, req, badRequest("Invalid JSON"));

  const policySource = (raw.client_settings && typeof raw.client_settings === 'object' && !Array.isArray(raw.client_settings))
    ? raw.client_settings
    : raw;
  const hasFinancialPolicy = Object.prototype.hasOwnProperty.call(policySource, 'reversal_complete_financials_date')
    || Object.prototype.hasOwnProperty.call(policySource, 'reversal_replacement_financials_date');
  if (hasFinancialPolicy) {
    const nestedUnsupported = raw.client_settings && typeof raw.client_settings === 'object'
      ? Object.keys(raw.client_settings).filter((key) => !['reversal_complete_financials_date', 'reversal_replacement_financials_date'].includes(key))
      : [];
    if (nestedUnsupported.length) {
      return withCORS(env, req, badRequest('Import financial-date overrides must be saved separately from unrelated client settings.'));
    }
    const policyPatch = {};
    for (const key of ['reversal_complete_financials_date', 'reversal_replacement_financials_date']) {
      if (!Object.prototype.hasOwnProperty.call(policySource, key)) continue;
      const rawValue = policySource[key];
      const value = rawValue == null || String(rawValue).trim() === '' ? null : String(rawValue).trim().toUpperCase();
      if (value !== null && !['PAID_DATE', 'NOW'].includes(value)) {
        return withCORS(env, req, badRequest(`${key} must be PAID_DATE, NOW or blank to inherit.`));
      }
      policyPatch[key] = value;
    }
    const clientPatch = {};
    for (const key of CLIENT_CREATE_FIELDS) {
      if (Object.prototype.hasOwnProperty.call(raw, key)) clientPatch[key] = raw[key];
    }
    if (!Number.isInteger(Number(raw.expected_client_rev)) || !raw.expected_settings_updated_at || String(raw.request_key || '').trim().length < 16) {
      return withCORS(env, req, badRequest('expected_client_rev, expected_settings_updated_at and a stable request_key are required.'));
    }
    try {
      const rpcRaw = await sbRpc(env, 'client_update_with_settings_v1', {
        p_client_id: clientId,
        p_expected_client_rev: Number(raw.expected_client_rev),
        p_expected_settings_updated_at: raw.expected_settings_updated_at,
        p_client_patch: clientPatch,
        p_financial_policy_patch: policyPatch,
        p_actor_user_id: user.id,
        p_request_key: String(raw.request_key).trim()
      }, { timeoutMs: 15000 });
      return withCORS(env, req, ok(unwrapRpcJsonb(rpcRaw, 'client_update_with_settings_v1')));
    } catch (error) {
      const code = String(error?.json?.message || error?.message || '').match(/[A-Z][A-Z0-9_]{4,}/)?.[0] || 'CLIENT_UPDATE_FAILED';
      return withCORS(env, req, new Response(JSON.stringify({
        ok: false,
        error_code: code,
        message: /CONFLICT|STALE/.test(code) ? 'Client settings changed. Reload and try again.' : 'The client import financial-date settings were not changed.'
      }), { status: /CONFLICT|STALE/.test(code) ? 409 : 400, headers: JSON_HEADERS }));
    }
  }

  const { cli_ref, cli_num, ...data } = raw;

  const TIME_KEYS = [
    'day_start','day_end',
    'night_start','night_end',
    'sat_start','sat_end',
    'sun_start','sun_end',
    'bh_start','bh_end'
  ];

  const asBool = (v) => {
    if (v === true) return true;
    if (v === false || v == null) return false;
    const s = String(v).trim().toLowerCase();
    return s === 'true' || s === 'yes' || s === 'y' || s === '1' || s === 'on';
  };

  const normTime = (v) => {
    if (v == null) return null;
    const s = String(v).trim();
    if (!s) return null;
    const m = s.match(/^(\d{2}:\d{2})/);
    return m ? m[1] : s;
  };

  const sameTime = (a, b) => {
    const na = normTime(a);
    const nb = normTime(b);
    return String(na ?? '') === String(nb ?? '');
  };

  const normEmail = (v) => {
    if (v == null) return null;
    const s = String(v).trim();
    return s ? s : null;
  };

  // ✅ NEW: normalise free-text fields with explicit clear semantics
  const normText = (v) => {
    if (v == null) return null;
    const s = String(v).trim();
    return s ? s : null;
  };

  // ✅ NEW: canonical invoice consolidation mode (never write junk)
  // Allowed: NONE | BY_WEEK | ANY_WEEK (UI may send ALL → ANY_WEEK)
  const normInvoiceConsol = (v) => {
    if (v == null) return null;
    const s = String(v).trim().toUpperCase();
    if (!s) return null;
    if (s === 'ALL') return 'ANY_WEEK';
    if (s === 'ANY') return 'ANY_WEEK';
    if (s === 'NONE' || s === 'BY_WEEK' || s === 'ANY_WEEK') return s;
    return '__INVALID__';
  };

  try {
    const { rows: beforeClientRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/clients` +
      `?id=eq.${encodeURIComponent(clientId)}` +
      `&select=id,name,invoice_address,primary_invoice_email,ap_phone,vat_chargeable,payment_terms_days,mileage_charge_rate,ts_queries_email,notes,updated_at`
    );
    if (!beforeClientRows?.length) return withCORS(env, req, notFound("Client not found"));
    const beforeClient = beforeClientRows[0];

    const { rows: beforeCsRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/client_settings` +
      `?client_id=eq.${encodeURIComponent(clientId)}` +
      `&select=` +
        [
          'id',
          'hr_validation_required','ts_reference_required','pay_reference_required','invoice_reference_required',
          'default_submission_mode',
          'week_ending_weekday',
          'is_nhsp','self_bill_no_invoices_sent','daily_calc_of_invoices',
          'no_timesheet_required','group_nightsat_sunbh',
          'auto_invoice_default',

          // ✅ NEW: client comms opt-ins (DB-backed)
          'opt_in_email','opt_in_sms','opt_in_whatsapp',

          'effective_from','timezone_id',
          'day_start','day_end','night_start','night_end','sat_start','sat_end','sun_start','sun_end','bh_start','bh_end',
          'bh_source','bh_list','bh_feed_url',
          'requires_hr','autoprocess_hr','hr_attach_to_invoice','ts_attach_to_invoice',

          // manual adjustment email routing
          'send_manual_invoices_to_different_email',
          'manual_invoices_alt_email_address',

          // ✅ NEW: invoice settings
          'invoice_consolidation_mode',
          'reference_number_required_to_issue_invoice',

          'created_at','updated_at'
        ].join(',') +
      `&order=effective_from.desc,created_at.desc&limit=1`
    );

    const beforeCs = beforeCsRows?.[0] || null;

    // ✅ FIX: guard against null client_settings (typeof null === 'object')
    const csInput = {
      ...((data.client_settings && typeof data.client_settings === 'object') ? data.client_settings : {})
    };

    delete csInput.weekly_mode;
    delete csInput.hr_weekly_behaviour;
    delete csInput.__from_ui;
    delete csInput.ts_queries_email; // never allow this to be treated as client_settings

    if ('hr_validation_required' in data)        csInput.hr_validation_required        = !!data.hr_validation_required;
    if ('ts_reference_required' in data)         csInput.ts_reference_required         = !!data.ts_reference_required;
    if ('pay_reference_required' in data)        csInput.pay_reference_required        = !!data.pay_reference_required;
    if ('invoice_reference_required' in data)    csInput.invoice_reference_required    = !!data.invoice_reference_required;
    if ('default_submission_mode' in data)       csInput.default_submission_mode       = data.default_submission_mode;

    if ('auto_invoice_default' in data || 'auto_invoice_default' in csInput) {
      csInput.auto_invoice_default = asBool(csInput.auto_invoice_default ?? data.auto_invoice_default);
    }

    if ('requires_hr' in data || 'requires_hr' in csInput) {
      csInput.requires_hr = asBool(csInput.requires_hr ?? data.requires_hr);
    }
    if ('autoprocess_hr' in data || 'autoprocess_hr' in csInput) {
      csInput.autoprocess_hr = asBool(csInput.autoprocess_hr ?? data.autoprocess_hr);
    }
    if ('hr_attach_to_invoice' in data || 'hr_attach_to_invoice' in csInput) {
      csInput.hr_attach_to_invoice = asBool(csInput.hr_attach_to_invoice ?? data.hr_attach_to_invoice);
    }
    if ('ts_attach_to_invoice' in data || 'ts_attach_to_invoice' in csInput) {
      csInput.ts_attach_to_invoice = asBool(csInput.ts_attach_to_invoice ?? data.ts_attach_to_invoice);
    }

    if ('is_nhsp' in data || 'is_nhsp' in csInput) {
      csInput.is_nhsp = asBool(csInput.is_nhsp ?? data.is_nhsp);
    }
    if ('self_bill_no_invoices_sent' in data || 'self_bill_no_invoices_sent' in csInput) {
      csInput.self_bill_no_invoices_sent = asBool(csInput.self_bill_no_invoices_sent ?? data.self_bill_no_invoices_sent);
    }
    if ('daily_calc_of_invoices' in data || 'daily_calc_of_invoices' in csInput) {
      csInput.daily_calc_of_invoices = asBool(csInput.daily_calc_of_invoices ?? data.daily_calc_of_invoices);
    }
    if ('no_timesheet_required' in data || 'no_timesheet_required' in csInput) {
      csInput.no_timesheet_required = asBool(csInput.no_timesheet_required ?? data.no_timesheet_required);
    }
    if ('group_nightsat_sunbh' in data || 'group_nightsat_sunbh' in csInput) {
      csInput.group_nightsat_sunbh = asBool(csInput.group_nightsat_sunbh ?? data.group_nightsat_sunbh);
    }

    if ('send_manual_invoices_to_different_email' in data || 'send_manual_invoices_to_different_email' in csInput) {
      csInput.send_manual_invoices_to_different_email =
        asBool(csInput.send_manual_invoices_to_different_email ?? data.send_manual_invoices_to_different_email);
    }
    if ('manual_invoices_alt_email_address' in data || 'manual_invoices_alt_email_address' in csInput) {
      csInput.manual_invoices_alt_email_address =
        normEmail(csInput.manual_invoices_alt_email_address ?? data.manual_invoices_alt_email_address);
    }

    // ✅ NEW: client comms opt-ins (DB-backed) — only apply when provided
    if ('opt_in_email' in data || 'opt_in_email' in csInput) {
      csInput.opt_in_email = asBool(csInput.opt_in_email ?? data.opt_in_email);
    }
    if ('opt_in_sms' in data || 'opt_in_sms' in csInput) {
      csInput.opt_in_sms = asBool(csInput.opt_in_sms ?? data.opt_in_sms);
    }
    if ('opt_in_whatsapp' in data || 'opt_in_whatsapp' in csInput) {
      csInput.opt_in_whatsapp = asBool(csInput.opt_in_whatsapp ?? data.opt_in_whatsapp);
    }

    // ✅ NEW: canonical invoice_consolidation_mode (reject invalid; never write junk)
    if ('invoice_consolidation_mode' in data || 'invoice_consolidation_mode' in csInput) {
      const v = normInvoiceConsol(csInput.invoice_consolidation_mode ?? data.invoice_consolidation_mode);
      if (v === '__INVALID__') {
        return withCORS(env, req, badRequest('invoice_consolidation_mode must be one of NONE, BY_WEEK, ANY_WEEK (or ALL).'));
      }
      if (v != null) csInput.invoice_consolidation_mode = v;
    }

    // ✅ NEW: accept reference_number_required_to_issue_invoice boolean
    if ('reference_number_required_to_issue_invoice' in data || 'reference_number_required_to_issue_invoice' in csInput) {
      csInput.reference_number_required_to_issue_invoice =
        asBool(csInput.reference_number_required_to_issue_invoice ?? data.reference_number_required_to_issue_invoice);
    }

    for (const k of TIME_KEYS) {
      if ((k in data) || (k in csInput)) {
        csInput[k] = normTime(csInput[k] ?? data[k]);
      }
    }

    const weIn = (data.week_ending_weekday ?? csInput.week_ending_weekday);
    if (weIn !== undefined) {
      let we = Number(weIn);
      if (!Number.isInteger(we) || we < 0 || we > 6) we = 0;
      csInput.week_ending_weekday = we;
    }

    if ('default_submission_mode' in csInput) {
      let dsm = String(csInput.default_submission_mode || '').toUpperCase();
      if (!['ELECTRONIC','MANUAL'].includes(dsm)) dsm = 'ELECTRONIC';
      csInput.default_submission_mode = dsm;
    }

    const {
      hr_validation_required,
      ts_reference_required,
      pay_reference_required,
      invoice_reference_required,
      default_submission_mode,
      client_settings,
      week_ending_weekday,

      is_nhsp,
      self_bill_no_invoices_sent,
      daily_calc_of_invoices,
      no_timesheet_required,
      group_nightsat_sunbh,
      auto_invoice_default,
      requires_hr,
      autoprocess_hr,
      hr_attach_to_invoice,
      ts_attach_to_invoice,

      // ensure these never fall into clients table patch
      send_manual_invoices_to_different_email,
      manual_invoices_alt_email_address,

      // ensure these never fall into clients table patch
      invoice_consolidation_mode,
      reference_number_required_to_issue_invoice,

      // ensure opt-ins never fall into clients table patch
      opt_in_email,
      opt_in_sms,
      opt_in_whatsapp,

      ...clientPatchRaw
    } = data;

    const clientPatch = {};

    // ✅ Explicit clear semantics for ts_queries_email:
    // - if key present and blank => set NULL (clears the field)
    // - if key present and non-blank => trimmed string
    // - if not present => no change
    if (Object.prototype.hasOwnProperty.call(clientPatchRaw, 'ts_queries_email')) {
      clientPatch.ts_queries_email = normEmail(clientPatchRaw.ts_queries_email);
      delete clientPatchRaw.ts_queries_email;
    }

    // ✅ Explicit clear semantics for notes:
    // - if key present and blank => set NULL (clears the field)
    // - if key present and non-blank => trimmed string
    // - if not present => no change
    if (Object.prototype.hasOwnProperty.call(clientPatchRaw, 'notes')) {
      clientPatch.notes = normText(clientPatchRaw.notes);
      delete clientPatchRaw.notes;
    }

    for (const [k, v] of Object.entries(clientPatchRaw)) {
      if (v === '' || v === undefined) continue;
      clientPatch[k] = v;
    }

    const clientKeysToChange = Object.keys(clientPatch).filter(k => {
      return JSON.stringify(clientPatch[k]) !== JSON.stringify(beforeClient[k]);
    });

    let client = beforeClient;

    if (clientKeysToChange.length) {
      clientPatch.updated_at = new Date().toISOString();

      const res = await fetch(
        `${env.SUPABASE_URL}/rest/v1/clients?id=eq.${encodeURIComponent(clientId)}`,
        {
          method: "PATCH",
          headers: { ...sbHeaders(env), "Prefer": "return=representation" },
          body: JSON.stringify(clientPatch)
        }
      );
      if (!res.ok) {
        const err = await res.text();
        return withCORS(env, req, badRequest(`Update failed: ${err}`));
      }
      const json = await res.json().catch(() => ({}));
      client = Array.isArray(json) ? json[0] : json;
    }

    let csChanged = false;
    let client_settings_updated = null;

    if (Object.keys(csInput).length) {
      const hasBefore = !!beforeCs?.id;

      const canon = canonicalizeClientSettingsServer(beforeCs, csInput);

      // ✅ Ensure canon contains opt-ins (canonicalizeClientSettingsServer does not currently include them)
      if (Object.prototype.hasOwnProperty.call(csInput, 'opt_in_email')) {
        canon.opt_in_email = asBool(csInput.opt_in_email);
      } else if (beforeCs && Object.prototype.hasOwnProperty.call(beforeCs, 'opt_in_email')) {
        canon.opt_in_email = asBool(beforeCs.opt_in_email);
      }

      if (Object.prototype.hasOwnProperty.call(csInput, 'opt_in_sms')) {
        canon.opt_in_sms = asBool(csInput.opt_in_sms);
      } else if (beforeCs && Object.prototype.hasOwnProperty.call(beforeCs, 'opt_in_sms')) {
        canon.opt_in_sms = asBool(beforeCs.opt_in_sms);
      }

      if (Object.prototype.hasOwnProperty.call(csInput, 'opt_in_whatsapp')) {
        canon.opt_in_whatsapp = asBool(csInput.opt_in_whatsapp);
      } else if (beforeCs && Object.prototype.hasOwnProperty.call(beforeCs, 'opt_in_whatsapp')) {
        canon.opt_in_whatsapp = asBool(beforeCs.opt_in_whatsapp);
      }

      if (Object.prototype.hasOwnProperty.call(csInput, 'invoice_consolidation_mode')) {
        const v = normInvoiceConsol(csInput.invoice_consolidation_mode);
        if (v === '__INVALID__') {
          return withCORS(env, req, badRequest('invoice_consolidation_mode must be one of NONE, BY_WEEK, ANY_WEEK (or ALL).'));
        }
        if (v != null) canon.invoice_consolidation_mode = v;
      }
      if (Object.prototype.hasOwnProperty.call(csInput, 'reference_number_required_to_issue_invoice')) {
        canon.reference_number_required_to_issue_invoice = asBool(csInput.reference_number_required_to_issue_invoice);
      }

      if (canon.send_manual_invoices_to_different_email && !canon.manual_invoices_alt_email_address) {
        return withCORS(env, req, badRequest('manual_invoices_alt_email_address is required when send_manual_invoices_to_different_email is true'));
      }

      for (const k of TIME_KEYS) {
        if (Object.prototype.hasOwnProperty.call(canon, k)) {
          canon[k] = normTime(canon[k]);
        }
      }

      {
        const filled = TIME_KEYS.filter(k => canon[k] != null && String(canon[k]).trim() !== '');
        if (filled.length > 0 && filled.length < TIME_KEYS.length) {
          return withCORS(env, req, badRequest('Shift times must be either all blank (inherit global) or all filled.'));
        }
      }

      const patchObj = {};
      if (hasBefore) {
        for (const [k, v] of Object.entries(canon)) {
          if (k === 'id' || k === 'client_id' || k === 'created_at' || k === 'updated_at') continue;

          const beforeV = beforeCs ? beforeCs[k] : undefined;

          if (TIME_KEYS.includes(k)) {
            if (!sameTime(beforeV, v)) patchObj[k] = v;
            continue;
          }

          if (JSON.stringify(beforeV) !== JSON.stringify(v)) patchObj[k] = v;
        }
        patchObj.updated_at = new Date().toISOString();

        const csRes = await fetch(
          `${env.SUPABASE_URL}/rest/v1/client_settings?id=eq.${encodeURIComponent(beforeCs.id)}`,
          {
            method: "PATCH",
            headers: { ...sbHeaders(env), "Prefer": "return=representation" },
            body: JSON.stringify(patchObj)
          }
        );
        if (!csRes.ok) {
          const err = await csRes.text();
          return withCORS(env, req, badRequest(`Client settings update failed: ${err}`));
        }
        const csJson = await csRes.json().catch(() => ({}));
        client_settings_updated = Array.isArray(csJson) ? csJson[0] : csJson;
      } else {
        const nowIso = new Date().toISOString();

        const ukTodayYmd = (() => {
          const parts = new Intl.DateTimeFormat('en-GB', {
            timeZone: 'Europe/London',
            year: 'numeric',
            month: '2-digit',
            day: '2-digit'
          }).formatToParts(new Date(nowIso));
          const m = {};
          for (const p of parts) m[p.type] = p.value;
          return `${m.year}-${m.month}-${m.day}`;
        })();

        const insertRow = {
          client_id: clientId,
          ...canon,
          created_at: nowIso,
          updated_at: nowIso
        };
        delete insertRow.id;

        if (!Object.prototype.hasOwnProperty.call(insertRow, 'effective_from') || !String(insertRow.effective_from || '').trim()) {
          insertRow.effective_from = ukTodayYmd;
        }

        const csRes = await fetch(`${env.SUPABASE_URL}/rest/v1/client_settings`, {
          method: "POST",
          headers: { ...sbHeaders(env), "Prefer": "return=representation" },
          body: JSON.stringify(insertRow)
        });
        if (!csRes.ok) {
          const err = await csRes.text();
          return withCORS(env, req, badRequest(`Client settings insert failed: ${err}`));
        }
        const csJson = await csRes.json().catch(() => ({}));
        client_settings_updated = Array.isArray(csJson) ? csJson[0] : csJson;
      }

      const beforeHr      = !!(beforeCs?.hr_validation_required        ?? false);
      const beforeRef     = !!(beforeCs?.ts_reference_required         ?? false);
      const beforePayRef  = !!(beforeCs?.pay_reference_required        ?? false);
      const beforeInvRef  = !!(beforeCs?.invoice_reference_required    ?? false);

      const nextHr        = !!(canon.hr_validation_required            ?? false);
      const nextRef       = !!(canon.ts_reference_required             ?? false);
      const nextPayRef    = !!(canon.pay_reference_required            ?? false);
      const nextInvRef    = !!(canon.invoice_reference_required        ?? false);

      const timesChanged = TIME_KEYS.some(k => !sameTime(beforeCs?.[k], canon?.[k]));

      csChanged = (
        beforeHr     !== nextHr     ||
        beforeRef    !== nextRef    ||
        beforePayRef !== nextPayRef ||
        beforeInvRef !== nextInvRef ||
        timesChanged
      );
    }

    const policyChanged =
      (data.vat_chargeable != null && !!data.vat_chargeable !== !!beforeClient.vat_chargeable) ||
      (data.payment_terms_days != null && Number(data.payment_terms_days) !== Number(beforeClient.payment_terms_days));

    const mileageChargeChanged =
      (data.mileage_charge_rate != null && Number(data.mileage_charge_rate) !== Number(beforeClient.mileage_charge_rate));

    if (policyChanged || mileageChargeChanged || csChanged) {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
          `?client_id=eq.${encodeURIComponent(clientId)}` +
          `&is_current=eq.true` +
          `&locked_by_invoice_id=is.null`,
        {
          method: "PATCH",
          headers: { ...sbHeaders(env), "Prefer": "return=minimal" },
          body: JSON.stringify({
            is_stale: true,
            stale_reason: 'CLIENT_SETTINGS_CHANGED',
            updated_at: new Date().toISOString()
          })
        }
      );

      const { rows: tsfins } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
          `?select=timesheet_id` +
          `&client_id=eq.${encodeURIComponent(clientId)}` +
          `&is_current=eq.true` +
          `&locked_by_invoice_id=is.null`
      );
      const toEnqueue = (tsfins || []).map(r => ({ timesheet_id: r.timesheet_id, reason: 'POLICY_CHANGED' }));
      if (toEnqueue.length) {
        await fetch(
          `${env.SUPABASE_URL}/rest/v1/ts_financials_outbox?on_conflict=timesheet_id,reason`,
          {
            method: "POST",
            headers: { ...sbHeaders(env), "Prefer": "resolution=ignore-duplicates" },
            body: JSON.stringify(toEnqueue)
          }
        );
      }
    }

    return withCORS(env, req, ok({
      client,
      client_settings: client_settings_updated || beforeCs || null
    }));
  } catch (e) {
    return withCORS(env, req, serverError("Failed to update client"));
  }
}

