// ============================================================
// UPDATED: handleTsfinPatchExpenses / handleTsfinPatchMileage / patchTsfinCommon
// - Supports category expenses (TRAVEL/ACCOMMODATION/OTHER) + totals derived
// - Enforces evidence via public.timesheet_evidence.kind (NOT TSFIN *_evidence_* fields)
// - Mileage evidence enforced via timesheet_evidence.kind = 'MILEAGE'
// - Stores expenses_description as notes/metadata only (string or JSON-stringified)
// ============================================================
async function handleTsfinPatchExpenses(env, req, timesheetId, ctx = null) {
  const body = await parseJSONBody(req).catch(() => ({}));

  // allow either top-level fields or nested { expenses: {...} }
  const src = (body && typeof body.expenses === 'object' && body.expenses) ? body.expenses : body;

  const hasOwn = (obj, key) => !!(obj && typeof obj === 'object' && Object.prototype.hasOwnProperty.call(obj, key));
  const cleanSig = (v) => {
    const s = String(v == null ? '' : v).trim();
    return s || null;
  };
  const firstSig = (...vals) => {
    for (const v of vals) {
      const s = cleanSig(v);
      if (s) return s;
    }
    return null;
  };

  const response = await patchTsfinCommon(env, req, timesheetId, {
    expected_timesheet_id: body?.expected_timesheet_id ?? src?.expected_timesheet_id,
    reason: body?.reason ?? src?.reason ?? null,
    _save_domain: 'EXPENSES',
    _diag_request_signature_fields: {
      expected_timesheet_id_present: hasOwn(body, 'expected_timesheet_id') || hasOwn(src, 'expected_timesheet_id'),
      expected_row_signature_present: hasOwn(body, 'expected_row_signature') || hasOwn(src, 'expected_row_signature'),
      backend_row_signature_present: hasOwn(body, 'backend_row_signature') || hasOwn(src, 'backend_row_signature'),
      mutation_row_signature_present: hasOwn(body, 'mutation_row_signature') || hasOwn(src, 'mutation_row_signature'),
      row_signature_present: hasOwn(body, 'row_signature') || hasOwn(src, 'row_signature'),
      current_row_signature_present: hasOwn(body, 'current_row_signature') || hasOwn(src, 'current_row_signature'),
      expected_row_signature: firstSig(body?.expected_row_signature, src?.expected_row_signature),
      backend_row_signature: firstSig(body?.backend_row_signature, src?.backend_row_signature),
      mutation_row_signature: firstSig(body?.mutation_row_signature, src?.mutation_row_signature),
      row_signature: firstSig(body?.row_signature, src?.row_signature),
      current_row_signature: firstSig(body?.current_row_signature, src?.current_row_signature)
    },
    expenses: {
      travel_pay_ex_vat: src?.travel_pay_ex_vat,
      travel_charge_ex_vat: src?.travel_charge_ex_vat,

      accommodation_pay_ex_vat: src?.accommodation_pay_ex_vat,
      accommodation_charge_ex_vat: src?.accommodation_charge_ex_vat,

      other_pay_ex_vat: src?.other_pay_ex_vat,
      other_charge_ex_vat: src?.other_charge_ex_vat,

      // notes/meta ONLY (string or object); stored into timesheets_financials.expenses_description
      description: (src?.expenses_description ?? src?.description ?? src?.expenses_meta_json)
    }
  });

  try {
    if (response && Number(response.status || 0) >= 200 && Number(response.status || 0) < 300) {
      if (typeof logBankingPayWorkbenchDiag === 'function') {
        logBankingPayWorkbenchDiag(env, 'BANKING_PAY_NUDGE_SKIPPED', {
          origin: 'TSFIN_EXPENSES_PATCH',
          reason: 'NOT_PAYMENT_ELIGIBILITY_BOUNDARY',
          mutation_type: 'TSFIN_EXPENSES_PATCH',
          timesheet_id: timesheetId || null,
          banking_pay_work_scheduled: false,
          workbench_drain_scheduled: false
        });
      }
    }
  } catch {}

  return withCORS(env, req, response);
}


// 4) PATCH /api/tsfin/:id/mileage  (mileage_units + pay/charge + rates)


async function handleTsfinPatchMileage(env, req, timesheetId) {
  const body = await parseJSONBody(req).catch(() => ({}));

  // allow either top-level fields or nested { mileage: {...} }
  const src = (body && typeof body.mileage === 'object' && body.mileage) ? body.mileage : body;

  const diagHasOwn = (obj, key) => !!(obj && typeof obj === 'object' && Object.prototype.hasOwnProperty.call(obj, key));
  const diagText = (v) => {
    const s = String(v == null ? '' : v).trim();
    return s || null;
  };
  const diagFirstText = (...values) => {
    for (const value of values) {
      const s = diagText(value);
      if (s) return s;
    }
    return null;
  };
  const diagExtractSignature = (obj) => {
    if (!obj || typeof obj !== 'object') {
      const s = diagText(obj);
      return {
        present: !!s,
        backend_row_signature: null,
        mutation_row_signature: null,
        row_signature: null,
        expected_row_signature: null,
        current_row_signature: null,
        signature: s
      };
    }
    const backend = diagText(obj.backend_row_signature);
    const mutation = diagText(obj.mutation_row_signature);
    const row = diagText(obj.row_signature);
    const expected = diagText(obj.expected_row_signature);
    const current = diagText(obj.current_row_signature);
    const generic = diagText(obj.signature || obj.render_signature);
    return {
      present: !!(backend || mutation || row || expected || current || generic),
      backend_row_signature: backend,
      mutation_row_signature: mutation,
      row_signature: row,
      expected_row_signature: expected,
      current_row_signature: current,
      signature: backend || mutation || row || expected || current || generic || null
    };
  };
  const diagResponseContains = (payload) => {
    const lp = payload?.lifecycle_patch && typeof payload.lifecycle_patch === 'object' ? payload.lifecycle_patch : null;
    return {
      updated: Object.prototype.hasOwnProperty.call(payload || {}, 'updated'),
      tsfin: !!(payload?.tsfin && typeof payload.tsfin === 'object'),
      timesheet: !!(payload?.timesheet && typeof payload.timesheet === 'object'),
      backend_row_signature: !!diagText(payload?.backend_row_signature),
      mutation_row_signature: !!diagText(payload?.mutation_row_signature),
      row_signature: !!diagText(payload?.row_signature),
      expected_row_signature: !!diagText(payload?.expected_row_signature),
      current_row_signature: !!diagText(payload?.current_row_signature),
      lifecycle_signature: !!payload?.lifecycle_signature,
      lifecycle_signature_has_signature: diagExtractSignature(payload?.lifecycle_signature).present,
      lifecycle_patch: !!lp,
      lifecycle_patch_backend_row_signature: !!diagText(lp?.backend_row_signature),
      lifecycle_patch_mutation_row_signature: !!diagText(lp?.mutation_row_signature),
      lifecycle_patch_row_signature: !!diagText(lp?.row_signature),
      lifecycle_patch_expected_row_signature: !!diagText(lp?.expected_row_signature),
      affected_rows: Array.isArray(payload?.affected_rows),
      affected_rows_count: Array.isArray(payload?.affected_rows) ? payload.affected_rows.length : null,
      action_flags: !!(payload?.action_flags || lp?.action_flags),
      priority_badge_hints: !!(payload?.priority_badge_hints || lp?.priority_badge_hints),
      refresh_hints: !!payload?.refresh_hints,
      dirty_state: !!payload?.dirty_state,
      save_patch_available: payload?.save_patch_available === true,
      immediate_lifecycle_patch_available: payload?.immediate_lifecycle_patch_available === true,
      requires_affected_row_refresh: payload?.requires_affected_row_refresh === true,
      requires_full_details_refresh: payload?.requires_full_details_refresh === true,
      refresh_required: payload?.refresh_required === true,
      authorise_preflight_refresh_required: payload?.authorise_preflight_refresh_required === true
    };
  };
  const diagRequestSignatureFields = {
    expected_timesheet_id_present: diagHasOwn(body, 'expected_timesheet_id') || diagHasOwn(src, 'expected_timesheet_id'),
    expected_row_signature_present: diagHasOwn(body, 'expected_row_signature') || diagHasOwn(src, 'expected_row_signature'),
    backend_row_signature_present: diagHasOwn(body, 'backend_row_signature') || diagHasOwn(src, 'backend_row_signature'),
    mutation_row_signature_present: diagHasOwn(body, 'mutation_row_signature') || diagHasOwn(src, 'mutation_row_signature'),
    row_signature_present: diagHasOwn(body, 'row_signature') || diagHasOwn(src, 'row_signature'),
    current_row_signature_present: diagHasOwn(body, 'current_row_signature') || diagHasOwn(src, 'current_row_signature'),
    expected_row_signature: diagFirstText(body?.expected_row_signature, src?.expected_row_signature),
    backend_row_signature: diagFirstText(body?.backend_row_signature, src?.backend_row_signature),
    mutation_row_signature: diagFirstText(body?.mutation_row_signature, src?.mutation_row_signature),
    row_signature: diagFirstText(body?.row_signature, src?.row_signature),
    current_row_signature: diagFirstText(body?.current_row_signature, src?.current_row_signature)
  };
  const logTsfinMileageSignatureDiag = (step, extra = {}) => {
    try {
      let routePath = null;
      try { routePath = new URL(req.url).pathname; } catch {}
      console.log('[TSFIN_SAVE_SIGNATURE_DIAG]', JSON.stringify({
        tag: 'TSFIN_SAVE_SIGNATURE_DIAG',
        handler: 'handleTsfinPatchMileage',
        route_family: 'MILEAGE',
        step,
        route_path: routePath,
        requested_timesheet_id: timesheetId || null,
        expected_timesheet_id: body?.expected_timesheet_id ?? src?.expected_timesheet_id ?? null,
        request_signature_fields: diagRequestSignatureFields,
        patch_field_names: Object.keys(src && typeof src === 'object' ? src : {}).filter((key) => src[key] !== undefined).sort(),
        server_utc: new Date().toISOString(),
        ...(extra && typeof extra === 'object' && !Array.isArray(extra) ? extra : {})
      }));
    } catch {}
  };

  logTsfinMileageSignatureDiag('received');

  const response = await patchTsfinCommon(env, req, timesheetId, {
    expected_timesheet_id: body?.expected_timesheet_id ?? src?.expected_timesheet_id,
    reason: body?.reason ?? src?.reason ?? null,
    mileage: {
      mileage_units: src?.mileage_units,
      pay_ex_vat: src?.pay_ex_vat,
      charge_ex_vat: src?.charge_ex_vat,
      pay_rate: src?.pay_rate,
      charge_rate: src?.charge_rate
    }
  });

  try {
    const payload = await response.clone().json().catch(() => null);
    logTsfinMileageSignatureDiag('response_shape', {
      status: Number(response.status || 0) || null,
      ok: !!response.ok,
      current_timesheet_id: payload?.current_timesheet_id || payload?.timesheet_id || null,
      requested_timesheet_id: payload?.requested_timesheet_id || timesheetId || null,
      contract_week_id: payload?.contract_week_id || null,
      updated: payload?.updated === true,
      save_domain: payload?.save_domain || null,
      response_signature: diagExtractSignature(payload || null),
      lifecycle_patch_signature: diagExtractSignature(payload?.lifecycle_patch || null),
      response_contains: diagResponseContains(payload || {})
    });
  } catch (e) {
    logTsfinMileageSignatureDiag('response_shape_log_failed', {
      status: Number(response?.status || 0) || null,
      error: String(e?.message || e || '').slice(0, 300)
    });
  }

  return withCORS(env, req, response);
}



function derivePayBatchRouteDisplay(context = {}) {
  const ctx = context && typeof context === 'object' && !Array.isArray(context) ? context : {};
  const trimText = (value) => String(value == null ? '' : value).trim();
  const normalise = (value) => trimText(value)
    .toUpperCase()
    .replace(/[·/\\|.\-\s]+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '');
  const bool = (value) => value === true || ['TRUE', 'T', '1', 'YES', 'Y', 'ON'].includes(normalise(value));
  const numberOrNull = (value) => {
    if (value == null || trimText(value) === '') return null;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  };
  const objectOrEmpty = (value) => {
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    if (typeof value !== 'string') return {};
    const raw = value.trim();
    if (!raw || raw[0] !== '{') return {};
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  };
  const arrayOrEmpty = (value) => Array.isArray(value) ? value : [];

  const sources = [];
  const seen = new Set();
  const nestedKeys = [
    'rail_meta_json', 'railMetaJson',
    'settlement_confirmation_json', 'settlementConfirmationJson',
    'execution_intent_json', 'executionIntentJson',
    'raw_payload', 'rawPayload',
    'payment_route_json', 'paymentRouteJson',
    'route_json', 'routeJson',
    'metadata', 'meta', 'details',
    'settlement', 'confirmation', 'execution', 'route', 'payment',
    'provider_event', 'providerEvent', 'latest_event', 'latestEvent'
  ];
  const addSource = (value, depth = 0) => {
    const objectValue = objectOrEmpty(value);
    if (!Object.keys(objectValue).length || seen.has(objectValue) || sources.length >= 400) return;
    seen.add(objectValue);
    sources.push(objectValue);
    if (depth >= 4) return;
    nestedKeys.forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(objectValue, key)) addSource(objectValue[key], depth + 1);
    });
  };

  addSource(ctx);
  addSource(ctx.batch);
  addSource(ctx.executionIntent || ctx.execution_intent);
  addSource(ctx.settlementConfirmation || ctx.settlement_confirmation);
  arrayOrEmpty(ctx.transfers).forEach((row) => addSource(row));
  arrayOrEmpty(ctx.events).forEach((row) => addSource(row));

  const values = (keys) => {
    const output = [];
    sources.forEach((item) => {
      keys.forEach((key) => {
        if (Object.prototype.hasOwnProperty.call(item, key)) output.push(item[key]);
      });
    });
    return output;
  };
  const firstText = (keys) => {
    for (const value of values(keys)) {
      const candidate = trimText(value);
      if (candidate) return candidate;
    }
    return '';
  };
  const anyTrue = (keys) => values(keys).some(bool);
  const tokens = (keys) => values(keys).map(normalise).filter(Boolean);

  const routeLabelTokens = tokens([
    'payment_route_display_label', 'paymentRouteDisplayLabel',
    'payment_route_label', 'paymentRouteLabel',
    'route_display_label', 'routeDisplayLabel',
    'provider_label', 'providerLabel'
  ]);
  const modeTokens = tokens([
    'execution_mode', 'executionMode',
    'settlement_mode', 'settlementMode',
    'confirmation_mode', 'confirmationMode',
    'manual_confirmation_mode', 'manualConfirmationMode',
    'payment_route_kind', 'paymentRouteKind',
    'route_kind', 'routeKind',
    'scope_kind', 'scopeKind',
    'rail_state', 'railState',
    'provider_state', 'providerState',
    'latest_event_provider_state', 'latestEventProviderState',
    'banking_system', 'bankingSystem',
    'banking_system_snapshot', 'bankingSystemSnapshot'
  ]);
  const providerTokens = tokens([
    'rail_provider', 'railProvider',
    'provider', 'provider_key', 'providerKey',
    'payment_provider', 'paymentProvider'
  ]);
  const allRouteTokens = routeLabelTokens.concat(modeTokens);

  const csvTokens = new Set([
    'BANK_CSV_UPLOAD',
    'CSV',
    'CSV_SETTLEMENT',
    'CSV_MANUAL_CONFIRM',
    'CSV_MANUAL_SETTLEMENT',
    'BANK_UPLOAD_CONFIRMED',
    'CSV_BANK_UPLOAD'
  ]);
  const externalTokens = new Set([
    'EXTERNAL_SETTLEMENT',
    'EXTERNAL_SETTLEMENT_CONFIRM',
    'EXTERNAL_SETTLEMENT_CONFIRMED',
    'EXTERNAL_MANUAL_CONFIRM',
    'MANUAL_SETTLEMENT',
    'MANUAL_EXTERNAL_SETTLEMENT'
  ]);
  const noBankTokens = new Set([
    'NO_BANK_PAYMENT_REQUIRED',
    'NO_BANK_PAYMENT',
    'NO_BANK_PAYMENT_EXECUTION',
    'NO_BANK_PAYMENT_REVIEW',
    'NO_BANK_PAYMENT_EXTERNAL_CONFIRMATION',
    'NO_BANK_TRANSFER',
    'ZERO_BANK',
    'ZERO_BANK_PAYMENT',
    'NO_MONEY'
  ]);
  const hasToken = (set, candidates) => candidates.some((candidate) => set.has(candidate));

  const positiveTransferCount = [
    ...values(['positive_transfer_count', 'positiveTransferCount']),
    ...values(['transfer_count', 'transferCount'])
  ].map(numberOrNull).find((value) => value !== null);
  const totalBankOut = [
    ...values(['total_bank_out', 'totalBankOut']),
    ...values(['payment_amount', 'paymentAmount']),
    ...values(['amount'])
  ].map(numberOrNull).find((value) => value !== null);
  const hasPositiveMoneyEvidence = (positiveTransferCount !== undefined && positiveTransferCount > 0)
    || (totalBankOut !== undefined && totalBankOut > 0)
    || arrayOrEmpty(ctx.transfers).some((row) => numberOrNull(row && row.amount) > 0);

  const explicitNoBankExecution = anyTrue([
    'no_bank_payment_execution', 'noBankPaymentExecution',
    'is_no_bank_payment', 'isNoBankPayment',
    'no_bank_payment_required', 'noBankPaymentRequired',
    'zero_bank_proof', 'zeroBankProof'
  ]) || hasToken(noBankTokens, allRouteTokens);
  const explicitBankPaymentDidNotOccur = values(['bank_payment_occurred', 'bankPaymentOccurred'])
    .some((value) => value === false || normalise(value) === 'FALSE');
  const noBankReferencePresent = !!firstText([
    'no_bank_scope_reference', 'noBankScopeReference',
    'no_bank_payment_note', 'noBankPaymentNote',
    'local_no_bank_commit_ref', 'localNoBankCommitRef'
  ]);
  const pureNoBankExecution = explicitNoBankExecution
    || (explicitBankPaymentDidNotOccur && noBankReferencePresent && !hasPositiveMoneyEvidence);

  const csvEvidence = hasToken(csvTokens, allRouteTokens)
    || providerTokens.some((token) => token === 'CSV' || token === 'BANK_CSV')
    || anyTrue(['csv_uploaded_confirmed', 'csvUploadedConfirmed', 'bank_upload_confirmed', 'bankUploadConfirmed']);
  const externalEvidence = hasToken(externalTokens, allRouteTokens)
    || anyTrue(['external_settlement_confirmed', 'externalSettlementConfirmed']);

  const localSettlementEvidenceOnly = anyTrue(['local_settlement_evidence_only', 'localSettlementEvidenceOnly']);
  const submittedToBankFalse = values(['submitted_to_bank', 'submittedToBank'])
    .some((value) => value === false || normalise(value) === 'FALSE');
  const providerSubmissionRequiredFalse = values(['provider_submission_required', 'providerSubmissionRequired'])
    .some((value) => value === false || normalise(value) === 'FALSE');
  const providerSubmissionAttemptedFalse = values(['provider_submission_attempted', 'providerSubmissionAttempted'])
    .some((value) => value === false || normalise(value) === 'FALSE');
  const strongLocalProof = localSettlementEvidenceOnly
    && submittedToBankFalse
    && providerSubmissionRequiredFalse
    && providerSubmissionAttemptedFalse;

  const result = (label, routeKind, isLocalSettlement, isNoBankPayment) => ({
    label,
    route_kind: routeKind,
    routeKind,
    is_local_settlement: isLocalSettlement,
    isLocalSettlement,
    is_no_bank_payment: isNoBankPayment,
    isNoBankPayment
  });

  // Explicit whole-route no-bank proof must win over the authorised CSV/external
  // mode. A mixed positive + zero batch lacks this whole-route flag and therefore
  // continues to display the actual positive-payment route.
  if (pureNoBankExecution) return result('No bank payment required', 'NO_BANK_PAYMENT', true, true);
  if (csvEvidence || (strongLocalProof && allRouteTokens.some((token) => token.includes('CSV')))) {
    return result('Bank CSV upload', 'CSV_SETTLEMENT', true, false);
  }
  if (externalEvidence || (strongLocalProof && allRouteTokens.some((token) => token.includes('EXTERNAL')))) {
    return result('External settlement', 'EXTERNAL_SETTLEMENT', true, false);
  }

  const transferProviders = arrayOrEmpty(ctx.transfers)
    .map((row) => trimText(row && (row.rail_provider || row.railProvider)))
    .filter(Boolean);
  const transferEnvironments = arrayOrEmpty(ctx.transfers)
    .map((row) => trimText(row && (row.rail_env || row.railEnv)))
    .filter(Boolean);
  const unique = (items) => Array.from(new Set(items.map(trimText).filter(Boolean)));
  const provider = unique(transferProviders).join('/') || trimText(
    ctx.fallbackRailProvider
    || ctx.fallback_rail_provider
    || ctx.fallbackProvider
    || ctx.fallback_provider
    || objectOrEmpty(ctx.batch).rail_provider_snapshot
    || objectOrEmpty(ctx.batch).banking_system_snapshot
  );
  const environment = unique(transferEnvironments).join('/') || trimText(
    ctx.fallbackRailEnv
    || ctx.fallback_rail_env
    || ctx.fallbackEnvironment
    || ctx.fallback_environment
    || objectOrEmpty(ctx.batch).rail_env_snapshot
  );
  const label = provider && environment && !normalise(provider).includes(normalise(environment))
    ? `${provider} ${environment}`
    : (provider || environment || trimText(ctx.fallbackLabel || ctx.fallback_label));
  return result(label, label ? 'PROVIDER' : 'UNKNOWN', false, false);
}


async function patchTsfinCommon(env, req, timesheetId, patch) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const enc = encodeURIComponent;

  const jsonResponse = (status, payload) => new Response(JSON.stringify(payload), {
    status,
    headers: { 'Content-Type': 'application/json' }
  });

  const blockedResponse = (code, message, status = 409, extra = {}) => jsonResponse(status, {
    error: code,
    error_code: code,
    message,
    ...extra
  });

  if (!patch || typeof patch !== 'object' || Array.isArray(patch)) {
    return blockedResponse(
      'TSFIN_PATCH_INVALID_PAYLOAD',
      'TSFIN expense/mileage patch payload is invalid.',
      400
    );
  }

  const topLevelAllowed = new Set([
    'expected_timesheet_id',
    'reason',
    'expenses',
    'mileage',
    'po',
    '_save_domain',
    '_diag_request_signature_fields'
  ]);
  const topLevelUnexpected = Object.keys(patch).filter((key) => !topLevelAllowed.has(key));
  if (topLevelUnexpected.length) {
    return blockedResponse(
      'TSFIN_PATCH_UNSUPPORTED_FIELDS',
      'TSFIN expense/mileage patch includes unsupported fields.',
      400,
      { fields: topLevelUnexpected }
    );
  }

  const diagNum0 = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };
  const diagRound2 = (v) => Math.round(diagNum0(v) * 100) / 100;
  const diagString = (v) => {
    const s = String(v == null ? '' : v).trim();
    return s || null;
  };
  const diagErrorText = (err) => {
    const s = String(err?.message || err || '').trim();
    return s ? s.slice(0, 300) : null;
  };
  const diagPath = (() => {
    try {
      return new URL(req.url).pathname;
    } catch {
      return null;
    }
  })();
  const diagSaveDomain = String(
    patch._save_domain ||
    (patch.expenses ? 'EXPENSES' : (patch.mileage ? 'MILEAGE' : (patch.po ? 'PO' : 'TSFIN')))
  ).toUpperCase();

  const diagSectionPresence = {
    expenses: !!patch.expenses,
    mileage: !!patch.mileage,
    po: !!patch.po
  };

  const diagChangedFieldNames = (obj) => {
    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return [];
    return Object.keys(obj).filter((key) => obj[key] !== undefined);
  };

  const diagExtractSignature = (obj) => {
    if (!obj || typeof obj !== 'object') {
      const s = diagString(obj);
      return {
        present: !!s,
        backend_row_signature: null,
        mutation_row_signature: null,
        row_signature: null,
        expected_row_signature: null,
        current_row_signature: null,
        signature: s
      };
    }

    const backend = diagString(obj.backend_row_signature);
    const mutation = diagString(obj.mutation_row_signature);
    const row = diagString(obj.row_signature);
    const expected = diagString(obj.expected_row_signature);
    const current = diagString(obj.current_row_signature);
    const generic = diagString(obj.signature || obj.render_signature);

    return {
      present: !!(backend || mutation || row || expected || current || generic),
      backend_row_signature: backend,
      mutation_row_signature: mutation,
      row_signature: row,
      expected_row_signature: expected,
      current_row_signature: current,
      signature: backend || mutation || row || expected || current || generic || null
    };
  };

  const diagTsfinSummary = (row) => {
    if (!row || typeof row !== 'object') return null;
    return {
      tsfin_id: row.id || null,
      timesheet_id: row.timesheet_id || null,
      is_current: row.is_current === true,
      is_stale: row.is_stale === true,
      stale_reason: row.stale_reason || null,
      processing_status: row.processing_status || null,
      updated_at: row.updated_at || null,
      computed_at_utc: row.computed_at_utc || null,
      authorised_at_utc: row.authorised_at_utc || null,
      paid: !!row.paid_at_utc,
      locked_by_invoice: !!row.locked_by_invoice_id,
      travel_pay_ex_vat: diagRound2(row.travel_pay_ex_vat),
      travel_charge_ex_vat: diagRound2(row.travel_charge_ex_vat),
      accommodation_pay_ex_vat: diagRound2(row.accommodation_pay_ex_vat),
      accommodation_charge_ex_vat: diagRound2(row.accommodation_charge_ex_vat),
      other_pay_ex_vat: diagRound2(row.other_pay_ex_vat),
      other_charge_ex_vat: diagRound2(row.other_charge_ex_vat),
      expenses_pay_ex_vat: diagRound2(row.expenses_pay_ex_vat),
      expenses_charge_ex_vat: diagRound2(row.expenses_charge_ex_vat),
      mileage_units: diagRound2(row.mileage_units),
      mileage_pay_ex_vat: diagRound2(row.mileage_pay_ex_vat),
      mileage_charge_ex_vat: diagRound2(row.mileage_charge_ex_vat),
      mileage_pay_rate: row.mileage_pay_rate == null ? null : diagRound2(row.mileage_pay_rate),
      mileage_charge_rate: row.mileage_charge_rate == null ? null : diagRound2(row.mileage_charge_rate),
      additional_pay_ex_vat: diagRound2(row.additional_pay_ex_vat),
      additional_charge_ex_vat: diagRound2(row.additional_charge_ex_vat),
      total_pay_ex_vat: diagRound2(row.total_pay_ex_vat),
      total_charge_ex_vat: diagRound2(row.total_charge_ex_vat),
      margin_ex_vat: diagRound2(row.margin_ex_vat),
      po_number_present: diagString(row.po_number) ? true : false
    };
  };

  const diagTimesheetSummary = (row) => {
    if (!row || typeof row !== 'object') return null;
    return {
      timesheet_id: row.timesheet_id || null,
      is_current: row.is_current === true,
      contract_id: row.contract_id || null,
      authorised: row.authorised_at_server != null && String(row.authorised_at_server).trim() !== '',
      authorised_at_server: row.authorised_at_server || null,
      revoked: row.revoked_at != null && String(row.revoked_at).trim() !== '',
      revoked_at: row.revoked_at || null,
      sheet_scope: row.sheet_scope || null,
      submission_mode: row.submission_mode || null,
      line_type: row.line_type || null,
      is_adjustment: row.is_adjustment === true,
      qr_status: row.qr_status || null
    };
  };

  const diagResponseContains = (payload) => {
    const lp = payload?.lifecycle_patch && typeof payload.lifecycle_patch === 'object' ? payload.lifecycle_patch : null;
    const tsfin = payload?.tsfin && typeof payload.tsfin === 'object' ? payload.tsfin : null;
    return {
      updated: Object.prototype.hasOwnProperty.call(payload || {}, 'updated'),
      tsfin: !!tsfin,
      timesheet: !!(payload?.timesheet && typeof payload.timesheet === 'object'),
      backend_row_signature: !!diagString(payload?.backend_row_signature),
      mutation_row_signature: !!diagString(payload?.mutation_row_signature),
      row_signature: !!diagString(payload?.row_signature),
      expected_row_signature: !!diagString(payload?.expected_row_signature),
      lifecycle_signature: !!payload?.lifecycle_signature,
      lifecycle_signature_has_signature: diagExtractSignature(payload?.lifecycle_signature).present,
      lifecycle_patch: !!lp,
      lifecycle_patch_backend_row_signature: !!diagString(lp?.backend_row_signature),
      lifecycle_patch_mutation_row_signature: !!diagString(lp?.mutation_row_signature),
      lifecycle_patch_row_signature: !!diagString(lp?.row_signature),
      lifecycle_patch_expected_row_signature: !!diagString(lp?.expected_row_signature),
      affected_rows: Array.isArray(payload?.affected_rows),
      affected_rows_count: Array.isArray(payload?.affected_rows) ? payload.affected_rows.length : null,
      action_flags: !!(payload?.action_flags || lp?.action_flags),
      priority_badge_hints: !!(payload?.priority_badge_hints || lp?.priority_badge_hints),
      refresh_hints: !!payload?.refresh_hints,
      dirty_state: !!payload?.dirty_state,
      save_patch_available: payload?.save_patch_available === true,
      immediate_lifecycle_patch_available: payload?.immediate_lifecycle_patch_available === true,
      requires_affected_row_refresh: payload?.requires_affected_row_refresh === true,
      requires_full_details_refresh: payload?.requires_full_details_refresh === true,
      refresh_required: payload?.refresh_required === true,
      permission_state_patch_complete: payload?.permission_state_patch_complete === true,
      priority_badges_patch_complete: payload?.priority_badges_patch_complete === true
    };
  };

  const logTsfinSaveDiag = (step, details = {}) => {
    try {
      const payload = {
        tag: 'TSFIN_SAVE_SIGNATURE_DIAG',
        handler: 'patchTsfinCommon',
        step,
        route_family: diagSaveDomain,
        route_path: diagPath,
        requested_timesheet_id: timesheetId || null,
        expected_timesheet_id: patch?.expected_timesheet_id || null,
        patch_sections: diagSectionPresence,
        patch_field_names: {
          expenses: diagChangedFieldNames(patch?.expenses),
          mileage: diagChangedFieldNames(patch?.mileage),
          po: diagChangedFieldNames(patch?.po)
        },
        request_signature_fields: patch?._diag_request_signature_fields || null,
        server_utc: new Date().toISOString(),
        ...details
      };
      console.log('[TSFIN_SAVE_SIGNATURE_DIAG]', JSON.stringify(payload));
    } catch (err) {
      try {
        console.log('[TSFIN_SAVE_SIGNATURE_DIAG]', {
          handler: 'patchTsfinCommon',
          step,
          route_family: diagSaveDomain,
          requested_timesheet_id: timesheetId || null,
          log_error: diagErrorText(err)
        });
      } catch {}
    }
  };

  const fetchLifecycleSignatureForDiag = async (pTimesheetId, pContractWeekId) => {
    try {
      const payload = await sbRpc(env, 'timesheet_lifecycle_signature_v1', {
        p_timesheet_id: pTimesheetId,
        p_contract_week_id: pContractWeekId || null,
        p_include_payload: false
      }, { timeoutMs: 8000 });

      const obj = Array.isArray(payload) ? (payload[0] || null) : payload;
      const signature = diagExtractSignature(obj);
      return {
        ok: signature.present,
        source: 'timesheet_lifecycle_signature_v1',
        signature,
        payload_field_names: obj && typeof obj === 'object' ? Object.keys(obj).slice(0, 50) : []
      };
    } catch (err) {
      return {
        ok: false,
        source: 'timesheet_lifecycle_signature_v1',
        error: diagErrorText(err)
      };
    }
  };

  logTsfinSaveDiag('received');

  const rejectUnsupportedNestedFields = (sectionName, value, allowedFields) => {
    if (value === undefined || value === null) return null;
    if (typeof value !== 'object' || Array.isArray(value)) {
      return blockedResponse(
        'TSFIN_PATCH_INVALID_PAYLOAD',
        `${sectionName} patch payload is invalid.`,
        400
      );
    }
    const unexpected = Object.keys(value).filter((key) => !allowedFields.has(key));
    if (!unexpected.length) return null;
    return blockedResponse(
      'TSFIN_PATCH_UNSUPPORTED_FIELDS',
      `${sectionName} patch includes unsupported fields.`,
      400,
      { section: sectionName, fields: unexpected }
    );
  };

  const expensesFieldError = rejectUnsupportedNestedFields('expenses', patch.expenses, new Set([
    'travel_pay_ex_vat',
    'travel_charge_ex_vat',
    'accommodation_pay_ex_vat',
    'accommodation_charge_ex_vat',
    'other_pay_ex_vat',
    'other_charge_ex_vat',
    'description'
  ]));
  if (expensesFieldError) {
    logTsfinSaveDiag('blocked_nested_fields', {
      section: 'expenses',
      status: expensesFieldError.status || 400
    });
    return expensesFieldError;
  }

  const mileageFieldError = rejectUnsupportedNestedFields('mileage', patch.mileage, new Set([
    'mileage_units',
    'pay_ex_vat',
    'charge_ex_vat',
    'pay_rate',
    'charge_rate'
  ]));
  if (mileageFieldError) {
    logTsfinSaveDiag('blocked_nested_fields', {
      section: 'mileage',
      status: mileageFieldError.status || 400
    });
    return mileageFieldError;
  }

  const poFieldError = rejectUnsupportedNestedFields('po', patch.po, new Set(['number']));
  if (poFieldError) {
    logTsfinSaveDiag('blocked_nested_fields', {
      section: 'po',
      status: poFieldError.status || 400
    });
    return poFieldError;
  }

  const expected = (patch && patch.expected_timesheet_id) ? String(patch.expected_timesheet_id) : '';
  if (!expected) {
    logTsfinSaveDiag('blocked_missing_expected_timesheet_id', {
      status: 400
    });
    return badRequest('expected_timesheet_id is required');
  }

  const resolved = await resolveTimesheetToCurrent(env, timesheetId);
  if (!resolved || !resolved.current_timesheet_id) {
    logTsfinSaveDiag('blocked_not_found_after_resolve', {
      status: 404,
      resolved_present: !!resolved
    });
    return notFound('Timesheet not found');
  }

  const currentTimesheetId = String(resolved.current_timesheet_id);
  logTsfinSaveDiag('resolved_current', {
    current_timesheet_id: currentTimesheetId,
    requested_timesheet_id: resolved.requested_timesheet_id || timesheetId || null,
    booking_id: resolved.booking_id || null,
    current_version: resolved.current_version ?? null,
    was_stale: !!resolved.was_stale
  });

  if (expected !== currentTimesheetId) {
    const payload = {
      error: 'TIMESHEET_MOVED',
      booking_id: resolved.booking_id || null,
      requested_timesheet_id: resolved.requested_timesheet_id || timesheetId || null,
      current_timesheet_id: resolved.current_timesheet_id || null,
      current_version: resolved.current_version != null ? resolved.current_version : null
    };
    logTsfinSaveDiag('blocked_timesheet_moved', {
      status: 409,
      current_timesheet_id: currentTimesheetId,
      requested_timesheet_id: resolved.requested_timesheet_id || timesheetId || null,
      current_version: resolved.current_version ?? null
    });
    return jsonResponse(409, payload);
  }

  const currentTs = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=timesheet_id,is_current,contract_id,authorised_at_server,revoked_at,sheet_scope,submission_mode,line_type,is_adjustment,adjustment_origin,parent_timesheet_id,qr_status,additional_units_week,additional_units_per_day`
  );
  if (!currentTs) {
    logTsfinSaveDiag('blocked_current_timesheet_not_found', {
      status: 404,
      current_timesheet_id: currentTimesheetId
    });
    return notFound('Timesheet not found');
  }

  const isCurrentRow = currentTs.is_current === true;
  const hasAuthorisedAtServer = currentTs.authorised_at_server != null && String(currentTs.authorised_at_server).trim() !== '';
  const hasRevokedAt = currentTs.revoked_at != null && String(currentTs.revoked_at).trim() !== '';

  if (isCurrentRow && hasAuthorisedAtServer && !hasRevokedAt) {
    logTsfinSaveDiag('blocked_authorised_edit', {
      status: 409,
      current_timesheet_id: currentTimesheetId,
      timesheet: diagTimesheetSummary(currentTs)
    });
    return blockedResponse(
      'TIMESHEET_AUTHORISED_EDIT_BLOCKED',
      'This timesheet is authorised. Unauthorise it before changing expenses or mileage.'
    );
  }

  const before = await fetchCurrentTsfin(env, currentTimesheetId);
  if (!before) {
    logTsfinSaveDiag('blocked_tsfin_current_not_found', {
      status: 404,
      current_timesheet_id: currentTimesheetId
    });
    return notFound('TSFIN current row not found');
  }

  const summary = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary_base` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&select=timesheet_id,client_no_timesheet_required,basis,route_type,additional_seq,is_adjustment,is_qr,qr_status,paid_at_utc,locked_by_invoice_id,invoice_segments_locked,client_is_nhsp` +
      `&limit=1`
  ).catch(() => null);

  const contract = currentTs?.contract_id
    ? await sbGetOne(
        env,
        `${env.SUPABASE_URL}/rest/v1/contracts` +
          `?id=eq.${enc(currentTs.contract_id)}` +
          `&select=id,self_bill,no_timesheet_required,weekly_timesheet_source,is_nhsp` +
          `&limit=1`
      ).catch(() => null)
    : null;

  const cw = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&select=id,totals_json,additional_seq,submission_mode_snapshot,is_adjustment` +
      `&limit=1`
  ).catch(() => null);

  const beforeSignatureDiag = await fetchLifecycleSignatureForDiag(currentTimesheetId, cw?.id || null);
  logTsfinSaveDiag('before_write', {
    current_timesheet_id: currentTimesheetId,
    contract_week_id: cw?.id || null,
    timesheet: diagTimesheetSummary(currentTs),
    before: diagTsfinSummary(before),
    before_signature: beforeSignatureDiag
  });

  const yes = (v) => {
    if (v === true) return true;
    if (v === false || v == null) return false;
    const s = String(v).trim().toLowerCase();
    return s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on';
  };
  const up = (v) => String(v == null ? '' : v).trim().toUpperCase();

  const routeTypeU = up(summary?.route_type || contract?.weekly_timesheet_source);
  const basisU = up(summary?.basis ?? before?.basis);
  const actualRouteOrBasisText = [routeTypeU, basisU].filter(Boolean).join('|');
  const derivedRouteFamily = actualRouteOrBasisText.includes('NHSP')
    ? 'NHSP'
    : actualRouteOrBasisText.includes('HEALTHROSTER')
      ? 'HEALTHROSTER'
      : actualRouteOrBasisText.includes('IMPORT')
        ? 'IMPORT'
        : '';

  const classificationContext = {
    ...(summary || {}),
    ...(currentTs || {}),
    basis: summary?.basis ?? before?.basis ?? null,
    route_type: summary?.route_type ?? contract?.weekly_timesheet_source ?? null,
    route_family: derivedRouteFamily,
    additional_seq: summary?.additional_seq ?? cw?.additional_seq ?? null,
    is_adjustment: currentTs?.is_adjustment ?? summary?.is_adjustment ?? cw?.is_adjustment ?? null,
    submission_mode: currentTs?.submission_mode ?? cw?.submission_mode_snapshot ?? null,
    self_bill: contract?.self_bill ?? false,
    no_timesheet_required: contract?.no_timesheet_required ?? false,
    contract_no_timesheet_required: contract?.no_timesheet_required ?? false,
    client_no_timesheet_required: summary?.client_no_timesheet_required ?? false,
    weekly_timesheet_source: contract?.weekly_timesheet_source ?? null,
    client_is_nhsp: summary?.client_is_nhsp ?? false,
    is_nhsp: contract?.is_nhsp ?? false,
    invoice_breakdown_json: before?.invoice_breakdown_json ?? null,
    invoice_segments_locked: summary?.invoice_segments_locked ?? 0,
    locked_by_invoice_id: before?.locked_by_invoice_id ?? summary?.locked_by_invoice_id ?? null,
    paid_at_utc: before?.paid_at_utc ?? summary?.paid_at_utc ?? null,
    is_qr: summary?.is_qr ?? null,
    qr_status: currentTs?.qr_status ?? summary?.qr_status ?? null
  };

  if (isImportAuthoritativeEvidenceContext(classificationContext)) {
    logTsfinSaveDiag('blocked_import_authoritative', {
      status: 409,
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null
    });
    return blockedResponse(
      'IMPORT_AUTHORITATIVE_EXPENSES_BLOCKED',
      'This original import-authoritative timesheet is view-only for direct expenses. Create an additional manual timesheet for expenses.'
    );
  }

  const lineTypeU = String(classificationContext?.line_type || '').toUpperCase();
  const sheetScopeU = String(classificationContext?.sheet_scope || '').toUpperCase();
  const segmentOnlyTarget =
    lineTypeU === 'SEGMENT' ||
    lineTypeU === 'SEGMENT_ONLY' ||
    sheetScopeU === 'SEGMENT' ||
    yes(classificationContext?.segment_only) ||
    !!classificationContext?.segment_id ||
    !!classificationContext?.segment_stable_key;

  if (segmentOnlyTarget) {
    logTsfinSaveDiag('blocked_segment_context', {
      status: 409,
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null,
      line_type: lineTypeU || null,
      sheet_scope: sheetScopeU || null
    });
    return blockedResponse(
      'SEGMENT_CONTEXT_EXPENSES_BLOCKED',
      'This segment-only context cannot be amended via parent-level expense or mileage endpoints.'
    );
  }

  const toNum = (v) => {
    if (v === null || v === undefined || v === '') return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : NaN;
  };
  const nonneg = (value) => {
    if (value === null || value === undefined || value === '') return true;
    const n = Number(value);
    return Number.isFinite(n) && n >= 0;
  };
  const num0 = (v) => {
    const n = toNum(v);
    return (n == null || Number.isNaN(n)) ? 0 : n;
  };
  const finiteOrNull = (v) => {
    const n = toNum(v);
    return (n == null || Number.isNaN(n)) ? null : n;
  };
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const hasOwn = (obj, key) => !!(obj && typeof obj === 'object' && Object.prototype.hasOwnProperty.call(obj, key));
  const explicitFiniteRate = (obj, key) => {
    if (!hasOwn(obj, key)) return { supplied: false, valid: false, value: null };
    const raw = obj[key];
    if (raw === null || raw === undefined || raw === '') return { supplied: false, valid: false, value: null };
    const n = Number(raw);
    if (!Number.isFinite(n) || n < 0) return { supplied: true, valid: false, value: null };
    return { supplied: true, valid: true, value: n };
  };

  const normalizeExpensesDescription = (v) => {
    if (v === undefined) return undefined;
    if (v === null) return null;
    if (typeof v === 'string') return v;
    try {
      if (typeof v === 'object') return JSON.stringify(v);
    } catch {}
    return String(v);
  };
  const extractExpenseDraftNote = (v) => {
    if (v === undefined || v === null) return '';
    if (typeof v === 'object') {
      const obj = v || {};
      return String(obj.note ?? obj.notes ?? obj.description ?? '').trim();
    }
    const s = String(v || '').trim();
    if (!s) return '';
    if ((s.startsWith('{') && s.endsWith('}')) || (s.startsWith('[') && s.endsWith(']'))) {
      try {
        const parsed = JSON.parse(s);
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          return String(parsed.note ?? parsed.notes ?? parsed.description ?? '').trim();
        }
      } catch {}
    }
    return s;
  };

  const additionalUnitNonCountNumericKeys = new Set([
    'pay_ex_vat',
    'charge_ex_vat',
    'margin_ex_vat',
    'pay_rate',
    'charge_rate',
    'rate',
    'amount',
    'pay',
    'charge',
    'margin',
    'price',
    'cost',
    'total',
    'total_pay',
    'total_charge',
    'total_margin',
    'total_pay_ex_vat',
    'total_charge_ex_vat',
    'total_margin_ex_vat',
    'vat',
    'vat_rate',
    'inc_vat',
    'code',
    'label',
    'name',
    'id',
    'sort_order',
    'order',
    'seq',
    'sequence',
    'version',
    'day_index',
    'additional_seq',
    'week',
    'date'
  ]);

  const additionalUnitHasNonZeroNumericSignal = (value, key = '') => {
    if (value === null || value === undefined || value === '') return false;

    if (typeof value === 'number' || typeof value === 'string') {
      const keyNorm = String(key == null ? '' : key).trim().toLowerCase();
      if (additionalUnitNonCountNumericKeys.has(keyNorm)) return false;
      const n = Number(value);
      return Number.isFinite(n) && n !== 0;
    }

    if (Array.isArray(value)) {
      return value.some((entry) => additionalUnitHasNonZeroNumericSignal(entry, key));
    }

    if (typeof value === 'object') {
      return Object.entries(value).some(([childKey, entry]) => additionalUnitHasNonZeroNumericSignal(entry, childKey));
    }

    return false;
  };

  const summariseAdditionalUnits = (unitsRaw) => {
    const unitsObj = (unitsRaw && typeof unitsRaw === 'object' && !Array.isArray(unitsRaw)) ? unitsRaw : {};
    let hasUnitRows = false;
    let hasAmountFields = false;
    let pay = 0;
    let charge = 0;

    for (const [unitKey, unit] of Object.entries(unitsObj)) {
      if (unit === null || unit === undefined || unit === '') continue;

      const hasUnitSignal = additionalUnitHasNonZeroNumericSignal(unit, unitKey);
      if (hasUnitSignal) hasUnitRows = true;

      if (!hasUnitSignal || !unit || typeof unit !== 'object' || Array.isArray(unit)) continue;

      if (Object.prototype.hasOwnProperty.call(unit, 'pay_ex_vat')) {
        hasAmountFields = true;
        pay += num0(unit.pay_ex_vat);
      }
      if (Object.prototype.hasOwnProperty.call(unit, 'charge_ex_vat')) {
        hasAmountFields = true;
        charge += num0(unit.charge_ex_vat);
      }
    }

    return {
      hasUnitRows,
      hasAmountFields,
      pay: round2(pay),
      charge: round2(charge)
    };
  };

  const KIND_ALIASES = {
    MILEAGE: ['MILEAGE', 'Mileage', 'mileage'],
    TRAVEL: ['TRAVEL', 'Travel', 'travel', 'EXPENSES', 'Expenses', 'expenses'],
    ACCOMMODATION: ['ACCOMMODATION', 'Accommodation', 'accommodation'],
    OTHER: ['OTHER', 'Other', 'other'],
  };

  const hasEvidenceForAnyKind = async (kinds) => {
    const ks = Array.isArray(kinds) ? kinds.filter(Boolean) : [];
    if (!ks.length) return false;

    const inParam = `in.(${ks.join(',')})`;
    const url =
      `${env.SUPABASE_URL}/rest/v1/timesheet_evidence` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&kind=${enc(inParam)}` +
      `&select=id` +
      `&limit=1`;

    try {
      const { rows } = await sbFetch(env, url);
      return !!(rows && rows[0] && rows[0].id);
    } catch {
      return false;
    }
  };

  const evidenceError = (missingArr) => {
    return new Response(JSON.stringify({
      error: 'EVIDENCE_REQUIRED',
      error_code: 'EVIDENCE_REQUIRED',
      missing: missingArr
    }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' }
    });
  };

  if (patch.expenses) {
    const xp = patch.expenses;
    if (!nonneg(xp.travel_pay_ex_vat) || !nonneg(xp.travel_charge_ex_vat) ||
        !nonneg(xp.accommodation_pay_ex_vat) || !nonneg(xp.accommodation_charge_ex_vat) ||
        !nonneg(xp.other_pay_ex_vat) || !nonneg(xp.other_charge_ex_vat)) {
      logTsfinSaveDiag('blocked_invalid_expense_values', {
        status: 400,
        current_timesheet_id: currentTimesheetId,
        contract_week_id: cw?.id || null
      });
      return badRequest('Expense values must be >= 0');
    }
  }

  if (patch.mileage) {
    const ml = patch.mileage;
    if (!nonneg(ml.mileage_units) || !nonneg(ml.pay_ex_vat) || !nonneg(ml.charge_ex_vat) || !nonneg(ml.pay_rate) || !nonneg(ml.charge_rate)) {
      logTsfinSaveDiag('blocked_invalid_mileage_values', {
        status: 400,
        current_timesheet_id: currentTimesheetId,
        contract_week_id: cw?.id || null
      });
      return badRequest('Mileage values must be >= 0');
    }
  }

  if ((before.paid_at_utc || summary?.paid_at_utc) && patch.po && hasOwn(patch.po, 'number')) {
    logTsfinSaveDiag('blocked_paid_po_edit', {
      status: 409,
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null,
      before: diagTsfinSummary(before)
    });
    return blockedResponse(
      'TIMESHEET_PAID_EDIT_BLOCKED',
      'This timesheet has been paid and its purchase order cannot be amended directly.'
    );
  }

  const segmentInvoiceLocked = hasAnySegmentInvoiceLock(before) || Number(summary?.invoice_segments_locked || 0) > 0;
  const wholeInvoiceLocked = !!(before.locked_by_invoice_id || summary?.locked_by_invoice_id);
  if (wholeInvoiceLocked || segmentInvoiceLocked) {
    logTsfinSaveDiag('blocked_invoice_locked', {
      status: 409,
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null,
      whole_invoice_locked: wholeInvoiceLocked,
      segment_invoice_locked: segmentInvoiceLocked,
      before: diagTsfinSummary(before)
    });
    return blockedResponse(
      segmentInvoiceLocked ? 'TIMESHEET_SEGMENT_INVOICE_LOCKED_EDIT_BLOCKED' : 'TIMESHEET_INVOICE_LOCKED_EDIT_BLOCKED',
      segmentInvoiceLocked
        ? 'This timesheet has invoice-locked segments. Create an additional manual adjustment for any further expenses.'
        : 'This timesheet is invoice locked. Create an additional manual adjustment for any further expenses.'
    );
  }

  let afterTravelPay = num0(before.travel_pay_ex_vat);
  let afterTravelChg = num0(before.travel_charge_ex_vat);
  let afterAccomPay  = num0(before.accommodation_pay_ex_vat);
  let afterAccomChg  = num0(before.accommodation_charge_ex_vat);
  let afterOtherPay  = num0(before.other_pay_ex_vat);
  let afterOtherChg  = num0(before.other_charge_ex_vat);

  let afterMileageUnits = num0(before.mileage_units);
  let afterMileagePay   = num0(before.mileage_pay_ex_vat);
  let afterMileageChg   = num0(before.mileage_charge_ex_vat);
  let afterMileagePayRate = finiteOrNull(before.mileage_pay_rate);
  let afterMileageChargeRate = finiteOrNull(before.mileage_charge_rate);

  if (patch.expenses) {
    const xp = patch.expenses;

    if (xp.travel_pay_ex_vat !== undefined)        afterTravelPay = num0(xp.travel_pay_ex_vat);
    if (xp.travel_charge_ex_vat !== undefined)     afterTravelChg = num0(xp.travel_charge_ex_vat);

    if (xp.accommodation_pay_ex_vat !== undefined)    afterAccomPay = num0(xp.accommodation_pay_ex_vat);
    if (xp.accommodation_charge_ex_vat !== undefined) afterAccomChg = num0(xp.accommodation_charge_ex_vat);

    if (xp.other_pay_ex_vat !== undefined)         afterOtherPay = num0(xp.other_pay_ex_vat);
    if (xp.other_charge_ex_vat !== undefined)      afterOtherChg = num0(xp.other_charge_ex_vat);
  }

  let mileageUnitsTouched = false;
  let mileagePayExplicit = false;
  let mileageChargeExplicit = false;
  let mileagePayRateTouched = false;
  let mileageChargeRateTouched = false;
  let mileagePayRateSupplied = false;
  let mileageChargeRateSupplied = false;

  if (patch.mileage) {
    const ml = patch.mileage;
    const payRatePatch = explicitFiniteRate(ml, 'pay_rate');
    const chargeRatePatch = explicitFiniteRate(ml, 'charge_rate');

    if (payRatePatch.supplied && !payRatePatch.valid) {
      logTsfinSaveDiag('blocked_invalid_mileage_pay_rate', {
        status: 400,
        current_timesheet_id: currentTimesheetId,
        contract_week_id: cw?.id || null
      });
      return badRequest('Mileage values must be >= 0');
    }
    if (chargeRatePatch.supplied && !chargeRatePatch.valid) {
      logTsfinSaveDiag('blocked_invalid_mileage_charge_rate', {
        status: 400,
        current_timesheet_id: currentTimesheetId,
        contract_week_id: cw?.id || null
      });
      return badRequest('Mileage values must be >= 0');
    }

    mileageUnitsTouched = ml.mileage_units !== undefined;
    mileagePayExplicit = ml.pay_ex_vat !== undefined;
    mileageChargeExplicit = ml.charge_ex_vat !== undefined;
    mileagePayRateTouched = hasOwn(ml, 'pay_rate');
    mileageChargeRateTouched = hasOwn(ml, 'charge_rate');
    mileagePayRateSupplied = payRatePatch.supplied && payRatePatch.valid;
    mileageChargeRateSupplied = chargeRatePatch.supplied && chargeRatePatch.valid;

    if (ml.mileage_units !== undefined) afterMileageUnits = num0(ml.mileage_units);
    if (mileagePayRateSupplied) afterMileagePayRate = payRatePatch.value;
    if (mileageChargeRateSupplied) afterMileageChargeRate = chargeRatePatch.value;

    if (afterMileageUnits > 0 && (afterMileagePayRate == null || afterMileageChargeRate == null)) {
      logTsfinSaveDiag('blocked_mileage_rate_missing', {
        status: 400,
        current_timesheet_id: currentTimesheetId,
        contract_week_id: cw?.id || null,
        after_mileage_units: round2(afterMileageUnits),
        pay_rate_present: afterMileagePayRate != null,
        charge_rate_present: afterMileageChargeRate != null
      });
      return blockedResponse(
        'MILEAGE_RATE_MISSING',
        'Mileage rates are missing, so mileage cannot be saved. Check the stored mileage rates, then try again.',
        400
      );
    }

    if (afterMileageUnits > 0) {
      afterMileagePay = round2(afterMileageUnits * afterMileagePayRate);
      afterMileageChg = round2(afterMileageUnits * afterMileageChargeRate);
    } else if (mileageUnitsTouched || mileagePayExplicit || mileageChargeExplicit || mileagePayRateTouched || mileageChargeRateTouched) {
      afterMileagePay = 0;
      afterMileageChg = 0;
    }
  }

  const missing = [];

  if (afterMileageUnits > 0 || afterMileagePay > 0 || afterMileageChg > 0) {
    const ok = await hasEvidenceForAnyKind(KIND_ALIASES.MILEAGE);
    if (!ok) missing.push({ category: 'mileage', required_kind: 'MILEAGE' });
  }

  if (afterTravelPay > 0 || afterTravelChg > 0) {
    const ok = await hasEvidenceForAnyKind(KIND_ALIASES.TRAVEL);
    if (!ok) missing.push({ category: 'travel', required_kind: 'TRAVEL' });
  }

  if (afterAccomPay > 0 || afterAccomChg > 0) {
    const ok = await hasEvidenceForAnyKind(KIND_ALIASES.ACCOMMODATION);
    if (!ok) missing.push({ category: 'accommodation', required_kind: 'ACCOMMODATION' });
  }

  if (afterOtherPay > 0 || afterOtherChg > 0) {
    const ok = await hasEvidenceForAnyKind(KIND_ALIASES.OTHER);
    if (!ok) missing.push({ category: 'other', required_kind: 'OTHER' });
  }

  if (missing.length) {
    logTsfinSaveDiag('blocked_evidence_required', {
      status: 400,
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null,
      missing
    });
    return evidenceError(missing);
  }

  const upd = {};
  const nowISO = nowIso();

  if (patch.expenses) {
    const xp = patch.expenses;

    if (xp.travel_pay_ex_vat !== undefined)        upd.travel_pay_ex_vat = afterTravelPay;
    if (xp.travel_charge_ex_vat !== undefined)     upd.travel_charge_ex_vat = afterTravelChg;

    if (xp.accommodation_pay_ex_vat !== undefined)    upd.accommodation_pay_ex_vat = afterAccomPay;
    if (xp.accommodation_charge_ex_vat !== undefined) upd.accommodation_charge_ex_vat = afterAccomChg;

    if (xp.other_pay_ex_vat !== undefined)         upd.other_pay_ex_vat = afterOtherPay;
    if (xp.other_charge_ex_vat !== undefined)      upd.other_charge_ex_vat = afterOtherChg;

    const sumPay = round2(num0(afterTravelPay) + num0(afterAccomPay) + num0(afterOtherPay));
    const sumChg = round2(num0(afterTravelChg) + num0(afterAccomChg) + num0(afterOtherChg));

    upd.expenses_pay_ex_vat = sumPay;
    upd.expenses_charge_ex_vat = sumChg;

    const desc = normalizeExpensesDescription(xp.description);
    if (desc !== undefined) upd.expenses_description = desc;
  }

  if (patch.mileage) {
    const mileageValueTouched = mileageUnitsTouched || mileagePayExplicit || mileageChargeExplicit || mileagePayRateTouched || mileageChargeRateTouched;

    if (mileageUnitsTouched) upd.mileage_units = afterMileageUnits;
    if (mileageValueTouched) upd.mileage_pay_ex_vat = afterMileagePay;
    if (mileageValueTouched) upd.mileage_charge_ex_vat = afterMileageChg;
    if (mileagePayRateSupplied && afterMileagePayRate !== finiteOrNull(before.mileage_pay_rate)) upd.mileage_pay_rate = afterMileagePayRate;
    if (mileageChargeRateSupplied && afterMileageChargeRate !== finiteOrNull(before.mileage_charge_rate)) upd.mileage_charge_rate = afterMileageChargeRate;
  }

  if (patch.po && patch.po.number !== undefined) {
    upd.po_number = (patch.po.number ?? null);
  }

  if (!Object.keys(upd).length) {
    let lifecycleSignatureObject = null;
    let lifecycleSignature = '';
    try {
      const signaturePayload = await sbRpc(env, 'timesheet_lifecycle_signature_v1', {
        p_timesheet_id: currentTimesheetId,
        p_contract_week_id: cw?.id || null,
        p_include_payload: false
      }, { timeoutMs: 8000 });
      const signatureObj = Array.isArray(signaturePayload) ? (signaturePayload[0] || null) : signaturePayload;
      const signatureText = String(
        signatureObj?.backend_row_signature ||
        signatureObj?.mutation_row_signature ||
        signatureObj?.row_signature ||
        signatureObj?.expected_row_signature ||
        signatureObj?.signature ||
        ''
      ).trim();
      if (signatureText) {
        lifecycleSignatureObject = signatureObj;
        lifecycleSignature = signatureText;
      }
    } catch {}

    const savePatchBundle = buildTimesheetLifecyclePatchFromMutation({
      action: 'SAVE',
      requestedTimesheetId: resolved.requested_timesheet_id || timesheetId || null,
      currentTimesheetId,
      currentVersion: resolved.current_version ?? null,
      contractWeekId: cw?.id || null,
      bookingId: resolved.booking_id || null,
      candidateId: before?.candidate_id || null,
      tsfinRow: before,
      currentTimesheetRow: currentTs,
      newProcessingStatus: before?.processing_status || null,
      backendRowSignature: lifecycleSignature || null,
      rowSignature: lifecycleSignature || null,
      expectedRowSignature: lifecycleSignature || null,
      authorised: false,
      readyToPay: null,
      staleMarkers: { was_stale: !!resolved.was_stale }
    });

    const responsePayload = {
      updated: false,
      tsfin: before,
      save_domain: patch._save_domain || (patch.expenses ? 'EXPENSES' : (patch.mileage ? 'MILEAGE' : (patch.po ? 'PO' : 'TSFIN'))),
      booking_id: resolved.booking_id || null,
      requested_timesheet_id: resolved.requested_timesheet_id || timesheetId || null,
      current_timesheet_id: currentTimesheetId,
      timesheet_id: currentTimesheetId,
      current_version: resolved.current_version ?? null,
      was_stale: !!resolved.was_stale,
      processing_status: before?.processing_status || null,
      authorised: false,
      contract_week_id: cw?.id || null,
      backend_row_signature: lifecycleSignature || null,
      mutation_row_signature: lifecycleSignature || null,
      row_signature: lifecycleSignature || null,
      expected_row_signature: lifecycleSignature || null,
      lifecycle_signature: lifecycleSignatureObject || null,
      lifecycle_patch: savePatchBundle.lifecycle_patch,
      affected_rows: savePatchBundle.affected_rows,
      refresh_hints: savePatchBundle.refresh_hints,
      priority_badge_hints: savePatchBundle.lifecycle_patch?.priority_badge_hints || null,
      dirty_state: { is_dirty: false, clean: true, save_applied: false, no_change: true },
      save_patch_available: savePatchBundle.immediate_lifecycle_patch_available,
      authorise_preflight_refresh_required: !lifecycleSignature,
      permission_state_patch_complete: savePatchBundle.permission_state_patch_complete,
      priority_badges_patch_complete: savePatchBundle.priority_badges_patch_complete,
      immediate_lifecycle_patch_available: savePatchBundle.immediate_lifecycle_patch_available,
      requires_affected_row_refresh: savePatchBundle.requires_affected_row_refresh,
      requires_full_details_refresh: savePatchBundle.requires_full_details_refresh,
      refresh_required: savePatchBundle.refresh_required
    };

    logTsfinSaveDiag('response_shape', {
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null,
      updated: false,
      before: diagTsfinSummary(before),
      after: diagTsfinSummary(before),
      before_signature: beforeSignatureDiag,
      after_signature: diagExtractSignature(lifecycleSignatureObject || lifecycleSignature),
      response_contains: diagResponseContains(responsePayload)
    });

    return ok(responsePayload);
  }

  const beforeExpPay = round2(num0(before.expenses_pay_ex_vat));
  const beforeExpChg = round2(num0(before.expenses_charge_ex_vat));
  const beforeMilPay = round2(num0(before.mileage_pay_ex_vat));
  const beforeMilChg = round2(num0(before.mileage_charge_ex_vat));
  const beforeAddPay = round2(num0(before.additional_pay_ex_vat));
  const beforeAddChg = round2(num0(before.additional_charge_ex_vat));
  const beforeAddMargin = round2(num0(before.additional_margin_ex_vat));
  const tsfinAdditionalSummary = summariseAdditionalUnits(before.additional_units_json);
  const hasTimesheetAdditionalUnitSignal =
    additionalUnitHasNonZeroNumericSignal(currentTs?.additional_units_week) ||
    additionalUnitHasNonZeroNumericSignal(currentTs?.additional_units_per_day);
  const cwTotals = (cw?.totals_json && typeof cw.totals_json === 'object' && !Array.isArray(cw.totals_json))
    ? cw.totals_json
    : {};
  const hasContractWeekAdditionalUnitSignal =
    additionalUnitHasNonZeroNumericSignal(cwTotals.additional_units_week) ||
    additionalUnitHasNonZeroNumericSignal(cwTotals.additional_units_per_day);
  const additionalSummary = {
    hasUnitRows: tsfinAdditionalSummary.hasUnitRows || hasTimesheetAdditionalUnitSignal || hasContractWeekAdditionalUnitSignal,
    hasAmountFields: tsfinAdditionalSummary.hasAmountFields,
    pay: tsfinAdditionalSummary.pay,
    charge: tsfinAdditionalSummary.charge
  };
  const addPay = additionalSummary.hasUnitRows
    ? (additionalSummary.hasAmountFields ? additionalSummary.pay : beforeAddPay)
    : 0;
  const addChg = additionalSummary.hasUnitRows
    ? (additionalSummary.hasAmountFields ? additionalSummary.charge : beforeAddChg)
    : 0;
  const addMargin = round2(addChg - addPay);

  if (addPay !== beforeAddPay) upd.additional_pay_ex_vat = addPay;
  if (addChg !== beforeAddChg) upd.additional_charge_ex_vat = addChg;
  if (addMargin !== beforeAddMargin) upd.additional_margin_ex_vat = addMargin;

  const afterExpPay = round2(num0(upd.expenses_pay_ex_vat !== undefined ? upd.expenses_pay_ex_vat : before.expenses_pay_ex_vat));
  const afterExpChg = round2(num0(upd.expenses_charge_ex_vat !== undefined ? upd.expenses_charge_ex_vat : before.expenses_charge_ex_vat));
  const afterMilPay = round2(num0(upd.mileage_pay_ex_vat !== undefined ? upd.mileage_pay_ex_vat : before.mileage_pay_ex_vat));
  const afterMilChg = round2(num0(upd.mileage_charge_ex_vat !== undefined ? upd.mileage_charge_ex_vat : before.mileage_charge_ex_vat));

  let corePay = round2(num0(before.total_pay_ex_vat) - beforeAddPay - beforeExpPay - beforeMilPay);
  let coreChg = round2(num0(before.total_charge_ex_vat) - beforeAddChg - beforeExpChg - beforeMilChg);

  const ib = (before.invoice_breakdown_json && typeof before.invoice_breakdown_json === 'object') ? before.invoice_breakdown_json : {};
  const mode = String(ib?.mode || '').toUpperCase();

  if (mode === 'SEGMENTS' && Array.isArray(ib?.segments)) {
    let segPay = 0;
    let segChg = 0;
    for (const seg of ib.segments) {
      if (!seg || typeof seg !== 'object') continue;
      const chg = num0(seg.charge_amount);
      const pay = num0(seg.pay_amount);
      const excl = !!seg.exclude_from_pay;
      segChg += chg;
      if (!excl) segPay += pay;
    }
    corePay = round2(segPay);
    coreChg = round2(segChg);
  } else if (ib?.base_hours && typeof ib.base_hours === 'object') {
    const bhPay = num0(ib.base_hours.pay_ex_vat);
    const bhChg = num0(ib.base_hours.charge_ex_vat);
    if (bhPay || bhChg) {
      corePay = round2(bhPay);
      coreChg = round2(bhChg);
    }
  }

  if (!Number.isFinite(corePay)) corePay = 0;
  if (!Number.isFinite(coreChg)) coreChg = 0;

  const nonsegPay = round2(addPay + afterExpPay + afterMilPay);
  const nonsegChg = round2(addChg + afterExpChg + afterMilChg);

  const totalPay = round2(corePay + nonsegPay);
  const totalChg = round2(coreChg + nonsegChg);

  const pol = (before.policy_snapshot_json && typeof before.policy_snapshot_json === 'object') ? before.policy_snapshot_json : {};
  const applyTo = String(pol.apply_erni_to || 'PAYE_ONLY').toUpperCase();
  const erniPctRaw = Number(pol.erni_pct ?? 0);

  let erniMult = 1;
  if (Number.isFinite(erniPctRaw) && erniPctRaw > 0) {
    const p = erniPctRaw > 1 ? (erniPctRaw / 100) : erniPctRaw;
    erniMult = 1 + p;
  }

  const payMethodU = String(before.pay_method || '').toUpperCase();
  const erniApplies = (payMethodU === 'PAYE') && (applyTo === 'ALL' || applyTo === 'PAYE_ONLY');

  const wagePay = round2(corePay + addPay);
  const reimbPay = round2(afterExpPay + afterMilPay);
  const wageCost = round2(erniApplies ? (wagePay * erniMult) : wagePay);
  const payCost = round2(wageCost + reimbPay);

  const margin = round2(totalChg - payCost);

  const addlWageCost = round2(erniApplies ? (addPay * erniMult) : addPay);
  const nonsegPayCost = round2(addlWageCost + reimbPay);
  const nonsegMargin = round2(nonsegChg - nonsegPayCost);

  const patchedBreakdown = (() => {
    const ib0 = (before.invoice_breakdown_json && typeof before.invoice_breakdown_json === 'object') ? before.invoice_breakdown_json : {};
    const out = { ...ib0 };

    const priorAdd = (ib0.additional && typeof ib0.additional === 'object') ? ib0.additional : {};
    const units = (before.additional_units_json && typeof before.additional_units_json === 'object' && !Array.isArray(before.additional_units_json))
      ? before.additional_units_json
      : ((priorAdd.units && typeof priorAdd.units === 'object' && !Array.isArray(priorAdd.units)) ? priorAdd.units : {});

    out.additional = {
      ...priorAdd,
      units,
      pay_ex_vat: addPay,
      charge_ex_vat: addChg,
      margin_ex_vat: addMargin
    };

    const priorTot = (ib0.totals && typeof ib0.totals === 'object') ? ib0.totals : {};
    out.totals = {
      ...priorTot,
      total_pay_ex_vat: totalPay,
      total_charge_ex_vat: totalChg,
      margin_ex_vat: margin
    };

    return out;
  })();

  upd.total_pay_ex_vat = totalPay;
  upd.total_charge_ex_vat = totalChg;
  upd.margin_ex_vat = margin;
  upd.invoice_breakdown_json = patchedBreakdown;
  upd.is_stale = false;
  upd.stale_reason = null;
  upd.updated_at = nowISO;

  logTsfinSaveDiag('patch_request', {
    current_timesheet_id: currentTimesheetId,
    contract_week_id: cw?.id || null,
    changed_fields: Object.keys(upd).sort(),
    before: diagTsfinSummary(before),
    planned_after_summary: {
      travel_pay_ex_vat: round2(afterTravelPay),
      travel_charge_ex_vat: round2(afterTravelChg),
      accommodation_pay_ex_vat: round2(afterAccomPay),
      accommodation_charge_ex_vat: round2(afterAccomChg),
      other_pay_ex_vat: round2(afterOtherPay),
      other_charge_ex_vat: round2(afterOtherChg),
      expenses_pay_ex_vat: round2(afterExpPay),
      expenses_charge_ex_vat: round2(afterExpChg),
      mileage_units: round2(afterMileageUnits),
      mileage_pay_ex_vat: round2(afterMilPay),
      mileage_charge_ex_vat: round2(afterMilChg),
      additional_pay_ex_vat: round2(addPay),
      additional_charge_ex_vat: round2(addChg),
      total_pay_ex_vat: round2(totalPay),
      total_charge_ex_vat: round2(totalChg),
      margin_ex_vat: round2(margin)
    }
  });

  const url =
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
    `?timesheet_id=eq.${encodeURIComponent(currentTimesheetId)}` +
    `&is_current=eq.true` +
    `&locked_by_invoice_id=is.null`;

  const res = await fetch(url, {
    method: 'PATCH',
    headers: { ...sbHeaders(env), 'Prefer': 'return=representation' },
    body: JSON.stringify(upd),
  });

  if (!res.ok) {
    const t = await res.text();
    logTsfinSaveDiag('patch_failed', {
      status: res.status,
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null,
      error_text: String(t || '').slice(0, 500)
    });
    return serverError(`TSFIN update failed: ${t}`);
  }

  const json = await res.json().catch(() => []);
  const after = Array.isArray(json) ? json[0] : json;
  let contractWeekExpenseDraftSynced = false;

  if ((patch.expenses || patch.mileage) && cw?.id && after) {
    const existingTotals = (cw.totals_json && typeof cw.totals_json === 'object' && !Array.isArray(cw.totals_json))
      ? cw.totals_json
      : {};
    const nextExpensesDraft = {
      mileage_units: round2(num0(after.mileage_units)),
      travel_pay: round2(num0(after.travel_pay_ex_vat)),
      travel_charge: round2(num0(after.travel_charge_ex_vat)),
      accommodation_pay: round2(num0(after.accommodation_pay_ex_vat)),
      accommodation_charge: round2(num0(after.accommodation_charge_ex_vat)),
      other_pay: round2(num0(after.other_pay_ex_vat)),
      other_charge: round2(num0(after.other_charge_ex_vat)),
      note: extractExpenseDraftNote(after.expenses_description)
    };

    const cwSyncRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(cw.id)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({
          totals_json: { ...existingTotals, expenses_draft: nextExpensesDraft },
          updated_at: nowISO
        })
      }
    );

    if (!cwSyncRes.ok) {
      const t = await cwSyncRes.text().catch(() => '');
      logTsfinSaveDiag('contract_week_expense_draft_sync_failed', {
        status: cwSyncRes.status,
        current_timesheet_id: currentTimesheetId,
        contract_week_id: cw?.id || null,
        after: diagTsfinSummary(after),
        error_text: String(t || '').slice(0, 500)
      });
      return serverError(`Contract week expense draft sync failed: ${t}`);
    }

    contractWeekExpenseDraftSynced = true;
  }

  logTsfinSaveDiag('after_write', {
    current_timesheet_id: currentTimesheetId,
    contract_week_id: cw?.id || null,
    before: diagTsfinSummary(before),
    after: diagTsfinSummary(after),
    contract_week_expense_draft_synced: contractWeekExpenseDraftSynced
  });

  await insertAuditEvent(env, req, {
    object_type: 'timesheets_financials',
    object_id_text: currentTimesheetId,
    action: 'PATCH',
    reason: patch.reason ?? null,
    before_json: {
      expenses: {
        travel_pay_ex_vat: before.travel_pay_ex_vat ?? 0,
        travel_charge_ex_vat: before.travel_charge_ex_vat ?? 0,
        accommodation_pay_ex_vat: before.accommodation_pay_ex_vat ?? 0,
        accommodation_charge_ex_vat: before.accommodation_charge_ex_vat ?? 0,
        other_pay_ex_vat: before.other_pay_ex_vat ?? 0,
        other_charge_ex_vat: before.other_charge_ex_vat ?? 0,
        expenses_pay_ex_vat: before.expenses_pay_ex_vat ?? 0,
        expenses_charge_ex_vat: before.expenses_charge_ex_vat ?? 0,
        expenses_description: before.expenses_description ?? null
      },
      mileage: {
        mileage_units: before.mileage_units ?? 0,
        pay_ex_vat: before.mileage_pay_ex_vat ?? 0,
        charge_ex_vat: before.mileage_charge_ex_vat ?? 0,
        pay_rate: before.mileage_pay_rate ?? null,
        charge_rate: before.mileage_charge_rate ?? null
      },
      po: { number: before.po_number ?? null }
    },
    after_json: {
      expenses: {
        travel_pay_ex_vat: after?.travel_pay_ex_vat ?? 0,
        travel_charge_ex_vat: after?.travel_charge_ex_vat ?? 0,
        accommodation_pay_ex_vat: after?.accommodation_pay_ex_vat ?? 0,
        accommodation_charge_ex_vat: after?.accommodation_charge_ex_vat ?? 0,
        other_pay_ex_vat: after?.other_pay_ex_vat ?? 0,
        other_charge_ex_vat: after?.other_charge_ex_vat ?? 0,
        expenses_pay_ex_vat: after?.expenses_pay_ex_vat ?? 0,
        expenses_charge_ex_vat: after?.expenses_charge_ex_vat ?? 0,
        expenses_description: after?.expenses_description ?? null
      },
      mileage: {
        mileage_units: after?.mileage_units ?? 0,
        pay_ex_vat: after?.mileage_pay_ex_vat ?? 0,
        charge_ex_vat: after?.mileage_charge_ex_vat ?? 0,
        pay_rate: after?.mileage_pay_rate ?? null,
        charge_rate: after?.mileage_charge_rate ?? null
      },
      po: { number: after?.po_number ?? null }
    }
  }).catch(() => {});

  let lifecycleSignaturePayload = null;
  let lifecycleSignatureObject = null;
  let lifecycleSignature = '';
  let lifecycleSignatureError = null;
  let lifecycleSignatureFallbackUsed = false;

  const adoptLifecycleSignaturePayload = (payload) => {
    const obj = Array.isArray(payload) ? (payload[0] || null) : payload;
    const signatureText = String(
      obj?.backend_row_signature ||
      obj?.mutation_row_signature ||
      obj?.row_signature ||
      obj?.expected_row_signature ||
      obj?.signature ||
      ''
    ).trim();
    if (!signatureText) return false;
    lifecycleSignatureObject = obj;
    lifecycleSignature = signatureText;
    return true;
  };

  try {
    lifecycleSignaturePayload = await sbRpc(env, 'timesheet_lifecycle_signature_v1', {
      p_timesheet_id: currentTimesheetId,
      p_contract_week_id: cw?.id || null,
      p_include_payload: false
    }, {
      timeoutMs: 8000
    });

    adoptLifecycleSignaturePayload(lifecycleSignaturePayload);
  } catch (signatureErr) {
    lifecycleSignatureError = signatureErr;
  }

  if (!lifecycleSignature) {
    try {
      const affectedRowsPayload = await sbRpc(env, 'timesheet_lifecycle_affected_rows_v1', {
        p_items: [{
          row_key: `timesheet:${currentTimesheetId}`,
          timesheet_id: currentTimesheetId,
          current_timesheet_id: currentTimesheetId,
          expected_timesheet_id: currentTimesheetId,
          contract_week_id: cw?.id || null,
          booking_id: resolved.booking_id || null,
          context: 'timesheet_modal'
        }],
        p_context: 'timesheet_modal',
        p_actor_user_id: user.id || null
      }, {
        timeoutMs: 8000
      });

      const affectedRow = Array.isArray(affectedRowsPayload?.rows) ? (affectedRowsPayload.rows[0] || null) : null;
      if (affectedRow) {
        lifecycleSignatureFallbackUsed = true;
        adoptLifecycleSignaturePayload({
          backend_row_signature: affectedRow.backend_row_signature || null,
          mutation_row_signature: affectedRow.mutation_row_signature || affectedRow.backend_row_signature || affectedRow.row_signature || null,
          row_signature: affectedRow.row_signature || affectedRow.backend_row_signature || null,
          expected_row_signature: affectedRow.expected_row_signature || affectedRow.backend_row_signature || affectedRow.row_signature || null,
          signature: affectedRow.render_signature || affectedRow.signature || affectedRow.backend_row_signature || affectedRow.row_signature || null,
          current_timesheet_id: affectedRow.current_timesheet_id || affectedRow.timesheet_id || currentTimesheetId,
          timesheet_id: affectedRow.timesheet_id || affectedRow.current_timesheet_id || currentTimesheetId,
          contract_week_id: affectedRow.contract_week_id || cw?.id || null
        });
      }
    } catch (fallbackErr) {
      lifecycleSignatureError = fallbackErr || lifecycleSignatureError;
    }
  }

  logTsfinSaveDiag('after_signature', {
    current_timesheet_id: currentTimesheetId,
    contract_week_id: cw?.id || null,
    before_signature: beforeSignatureDiag,
    after_signature: diagExtractSignature(lifecycleSignatureObject || lifecycleSignature),
    lifecycle_signature_rpc_payload_shape: lifecycleSignatureObject && typeof lifecycleSignatureObject === 'object'
      ? Object.keys(lifecycleSignatureObject).slice(0, 50)
      : [],
    lifecycle_signature_fallback_used: lifecycleSignatureFallbackUsed,
    lifecycle_signature_error: lifecycleSignatureError ? diagErrorText(lifecycleSignatureError) : null
  });

  if (!lifecycleSignature) {
    logTsfinSaveDiag('signature_failure', {
      status: 500,
      current_timesheet_id: currentTimesheetId,
      contract_week_id: cw?.id || null,
      before: diagTsfinSummary(before),
      after: diagTsfinSummary(after),
      lifecycle_signature_error: diagErrorText(lifecycleSignatureError) || 'no signature returned'
    });
    return serverError(`TSFIN lifecycle signature refresh failed: ${String(lifecycleSignatureError?.message || lifecycleSignatureError || 'no signature returned')}`);
  }

  const savePatchBundle = buildTimesheetLifecyclePatchFromMutation({
    action: 'SAVE',
    requestedTimesheetId: resolved.requested_timesheet_id || timesheetId || null,
    currentTimesheetId,
    currentVersion: resolved.current_version ?? null,
    contractWeekId: cw?.id || null,
    bookingId: resolved.booking_id || null,
    candidateId: after?.candidate_id || before?.candidate_id || null,
    tsfinRow: after || before,
    currentTimesheetRow: currentTs,
    newProcessingStatus: after?.processing_status || before?.processing_status || null,
    backendRowSignature: lifecycleSignature,
    rowSignature: lifecycleSignature,
    expectedRowSignature: lifecycleSignature,
    authorised: false,
    readyToPay: null,
    staleMarkers: { was_stale: !!resolved.was_stale }
  });

  const responsePayload = {
    updated: true,
    tsfin: after,
    save_domain: patch._save_domain || (patch.expenses ? 'EXPENSES' : (patch.mileage ? 'MILEAGE' : (patch.po ? 'PO' : 'TSFIN'))),
    booking_id: resolved.booking_id || null,
    requested_timesheet_id: resolved.requested_timesheet_id || timesheetId || null,
    current_timesheet_id: currentTimesheetId,
    timesheet_id: currentTimesheetId,
    current_version: resolved.current_version ?? null,
    was_stale: !!resolved.was_stale,
    processing_status: after?.processing_status || before?.processing_status || null,
    authorised: false,
    contract_week_id: cw?.id || null,
    backend_row_signature: lifecycleSignature,
    mutation_row_signature: lifecycleSignature,
    row_signature: lifecycleSignature,
    expected_row_signature: lifecycleSignature,
    lifecycle_signature: lifecycleSignatureObject || null,
    lifecycle_patch: savePatchBundle.lifecycle_patch,
    affected_rows: savePatchBundle.affected_rows,
    refresh_hints: savePatchBundle.refresh_hints,
    priority_badge_hints: savePatchBundle.lifecycle_patch?.priority_badge_hints || null,
    dirty_state: { is_dirty: false, clean: true, save_applied: true },
    save_patch_available: savePatchBundle.immediate_lifecycle_patch_available,
    authorise_preflight_refresh_required: !lifecycleSignature,
    permission_state_patch_complete: savePatchBundle.permission_state_patch_complete,
    priority_badges_patch_complete: savePatchBundle.priority_badges_patch_complete,
    immediate_lifecycle_patch_available: savePatchBundle.immediate_lifecycle_patch_available,
    requires_affected_row_refresh: savePatchBundle.requires_affected_row_refresh,
    requires_full_details_refresh: savePatchBundle.requires_full_details_refresh,
    refresh_required: savePatchBundle.refresh_required
  };

  logTsfinSaveDiag('response_shape', {
    current_timesheet_id: currentTimesheetId,
    contract_week_id: cw?.id || null,
    updated: true,
    before: diagTsfinSummary(before),
    after: diagTsfinSummary(after),
    before_signature: beforeSignatureDiag,
    after_signature: diagExtractSignature(lifecycleSignatureObject || lifecycleSignature),
    response_contains: diagResponseContains(responsePayload)
  });

  return ok(responsePayload);
}


// ============================================================
// UPDATED: handleTimesheetEvidenceAdd / handleTimesheetEvidenceUpdateKind
// - Normalizes kind to canonical set where applicable:
//     MILEAGE, TRAVEL, ACCOMMODATION, OTHER, TIMESHEET
// - Maps legacy UI "Expenses" -> TRAVEL
// - Keeps other/system kinds as UPPER(TRIM(...))
// ============================================================


// ============================================================
// UPDATED: handleTimesheetEvidenceAdd / handleTimesheetEvidenceUpdateKind
// - Normalizes kind to canonical set where applicable:
//     MILEAGE, TRAVEL, ACCOMMODATION, OTHER, TIMESHEET
// - Maps legacy UI "Expenses" -> TRAVEL
// - Keeps other/system kinds as UPPER(TRIM(...))
// ============================================================

async function handleTimesheetEvidenceAdd(env, req, tsId, ctx) {
  const enc = encodeURIComponent;

  const evidencePolicyBlockedResponse = (policy, actionLabel) => {
    const reason = policy?.protected_reason || (!policy?.can_manage_evidence ? 'EVIDENCE_MUTATION_BLOCKED' : null);
    const code = reason || 'EVIDENCE_MUTATION_BLOCKED';
    let message = `Evidence cannot be ${actionLabel || 'changed'} for this timesheet.`;
    if (code === 'TIMESHEET_AUTHORISED_EDIT_BLOCKED') {
      message = 'This timesheet is authorised. Unauthorise it before changing expenses or expense evidence.';
    } else if (code === 'TIMESHEET_PAID_EDIT_BLOCKED') {
      message = 'This timesheet has been paid and cannot be amended directly.';
    } else if (code === 'TIMESHEET_SEGMENT_INVOICE_LOCKED_EDIT_BLOCKED') {
      message = 'This timesheet has invoice-locked segments. Create an additional manual adjustment for any further expenses or expense evidence.';
    } else if (code === 'TIMESHEET_INVOICE_LOCKED_EDIT_BLOCKED') {
      message = 'This timesheet is invoice locked. Create an additional manual adjustment for any further expenses or expense evidence.';
    } else if (code === 'IMPORT_AUTHORITATIVE_EXPENSES_BLOCKED' || code === 'IMPORT_AUTHORITATIVE_ROUTE') {
      message = 'This original import-authoritative timesheet is view-only for direct expenses. Create an additional manual timesheet for expenses and expense evidence.';
    } else if (code === 'PROTECTED_IMPORT_OR_SYSTEM_EVIDENCE' || code === 'SYSTEM_EVIDENCE') {
      message = 'This protected system or import evidence cannot be changed.';
    } else if (code === 'INVALID_TIMESHEET_CONTEXT') {
      message = 'Invalid or missing current timesheet context.';
    }
    return new Response(
      JSON.stringify({ error: code, error_code: code, message, protected_reason: reason }),
      { status: code === 'INVALID_TIMESHEET_CONTEXT' ? 400 : 409, headers: JSON_HEADERS }
    );
  };

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!tsId) return withCORS(env, req, badRequest('timesheet_id is required'));

  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    return withCORS(env, req, badRequest('Invalid JSON payload'));
  }


  const handleTimesheetEvidenceAddDiagText = (v) => {
    const s = String(v == null ? '' : v).trim();
    return s || null;
  };
  const handleTimesheetEvidenceAddDiagKeys = (obj) => (obj && typeof obj === 'object' && !Array.isArray(obj)) ? Object.keys(obj).sort() : [];
  const handleTimesheetEvidenceAddDiagSignature = (obj) => {
    if (!obj || typeof obj !== 'object') {
      const s = handleTimesheetEvidenceAddDiagText(obj);
      return { present: !!s, backend_row_signature: null, mutation_row_signature: null, row_signature: null, expected_row_signature: null, current_row_signature: null, signature: s };
    }
    const backend = handleTimesheetEvidenceAddDiagText(obj.backend_row_signature);
    const mutation = handleTimesheetEvidenceAddDiagText(obj.mutation_row_signature);
    const row = handleTimesheetEvidenceAddDiagText(obj.row_signature);
    const expected = handleTimesheetEvidenceAddDiagText(obj.expected_row_signature);
    const current = handleTimesheetEvidenceAddDiagText(obj.current_row_signature);
    const generic = handleTimesheetEvidenceAddDiagText(obj.signature || obj.render_signature);
    return {
      present: !!(backend || mutation || row || expected || current || generic),
      backend_row_signature: backend,
      mutation_row_signature: mutation,
      row_signature: row,
      expected_row_signature: expected,
      current_row_signature: current,
      signature: backend || mutation || row || expected || current || generic || null
    };
  };
  const handleTimesheetEvidenceAddDiagResponseContains = (payload) => ({
    ok: Object.prototype.hasOwnProperty.call(payload || {}, 'ok'),
    evidence: !!(payload?.evidence && typeof payload.evidence === 'object'),
    queue_id: !!handleTimesheetEvidenceAddDiagText(payload?.queue_id),
    returned_to_queue: Object.prototype.hasOwnProperty.call(payload || {}, 'returned_to_queue'),
    backend_row_signature: !!handleTimesheetEvidenceAddDiagText(payload?.backend_row_signature),
    mutation_row_signature: !!handleTimesheetEvidenceAddDiagText(payload?.mutation_row_signature),
    row_signature: !!handleTimesheetEvidenceAddDiagText(payload?.row_signature),
    expected_row_signature: !!handleTimesheetEvidenceAddDiagText(payload?.expected_row_signature),
    current_row_signature: !!handleTimesheetEvidenceAddDiagText(payload?.current_row_signature),
    affected_rows: Array.isArray(payload?.affected_rows),
    refresh_required: payload?.refresh_required === true,
    requires_affected_row_refresh: payload?.requires_affected_row_refresh === true
  });
  const handleTimesheetEvidenceAddDiagLog = (step, extra = {}) => {
    try {
      let routePath = null;
      try { routePath = new URL(req?.url || '').pathname; } catch {}
      console.log('[TIMESHEET_SAVE_SIGNATURE_DIAG]', JSON.stringify({
        tag: 'TIMESHEET_SAVE_SIGNATURE_DIAG',
        handler: 'handleTimesheetEvidenceAdd',
        route_family: 'EVIDENCE_ADD',
        step,
        route_path: routePath,
        requested_timesheet_id: tsId || null,
        evidence_id: typeof evidenceId === 'undefined' ? null : (evidenceId || null),
        server_utc: new Date().toISOString(),
        ...(extra && typeof extra === 'object' && !Array.isArray(extra) ? extra : {})
      }));
    } catch {}
  };
  const fetchhandleTimesheetEvidenceAddLifecycleSignatureDiag = async (pTimesheetId, pContractWeekId = null) => {
    if (!pTimesheetId) return { ok: false, skipped: true, reason: 'NO_TIMESHEET_ID' };
    try {
      const payload = await sbRpc(env, 'timesheet_lifecycle_signature_v1', {
        p_timesheet_id: pTimesheetId,
        p_contract_week_id: pContractWeekId || null,
        p_include_payload: false
      }, { timeoutMs: 8000 });
      const obj = Array.isArray(payload) ? (payload[0] || null) : payload;
      const signature = handleTimesheetEvidenceAddDiagSignature(obj);
      return { ok: signature.present, source: 'timesheet_lifecycle_signature_v1', signature, payload_field_names: handleTimesheetEvidenceAddDiagKeys(obj) };
    } catch (err) {
      return { ok: false, source: 'timesheet_lifecycle_signature_v1', error: String(err?.message || err || '').slice(0, 300) };
    }
  };
  const expected = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  handleTimesheetEvidenceAddDiagLog('received', {
    body_keys: handleTimesheetEvidenceAddDiagKeys(body),
    expected_timesheet_id: expected || null,
    kind: body?.kind ? String(body.kind).trim().toUpperCase() : null,
    storage_key_present: handleTimesheetEvidenceAddDiagText(body?.storage_key) ? true : false
  });
  if (!expected) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  const resolved = await resolveTimesheetToCurrent(env, tsId);
  if (!resolved) {
    handleTimesheetEvidenceAddDiagLog('timesheet_not_found', { status: 404 });
    return withCORS(env, req, notFound('Timesheet not found'));
  }
  const currentTsId = resolved.current_timesheet_id;
  handleTimesheetEvidenceAddDiagLog('resolved_current', {
    current_timesheet_id: currentTsId || null,
    requested_timesheet_id: resolved.requested_timesheet_id || tsId,
    current_version: resolved.current_version ?? null,
    was_stale: !!resolved.was_stale
  });

  if (String(expected) !== String(currentTsId)) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({ error: 'TIMESHEET_MOVED', current_timesheet_id: currentTsId }),
        { status: 409, headers: { 'Content-Type': 'application/json' } }
      )
    );
  }

  const rawKind = body && body.kind && String(body.kind).trim();
  const displayNameIn = body && body.display_name != null ? String(body.display_name).trim() : null;

  const normalizeKind = (k) => {
    const s = String(k || '').trim();
    if (!s) return '';
    const u = s.toUpperCase();

    if (u === 'EXPENSES' || u === 'EXPENSE') return 'TRAVEL';
    if (u === 'TRAVEL') return 'TRAVEL';

    if (u === 'MILEAGE' || u === 'MILES' || u === 'MILE') return 'MILEAGE';
    if (u === 'ACCOMMODATION' || u === 'ACCOM') return 'ACCOMMODATION';
    if (u === 'OTHER') return 'OTHER';
    if (u === 'TIMESHEET' || u === 'TS') return 'TIMESHEET';

    return u;
  };

  const prettyKind = (k) => {
    const u = String(k || '').toUpperCase();
    if (u === 'TRAVEL') return 'Travel';
    if (u === 'MILEAGE') return 'Mileage';
    if (u === 'ACCOMMODATION') return 'Accommodation';
    if (u === 'OTHER') return 'Other';
    if (u === 'TIMESHEET') return 'Timesheet';
    return String(k || '');
  };

  const validateTimesheetStorageKey = async (rawKey, sourceLabel) => {
    const cleanStorageKey = String(rawKey || '').trim().replace(/^\/+/, '');
    if (!cleanStorageKey) throw new Error('storage_key is required');

    const sourceBytes = await r2GetBytes(env, cleanStorageKey);
    if (!sourceBytes?.length) throw new Error(`${sourceLabel || 'Timesheet evidence'} source file is missing or empty`);

    const contentKind = detectPdfOrImageContentKind(sourceBytes);
    if (contentKind !== 'application/pdf' && contentKind !== 'image/png' && contentKind !== 'image/jpeg') {
      throw new Error(`${sourceLabel || 'Timesheet evidence'} must be a PDF or supported image (PNG/JPEG). Detected: ${contentKind}`);
    }

    return {
      storageKey: cleanStorageKey,
      contentKind
    };
  };

  const kind = normalizeKind(rawKind);
  const allowedKinds = new Set(['TIMESHEET', 'MILEAGE', 'TRAVEL', 'ACCOMMODATION', 'OTHER']);

  const storageKeyRaw = body && body.storage_key && String(body.storage_key).trim();
  const storageKey = storageKeyRaw ? storageKeyRaw.replace(/^\/+/, '') : '';
  const hasReplacementField =
    Object.prototype.hasOwnProperty.call(body || {}, 'replace_existing') ||
    Object.prototype.hasOwnProperty.call(body || {}, 'replace_evidence_id');

  if (!kind) return withCORS(env, req, badRequest('kind is required'));
  if (!allowedKinds.has(kind)) return withCORS(env, req, badRequest('Invalid evidence kind'));
  if (!storageKey) return withCORS(env, req, badRequest('storage_key is required'));
  if (hasReplacementField) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({
          error: 'DIRECT_REPLACEMENT_NOT_SUPPORTED',
          message: 'Direct replacement is not supported. Delete the existing evidence or return it to queue first, then add/attach the new evidence.'
        }),
        { status: 409, headers: JSON_HEADERS }
      )
    );
  }

  try {
    const evidencePolicy = await getTimesheetEvidenceMutationPolicy(env, currentTsId, { requested_kind: kind });
    if (!evidencePolicy?.can_manage_evidence) {
      return withCORS(env, req, evidencePolicyBlockedResponse(evidencePolicy, 'added'));
    }
    if (!evidencePolicy.current_timesheet_id) {
      return withCORS(env, req, badRequest('Invalid or missing current timesheet context'));
    }

    const { rows: tsRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(currentTsId)}` +
        `&is_current=eq.true` +
        `&select=timesheet_id,contract_id,week_ending_date,sheet_scope,submission_mode,manual_pdf_r2_key,manual_pdf_rotation_degrees` +
        `&limit=1`
    );
    const ts = tsRows?.[0] || null;
    if (!ts) return withCORS(env, req, notFound('Timesheet not found'));

    try {
      if (typeof r2Exists === 'function') {
        const exists = await r2Exists(env, storageKey);
        if (!exists) return withCORS(env, req, badRequest('storage_key does not exist in R2'));
      }
    } catch (e) {
      console.warn('[handleTimesheetEvidenceAdd] r2Exists failed (non-fatal)', {
        storage_key: storageKey,
        err: e?.message || String(e)
      });
    }

    let finalStorageKey = storageKey;
    let manualMaterialized = null;
    if (kind === 'TIMESHEET') {
      const validatedTimesheetStorage = await validateTimesheetStorageKey(
        storageKey,
        'Timesheet evidence upload'
      );
      finalStorageKey = String(validatedTimesheetStorage.storageKey || '').trim().replace(/^\/+/, '');
      manualMaterialized = {
        pdfKey: finalStorageKey,
        wasConverted: false,
        sourceKey: finalStorageKey,
        contentKind: validatedTimesheetStorage.contentKind
      };
    }

    const beforeSignatureDiag = await fetchhandleTimesheetEvidenceAddLifecycleSignatureDiag(currentTsId, null);

    const { rows: existingRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheet_evidence` +
        `?timesheet_id=eq.${enc(currentTsId)}` +
        `&select=id,kind,display_name,storage_key,created_at,created_by`
    );
    const existingEvidence = Array.isArray(existingRows) ? existingRows : [];

    const sameStorageExisting = existingEvidence.find(row =>
      String(row?.storage_key || '').trim().replace(/^\/+/, '') === finalStorageKey
    ) || null;

    if (sameStorageExisting && String(sameStorageExisting.kind || '').trim().toUpperCase() === kind) {
      const afterSignatureDiag = await fetchhandleTimesheetEvidenceAddLifecycleSignatureDiag(currentTsId, null);
      const responsePayload = {
        ok: true,
        requested_timesheet_id: resolved.requested_timesheet_id || tsId,
        current_timesheet_id: currentTsId,
        was_stale: !!resolved.was_stale,
        evidence: sameStorageExisting
      };
      handleTimesheetEvidenceAddDiagLog('response_shape', {
        mode: 'idempotent_existing_evidence',
        status: 200,
        current_timesheet_id: currentTsId || null,
        evidence_kind: kind || null,
        evidence_id: sameStorageExisting?.id || null,
        before_signature: beforeSignatureDiag,
        after_signature: afterSignatureDiag,
        response_signature: handleTimesheetEvidenceAddDiagSignature(responsePayload),
        response_contains: handleTimesheetEvidenceAddDiagResponseContains(responsePayload)
      });
      return withCORS(env, req, ok(responsePayload));
    }

    if (kind === 'TIMESHEET') {
      const existingTimesheetEvidence = existingEvidence.find(row =>
        String(row?.kind || '').trim().toUpperCase() === 'TIMESHEET'
      ) || null;

      if (existingTimesheetEvidence) {
        return withCORS(env, req, badRequest('Only one TIMESHEET evidence file may be attached to a timesheet at a time'));
      }
    }

    handleTimesheetEvidenceAddDiagLog('before_write', {
      current_timesheet_id: currentTsId || null,
      evidence_kind: kind || null,
      display_name_present: handleTimesheetEvidenceAddDiagText(displayNameIn) ? true : false,
      storage_key_present: !!finalStorageKey,
      existing_evidence_count: existingEvidence.length,
      before_signature: beforeSignatureDiag
    });

    const nowIso = new Date().toISOString();

    const payload = [{
      timesheet_id: currentTsId,
      kind,
      display_name: (displayNameIn && displayNameIn.length ? displayNameIn : prettyKind(kind) || kind),
      storage_key: finalStorageKey,
      created_at: nowIso,
      created_by: user.id || null
    }];

    const insRes = await fetch(`${env.SUPABASE_URL}/rest/v1/timesheet_evidence`, {
      method: 'POST',
      headers: { ...sbHeaders(env), Prefer: 'return=representation' },
      body: JSON.stringify(payload)
    });

    const txt = await insRes.text().catch(() => '');
    if (!insRes.ok) {
      return withCORS(env, req, serverError(`Failed to add timesheet evidence: ${txt}`));
    }

    let row = null;
    try {
      const json = txt ? JSON.parse(txt) : [];
      row = Array.isArray(json) ? json[0] : json;
    } catch {
      row = null;
    }

    if (String(kind).toUpperCase() === 'TIMESHEET' && !isInvoiceAsyncPipelineEnabled(env)) {
      try {
        const updRes = await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTsId)}&is_current=eq.true`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
            body: JSON.stringify({ manual_pdf_r2_key: finalStorageKey })
          }
        );
        if (!updRes.ok) {
          const t2 = await updRes.text().catch(() => '');
          console.warn('[handleTimesheetEvidenceAdd] manual_pdf_r2_key update failed (non-fatal)', {
            timesheet_id: currentTsId,
            storage_key: finalStorageKey,
            err: t2
          });
        }
      } catch (e) {
        console.warn('[handleTimesheetEvidenceAdd] manual_pdf_r2_key update exception (non-fatal)', {
          timesheet_id: currentTsId,
          err: e?.message || String(e)
        });
      }
    }

    let documentPreparation = null;
    if (isInvoiceAsyncPipelineEnabled(env) && row?.id) {
      const originalObject = await env.R2.head(finalStorageKey);
      if (!originalObject) {
        return withCORS(env, req, serverError('Uploaded evidence object is missing before document preparation'));
      }
      const started = await sbRpc(env, 'invoice_operation_start_batch', {
        p_commands: [{
          command_type: 'PREPARE_ASSET',
          source_kind: kind === 'TIMESHEET' ? 'MANUAL_TIMESHEET' : 'TIMESHEET_EVIDENCE',
          source_id: row.id,
          source_revision: `EVIDENCE:${row.id}:${nowIso}`,
          original_r2_key: finalStorageKey,
          original_filename: payload[0].display_name,
          declared_media_type: originalObject.httpMetadata?.contentType || 'application/octet-stream',
          rotation_degrees: normalizeRightAngleRotation(ts.manual_pdf_rotation_degrees || 0)
        }],
        p_actor_user_id: user.id,
        p_now_utc: nowIso
      });
      documentPreparation = unwrapRpcJsonb(started, 'invoice_operation_start_batch') || started;
      await nudgeInvoiceOperations(env, documentPreparation, {
        ctx,
        rpc: (functionName, args, options) => sbRpc(env, functionName, args, options),
        lanes: ['DOCUMENT']
      });
    }

    try {
      await writeAudit(
        env,
        user,
        'TIMESHEET_EVIDENCE_ADDED',
        {
          timesheet_id: currentTsId,
          evidence_id: row?.id || null,
          kind,
          display_name: (displayNameIn && displayNameIn.length ? displayNameIn : prettyKind(kind) || kind),
          storage_key: finalStorageKey,
          source_storage_key: manualMaterialized ? storageKey : null,
          materialized_pdf_r2_key: manualMaterialized ? finalStorageKey : null,
          materialized_was_converted: manualMaterialized ? !!manualMaterialized.wasConverted : false,
          contract_id: ts.contract_id || null,
          week_ending_date: ts.week_ending_date || null,
          sheet_scope: ts.sheet_scope || null,
          submission_mode: ts.submission_mode || null
        },
        { entity: 'timesheets', subject_id: currentTsId, req }
      );
    } catch {}

    const afterSignatureDiag = await fetchhandleTimesheetEvidenceAddLifecycleSignatureDiag(currentTsId, null);
    const responsePayload = {
      ok: true,
      requested_timesheet_id: resolved.requested_timesheet_id || tsId,
      current_timesheet_id: currentTsId,
      was_stale: !!resolved.was_stale,
      evidence: row || null,
      document_preparation: documentPreparation
    };
    handleTimesheetEvidenceAddDiagLog('response_shape', {
      mode: 'inserted',
      status: 200,
      current_timesheet_id: currentTsId || null,
      evidence_kind: kind || null,
      evidence_id: row?.id || null,
      before_signature: beforeSignatureDiag,
      after_signature: afterSignatureDiag,
      response_signature: handleTimesheetEvidenceAddDiagSignature(responsePayload),
      response_contains: handleTimesheetEvidenceAddDiagResponseContains(responsePayload)
    });

    return withCORS(env, req, new Response(JSON.stringify(responsePayload), {
      status: documentPreparation ? 202 : 200,
      headers: JSON_HEADERS
    }));
  } catch (e) {
    return withCORS(env, req, serverError(`Failed to add timesheet evidence: ${e?.message || e}`));
  }
}

async function handleTimesheetEvidenceUpdateKind(env, req, tsId, evidenceId, ctx) {
  const enc = encodeURIComponent;

  const evidencePolicyBlockedResponse = (policy, actionLabel) => {
    const reason = policy?.protected_reason || (!policy?.can_manage_evidence ? 'EVIDENCE_MUTATION_BLOCKED' : null);
    const code = reason || 'EVIDENCE_MUTATION_BLOCKED';
    let message = `Evidence cannot be ${actionLabel || 'changed'} for this timesheet.`;
    if (code === 'TIMESHEET_AUTHORISED_EDIT_BLOCKED') {
      message = 'This timesheet is authorised. Unauthorise it before changing expenses or expense evidence.';
    } else if (code === 'TIMESHEET_PAID_EDIT_BLOCKED') {
      message = 'This timesheet has been paid and cannot be amended directly.';
    } else if (code === 'TIMESHEET_SEGMENT_INVOICE_LOCKED_EDIT_BLOCKED') {
      message = 'This timesheet has invoice-locked segments. Create an additional manual adjustment for any further expenses or expense evidence.';
    } else if (code === 'TIMESHEET_INVOICE_LOCKED_EDIT_BLOCKED') {
      message = 'This timesheet is invoice locked. Create an additional manual adjustment for any further expenses or expense evidence.';
    } else if (code === 'IMPORT_AUTHORITATIVE_EXPENSES_BLOCKED' || code === 'IMPORT_AUTHORITATIVE_ROUTE') {
      message = 'This original import-authoritative timesheet is view-only for direct expenses. Create an additional manual timesheet for expenses and expense evidence.';
    } else if (code === 'PROTECTED_IMPORT_OR_SYSTEM_EVIDENCE' || code === 'SYSTEM_EVIDENCE') {
      message = 'This protected system or import evidence cannot be changed.';
    } else if (code === 'INVALID_TIMESHEET_CONTEXT') {
      message = 'Invalid or missing current timesheet context.';
    }
    return new Response(
      JSON.stringify({ error: code, error_code: code, message, protected_reason: reason }),
      { status: code === 'INVALID_TIMESHEET_CONTEXT' ? 400 : 409, headers: JSON_HEADERS }
    );
  };

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!tsId) return withCORS(env, req, badRequest('timesheet_id is required'));
  if (!evidenceId) return withCORS(env, req, badRequest('evidence_id is required'));

  if (String(evidenceId).startsWith('SYS:')) {
    return withCORS(env, req, evidencePolicyBlockedResponse({ protected_reason: 'PROTECTED_IMPORT_OR_SYSTEM_EVIDENCE', can_manage_evidence: false }, 'edited'));
  }

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (!uuidRe.test(String(evidenceId))) {
    return withCORS(env, req, badRequest('Invalid evidence_id'));
  }

  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    return withCORS(env, req, badRequest('Invalid JSON payload'));
  }


  const handleTimesheetEvidenceUpdateKindDiagText = (v) => {
    const s = String(v == null ? '' : v).trim();
    return s || null;
  };
  const handleTimesheetEvidenceUpdateKindDiagKeys = (obj) => (obj && typeof obj === 'object' && !Array.isArray(obj)) ? Object.keys(obj).sort() : [];
  const handleTimesheetEvidenceUpdateKindDiagSignature = (obj) => {
    if (!obj || typeof obj !== 'object') {
      const s = handleTimesheetEvidenceUpdateKindDiagText(obj);
      return { present: !!s, backend_row_signature: null, mutation_row_signature: null, row_signature: null, expected_row_signature: null, current_row_signature: null, signature: s };
    }
    const backend = handleTimesheetEvidenceUpdateKindDiagText(obj.backend_row_signature);
    const mutation = handleTimesheetEvidenceUpdateKindDiagText(obj.mutation_row_signature);
    const row = handleTimesheetEvidenceUpdateKindDiagText(obj.row_signature);
    const expected = handleTimesheetEvidenceUpdateKindDiagText(obj.expected_row_signature);
    const current = handleTimesheetEvidenceUpdateKindDiagText(obj.current_row_signature);
    const generic = handleTimesheetEvidenceUpdateKindDiagText(obj.signature || obj.render_signature);
    return {
      present: !!(backend || mutation || row || expected || current || generic),
      backend_row_signature: backend,
      mutation_row_signature: mutation,
      row_signature: row,
      expected_row_signature: expected,
      current_row_signature: current,
      signature: backend || mutation || row || expected || current || generic || null
    };
  };
  const handleTimesheetEvidenceUpdateKindDiagResponseContains = (payload) => ({
    ok: Object.prototype.hasOwnProperty.call(payload || {}, 'ok'),
    evidence: !!(payload?.evidence && typeof payload.evidence === 'object'),
    queue_id: !!handleTimesheetEvidenceUpdateKindDiagText(payload?.queue_id),
    returned_to_queue: Object.prototype.hasOwnProperty.call(payload || {}, 'returned_to_queue'),
    backend_row_signature: !!handleTimesheetEvidenceUpdateKindDiagText(payload?.backend_row_signature),
    mutation_row_signature: !!handleTimesheetEvidenceUpdateKindDiagText(payload?.mutation_row_signature),
    row_signature: !!handleTimesheetEvidenceUpdateKindDiagText(payload?.row_signature),
    expected_row_signature: !!handleTimesheetEvidenceUpdateKindDiagText(payload?.expected_row_signature),
    current_row_signature: !!handleTimesheetEvidenceUpdateKindDiagText(payload?.current_row_signature),
    affected_rows: Array.isArray(payload?.affected_rows),
    refresh_required: payload?.refresh_required === true,
    requires_affected_row_refresh: payload?.requires_affected_row_refresh === true
  });
  const handleTimesheetEvidenceUpdateKindDiagLog = (step, extra = {}) => {
    try {
      let routePath = null;
      try { routePath = new URL(req?.url || '').pathname; } catch {}
      console.log('[TIMESHEET_SAVE_SIGNATURE_DIAG]', JSON.stringify({
        tag: 'TIMESHEET_SAVE_SIGNATURE_DIAG',
        handler: 'handleTimesheetEvidenceUpdateKind',
        route_family: 'EVIDENCE_UPDATE_KIND',
        step,
        route_path: routePath,
        requested_timesheet_id: tsId || null,
        evidence_id: typeof evidenceId === 'undefined' ? null : (evidenceId || null),
        server_utc: new Date().toISOString(),
        ...(extra && typeof extra === 'object' && !Array.isArray(extra) ? extra : {})
      }));
    } catch {}
  };
  const fetchhandleTimesheetEvidenceUpdateKindLifecycleSignatureDiag = async (pTimesheetId, pContractWeekId = null) => {
    if (!pTimesheetId) return { ok: false, skipped: true, reason: 'NO_TIMESHEET_ID' };
    try {
      const payload = await sbRpc(env, 'timesheet_lifecycle_signature_v1', {
        p_timesheet_id: pTimesheetId,
        p_contract_week_id: pContractWeekId || null,
        p_include_payload: false
      }, { timeoutMs: 8000 });
      const obj = Array.isArray(payload) ? (payload[0] || null) : payload;
      const signature = handleTimesheetEvidenceUpdateKindDiagSignature(obj);
      return { ok: signature.present, source: 'timesheet_lifecycle_signature_v1', signature, payload_field_names: handleTimesheetEvidenceUpdateKindDiagKeys(obj) };
    } catch (err) {
      return { ok: false, source: 'timesheet_lifecycle_signature_v1', error: String(err?.message || err || '').slice(0, 300) };
    }
  };
  const expected = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  handleTimesheetEvidenceUpdateKindDiagLog('received', {
    body_keys: handleTimesheetEvidenceUpdateKindDiagKeys(body),
    expected_timesheet_id: expected || null,
    requested_kind: body?.kind ? String(body.kind).trim().toUpperCase() : null
  });
  if (!expected) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  const resolved = await resolveTimesheetToCurrent(env, tsId);
  if (!resolved) {
    handleTimesheetEvidenceUpdateKindDiagLog('timesheet_not_found', { status: 404 });
    return withCORS(env, req, notFound('Timesheet not found'));
  }
  const currentTsId = resolved.current_timesheet_id;
  handleTimesheetEvidenceUpdateKindDiagLog('resolved_current', {
    current_timesheet_id: currentTsId || null,
    requested_timesheet_id: resolved.requested_timesheet_id || tsId,
    was_stale: !!resolved.was_stale
  });

  if (String(expected) !== String(currentTsId)) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({ error: 'TIMESHEET_MOVED', current_timesheet_id: currentTsId }),
        { status: 409, headers: { 'Content-Type': 'application/json' } }
      )
    );
  }

  const normalizeKind = (k) => {
    const s = String(k || '').trim();
    if (!s) return '';
    const u = s.toUpperCase();
    if (u === 'EXPENSES' || u === 'EXPENSE') return 'TRAVEL';
    if (u === 'TRAVEL') return 'TRAVEL';
    if (u === 'MILEAGE' || u === 'MILES' || u === 'MILE') return 'MILEAGE';
    if (u === 'ACCOMMODATION' || u === 'ACCOM') return 'ACCOMMODATION';
    if (u === 'OTHER') return 'OTHER';
    if (u === 'TIMESHEET' || u === 'TS') return 'TIMESHEET';
    return u;
  };

  const newKindRaw = body && body.kind != null ? String(body.kind).trim() : '';
  const newKind = normalizeKind(newKindRaw);
  const allowedKinds = new Set(['TIMESHEET', 'MILEAGE', 'TRAVEL', 'ACCOMMODATION', 'OTHER']);

  const validateTimesheetStorageKey = async (rawKey, sourceLabel) => {
    const cleanStorageKey = String(rawKey || '').trim().replace(/^\/+/, '');
    if (!cleanStorageKey) throw new Error('Unsupported TIMESHEET evidence');

    const sourceBytes = await r2GetBytes(env, cleanStorageKey);
    if (!sourceBytes?.length) throw new Error(`${sourceLabel || 'TIMESHEET evidence'} source file is missing or empty`);

    const contentKind = detectPdfOrImageContentKind(sourceBytes);
    if (contentKind !== 'application/pdf' && contentKind !== 'image/png' && contentKind !== 'image/jpeg') {
      throw new Error(`${sourceLabel || 'TIMESHEET evidence'} must be a PDF or supported image (PNG/JPEG). Detected: ${contentKind}`);
    }

    return {
      storageKey: cleanStorageKey,
      contentKind
    };
  };

  if (!newKind) return withCORS(env, req, badRequest('kind is required'));
  if (!allowedKinds.has(newKind)) return withCORS(env, req, badRequest('Invalid evidence kind'));

  try {
    const evidencePolicy = await getTimesheetEvidenceMutationPolicy(env, currentTsId, { allow_expense_evidence_preflight: true });
    if (!evidencePolicy?.can_manage_evidence) {
      return withCORS(env, req, evidencePolicyBlockedResponse(evidencePolicy, 'edited'));
    }

    const { rows: evRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheet_evidence` +
        `?id=eq.${enc(evidenceId)}` +
        `&timesheet_id=eq.${enc(currentTsId)}` +
        `&select=id,kind,display_name,storage_key,created_at,created_by,document_asset_id,source_revision,processing_state,processing_error_json` +
        `&limit=1`
    );

    const ev = evRows?.[0] || null;
    if (!ev) return withCORS(env, req, notFound('Evidence not found for this timesheet'));

    const evPolicy = await getTimesheetEvidenceMutationPolicy(env, currentTsId, { evidence_item: ev, requested_kind: newKind });
    if (!evPolicy?.can_manage_evidence) {
      return withCORS(env, req, evidencePolicyBlockedResponse(evPolicy, 'edited'));
    }

    const oldKind = ev.kind != null ? String(ev.kind) : '';
    const oldKindU = String(oldKind || '').toUpperCase();
    const newKindU = String(newKind || '').toUpperCase();

    const beforeSignatureDiag = await fetchhandleTimesheetEvidenceUpdateKindLifecycleSignatureDiag(currentTsId, null);

    if (oldKindU === newKindU) {
      const afterSignatureDiag = await fetchhandleTimesheetEvidenceUpdateKindLifecycleSignatureDiag(currentTsId, null);
      const responsePayload = {
        ok: true,
        requested_timesheet_id: resolved.requested_timesheet_id || tsId,
        current_timesheet_id: currentTsId,
        was_stale: !!resolved.was_stale,
        evidence: ev
      };
      handleTimesheetEvidenceUpdateKindDiagLog('response_shape', {
        mode: 'idempotent_same_kind',
        status: 200,
        current_timesheet_id: currentTsId || null,
        evidence_id: evidenceId || null,
        old_kind: oldKindU || null,
        new_kind: newKindU || null,
        before_signature: beforeSignatureDiag,
        after_signature: afterSignatureDiag,
        response_signature: handleTimesheetEvidenceUpdateKindDiagSignature(responsePayload),
        response_contains: handleTimesheetEvidenceUpdateKindDiagResponseContains(responsePayload)
      });
      return withCORS(env, req, ok(responsePayload));
    }

    const originalStorageKey = (ev.storage_key != null) ? String(ev.storage_key).trim().replace(/^\/+/, '') : '';
    let updatedStorageKey = originalStorageKey;

    if (newKindU === 'TIMESHEET') {
      const { rows: siblingRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheet_evidence` +
          `?timesheet_id=eq.${enc(currentTsId)}` +
          `&kind=eq.${enc('TIMESHEET')}` +
          `&select=id` +
          `&limit=10`
      );
      const duplicateTimesheet = (siblingRows || []).find(row => String(row?.id || '') !== String(evidenceId));
      if (duplicateTimesheet) {
        return withCORS(env, req, badRequest('Only one TIMESHEET evidence file may be attached to a timesheet at a time'));
      }

      if (!isInvoiceAsyncPipelineEnabled(env)) {
        try {
          const validatedTimesheetStorage = await validateTimesheetStorageKey(
            originalStorageKey,
            'timesheet_evidence.storage_key'
          );
          updatedStorageKey = String(validatedTimesheetStorage.storageKey || '').trim().replace(/^\/+/, '');
        } catch (e) {
          return withCORS(env, req, badRequest(e?.message || 'Unsupported TIMESHEET evidence'));
        }
      }

      if (!updatedStorageKey) {
        return withCORS(env, req, badRequest('Unsupported TIMESHEET evidence'));
      }
    }

    const patchPayload = { kind: newKind };
    if (newKindU === 'TIMESHEET' && !isInvoiceAsyncPipelineEnabled(env)) {
      patchPayload.storage_key = updatedStorageKey;
    }

    handleTimesheetEvidenceUpdateKindDiagLog('before_write', {
      current_timesheet_id: currentTsId || null,
      evidence_id: evidenceId || null,
      old_kind: oldKindU || null,
      new_kind: newKindU || null,
      storage_key_present: !!updatedStorageKey,
      before_signature: beforeSignatureDiag
    });

    const patchRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheet_evidence?id=eq.${enc(evidenceId)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return=representation' },
        body: JSON.stringify(patchPayload)
      }
    );

    const txt = await patchRes.text().catch(() => '');
    if (!patchRes.ok) {
      return withCORS(env, req, serverError(`Failed to update evidence kind: ${txt}`));
    }

    let updated = null;
    try {
      const json = txt ? JSON.parse(txt) : [];
      updated = Array.isArray(json) ? json[0] : json;
    } catch {
      updated = null;
    }

    const effectiveUpdatedStorageKey = (updated?.storage_key != null)
      ? String(updated.storage_key).trim().replace(/^\/+/, '')
      : updatedStorageKey;

    try {
      let tsRow = null;
      try {
        const { rows: tsRows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/timesheets` +
            `?timesheet_id=eq.${enc(currentTsId)}` +
            `&is_current=eq.true` +
            `&select=manual_pdf_r2_key,manual_document_asset_id,document_revision,document_state,active_document_operation_id` +
            `&limit=1`
        );
        tsRow = tsRows?.[0] || null;
      } catch {
        tsRow = null;
      }

      const curMk = (tsRow?.manual_pdf_r2_key != null) ? String(tsRow.manual_pdf_r2_key).trim().replace(/^\/+/, '') : '';

      if (newKindU === 'TIMESHEET' && isInvoiceAsyncPipelineEnabled(env)) {
        const updRes = await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTsId)}&is_current=eq.true`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
            body: JSON.stringify({ manual_document_asset_id: ev.document_asset_id || null })
          }
        );
        if (!updRes.ok) {
          const t2 = await updRes.text().catch(() => '');
          return withCORS(env, req, serverError(`Failed to update timesheet document asset pointer: ${t2}`));
        }
      } else if (newKindU === 'TIMESHEET') {
        const updRes = await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTsId)}&is_current=eq.true`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
            body: JSON.stringify({ manual_pdf_r2_key: effectiveUpdatedStorageKey })
          }
        );
        if (!updRes.ok) {
          const t2 = await updRes.text().catch(() => '');
          try {
            await fetch(
              `${env.SUPABASE_URL}/rest/v1/timesheet_evidence?id=eq.${enc(evidenceId)}`,
              {
                method: 'PATCH',
                headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
                body: JSON.stringify({ kind: oldKind, storage_key: originalStorageKey })
              }
            ).catch(() => {});
          } catch {}
          return withCORS(env, req, serverError(`Failed to update timesheet manual PDF pointer: ${t2}`));
        }
      } else if (oldKindU === 'TIMESHEET' && isInvoiceAsyncPipelineEnabled(env)) {
        if (
          ev.document_asset_id
          && String(tsRow?.manual_document_asset_id || '') === String(ev.document_asset_id)
        ) {
          const updRes = await fetch(
            `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTsId)}&is_current=eq.true`,
            {
              method: 'PATCH',
              headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
              body: JSON.stringify({ manual_document_asset_id: null })
            }
          );
          if (!updRes.ok) {
            const t2 = await updRes.text().catch(() => '');
            console.warn('[handleTimesheetEvidenceUpdateKind] clear manual_document_asset_id failed (non-fatal)', {
              timesheet_id: currentTsId,
              err: t2
            });
          }
        }
      } else if (oldKindU === 'TIMESHEET') {
        if (curMk && curMk === originalStorageKey) {
          const updRes = await fetch(
            `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTsId)}&is_current=eq.true`,
            {
              method: 'PATCH',
              headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
              body: JSON.stringify({ manual_pdf_r2_key: null })
            }
          );
          if (!updRes.ok) {
            const t2 = await updRes.text().catch(() => '');
            console.warn('[handleTimesheetEvidenceUpdateKind] clear manual_pdf_r2_key failed (non-fatal)', {
              timesheet_id: currentTsId,
              err: t2
            });
          }
        }
      }
    } catch (e) {
      if (newKindU === 'TIMESHEET') {
        try {
          await fetch(
            `${env.SUPABASE_URL}/rest/v1/timesheet_evidence?id=eq.${enc(evidenceId)}`,
            {
              method: 'PATCH',
              headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
              body: JSON.stringify({ kind: oldKind, storage_key: originalStorageKey })
            }
          ).catch(() => {});
        } catch {}
        return withCORS(env, req, serverError(`Failed to update timesheet manual PDF pointer: ${e?.message || e}`));
      }
      console.warn('[handleTimesheetEvidenceUpdateKind] manual_pdf_r2_key transition handling failed (non-fatal)', {
        timesheet_id: currentTsId,
        evidence_id: evidenceId,
        err: e?.message || String(e)
      });
    }

    try {
      await writeAudit(
        env,
        user,
        'TIMESHEET_EVIDENCE_RECLASSIFIED',
        {
          timesheet_id: currentTsId,
          evidence_id: evidenceId,
          old_kind: oldKind || null,
          new_kind: newKind,
          storage_key: effectiveUpdatedStorageKey || ev.storage_key || null,
          display_name: ev.display_name || null
        },
        { entity: 'timesheets', subject_id: currentTsId, req }
      );
    } catch {}

    let asset_operation = null;
    if (
      isInvoiceAsyncPipelineEnabled(env)
      && !ev.document_asset_id
      && effectiveUpdatedStorageKey
    ) {
      try {
        const started = await sbRpc(env, 'invoice_operation_start_batch', {
          p_commands: [{
            command_type: 'PREPARE_ASSET',
            source_kind: newKindU === 'TIMESHEET' ? 'MANUAL_TIMESHEET' : 'TIMESHEET_EVIDENCE',
            source_id: evidenceId,
            source_revision: ev.source_revision || `LEGACY_EVIDENCE_V1:${evidenceId}`,
            original_r2_key: effectiveUpdatedStorageKey,
            original_filename: ev.display_name || `evidence-${evidenceId}`,
            declared_media_type: 'application/octet-stream',
            rotation_degrees: 0
          }],
          p_actor_user_id: user.id,
          p_now_utc: new Date().toISOString()
        });
        const startedRows = Array.isArray(started)
          ? started
          : (Array.isArray(started?.data) ? started.data : [started].filter(Boolean));
        asset_operation = startedRows[0] || null;
        await nudgeInvoiceOperations(env, startedRows, {
          ctx,
          rpc: (functionName, args, options) => sbRpc(env, functionName, args, options),
          lanes: ['DOCUMENT']
        });
      } catch (assetError) {
        asset_operation = {
          accepted: false,
          error_code: 'ASSET_REGISTRATION_FAILED',
          message: String(assetError?.message || assetError).slice(0, 500)
        };
      }
    }

    const afterSignatureDiag = await fetchhandleTimesheetEvidenceUpdateKindLifecycleSignatureDiag(currentTsId, null);
    const responsePayload = {
      ok: true,
      requested_timesheet_id: resolved.requested_timesheet_id || tsId,
      current_timesheet_id: currentTsId,
      was_stale: !!resolved.was_stale,
      evidence: updated || { ok: true },
      asset_operation
    };
    handleTimesheetEvidenceUpdateKindDiagLog('response_shape', {
      mode: 'updated_kind',
      status: 200,
      current_timesheet_id: currentTsId || null,
      evidence_id: evidenceId || null,
      old_kind: oldKindU || null,
      new_kind: newKindU || null,
      before_signature: beforeSignatureDiag,
      after_signature: afterSignatureDiag,
      response_signature: handleTimesheetEvidenceUpdateKindDiagSignature(responsePayload),
      response_contains: handleTimesheetEvidenceUpdateKindDiagResponseContains(responsePayload)
    });

    return withCORS(env, req, ok(responsePayload));
  } catch (e) {
    return withCORS(env, req, serverError(`Failed to update evidence kind: ${e?.message || e}`));
  }
}

async function handleTimesheetEvidenceDelete(env, req, tsId, evidenceId) {
  const enc = encodeURIComponent;

  const evidencePolicyBlockedResponse = (policy, actionLabel) => {
    const reason = policy?.protected_reason || (!policy?.can_manage_evidence ? 'EVIDENCE_MUTATION_BLOCKED' : null);
    const code = reason || 'EVIDENCE_MUTATION_BLOCKED';
    let message = `Evidence cannot be ${actionLabel || 'changed'} for this timesheet.`;
    if (code === 'TIMESHEET_AUTHORISED_EDIT_BLOCKED') {
      message = 'This timesheet is authorised. Unauthorise it before changing expenses or expense evidence.';
    } else if (code === 'TIMESHEET_PAID_EDIT_BLOCKED') {
      message = 'This timesheet has been paid and cannot be amended directly.';
    } else if (code === 'TIMESHEET_SEGMENT_INVOICE_LOCKED_EDIT_BLOCKED') {
      message = 'This timesheet has invoice-locked segments. Create an additional manual adjustment for any further expenses or expense evidence.';
    } else if (code === 'TIMESHEET_INVOICE_LOCKED_EDIT_BLOCKED') {
      message = 'This timesheet is invoice locked. Create an additional manual adjustment for any further expenses or expense evidence.';
    } else if (code === 'IMPORT_AUTHORITATIVE_EXPENSES_BLOCKED' || code === 'IMPORT_AUTHORITATIVE_ROUTE') {
      message = 'This original import-authoritative timesheet is view-only for direct expenses. Create an additional manual timesheet for expenses and expense evidence.';
    } else if (code === 'PROTECTED_IMPORT_OR_SYSTEM_EVIDENCE' || code === 'SYSTEM_EVIDENCE') {
      message = 'This protected system or import evidence cannot be changed.';
    } else if (code === 'INVALID_TIMESHEET_CONTEXT') {
      message = 'Invalid or missing current timesheet context.';
    }
    return new Response(
      JSON.stringify({ error: code, error_code: code, message, protected_reason: reason }),
      { status: code === 'INVALID_TIMESHEET_CONTEXT' ? 400 : 409, headers: JSON_HEADERS }
    );
  };

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!tsId) return withCORS(env, req, badRequest('timesheet_id is required'));
  if (!evidenceId) return withCORS(env, req, badRequest('evidence_id is required'));

  if (String(evidenceId).startsWith('SYS:')) {
    return withCORS(env, req, evidencePolicyBlockedResponse({ protected_reason: 'PROTECTED_IMPORT_OR_SYSTEM_EVIDENCE', can_manage_evidence: false }, 'deleted'));
  }

  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }

  const handleTimesheetEvidenceDeleteDiagText = (v) => {
    const s = String(v == null ? '' : v).trim();
    return s || null;
  };
  const handleTimesheetEvidenceDeleteDiagKeys = (obj) => (obj && typeof obj === 'object' && !Array.isArray(obj)) ? Object.keys(obj).sort() : [];
  const handleTimesheetEvidenceDeleteDiagSignature = (obj) => {
    if (!obj || typeof obj !== 'object') {
      const s = handleTimesheetEvidenceDeleteDiagText(obj);
      return { present: !!s, backend_row_signature: null, mutation_row_signature: null, row_signature: null, expected_row_signature: null, current_row_signature: null, signature: s };
    }
    const backend = handleTimesheetEvidenceDeleteDiagText(obj.backend_row_signature);
    const mutation = handleTimesheetEvidenceDeleteDiagText(obj.mutation_row_signature);
    const row = handleTimesheetEvidenceDeleteDiagText(obj.row_signature);
    const expected = handleTimesheetEvidenceDeleteDiagText(obj.expected_row_signature);
    const current = handleTimesheetEvidenceDeleteDiagText(obj.current_row_signature);
    const generic = handleTimesheetEvidenceDeleteDiagText(obj.signature || obj.render_signature);
    return {
      present: !!(backend || mutation || row || expected || current || generic),
      backend_row_signature: backend,
      mutation_row_signature: mutation,
      row_signature: row,
      expected_row_signature: expected,
      current_row_signature: current,
      signature: backend || mutation || row || expected || current || generic || null
    };
  };
  const handleTimesheetEvidenceDeleteDiagResponseContains = (payload) => ({
    ok: Object.prototype.hasOwnProperty.call(payload || {}, 'ok'),
    evidence: !!(payload?.evidence && typeof payload.evidence === 'object'),
    queue_id: !!handleTimesheetEvidenceDeleteDiagText(payload?.queue_id),
    returned_to_queue: Object.prototype.hasOwnProperty.call(payload || {}, 'returned_to_queue'),
    backend_row_signature: !!handleTimesheetEvidenceDeleteDiagText(payload?.backend_row_signature),
    mutation_row_signature: !!handleTimesheetEvidenceDeleteDiagText(payload?.mutation_row_signature),
    row_signature: !!handleTimesheetEvidenceDeleteDiagText(payload?.row_signature),
    expected_row_signature: !!handleTimesheetEvidenceDeleteDiagText(payload?.expected_row_signature),
    current_row_signature: !!handleTimesheetEvidenceDeleteDiagText(payload?.current_row_signature),
    affected_rows: Array.isArray(payload?.affected_rows),
    refresh_required: payload?.refresh_required === true,
    requires_affected_row_refresh: payload?.requires_affected_row_refresh === true
  });
  const handleTimesheetEvidenceDeleteDiagLog = (step, extra = {}) => {
    try {
      let routePath = null;
      try { routePath = new URL(req?.url || '').pathname; } catch {}
      console.log('[TIMESHEET_SAVE_SIGNATURE_DIAG]', JSON.stringify({
        tag: 'TIMESHEET_SAVE_SIGNATURE_DIAG',
        handler: 'handleTimesheetEvidenceDelete',
        route_family: 'EVIDENCE_DELETE',
        step,
        route_path: routePath,
        requested_timesheet_id: tsId || null,
        evidence_id: typeof evidenceId === 'undefined' ? null : (evidenceId || null),
        server_utc: new Date().toISOString(),
        ...(extra && typeof extra === 'object' && !Array.isArray(extra) ? extra : {})
      }));
    } catch {}
  };
  const fetchhandleTimesheetEvidenceDeleteLifecycleSignatureDiag = async (pTimesheetId, pContractWeekId = null) => {
    if (!pTimesheetId) return { ok: false, skipped: true, reason: 'NO_TIMESHEET_ID' };
    try {
      const payload = await sbRpc(env, 'timesheet_lifecycle_signature_v1', {
        p_timesheet_id: pTimesheetId,
        p_contract_week_id: pContractWeekId || null,
        p_include_payload: false
      }, { timeoutMs: 8000 });
      const obj = Array.isArray(payload) ? (payload[0] || null) : payload;
      const signature = handleTimesheetEvidenceDeleteDiagSignature(obj);
      return { ok: signature.present, source: 'timesheet_lifecycle_signature_v1', signature, payload_field_names: handleTimesheetEvidenceDeleteDiagKeys(obj) };
    } catch (err) {
      return { ok: false, source: 'timesheet_lifecycle_signature_v1', error: String(err?.message || err || '').slice(0, 300) };
    }
  };
  const expected = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  handleTimesheetEvidenceDeleteDiagLog('received', {
    body_keys: handleTimesheetEvidenceDeleteDiagKeys(body),
    expected_timesheet_id: expected || null
  });
  if (!expected) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  const resolved = await resolveTimesheetToCurrent(env, tsId);
  if (!resolved) {
    handleTimesheetEvidenceDeleteDiagLog('timesheet_not_found', { status: 404 });
    return withCORS(env, req, notFound('Timesheet not found'));
  }
  const currentTsId = resolved.current_timesheet_id;
  handleTimesheetEvidenceDeleteDiagLog('resolved_current', {
    current_timesheet_id: currentTsId || null,
    requested_timesheet_id: resolved.requested_timesheet_id || tsId,
    was_stale: !!resolved.was_stale
  });

  if (String(expected) !== String(currentTsId)) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({ error: 'TIMESHEET_MOVED', current_timesheet_id: currentTsId }),
        { status: 409, headers: { 'Content-Type': 'application/json' } }
      )
    );
  }

  const r2DeleteLocal = async (key) => {
    const bucket = env.R2_BUCKET || env.R2;
    if (!bucket || typeof bucket.delete !== 'function') {
      throw new Error('Storage not configured (expected env.R2 or env.R2_BUCKET with delete())');
    }
    const k = String(key || '').replace(/^\/+/, '').trim();
    if (!k) return false;
    await bucket.delete(k);
    return true;
  };

  try {
    const evidencePolicy = await getTimesheetEvidenceMutationPolicy(env, currentTsId, { allow_expense_evidence_preflight: true });
    if (!evidencePolicy?.can_manage_evidence) {
      return withCORS(env, req, evidencePolicyBlockedResponse(evidencePolicy, 'deleted'));
    }

    const { rows: evRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheet_evidence` +
        `?id=eq.${enc(evidenceId)}` +
        `&timesheet_id=eq.${enc(currentTsId)}` +
        `&select=id,storage_key,kind,display_name,document_asset_id,source_revision,processing_state` +
        `&limit=1`
    );
    const ev = evRows?.[0] || null;
    if (!ev) return withCORS(env, req, notFound('Evidence not found for this timesheet'));

    const evPolicy = await getTimesheetEvidenceMutationPolicy(env, currentTsId, { evidence_item: ev });
    if (!evPolicy?.can_manage_evidence) {
      return withCORS(env, req, evidencePolicyBlockedResponse(evPolicy, 'deleted'));
    }

    let tsMeta = null;
    try {
      const { rows: tsRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
          `?timesheet_id=eq.${enc(currentTsId)}` +
          `&is_current=eq.true` +
          `&select=timesheet_id,contract_id,week_ending_date,sheet_scope,submission_mode,manual_pdf_r2_key,manual_pdf_rotation_degrees,generated_pdf_at_utc,manual_document_asset_id,document_revision,document_state,active_document_operation_id` +
          `&limit=1`
      );
      tsMeta = tsRows?.[0] || null;
    } catch {}

    const beforeSignatureDiag = await fetchhandleTimesheetEvidenceDeleteLifecycleSignatureDiag(currentTsId, null);
    const storageKeyRaw = ev.storage_key || null;
    const storageKeyForR2 = storageKeyRaw ? String(storageKeyRaw).trim().replace(/^\/+/, '') : null;

    handleTimesheetEvidenceDeleteDiagLog('before_write', {
      current_timesheet_id: currentTsId || null,
      evidence_id: evidenceId || null,
      evidence_kind: ev?.kind || null,
      storage_key_present: !!storageKeyForR2,
      before_signature: beforeSignatureDiag
    });

    try {
      if (storageKeyForR2 && !isInvoiceAsyncPipelineEnabled(env)) {
        await r2DeleteLocal(storageKeyForR2);
      }
    } catch (e) {
      console.warn('[handleTimesheetEvidenceDelete] R2 delete failed (non-fatal)', {
        storage_key: storageKeyForR2,
        err: e?.message || String(e)
      });
    }

    const delRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheet_evidence?id=eq.${enc(evidenceId)}`,
      { method: 'DELETE', headers: { ...sbHeaders(env), Prefer: 'return=minimal' } }
    );

    if (!delRes.ok) {
      const t = await delRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to delete timesheet evidence: ${t}`));
    }

    if (storageKeyForR2 && !isInvoiceAsyncPipelineEnabled(env)) {
      try {
        const provDelRes = await fetch(
          `${env.SUPABASE_URL}/rest/v1/manual_timesheet_queue` +
            `?timesheet_id=eq.${enc(currentTsId)}` +
            `&r2_key=eq.${enc(storageKeyForR2)}`,
          {
            method: 'DELETE',
            headers: { ...sbHeaders(env), Prefer: 'return=minimal' }
          }
        );
        if (!provDelRes.ok) {
          const txtProv = await provDelRes.text().catch(() => '');
          console.warn('[handleTimesheetEvidenceDelete] matching provenance delete failed (non-fatal)', {
            timesheet_id: currentTsId,
            storage_key: storageKeyForR2,
            err: txtProv
          });
        }
      } catch (e) {
        console.warn('[handleTimesheetEvidenceDelete] matching provenance delete exception (non-fatal)', {
          timesheet_id: currentTsId,
          storage_key: storageKeyForR2,
          err: e?.message || String(e)
        });
      }
    }

    try {
      const patches = {};

      const mk = tsMeta?.manual_pdf_r2_key ? String(tsMeta.manual_pdf_r2_key).replace(/^\/+/, '').trim() : '';
      const sk = storageKeyForR2 ? String(storageKeyForR2).trim() : '';
      const evKindU = String(ev.kind || '').toUpperCase();

      if (evKindU === 'TIMESHEET') {
        if (
          isInvoiceAsyncPipelineEnabled(env)
          && ev.document_asset_id
          && String(tsMeta?.manual_document_asset_id || '') === String(ev.document_asset_id)
        ) {
          patches.manual_document_asset_id = null;
        } else if (!isInvoiceAsyncPipelineEnabled(env) && mk && sk && mk === sk) {
          patches.manual_pdf_r2_key = null;
          patches.manual_pdf_rotation_degrees = 0;
        }
      }

      const generatedKey = `docs-pdf/timesheets/ts_${currentTsId}.pdf`;
      if (!isInvoiceAsyncPipelineEnabled(env) && sk && sk === generatedKey) {
        patches.generated_pdf_at_utc = null;
      }

      if (Object.keys(patches).length) {
        const updRes = await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTsId)}&is_current=eq.true`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
            body: JSON.stringify(patches)
          }
        );

        if (!updRes.ok) {
          const txt2 = await updRes.text().catch(() => '');
          console.warn('[handleTimesheetEvidenceDelete] timesheets pointer cleanup failed (non-fatal)', {
            timesheet_id: currentTsId,
            patches,
            err: txt2
          });
        }
      }
    } catch (e) {
      console.warn('[handleTimesheetEvidenceDelete] pointer cleanup failed (non-fatal)', {
        timesheet_id: currentTsId,
        err: e?.message || String(e)
      });
    }

    try {
      await writeAudit(
        env,
        user,
        'TIMESHEET_EVIDENCE_REMOVED',
        {
          timesheet_id: currentTsId,
          evidence_id: evidenceId,
          kind: ev.kind || null,
          display_name: ev.display_name || null,
          storage_key: storageKeyRaw,
          contract_id: tsMeta?.contract_id || null,
          week_ending_date: tsMeta?.week_ending_date || null,
          sheet_scope: tsMeta?.sheet_scope || null,
          submission_mode: tsMeta?.submission_mode || null
        },
        { entity: 'timesheets', subject_id: currentTsId, req }
      );
    } catch {}

    const afterSignatureDiag = await fetchhandleTimesheetEvidenceDeleteLifecycleSignatureDiag(currentTsId, null);
    const responsePayload = {
      ok: true,
      requested_timesheet_id: resolved.requested_timesheet_id || tsId,
      current_timesheet_id: currentTsId,
      was_stale: !!resolved.was_stale,
      document_revision: tsMeta?.document_revision ?? null,
      document_state: tsMeta?.document_state || null,
      active_document_operation_id: tsMeta?.active_document_operation_id || null,
      immutable_source_preserved: isInvoiceAsyncPipelineEnabled(env)
    };
    handleTimesheetEvidenceDeleteDiagLog('response_shape', {
      status: 200,
      current_timesheet_id: currentTsId || null,
      evidence_id: evidenceId || null,
      evidence_kind: ev?.kind || null,
      before_signature: beforeSignatureDiag,
      after_signature: afterSignatureDiag,
      response_signature: handleTimesheetEvidenceDeleteDiagSignature(responsePayload),
      response_contains: handleTimesheetEvidenceDeleteDiagResponseContains(responsePayload)
    });

    return withCORS(env, req, ok(responsePayload));
  } catch (e) {
    return withCORS(env, req, serverError(`Failed to delete timesheet evidence: ${e?.message || e}`));
  }
}




// Resolve any timesheet_id (current or historical) to the current row for its booking_id.
// Returns null if the requested timesheet_id does not exist.

async function resolveTimesheetToCurrent(env, timesheet_id) {
  const enc = encodeURIComponent;
  const WLOG = true;
  const wlog = (step, extra = {}) => {
    if (!WLOG) return;
    try {
      console.log(JSON.stringify({
        tag: 'RESOLVE_TIMESHEET_TO_CURRENT',
        step,
        at_utc: new Date().toISOString(),
        requested_timesheet_id: String(timesheet_id || ''),
        ...(extra && typeof extra === 'object' ? extra : {})
      }));
    } catch {}
  };

  if (!timesheet_id) return null;

  wlog('start');

  // 1) Load the requested row by PK (current OR historical)
  const { rows: reqRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(timesheet_id)}` +
      `&select=timesheet_id,booking_id,version,is_current` +
      `&limit=1`
  );

  const reqRow = (reqRows && reqRows[0]) ? reqRows[0] : null;
  if (!reqRow) {
    wlog('not_found_requested_row');
    return null;
  }

  const booking_id = reqRow.booking_id || null;

  wlog('requested_row_loaded', {
    requested_row: reqRow
  });

  // If booking_id is missing, we cannot resolve the series.
  // Return a structured response so callers can turn this into a 400.
  if (!booking_id) {
    const out = {
      booking_id: null,
      requested_timesheet_id: reqRow.timesheet_id,
      current_timesheet_id: reqRow.timesheet_id,
      current_version: reqRow.version != null ? Number(reqRow.version) : null,
      was_stale: false
    };
    wlog('finish_no_booking_id', out);
    return out;
  }

  // 2) Load the current row for this booking_id
  let curRow = null;
  try {
    const { rows: curRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?booking_id=eq.${enc(booking_id)}` +
        `&is_current=eq.true` +
        `&select=timesheet_id,booking_id,version,is_current` +
        `&order=version.desc` +
        `&limit=1`
    );
    curRow = (curRows && curRows[0]) ? curRows[0] : null;
  } catch {
    curRow = null;
  }

  wlog('queried_current_row', {
    booking_id,
    current_row: curRow
  });

  // Defensive fallback if data is inconsistent (no is_current row found):
  // pick the highest version row.
  if (!curRow) {
    try {
      const { rows: vRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
          `?booking_id=eq.${enc(booking_id)}` +
          `&select=timesheet_id,booking_id,version,is_current` +
          `&order=version.desc` +
          `&limit=1`
      );
      curRow = (vRows && vRows[0]) ? vRows[0] : null;
    } catch {
      curRow = null;
    }

    wlog('fallback_highest_version_row', {
      booking_id,
      fallback_row: curRow
    });
  }

  // If still missing, treat the requested row as the best-known "current".
  if (!curRow) curRow = reqRow;

  const current_timesheet_id = curRow.timesheet_id;
  const current_version = curRow.version != null ? Number(curRow.version) : null;

  const out = {
    booking_id,
    requested_timesheet_id: reqRow.timesheet_id,
    current_timesheet_id,
    current_version,
    was_stale: String(reqRow.timesheet_id) !== String(current_timesheet_id)
  };

  wlog('finish', out);

  return out;
}



async function validateDailyRotaRowAgainstTimesheet(env, ts, hrRow, { roleForRates }) {
  const LOG = (typeof wranglerimportlog !== 'undefined' && wranglerimportlog === true);
  const L = (...a) => { if (LOG) console.log('[TSFIN][DAILY][validateDailyRotaRowAgainstTimesheet]', ...a); };

  const enc = encodeURIComponent;

  const normRole = (s) =>
    String(s || '').trim().replace(/\s+/g, ' ').toUpperCase();

  const normBand = (v) => {
    const s = String(v || '').trim();
    if (!s) return null;
    let m = s.match(/^\s*band\s*([0-9]+)\s*$/i);
    if (!m) m = s.match(/^\s*b\s*([0-9]+)\s*$/i);
    if (!m) m = s.match(/^\s*([0-9]+)\s*$/);
    if (m && m[1]) return `Band ${parseInt(m[1], 10)}`;
    return s;
  };

  const hrRequestId = hrRow?.hr_request_id || hrRow?.payload_json?.request_id || null;
  const dateLocal   = hrRow?.date_local || null;

  L('START', { timesheet_id: ts?.timesheet_id, hr_request_id: hrRequestId, date_local: dateLocal });

  const pad2 = (n) => String(n).padStart(2, '0');

  const parseHhmm = (v) => {
    if (v == null || v === '') return null;
    if (typeof v === 'number') {
      if (v >= 0 && v < 1) {
        const totalMinutes = Math.round(v * 24 * 60);
        const hh = Math.floor(totalMinutes / 60);
        const mm = totalMinutes % 60;
        return `${pad2(hh)}:${pad2(mm)}`;
      }
    }
    const s = String(v).trim();
    if (!s) return null;
    const m = s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
    if (!m) {
      const s2 = s.replace(':', '');
      if (/^\d{3,4}$/.test(s2)) {
        const hh = pad2(parseInt(s2.slice(0, -2), 10) || 0);
        const mm = pad2(parseInt(s2.slice(-2), 10) || 0);
        return `${hh}:${mm}`;
      }
      return null;
    }
    return `${pad2(parseInt(m[1], 10) || 0)}:${pad2(parseInt(m[2], 10) || 0)}`;
  };

  const hhmmToMinutes = (hhmm) => {
    if (!hhmm) return null;
    const [h, m] = hhmm.split(':').map(Number);
    if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
    return h * 60 + m;
  };

  const parseActualHours = (v) => {
    if (v == null || v === '') return null;
    if (typeof v === 'number') return Number(v);
    const s = String(v).trim();
    if (!s) return null;
    const m = s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
    if (m) {
      const h = parseInt(m[1], 10) || 0;
      const mm = parseInt(m[2], 10) || 0;
      return h + mm / 60;
    }
    const num = Number(s);
    return Number.isFinite(num) ? num : null;
  };

  const parseBreakMinutes = (v) => {
    if (v == null || v === '') return null;
    if (typeof v === 'number') {
      if (!Number.isFinite(v)) return null;
      if (v >= 0 && v <= 600) return Math.round(v);
      // support Excel day-fraction formats (rare, but safe)
      if (v > 0 && v < 1) {
        const mins = Math.round(v * 24 * 60);
        if (mins >= 0 && mins <= 600) return mins;
      }
      return null;
    }
    const s = String(v).trim();
    if (!s) return null;
    const m = s.match(/^\s*([0-9]+)\s*(mins?|minutes?)?\s*$/i);
    if (m && m[1]) {
      const n = Number(m[1]);
      if (Number.isFinite(n) && n >= 0 && n <= 600) return Math.round(n);
    }
    const num = Number(s);
    if (Number.isFinite(num) && num >= 0 && num <= 600) return Math.round(num);
    return null;
  };

  const addDaysYmd = (ymd, days) => {
    const d = new Date(`${String(ymd)}T00:00:00Z`);
    if (!Number.isFinite(d.getTime())) return null;
    d.setUTCDate(d.getUTCDate() + Number(days || 0));
    return `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`;
  };

  const localToUtcIso = (ymd, hhmm, addDays = 0, opts = null) => {
    if (!ymd || !hhmm) return null;

    const base = new Date(`${String(ymd)}T00:00:00Z`);
    if (!Number.isFinite(base.getTime())) return null;
    if (addDays) {
      base.setUTCDate(base.getUTCDate() + Number(addDays || 0));
    }

    const y2 = base.getUTCFullYear();
    const m2 = base.getUTCMonth() + 1;
    const d2 = base.getUTCDate();
    const targetYmd = `${y2}-${pad2(m2)}-${pad2(d2)}`;

    if (typeof ukLocalToUtcISO === 'function') {
      const options = (opts && typeof opts === 'object') ? opts : null;
      return ukLocalToUtcISO(targetYmd, hhmm, options);
    }

    const m = String(hhmm).trim().match(/^(\d{2}):(\d{2})(?::\d{2})?$/);
    if (!m) return null;
    const hh = Number(m[1]);
    const mm = Number(m[2]);
    if (!Number.isFinite(hh) || !Number.isFinite(mm)) return null;

    return new Date(Date.UTC(y2, m2 - 1, d2, hh, mm, 0, 0)).toISOString();
  };

  const uniqueLocalUtcCandidates = (ymd, hhmm) => {
    const out = [];
    const seen = new Set();

    const pushIso = (iso) => {
      if (!iso) return;
      const ms = new Date(String(iso)).getTime();
      if (!Number.isFinite(ms)) return;
      const normIso = new Date(ms).toISOString();
      if (seen.has(normIso)) return;
      seen.add(normIso);
      out.push({ iso: normIso, ms });
    };

    if (typeof ukLocalToUtcISO === 'function') {
      pushIso(localToUtcIso(ymd, hhmm, 0, { prefer: 'earlier' }));
      pushIso(localToUtcIso(ymd, hhmm, 0, { prefer: 'later' }));
    } else {
      pushIso(localToUtcIso(ymd, hhmm, 0));
    }

    out.sort((a, b) => a.ms - b.ms);
    return out;
  };

  const resolveShiftUtcRange = (workDateYmd, startHhmm, endHhmm) => {
    if (!workDateYmd || !startHhmm || !endHhmm) {
      return { startUtcIso: null, endUtcIso: null, error: 'Shift date/start/end are required' };
    }

    const startMins = hhmmToMinutes(startHhmm);
    const endMins = hhmmToMinutes(endHhmm);
    if (startMins == null || endMins == null) {
      return { startUtcIso: null, endUtcIso: null, error: `Invalid HH:MM for ${workDateYmd}` };
    }
    if (startMins === endMins) {
      return { startUtcIso: null, endUtcIso: null, error: `Shift start and end cannot be the same on ${workDateYmd}` };
    }

    const overnight = endMins <= startMins;
    const endYmd = overnight ? addDaysYmd(workDateYmd, 1) : workDateYmd;
    if (!endYmd) {
      return { startUtcIso: null, endUtcIso: null, error: `Invalid work date for ${workDateYmd}` };
    }

    if (typeof ukLocalToUtcISO !== 'function') {
      const startUtcIso = localToUtcIso(workDateYmd, startHhmm, 0);
      const endUtcIso = localToUtcIso(workDateYmd, endHhmm, overnight ? 1 : 0);
      const startMs = new Date(String(startUtcIso || '')).getTime();
      const endMs = new Date(String(endUtcIso || '')).getTime();
      if (!startUtcIso || !endUtcIso || !Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid local time range on ${workDateYmd}` };
      }
      return {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        error: null
      };
    }

    const startCandidates = uniqueLocalUtcCandidates(workDateYmd, startHhmm);
    if (!startCandidates.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Non-existent local start time on ${workDateYmd}` };
    }

    const endCandidates = uniqueLocalUtcCandidates(endYmd, endHhmm);
    if (!endCandidates.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Non-existent local end time on ${endYmd}` };
    }

    const pairMap = new Map();

    const pushPair = (startIso, endIso) => {
      if (!startIso || !endIso) return;
      const startMs = new Date(String(startIso)).getTime();
      const endMs = new Date(String(endIso)).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return;
      const key = `${startMs}|${endMs}`;
      if (pairMap.has(key)) return;
      pairMap.set(key, {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        startMs,
        endMs
      });
    };

    for (const startCand of startCandidates) {
      const endIsoAfterStart = localToUtcIso(endYmd, endHhmm, 0, { afterIso: startCand.iso, prefer: 'later' });
      pushPair(startCand.iso, endIsoAfterStart);

      for (const endCand of endCandidates) {
        pushPair(startCand.iso, endCand.iso);
      }
    }

    const pairs = Array.from(pairMap.values()).sort((a, b) => a.startMs - b.startMs || a.endMs - b.endMs);

    if (!pairs.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Invalid local time range on ${workDateYmd}` };
    }

    if (pairs.length > 1) {
      return { startUtcIso: null, endUtcIso: null, error: `Ambiguous local time range across DST change on ${workDateYmd}` };
    }

    return {
      startUtcIso: pairs[0].startUtcIso,
      endUtcIso: pairs[0].endUtcIso,
      error: null
    };
  };

  const utcElapsedMinutes = (startIso, endIso) => {
    if (!startIso || !endIso) return null;
    const startMs = new Date(String(startIso)).getTime();
    const endMs = new Date(String(endIso)).getTime();
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return null;
    return Math.round((endMs - startMs) / 60000);
  };

  // ─────────────────────────────────────────────────────────────
  // HR / Rota parsing
  // ─────────────────────────────────────────────────────────────
  const hrStartLocal = parseHhmm(hrRow?.start_time_local || hrRow?.payload_json?.start_local || hrRow?.payload_json?.start_time_local);
  const hrEndLocal   = parseHhmm(hrRow?.end_time_local   || hrRow?.payload_json?.end_local   || hrRow?.payload_json?.end_time_local);

  const hrStartMin = hhmmToMinutes(hrStartLocal);
  const hrEndMin   = hhmmToMinutes(hrEndLocal);

  let shiftMinutes = null;
  const hrResolvedRange =
    (dateLocal && hrStartLocal && hrEndLocal)
      ? resolveShiftUtcRange(dateLocal, hrStartLocal, hrEndLocal)
      : { startUtcIso: null, endUtcIso: null, error: null };

  if (hrResolvedRange.startUtcIso && hrResolvedRange.endUtcIso) {
    shiftMinutes = utcElapsedMinutes(hrResolvedRange.startUtcIso, hrResolvedRange.endUtcIso);
  }

  const actualHoursRota =
    parseActualHours(hrRow?.hours_worked) ??
    parseActualHours(hrRow?.payload_json?.actual_hours);

  let paidMinutesRota = null;
  if (actualHoursRota != null) {
    paidMinutesRota = Math.round(actualHoursRota * 60);
  }

  let breakMinutesRota = null;
  if (shiftMinutes != null && paidMinutesRota != null) {
    breakMinutesRota = Math.max(0, shiftMinutes - paidMinutesRota);
  }

  // If rota hours are not provided, try to use explicit break minutes from file (common in HR exports).
  const breakMinutesRotaExplicit =
    parseBreakMinutes(hrRow?.payload_json?.break_minutes) ??
    parseBreakMinutes(hrRow?.payload_json?.breakMinutes) ??
    parseBreakMinutes(hrRow?.payload_json?.BreakMinutes) ??
    parseBreakMinutes(hrRow?.payload_json?.Break) ??
    parseBreakMinutes(hrRow?.payload_json?.['Actual Break']) ??
    parseBreakMinutes(hrRow?.payload_json?.ActualBreak) ??
    null;

  const breakMinutesRotaForDisplay =
    (breakMinutesRota != null ? breakMinutesRota : breakMinutesRotaExplicit);

  L('rota parsed', {
    hr_start_local: hrStartLocal,
    hr_end_local: hrEndLocal,
    shift_minutes: shiftMinutes,
    actual_hours: actualHoursRota,
    break_minutes: breakMinutesRotaForDisplay,
    hr_shift_resolution_error: hrResolvedRange.error || null
  });

  // ─────────────────────────────────────────────────────────────
  // Timesheet time derivation
  // ─────────────────────────────────────────────────────────────
  const tsStartIso = ts.worked_start_iso || null;
  const tsEndIso   = ts.worked_end_iso   || null;

  let tsStartMin = null;
  let tsEndMin   = null;
  let tsShiftMin = null;

  let tsStartLocal = null;
  let tsEndLocal = null;

  if (tsStartIso && tsEndIso) {
    try {
      const partsStart = toLocalParts(tsStartIso, null);
      const partsEnd   = toLocalParts(tsEndIso, null);
      const sHm = partsStart && partsStart.hm ? partsStart.hm : tsStartIso.slice(11, 16);
      const eHm = partsEnd   && partsEnd.hm   ? partsEnd.hm   : tsEndIso.slice(11, 16);

      tsStartLocal = parseHhmm(sHm) || null;
      tsEndLocal   = parseHhmm(eHm) || null;

      tsStartMin = hhmmToMinutes(tsStartLocal);
      tsEndMin   = hhmmToMinutes(tsEndLocal);

      tsShiftMin = utcElapsedMinutes(tsStartIso, tsEndIso);
    } catch {}
  }

  // Load TSFIN
  let tsfin = null;
  try {
    const { rows: finRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
        `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
        `&is_current=eq.true` +
        `&select=timesheet_id,total_hours,hours_day,hours_night,hours_sat,hours_sun,hours_bh,` +
        `candidate_id,client_id,break_minutes` +
        `&limit=1`
    );
    tsfin = finRows?.[0] || null;
  } catch (e) {
    console.warn('[HR_DAILY_VALIDATE] TSFIN lookup failed', {
      timesheet_id: ts.timesheet_id,
      err: e?.message || String(e)
    });
  }

  const totalHoursTsfin = tsfin?.total_hours != null ? Number(tsfin.total_hours) : null;

  let breakMinutesTs = null;
  if (typeof ts.break_minutes === 'number') {
    breakMinutesTs = ts.break_minutes;
  } else if (tsfin?.break_minutes != null) {
    breakMinutesTs = tsfin.break_minutes;
  } else if (tsShiftMin != null && totalHoursTsfin != null) {
    const b = tsShiftMin - totalHoursTsfin * 60;
    breakMinutesTs = b > 0 ? b : 0;
  }

  const refBefore =
    (ts.reference_number != null && String(ts.reference_number).trim())
      ? String(ts.reference_number).trim()
      : null;

  const refAfter =
    (hrRequestId != null && String(hrRequestId).trim())
      ? String(hrRequestId).trim()
      : null;

  L('timesheet/tsfin derived', {
    ts_start_iso: tsStartIso,
    ts_end_iso: tsEndIso,
    ts_start_local: tsStartLocal,
    ts_end_local: tsEndLocal,
    ts_shift_minutes: tsShiftMin,
    ts_break_minutes: breakMinutesTs,
    tsfin_total_hours: totalHoursTsfin,
    tsfin_candidate_id: tsfin?.candidate_id || null,
    tsfin_client_id: tsfin?.client_id || null,
    ref_before: refBefore,
    ref_after: refAfter
  });

  let reason = null;

  // 1) Start/end mismatch
  if (reason == null && hrStartMin != null && tsStartMin != null) {
    const diffStart = Math.abs(hrStartMin - tsStartMin);
    const diffEnd   = (hrEndMin != null && tsEndMin != null) ? Math.abs(hrEndMin - tsEndMin) : 0;
    if (diffStart > 1 || diffEnd > 1) reason = 'start_end_mismatch';
    L('check start/end', { diffStart, diffEnd, reason });
  }

  // 2) Break minutes mismatch
  if (reason == null && breakMinutesRotaForDisplay != null && breakMinutesTs != null) {
    const diffBreak = Math.abs(breakMinutesRotaForDisplay - breakMinutesTs);
    if (diffBreak > 5) reason = 'break_minutes_mismatch';
    L('check breaks', { diffBreak, reason });
  }

  // 3) Actual hours mismatch
  if (reason == null && actualHoursRota != null && totalHoursTsfin != null) {
    const diffHours = Math.abs(actualHoursRota - totalHoursTsfin);
    if (diffHours > 0.05) reason = 'actual_hours_mismatch';
    L('check hours', { diffHours, reason });
  }

  // 4) Grade → rates existence
  if (reason == null) {
    let rf = roleForRates && roleForRates.role
      ? { role: normRole(roleForRates.role), band: normBand(roleForRates.band || null) }
      : null;

    L('roleForRates input', { rf_in: roleForRates || null, rf });

    if (!rf) {
      try {
        const clientId     = tsfin?.client_id || null;
        const candidateId  = tsfin?.candidate_id || null;
        const gradeGuess =
          hrRow?.grade ||
          hrRow?.payload_json?.grade ||
          ts.job_title_norm ||
          null;

        L('derive roleForRates (best-effort)', { clientId, candidateId, dateLocal, gradeGuess });

        if (clientId && candidateId && dateLocal && gradeGuess) {
          const mapped = await mapRequestGradeToRole(env, {
            client_id: clientId,
            candidate_id: candidateId,
            gradeRaw: gradeGuess,
            dateYmd: dateLocal
          });
          L('mapped grade->role', mapped || null);
          if (mapped?.role) rf = { role: normRole(mapped.role), band: normBand(mapped.band || null) };
        }
      } catch (e) {
        L('derive roleForRates failed', { err: String(e?.message || e) });
      }
    }

    if (!rf || !rf.role) {
      reason = 'rate_missing_for_grade';
      L('rate check: missing roleForRates', { reason });
    } else {
      try {
        const usedBuckets = {
          day:   Number(tsfin?.hours_day   || 0),
          night: Number(tsfin?.hours_night || 0),
          sat:   Number(tsfin?.hours_sat   || 0),
          sun:   Number(tsfin?.hours_sun   || 0),
          bh:    Number(tsfin?.hours_bh    || 0)
        };

        const clientId     = tsfin?.client_id || null;
        const candidateId  = tsfin?.candidate_id || null;

        L('rate check: resolveRates', { usedBuckets, clientId, candidateId, rf, dateLocal });

        const rates = await resolveRates(env, {
          candidate_id: candidateId,
          client_id: clientId,
          role: rf.role,
          band: rf.band || null,
          dateYmd: dateLocal || null
        });

        const pay = rates.pay || {};
        const chg = rates.charge || {};

        const anyMissing =
          (usedBuckets.day   > 0 && (pay.day   == null || chg.day   == null)) ||
          (usedBuckets.night > 0 && (pay.night == null || chg.night == null)) ||
          (usedBuckets.sat   > 0 && (pay.sat   == null || chg.sat   == null)) ||
          (usedBuckets.sun   > 0 && (pay.sun   == null || chg.sun   == null)) ||
          (usedBuckets.bh    > 0 && (pay.bh    == null || chg.bh    == null));

        if (anyMissing) reason = 'rate_missing_for_grade';

        L('rate check result', {
          source: rates?.source || null,
          pay,
          charge: chg,
          anyMissing,
          reason
        });
      } catch (e) {
        console.warn('[HR_DAILY_VALIDATE] resolveRates failed for grade role', {
          timesheet_id: ts.timesheet_id,
          err: e?.message || String(e)
        });
        reason = 'rate_missing_for_grade';
        L('rate check exception', { err: String(e?.message || e), reason });
      }
    }
  }

  // ✅ IMPORTANT: detail must contain the keys expected by the weekly Mode-A renderer.
  // - HR side: detail.start_local / detail.end_local / detail.healthroster_break_mins
  // - TS side: detail.timesheet_start / detail.timesheet_end / detail.timesheet_break_mins
  // Also keep existing fields for downstream email/diagnostics.
  const matchStatus = reason ? 'MISMATCH' : 'MATCH';

  const detail = {
    // identity
    hr_request_id: hrRequestId,
    date_local: dateLocal,

    // match status used by adapter/renderers
    match_status: matchStatus,

    // HR (HealthRoster) — keys the UI reads
    start_local: hrStartLocal,
    end_local: hrEndLocal,
    healthroster_start: hrStartLocal,
    healthroster_end: hrEndLocal,
    healthroster_break_mins: breakMinutesRotaForDisplay,

    // Back-compat HR aliases used elsewhere
    hr_start_local: hrStartLocal,
    hr_end_local: hrEndLocal,
    hr_start: hrStartLocal,
    hr_end: hrEndLocal,
    hr_shift_minutes: shiftMinutes,
    hr_actual_hours: actualHoursRota,
    hr_hours: actualHoursRota,
    hours_worked: actualHoursRota,
    hr_break_minutes: breakMinutesRotaForDisplay,
    hr_break_mins: breakMinutesRotaForDisplay,

    // Timesheet — keys the UI reads
    timesheet_start: tsStartLocal,
    timesheet_end: tsEndLocal,
    timesheet_break_mins: breakMinutesTs,

    // Back-compat TS aliases / diagnostics
    ts_start_local: tsStartLocal,
    ts_end_local: tsEndLocal,
    ts_shift_minutes: tsShiftMin,
    ts_break_minutes: breakMinutesTs,
    ts_break_mins: breakMinutesTs,
    ts_total_hours: totalHoursTsfin,
    ts_hours: totalHoursTsfin,
    ts_worked_start_iso: tsStartIso,
    ts_worked_end_iso: tsEndIso,

    // References (useful for UI and for invoice-lock semantics elsewhere)
    ref_before: refBefore || '',
    ref_after: refAfter || ''
  };

  if (!reason) {
    L('EXIT OK', detail);
    return { ok: true, reason_code: null, hr_request_id: hrRequestId, detail };
  }

  L('EXIT FAIL', { reason, detail });
  return { ok: false, reason_code: reason, hr_request_id: hrRequestId, detail };
}


async function handleTimesheetsResolvePreview(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    body = null;
  }

  const trimStr = (v) => String(v == null ? '' : v).trim();
  const normalizeIdArray = (arr) => Array.from(new Set(
    (Array.isArray(arr) ? arr : [])
      .map((v) => trimStr(v))
      .filter(Boolean)
  ));
  const clonePlain = (value) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    try {
      return JSON.parse(JSON.stringify(value));
    } catch {
      const out = {};
      Object.keys(value).forEach((key) => {
        out[key] = value[key];
      });
      return out;
    }
  };

  const selectionScope = (body && body.selection_scope && typeof body.selection_scope === 'object' && !Array.isArray(body.selection_scope))
    ? body.selection_scope
    : ((body && body.selectionScope && typeof body.selectionScope === 'object' && !Array.isArray(body.selectionScope)) ? body.selectionScope : null);

  const ids = Array.isArray(body?.timesheet_ids)
    ? [...new Set(body.timesheet_ids.map(String).filter(Boolean))]
    : [];

  const previewLimitRaw = Number(body?.preview_limit ?? body?.previewLimit ?? 200);
  const previewLimit = Number.isFinite(previewLimitRaw) ? Math.max(1, Math.min(500, Math.trunc(previewLimitRaw))) : 200;

  if (!selectionScope && !ids.length) {
    return withCORS(
      env,
      req,
      badRequest('timesheet_ids[] required')
    );
  }

  const fetchResolveRows = async (timesheetIds) => {
    const rowsByTimesheetId = new Map();
    const chunkSize = 200;

    for (let idx = 0; idx < timesheetIds.length; idx += chunkSize) {
      const chunk = timesheetIds.slice(idx, idx + chunkSize);
      const idsParam = chunk.map(encodeURIComponent).join(',');
      if (!idsParam) continue;

      const { rows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary` +
          `?timesheet_id=in.(${idsParam})` +
          `&select=` +
            [
              'timesheet_id',
              'sheet_scope',
              'week_ending_date',
              'candidate_id',
              'client_id',
              'processing_status',
              'occupant_key_norm',
              'hospital_norm',
              'candidate_name',
              'candidate_hint_text'
            ].join(',')
      );

      (rows || []).forEach((row) => {
        const timesheetId = trimStr(row && row.timesheet_id);
        if (!timesheetId) return;
        rowsByTimesheetId.set(timesheetId, row);
      });
    }

    return rowsByTimesheetId;
  };

  try {
    if (!selectionScope) {
      const rowsByTimesheetId = await fetchResolveRows(ids);

      const filtered = ids
        .map((timesheetId) => rowsByTimesheetId.get(String(timesheetId)) || null)
        .filter(Boolean)
        .filter((row) => {
          const p = String(row.processing_status || '').toUpperCase();
          return p === 'UNASSIGNED' || p === 'CLIENT_UNRESOLVED';
        });

      return withCORS(env, req, ok(filtered));
    }

    const selectionMode = trimStr(selectionScope.selection_mode || selectionScope.mode).toLowerCase() === 'all_filtered'
      ? 'all_filtered'
      : 'explicit';

    const includedIds = normalizeIdArray(
      Array.isArray(selectionScope.included_ids)
        ? selectionScope.included_ids
        : (Array.isArray(selectionScope.ids) ? selectionScope.ids : [])
    );

    const excludedIds = normalizeIdArray(
      selectionMode === 'all_filtered' && Array.isArray(selectionScope.excluded_ids)
        ? selectionScope.excluded_ids
        : []
    );

    const effectiveFilters = clonePlain(
      (body && body.effective_filters && typeof body.effective_filters === 'object' && !Array.isArray(body.effective_filters))
        ? body.effective_filters
        : ((selectionScope.effective_filters && typeof selectionScope.effective_filters === 'object' && !Array.isArray(selectionScope.effective_filters))
            ? selectionScope.effective_filters
            : ((selectionScope.filters && typeof selectionScope.filters === 'object' && !Array.isArray(selectionScope.filters))
                ? selectionScope.filters
                : {}))
    );

    const resolvedSelection = await resolveBulkContextIdsFromSummarySelection(
      'timesheets',
      effectiveFilters,
      selectionMode,
      includedIds,
      excludedIds,
      env,
      req
    );

    const timesheetIds = normalizeIdArray(resolvedSelection && resolvedSelection.context_ids);
    const skippedRows = Array.isArray(resolvedSelection && resolvedSelection.skipped_rows)
      ? resolvedSelection.skipped_rows.map((row) => ({
          selected_row_id: row && row.selected_row_id != null ? String(row.selected_row_id) : null,
          skip_reason: row && row.skip_reason != null ? String(row.skip_reason) : 'SKIPPED'
        }))
      : [];

    if (!timesheetIds.length) {
      return withCORS(env, req, ok({
        rows: [],
        unresolved_total: 0,
        preview_count: 0,
        capped: false,
        selection_scope: {
          section: 'timesheets',
          dataset_key: trimStr(selectionScope.dataset_key || selectionScope.fingerprint || ''),
          selection_mode: selectionMode,
          included_ids: includedIds.slice(),
          excluded_ids: excludedIds.slice(),
          effective_filters: effectiveFilters
        },
        resolved_timesheet_ids: [],
        skipped_rows: skippedRows
      }));
    }

    const rowsByTimesheetId = await fetchResolveRows(timesheetIds);

    const fetchSkippedRows = [];
    const filtered = [];

    timesheetIds.forEach((timesheetId) => {
      const row = rowsByTimesheetId.get(timesheetId) || null;
      if (!row) {
        fetchSkippedRows.push({
          selected_row_id: timesheetId,
          skip_reason: 'TIMESHEET_NOT_FOUND'
        });
        return;
      }

      const p = String(row.processing_status || '').toUpperCase();
      if (p === 'UNASSIGNED' || p === 'CLIENT_UNRESOLVED') {
        filtered.push(row);
      }
    });

    const previewRows = filtered.slice(0, previewLimit);
    const capped = filtered.length > previewLimit;

    return withCORS(env, req, ok({
      rows: previewRows,
      unresolved_total: filtered.length,
      preview_count: previewRows.length,
      capped,
      selection_scope: {
        section: 'timesheets',
        dataset_key: trimStr(selectionScope.dataset_key || selectionScope.fingerprint || ''),
        selection_mode: selectionMode,
        included_ids: includedIds.slice(),
        excluded_ids: excludedIds.slice(),
        effective_filters: effectiveFilters
      },
      resolved_timesheet_ids: timesheetIds,
      skipped_rows: skippedRows.concat(fetchSkippedRows)
    }));
  } catch (e) {
    return withCORS(
      env,
      req,
      serverError(`Failed to build resolve preview: ${e?.message || e}`)
    );
  }
}



async function handleTimesheetResolveCandidate(env, req, timesheetId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!timesheetId) {
    return withCORS(env, req, badRequest('timesheet_id is required'));
  }

  let body;
  try { body = await parseJSONBody(req); } catch { body = null; }

  // ✅ Guarded write
  const expected = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  if (!expected) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  const candidateId = body?.candidate_id || body?.candidateId || null;
  if (!candidateId) return withCORS(env, req, badRequest('candidate_id is required'));

  // ✅ stale-safe resolve
  const resolved = await resolveTimesheetToCurrent(env, timesheetId);
  if (!resolved?.current_timesheet_id) return withCORS(env, req, notFound('Timesheet not found'));

  const currentTimesheetId   = String(resolved.current_timesheet_id);
  const requestedTimesheetId = String(timesheetId);
  const wasStale = (currentTimesheetId !== requestedTimesheetId);

  // ✅ Guard mismatch → 409 TIMESHEET_MOVED
  if (String(expected) !== String(currentTimesheetId)) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({ error: 'TIMESHEET_MOVED', current_timesheet_id: currentTimesheetId }),
        { status: 409, headers: { 'Content-Type': 'application/json' } }
      )
    );
  }

  // Pull TSFIN knobs
  let maxInlineItems = 3;
  try {
    const s = await loadSettingsDefaults(env);
    const n = Number(s?.importConfig?.tsfin?.maxInlineItems);
    if (Number.isFinite(n) && n > 0) maxInlineItems = Math.floor(n);
  } catch {}

  try {
    // Load CURRENT timesheet (no candidate_id column on timesheets)
    const ts = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&is_current=eq.true` +
        `&select=timesheet_id,occupant_key_norm,sheet_scope,submission_mode,authorised_at_server` +
        `&limit=1`
    );
    if (!ts) return withCORS(env, req, notFound('Timesheet not found'));

    // Load candidate
    const cand = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?id=eq.${enc(candidateId)}` +
        `&select=id,nhsp_hr_name_aliases,key_norm` +
        `&limit=1`
    );
    if (!cand) return withCORS(env, req, notFound('Candidate not found'));

    const rawOcc  = ts.occupant_key_norm || '';
    const occNorm = String(rawOcc).trim().toLowerCase();

    const sheetScope = String(ts.sheet_scope || '').toUpperCase();
    const subMode    = String(ts.submission_mode || '').toUpperCase();
    const isDailyElectronic = (sheetScope === 'DAILY' && subMode === 'ELECTRONIC');

    // Helper: enqueue via SQL helper + drain a small, capped set inline
    const bumpTsfinNow = async ({ occKeyNorm }) => {
      // 1) Bulk enqueue (SQL helper)
      //    This queues ALL matching current authorised, unlocked, unpaid timesheets for this occKey.
      let enqueuedCount = 0;
      if (occKeyNorm) {
        try {
          enqueuedCount = await rpcEnqueueTsfinForOccKey(env, {
            occKey: occKeyNorm,
            reason: 'CONTEXT_CHANGED',
            priority: true,
            limit: 500
          });
        } catch (e) {
          console.warn('[TS_RESOLVE_CAND] enqueue_tsfin_for_occ_key failed', e?.message || e);
        }
      } else {
        // Fallback: only enqueue the current timesheet
        try {
          await sbRpc(env, 'enqueue_ts_financials_priority', {
            _timesheet_ids: [currentTimesheetId],
            _reason: 'CONTEXT_CHANGED'
          });
          enqueuedCount = 1;
        } catch {}
      }

      // 2) Determine inline drain ids (bounded)
      //    We always attempt the current timesheet inline.
      const inlineIds = [currentTimesheetId];

      // Optionally include a few related IDs inline (only if we have an occKeyNorm and budget)
      if (occKeyNorm && maxInlineItems > 1) {
        try {
       const { rows } = await sbFetch(
  env,
  `${env.SUPABASE_URL}/rest/v1/timesheets` +
    `?is_current=eq.true` +
    `&occupant_key_norm=eq.${enc(occKeyNorm)}` +
    `&select=timesheet_id` +
    `&limit=${Math.min(500, Math.max(1, maxInlineItems - 1) + 1)}`
);

          for (const r of (rows || [])) {
            const id = r?.timesheet_id ? String(r.timesheet_id) : '';
            if (!id || id === currentTimesheetId) continue;
            inlineIds.push(id);
            if (inlineIds.length >= maxInlineItems) break;
          }
        } catch {}
      }

      // 3) Targeted drain ONLY the inline ids
      let drainRes = null;
      try {
        drainRes = await runTsfinWorkerOnce(env, { limit: inlineIds.length, onlyTimesheetIds: inlineIds });
      } catch (e) {
        console.warn('[TS_RESOLVE_CAND] targeted runTsfinWorkerOnce failed', e?.message || e);
      }

      return { enqueuedCount, inlineIds, drainRes };
    };

    // ==========================================================
    // ✅ DAILY/ELECTRONIC = occupant_key_norm is a GCK (key_norm)
    // ==========================================================
    if (isDailyElectronic) {
      const gck = occNorm;

      if (!gck) {
        return withCORS(env, req, badRequest('Timesheet has no occupant_key_norm (GCK) to assign'));
      }

      // Block if this GCK belongs to a different candidate
      try {
        const other = await sbGetOne(
          env,
          `${env.SUPABASE_URL}/rest/v1/candidates` +
            `?key_norm=eq.${enc(gck)}` +
            `&id=neq.${enc(candidateId)}` +
            `&select=id` +
            `&limit=1`
        );
        if (other?.id) {
          return withCORS(
            env,
            req,
            new Response(
              JSON.stringify({
                error: 'CANDIDATE_KEY_CONFLICT',
                message: 'This GCK is already assigned to another candidate.',
                candidate_id: candidateId,
                conflicting_candidate_id: other.id,
                attempted_key_norm: gck
              }),
              { status: 409, headers: { 'Content-Type': 'application/json' } }
            )
          );
        }
      } catch {}

      // Block overwriting an existing different key_norm on THIS candidate
      const existingKey = String(cand.key_norm || '').trim().toLowerCase();
      if (existingKey && existingKey !== gck) {
        return withCORS(
          env,
          req,
          new Response(
            JSON.stringify({
              error: 'CANDIDATE_KEY_CONFLICT',
              message: 'This candidate already has a different key_norm; cannot assign this GCK.',
              candidate_id: candidateId,
              existing_key_norm: cand.key_norm,
              attempted_key_norm: gck
            }),
            { status: 409, headers: { 'Content-Type': 'application/json' } }
          )
        );
      }

      // Patch candidate key_norm
      const res = await fetch(
        `${env.SUPABASE_URL}/rest/v1/candidates?id=eq.${enc(candidateId)}`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({ key_norm: gck })
        }
      );
      if (!res.ok) {
        const txt = await res.text().catch(() => '');
        console.warn('[TS_RESOLVE_CAND] patch candidate key_norm failed', { candidate_id: candidateId, status: res.status, body: txt });
      }

      // ✅ Enqueue all matching occKey timesheets + drain a few inline
      await bumpTsfinNow({ occKeyNorm: gck });

    } else {
      // ==========================================================
      // Legacy behaviour: occupant_key_norm is a name alias list (nhsp_hr_name_aliases)
      // ==========================================================
      const alias = occNorm;

      if (!alias) {
        // Still kick TSFIN for the current timesheet only
        await bumpTsfinNow({ occKeyNorm: null });
      } else {
        const existingAliases = Array.isArray(cand.nhsp_hr_name_aliases) ? cand.nhsp_hr_name_aliases : [];
        const mergedAliases = normaliseAliasList([ ...existingAliases, alias ]);

        // Do NOT touch key_norm here
        const res = await fetch(
          `${env.SUPABASE_URL}/rest/v1/candidates?id=eq.${enc(candidateId)}`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
            body: JSON.stringify({ nhsp_hr_name_aliases: mergedAliases })
          }
        );
        if (!res.ok) {
          const txt = await res.text().catch(() => '');
          console.warn('[TS_RESOLVE_CAND] patch candidate aliases failed', { candidate_id: candidateId, status: res.status, body: txt });
        }

        // Enqueue all timesheets with this occupant_key_norm alias (if that’s how they’re stored)
        await bumpTsfinNow({ occKeyNorm: alias });
      }
    }

    // Return updated summary row (so FE can repaint immediately)
    let summaryRow = null;
    try {
      summaryRow = await sbGetOne(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary` +
          `?timesheet_id=eq.${enc(currentTimesheetId)}` +
          `&select=timesheet_id,processing_status,candidate_id,client_id,candidate_name,client_name` +
          `&limit=1`
      );
    } catch {}

    return withCORS(env, req, ok({
      ok: true,
      requested_timesheet_id: requestedTimesheetId,
      current_timesheet_id: currentTimesheetId,
      was_stale: wasStale,
      summary: summaryRow || null
    }));
  } catch (e) {
    return withCORS(env, req, serverError(`Failed to resolve timesheet candidate: ${e?.message || e}`));
  }
}


async function handleTimesheetResolveClient(env, req, timesheetId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!timesheetId) {
    return withCORS(env, req, badRequest('timesheet_id is required'));
  }

  let body;
  try { body = await parseJSONBody(req); } catch { body = null; }

  // ✅ Guarded write
  const expected = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  if (!expected) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  const clientId = body?.client_id || body?.clientId || null;
  if (!clientId) return withCORS(env, req, badRequest('client_id is required'));

  // ✅ stale-safe resolve
  const resolved = await resolveTimesheetToCurrent(env, timesheetId);
  if (!resolved?.current_timesheet_id) return withCORS(env, req, notFound('Timesheet not found'));

  const currentTimesheetId   = String(resolved.current_timesheet_id);
  const requestedTimesheetId = String(timesheetId);
  const wasStale = (currentTimesheetId !== requestedTimesheetId);

  // ✅ Guard mismatch → 409 TIMESHEET_MOVED
  if (String(expected) !== String(currentTimesheetId)) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({ error: 'TIMESHEET_MOVED', current_timesheet_id: currentTimesheetId }),
        { status: 409, headers: { 'Content-Type': 'application/json' } }
      )
    );
  }

  // Pull TSFIN knobs
  let maxInlineItems = 3;
  try {
    const s = await loadSettingsDefaults(env);
    const n = Number(s?.importConfig?.tsfin?.maxInlineItems);
    if (Number.isFinite(n) && n > 0) maxInlineItems = Math.floor(n);
  } catch {}

  try {
    // Load CURRENT timesheet to get hospital_norm
    const ts = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&is_current=eq.true` +
        `&select=timesheet_id,hospital_norm,is_current` +
        `&limit=1`
    );
    if (!ts) return withCORS(env, req, notFound('Timesheet not found'));

    const alias = String(ts.hospital_norm || '').trim().toLowerCase();

    const normaliseList = (val) => {
      if (!val) return [];
      if (Array.isArray(val)) return val;
      if (typeof val === 'string') {
        try {
          const parsed = JSON.parse(val);
          return Array.isArray(parsed) ? parsed : [val];
        } catch {
          return [val];
        }
      }
      return [];
    };

    // Helper: enqueue via SQL helper + drain a small, capped set inline
    const bumpTsfinNow = async ({ hospitalNorm }) => {
      // 1) Bulk enqueue (SQL helper)
      let enqueuedCount = 0;
      if (hospitalNorm) {
        try {
          enqueuedCount = await rpcEnqueueTsfinForHospitalNorm(env, {
            hospitalNorm,
            reason: 'CONTEXT_CHANGED',
            priority: true,
            limit: 500
          });
        } catch (e) {
          console.warn('[TS_RESOLVE_CLIENT] enqueue_tsfin_for_hospital_norm failed', e?.message || e);
        }
      } else {
        // Fallback: only enqueue the current timesheet
        try {
          await sbRpc(env, 'enqueue_ts_financials_priority', {
            _timesheet_ids: [currentTimesheetId],
            _reason: 'CONTEXT_CHANGED'
          });
          enqueuedCount = 1;
        } catch {}
      }

      // 2) Inline drain IDs (always include current)
      const inlineIds = [currentTimesheetId];

      if (hospitalNorm && maxInlineItems > 1) {
        try {
    const { rows } = await sbFetch(
  env,
  `${env.SUPABASE_URL}/rest/v1/timesheets` +
    `?is_current=eq.true` +
    `&hospital_norm=eq.${enc(hospitalNorm)}` +
    `&select=timesheet_id` +
    `&limit=${Math.min(500, Math.max(1, maxInlineItems - 1) + 1)}`
);

          for (const r of (rows || [])) {
            const id = r?.timesheet_id ? String(r.timesheet_id) : '';
            if (!id || id === currentTimesheetId) continue;
            inlineIds.push(id);
            if (inlineIds.length >= maxInlineItems) break;
          }
        } catch {}
      }

      // 3) Targeted drain
      try {
        await runTsfinWorkerOnce(env, { limit: inlineIds.length, onlyTimesheetIds: inlineIds });
      } catch (e) {
        console.warn('[TS_RESOLVE_CLIENT] targeted runTsfinWorkerOnce failed', e?.message || e);
      }

      return { enqueuedCount, inlineIds };
    };

    // If there is no alias, we can't enforce mapping; still kick TSFIN for current only.
    if (!alias) {
      await bumpTsfinNow({ hospitalNorm: null });

      let summaryRow = null;
      try {
        summaryRow = await sbGetOne(
          env,
          `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary` +
            `?timesheet_id=eq.${enc(currentTimesheetId)}` +
            `&select=timesheet_id,processing_status,candidate_id,client_id,candidate_name,client_name` +
            `&limit=1`
        );
      } catch {}

      return withCORS(env, req, ok({
        ok: true,
        requested_timesheet_id: requestedTimesheetId,
        current_timesheet_id: currentTimesheetId,
        was_stale: wasStale,
        summary: summaryRow || null
      }));
    }

    // ✅ Enforce alias uniqueness across clients (existing behaviour preserved)
    try {
      const aliasJson = JSON.stringify([alias]); // ["alias"]
      let rowsWithAlias = [];

      try {
        const { rows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/client_hospitals` +
            `?hospital_name_norm=cs.${enc(aliasJson)}` +
            `&select=id,client_id,hospital_name_norm` +
            `&order=id.asc`
        );
        rowsWithAlias = Array.isArray(rows) ? rows : [];
      } catch (e) {
        rowsWithAlias = [];
        console.warn('[TS_RESOLVE_CLIENT] client_hospitals cs lookup failed (fallback)', e?.message || e);
      }

      const ownedByChosen = rowsWithAlias.find(r => String(r.client_id) === String(clientId)) || null;
      const ownedByOthers = rowsWithAlias.filter(r => String(r.client_id) !== String(clientId));

      // 1) Remove alias from other clients
      for (const r of ownedByOthers) {
        const cur = normaliseList(r.hospital_name_norm);
        const next = cur.filter(x => String(x || '').trim().toLowerCase() !== alias);

        if (next.length !== cur.length) {
          const res = await fetch(
            `${env.SUPABASE_URL}/rest/v1/client_hospitals?id=eq.${enc(r.id)}`,
            {
              method: 'PATCH',
              headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
              body: JSON.stringify({ hospital_name_norm: next })
            }
          );
          if (!res.ok) {
            const txt = await res.text().catch(() => '');
            console.warn('[TS_RESOLVE_CLIENT] client_hospitals de-alias failed', {
              id: r.id,
              from_client_id: r.client_id,
              alias,
              status: res.status,
              body: txt
            });
          }
        }
      }

      // 2) Ensure chosen client has the alias
      if (!ownedByChosen) {
        const res = await fetch(
          `${env.SUPABASE_URL}/rest/v1/client_hospitals`,
          {
            method: 'POST',
            headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
            body: JSON.stringify([{
              client_id: clientId,
              hospital_name_norm: [alias]
            }])
          }
        );
        if (!res.ok) {
          const txt = await res.text().catch(() => '');
          console.warn('[TS_RESOLVE_CLIENT] client_hospitals insert failed', {
            client_id: clientId,
            alias,
            status: res.status,
            body: txt
          });
        }
      }
    } catch (e) {
      console.warn('[TS_RESOLVE_CLIENT] client_hospitals alias enforcement failed (non-fatal)', {
        client_id: clientId,
        alias,
        err: e?.message || String(e)
      });
    }

    // ✅ Enqueue all timesheets matching hospital_norm + drain a few inline
    await bumpTsfinNow({ hospitalNorm: alias });

    // Return updated summary row
    let summaryRow = null;
    try {
      summaryRow = await sbGetOne(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary` +
          `?timesheet_id=eq.${enc(currentTimesheetId)}` +
          `&select=timesheet_id,processing_status,candidate_id,client_id,candidate_name,client_name` +
          `&limit=1`
      );
    } catch {}

    return withCORS(env, req, ok({
      ok: true,
      requested_timesheet_id: requestedTimesheetId,
      current_timesheet_id: currentTimesheetId,
      was_stale: wasStale,
      summary: summaryRow || null
    }));
  } catch (e) {
    return withCORS(env, req, serverError(`Failed to resolve timesheet client: ${e?.message || e}`));
  }
}

async function handleTimesheetDailyQrPrintable(env, req, timesheetId) {
  const enc = encodeURIComponent;
  const cleanKey = (k) => String(k || '').replace(/^\/+/, '').trim();

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!timesheetId) return withCORS(env, req, badRequest('timesheet_id is required'));

  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }
  const expected = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  if (!expected) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  const resolved = await resolveTimesheetToCurrent(env, timesheetId);
  if (!resolved) return withCORS(env, req, notFound('Timesheet not found'));
  const currentTimesheetId = resolved.current_timesheet_id;

  if (String(expected) !== String(currentTimesheetId)) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({ error: 'TIMESHEET_MOVED', current_timesheet_id: currentTimesheetId }),
        { status: 409, headers: { 'Content-Type': 'application/json' } }
      )
    );
  }

  const ts = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=*` +
      `&limit=1`
  );
  if (!ts) return withCORS(env, req, notFound('Timesheet not found'));

  const oldQrKey = ts.qr_r2_key ? cleanKey(ts.qr_r2_key) : null;

  const scope = String(ts.sheet_scope || '').toUpperCase();
  let subMode = String(ts.submission_mode || '').toUpperCase();

  if (scope !== 'DAILY') {
    return withCORS(env, req, badRequest('Timesheet is not DAILY; cannot generate daily QR'));
  }

  const tsfin = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=*` +
      `&limit=1`
  );
  if (tsfin && (tsfin.locked_by_invoice_id || tsfin.paid_at_utc)) {
    return withCORS(env, req, badRequest('Timesheet already invoiced or paid; cannot generate QR'));
  }

  const now = nowIso();

  if (subMode !== 'MANUAL') {
    if (subMode !== 'ELECTRONIC') {
      return withCORS(env, req, badRequest('Unsupported submission_mode for DAILY QR'));
    }

    try {
      const flipRes = await fetch(
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
          `?timesheet_id=eq.${enc(currentTimesheetId)}&is_current=eq.true`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({
            submission_mode: 'MANUAL',
            r2_auth_key: null,
            authorised_at_server: null,
            updated_at: now
          })
        }
      );

      if (!flipRes.ok) {
        const t = await flipRes.text().catch(() => '');
        console.warn('[TS_DAILY_QR] failed to flip ELECTRONIC→MANUAL', {
          timesheet_id: currentTimesheetId,
          status: flipRes.status,
          bodyPreview: (t || '').slice(0, 200)
        });
        return withCORS(env, req, serverError('Failed to switch DAILY timesheet to MANUAL for QR'));
      }

      subMode = 'MANUAL';
    } catch (e) {
      console.warn('[TS_DAILY_QR] failed to flip ELECTRONIC→MANUAL (exception)', {
        timesheet_id: currentTimesheetId,
        err: e?.message || String(e)
      });
      return withCORS(env, req, serverError('Failed to switch DAILY timesheet to MANUAL for QR'));
    }
  }

  if (tsfin && String(tsfin.processing_status || '').toUpperCase() !== 'AWAITING_MANUAL_SIGNATURE') {
    try {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(tsfin.id)}`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({
            processing_status: 'AWAITING_MANUAL_SIGNATURE',
            updated_at: now
          })
        }
      );
    } catch (e) {
      console.warn('[TS_DAILY_QR] failed to patch TSFIN to AWAITING_MANUAL_SIGNATURE', {
        timesheet_id: currentTimesheetId,
        err: e?.message || String(e)
      });
    }
  }

  let workedDateYmd = null;
  if (ts.worked_start_iso) {
    try {
      const parts = toLocalParts(ts.worked_start_iso, null);
      workedDateYmd = parts && parts.ymd ? parts.ymd : String(ts.worked_start_iso).slice(0, 10);
    } catch {
      workedDateYmd = String(ts.worked_start_iso).slice(0, 10);
    }
  }

  let qrToken;
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      qrToken = crypto.randomUUID();
    } else {
      qrToken = `${currentTimesheetId}:${Date.now()}`;
    }
  } catch {
    qrToken = `${currentTimesheetId}:${Date.now()}`;
  }

  let qr_r2_key = null;
  try {
    const res = await generateAndStoreTimesheetQr(env, {
      timesheet_id: currentTimesheetId,
      contract_week_id: null,
      contract_id: ts.contract_id || null,
      candidate_id: ts.candidate_id || null,
      client_id: (tsfin && tsfin.client_id) || ts.client_id || null,
      week_ending_ymd: workedDateYmd || null,
      qr_token: qrToken
    });
    qr_r2_key = res?.qr_r2_key || null;
  } catch (e) {
    console.warn('[TS_DAILY_QR] generateAndStoreTimesheetQr failed', {
      timesheet_id: currentTimesheetId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to generate QR payload'));
  }

  // Patch QR fields
  try {
    const patchRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}&is_current=eq.true`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({
          qr_token: qrToken,
          qr_status: 'PENDING',
          qr_generated_at: now,
          qr_scanned_at: null,
          qr_scan_info_json: null,
          qr_r2_key: qr_r2_key || null,
          updated_at: now
        })
      }
    );

    if (!patchRes.ok) {
      const t = await patchRes.text().catch(() => '');
      console.warn('[TS_DAILY_QR] failed to patch timesheet QR fields', {
        timesheet_id: currentTimesheetId,
        status: patchRes.status,
        bodyPreview: (t || '').slice(0, 200)
      });
      return withCORS(env, req, serverError('Failed to update timesheet QR fields'));
    }
  } catch (e) {
    console.warn('[TS_DAILY_QR] failed to patch timesheet QR fields (exception)', {
      timesheet_id: currentTimesheetId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to update timesheet QR fields'));
  }

  // ✅ NEW: delete old QR image key now that we replaced it (best-effort)
  try {
    const bucket = env.R2_BUCKET || env.R2;
    const newQrKeyClean = qr_r2_key ? cleanKey(qr_r2_key) : null;
    if (bucket && typeof bucket.delete === 'function' && oldQrKey && newQrKeyClean && oldQrKey !== newQrKeyClean) {
      await bucket.delete(oldQrKey).catch(() => {});
    }
  } catch {
    // non-fatal
  }

  let pdfKey = null;
  try {
    pdfKey = await ensureTimesheetPdf(env, currentTimesheetId);
    if (pdfKey) {
      // ✅ FIX: only set manual_pdf_r2_key if it is currently NULL/empty (do not overwrite scanned evidence)
      const patchUrl =
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&is_current=eq.true` +
        `&or=(manual_pdf_r2_key.is.null,manual_pdf_r2_key.eq.)`;

      await fetch(
        patchUrl,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({
            manual_pdf_r2_key: pdfKey,
            updated_at: nowIso()
          })
        }
      ).catch(() => {});
    }
  } catch (e) {
    console.warn('[TS_DAILY_QR] ensureTimesheetPdf failed', {
      timesheet_id: currentTimesheetId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to prepare timesheet PDF'));
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ compute + persist last-sent hash after PDF is ensured
  // ─────────────────────────────────────────────────────────────
  try {
    const stableClone = (v) => {
      if (Array.isArray(v)) return v.map(stableClone);
      if (v && typeof v === 'object') {
        const out = {};
        for (const k of Object.keys(v).sort()) out[k] = stableClone(v[k]);
        return out;
      }
      return v;
    };

    // Daily printable content basis (hours + refs + breaks)
    const hashObj = {
      sheet_scope: scope || 'DAILY',
      worked_start_iso: ts.worked_start_iso || null,
      worked_end_iso: ts.worked_end_iso || null,
      break_start_iso: ts.break_start_iso || null,
      break_end_iso: ts.break_end_iso || null,
      break_minutes: (ts.break_minutes != null ? ts.break_minutes : null),
      reference_number: ts.reference_number || null,
      day_references_json: ts.day_references_json || null
    };

    const current_hash = await sha256Hex(JSON.stringify(stableClone(hashObj)));
    const sentAt = nowIso();

    await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}&is_current=eq.true`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({
          qr_last_sent_hash: current_hash,
          qr_last_sent_at_utc: sentAt,
          updated_at: sentAt
        })
      }
    ).catch(() => {});
  } catch (e) {
    console.warn('[TS_DAILY_QR] hash compute/persist failed (non-fatal)', {
      timesheet_id: currentTimesheetId,
      err: e?.message || String(e)
    });
  }

  // Automatically queue email
  try {
    let email = null;
    let candName = null;

    if (ts.candidate_id) {
      const cand = await sbGetOne(
        env,
        `${env.SUPABASE_URL}/rest/v1/candidates?id=eq.${enc(ts.candidate_id)}&select=email,display_name&limit=1`
      );
      email = cand?.email ? String(cand.email).trim() : null;
      candName = cand?.display_name || null;
    }

    if (email && pdfKey) {
      const subject = workedDateYmd
        ? `Daily QR timesheet – ${workedDateYmd}`
        : `Daily QR timesheet`;

      const lines = [
        `Please print the attached timesheet, ask the ward manager to sign it,`,
        `and then upload the signed copy via the app.`,
        ``,
        ...(candName ? [`Candidate: ${candName}`] : []),
        ...(workedDateYmd ? [`Date: ${workedDateYmd}`] : []),
        `Timesheet ID: ${currentTimesheetId}`
      ];

      const bodyText = lines.join('\n');
      const bodyHtml = `<p>${lines.map(l => (l === '' ? '<br/>' : l)).join('<br/>')}</p>`;

      const ins = await fetch(
        `${env.SUPABASE_URL}/rest/v1/mail_outbox`,
        {
          method: 'POST',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({
            type: 'TIMESHEET_QR',
            to: email,
            cc: null,
            bcc: null,
            reply_to: null,
            importance: 'Normal',
            email_type: 'html',
            subject,
            body_text: bodyText,
            body_html: bodyHtml,
            attachments: [{
              r2_key: pdfKey,
              filename: workedDateYmd ? `Timesheet_${workedDateYmd}.pdf` : `Timesheet_${currentTimesheetId}.pdf`
            }],
            status: 'QUEUED',
            reference: `timesheet_qr:daily:${currentTimesheetId}:${workedDateYmd || ''}`,
            recipient_kind: 'candidate',
            recipient_id: ts.candidate_id || null,
            context_kind: 'timesheets',
            context_id: currentTimesheetId,
            mailshot_run_id: null,
            document_template_id: null,
            created_by: user?.id || null
          })
        }
      ).catch(() => null);

      // ✅ UPDATED: capture refs snapshot/signature at the moment the QR email is actually queued
      // Canonical model (SQL):
      //   - snapshot: ordered [{ row_key, current_reference }]
      //   - sig: public.timesheet_pdf_reference_sig(p_timesheet_id)
      if (ins && ins.ok) {
        try {
          const unwrapScalar = (v, fnName) => {
            if (v == null) return null;
            if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return String(v);
            if (v && typeof v === 'object' && !Array.isArray(v) && Object.prototype.hasOwnProperty.call(v, 'data')) {
              return unwrapScalar(v.data, fnName);
            }
            if (Array.isArray(v)) {
              if (v.length === 0) return null;
              const o = v[0];
              if (typeof o === 'string' || typeof o === 'number' || typeof o === 'boolean') return String(o);
              if (o && typeof o === 'object') {
                if (fnName && Object.prototype.hasOwnProperty.call(o, fnName)) return o[fnName] == null ? null : String(o[fnName]);
                const ks = Object.keys(o);
                if (ks.length === 1) return o[ks[0]] == null ? null : String(o[ks[0]]);
              }
              return null;
            }
            if (v && typeof v === 'object') {
              if (fnName && Object.prototype.hasOwnProperty.call(v, fnName)) return v[fnName] == null ? null : String(v[fnName]);
              const ks = Object.keys(v);
              if (ks.length === 1) return v[ks[0]] == null ? null : String(v[ks[0]]);
            }
            return null;
          };

          const asArray = (v) => {
            if (v == null) return [];
            if (Array.isArray(v)) return v;
            if (v && typeof v === 'object' && Array.isArray(v.data)) return v.data;
            if (v && typeof v === 'object' && Array.isArray(v.rows)) return v.rows;
            return [v];
          };

          const capAt = nowIso();

          // Canonical snapshot rows
          const rowsRes = await sbRpc(env, 'timesheet_pdf_reference_rows', { p_timesheet_id: currentTimesheetId });
          const rowsArr = asArray(rowsRes);

          const refRows = [];
          for (const r of rowsArr) {
            const rowKey = String(r?.row_key || r?.rowKey || '').trim();
            if (!rowKey) continue;
            const refVal = (r && (r.current_reference ?? r.currentReference)) ?? null;
            refRows.push({ row_key: rowKey, current_reference: (refVal == null ? null : String(refVal)) });
          }
          refRows.sort((a, b) => String(a.row_key).localeCompare(String(b.row_key)));

          // Canonical signature
          let refsSig = null;
          try {
            const sigRes = await sbRpc(env, 'timesheet_pdf_reference_sig', { p_timesheet_id: currentTimesheetId });
            const sig = unwrapScalar(sigRes, 'timesheet_pdf_reference_sig');
            refsSig = (sig && String(sig).trim()) ? String(sig).trim() : null;
          } catch {
            refsSig = null;
          }

          // Defensive fallback: match SQL rawSig join rules (row_key=ref||...)
          if (!refsSig) {
            const rawSig = refRows
              .map(r => `${String(r.row_key)}=${String(r.current_reference ?? '')}`)
              .join('||');
            refsSig = await sha256Hex(rawSig);
          }

          await fetch(
            `${env.SUPABASE_URL}/rest/v1/timesheets` +
              `?timesheet_id=eq.${enc(currentTimesheetId)}&is_current=eq.true`,
            {
              method: 'PATCH',
              headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
              body: JSON.stringify({
                qr_sent_refs_snapshot_json: refRows,
                qr_sent_refs_sig: refsSig,
                qr_sent_refs_captured_at_utc: capAt,
                updated_at: capAt
              })
            }
          ).catch(() => {});
        } catch (e2) {
          console.warn('[TS_DAILY_QR] failed to persist qr_sent_refs_* (non-fatal)', {
            timesheet_id: currentTimesheetId,
            err: e2?.message || String(e2)
          });
        }
      }
    }

  } catch (e) {
    console.warn('[TS_DAILY_QR] mail queue failed (non-fatal)', {
      timesheet_id: currentTimesheetId,
      err: e?.message || String(e)
    });
  }

  // Audit
  try {
    await writeAudit(
      env,
      user,
      'DAILY_QR_PRINTABLE_GENERATED',
      {
        timesheet_id: currentTimesheetId,
        qr_token: qrToken,
        qr_status: 'PENDING',
        qr_r2_key,
        pdf_r2_key: pdfKey || null,
        worked_date: workedDateYmd || null
      },
      { entity: 'timesheets', subject_id: currentTimesheetId, req }
    );
  } catch (e) {
    console.warn('[TS_DAILY_QR] audit failed (non-fatal)', e?.message || e);
  }

  return withCORS(env, req, ok({
    ok: true,
    timesheet_id: currentTimesheetId,
    current_timesheet_id: currentTimesheetId,
    requested_timesheet_id: resolved.requested_timesheet_id || timesheetId,
    was_stale: !!resolved.was_stale,

    sheet_scope: 'DAILY',
    qr_status: 'PENDING',
    qr_token: qrToken,
    qr_r2_key: qr_r2_key || null,
    worked_date: workedDateYmd,
    pdf_key: pdfKey || null
  }));
}




















































// ====================== CLIENT HOSPITALS ======================
/**
 * @openapi
 * /api/clients/{client_id}/hospitals:
 *   get:
 *     summary: List client hospitals
 *     tags: [Client Hospitals]
 *     security:
 *       - bearerAuth: []
 *   post:
 *     summary: Create client hospital
 *     tags: [Client Hospitals]
 *     security:
 *       - bearerAuth: []
 * /api/clients/{client_id}/hospitals/{hospital_id}:
 *   get:
 *     summary: Get client hospital
 *     tags: [Client Hospitals]
 *     security:
 *       - bearerAuth: []
 *   patch:
 *     summary: Update client hospital
 *     tags: [Client Hospitals]
 *     security:
 *       - bearerAuth: []
 *   delete:
 *     summary: Delete client hospital
 *     tags: [Client Hospitals]
 *     security:
 *       - bearerAuth: []
 */
async function handleListHospitals(env, req, clientId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/client_hospitals?client_id=eq.${encodeURIComponent(clientId)}&select=*`
    );
    return withCORS(env, req, ok({ items: rows }));
  } catch {
    return withCORS(env, req, serverError("Failed to list client hospitals"));
  }
}

async function handleGetHospital(env, req, clientId, hospitalId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/client_hospitals?id=eq.${encodeURIComponent(hospitalId)}&client_id=eq.${encodeURIComponent(clientId)}&select=*`
    );
    if (!rows.length) return withCORS(env, req, notFound("Hospital not found"));
    return withCORS(env, req, ok({ hospital: rows[0] }));
  } catch {
    return withCORS(env, req, serverError("Failed to fetch client hospital"));
  }
}

async function handleClientEHistory(env, req, clientId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const enc = encodeURIComponent;

  try {
    // Legacy contract rate lines (flat) filtered by client_id
    // View definition includes: candidate_name (cand.display_name), start/end, job_title,
    // pay_method, label, pay_rate, margin, charge_rate, line_no, etc.
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/v_legacy_contract_rate_lines_flat` +
        `?client_id=eq.${enc(clientId)}` +
        `&select=` +
          [
            'candidate_id',
            'candidate_name',
            'start_date',
            'end_date',
            'job_title',
            'pay_method',
            'label',
            'pay_rate',
            'margin',
            'charge_rate',
            'line_no'
          ].join(',') +
        `&order=start_date.desc,end_date.desc,line_no.asc`
    );

    return withCORS(env, req, ok({ rows: Array.isArray(rows) ? rows : [] }));
  } catch (e) {
    console.error('handleClientEHistory failed', {
      client_id: clientId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to fetch client e-history'));
  }
}


async function handleCandidatesGet(env, req, candidateId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!candidateId) return withCORS(env, req, badRequest('candidate_id required'));

  // Base candidate row (unchanged)
  const { rows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/candidates` +
      `?id=eq.${enc(candidateId)}` +
      `&select=*` +
      `&limit=1`
  );
  const row = (rows && rows[0]) || null;
  if (!row) return withCORS(env, req, notFound('Candidate not found'));

  // NEW: fetch hr_name_mappings for this candidate so the FE can see aliases
  try {
    const { rows: aliasRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/hr_name_mappings` +
        `?candidate_id=eq.${enc(candidateId)}` +
        `&select=id,hr_name_norm,hospital_or_trust,last_used_at`
    );
    row.hr_aliases = Array.isArray(aliasRows) ? aliasRows : [];
  } catch (e) {
    console.error('handleCandidatesGet: hr_name_mappings lookup failed', {
      candidate_id: candidateId,
      err: e?.message || String(e)
    });
    row.hr_aliases = [];
  }

  return withCORS(env, req, ok(row));
}

// 2) GET /api/clients/:id (picker/base client row + latest client_settings)
async function handleClientsGet(env, req, clientId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!clientId) return withCORS(env, req, badRequest('client_id required'));

  const { rows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/clients?id=eq.${enc(clientId)}&select=*&limit=1`
  );
  const client = (rows && rows[0]) || null;
  if (!client) return withCORS(env, req, notFound('Client not found'));

  // Also return the latest client_settings
  // ✅ FIX: include invoice_consolidation_mode + reference_number_required_to_issue_invoice so UI can populate them
  const { rows: csRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/client_settings` +
      `?client_id=eq.${enc(client.id)}` +
      `&select=` +
        [
          'id',
          'hr_validation_required',
          'ts_reference_required',
          'pay_reference_required',
          'invoice_reference_required',
          'default_submission_mode',
          'is_nhsp',
          'self_bill_no_invoices_sent',
          'daily_calc_of_invoices',
          'no_timesheet_required',
          'group_nightsat_sunbh',
          'auto_invoice_default',
          'requires_hr',
          'autoprocess_hr',
          'hr_attach_to_invoice',
          'ts_attach_to_invoice',

          // ✅ manual adjustment email routing
          'send_manual_invoices_to_different_email',
          'manual_invoices_alt_email_address',

          // ✅ NEW: invoice settings (DB-backed)
          'invoice_consolidation_mode',
          'reference_number_required_to_issue_invoice',

          'effective_from',
          'timezone_id',
          'day_start',
          'day_end',
          'night_start',
          'night_end',
          'sat_start',
          'sat_end',
          'sun_start',
          'sun_end',
          'bh_start',
          'bh_end',
          'bh_source',
          'bh_list',
          'bh_feed_url',
          'week_ending_weekday',
          'created_at',
          'updated_at'
        ].join(',') +
      `&order=effective_from.desc,created_at.desc&limit=1`
  );
  const client_settings = (csRows && csRows[0]) || null;

  // Surface week_ending_weekday at top-level for convenience
  const week_ending_weekday = (client_settings && Number.isInteger(Number(client_settings.week_ending_weekday)))
    ? Number(client_settings.week_ending_weekday)
    : (Number.isInteger(Number(client.week_ending_weekday)) ? Number(client.week_ending_weekday) : 0);

  return withCORS(env, req, ok({ ...client, week_ending_weekday, client_settings }));
}



async function handleUpdateHospital(env, req, clientId, hospitalId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const data = await parseJSONBody(req);
  if (!data) return withCORS(env, req, badRequest("Invalid JSON"));

  try {
    // Build safe patch: normalise name, tidy empties, block immutable fields
    const patch = { ...data };

    // Work out any hospital_name_norm input (can be string, array, or via name/hospital)
    let hospitalInput =
      typeof patch.hospital_name_norm !== 'undefined'
        ? patch.hospital_name_norm
        : (data.name || data.hospital);

    if (typeof hospitalInput !== 'undefined') {
      let hospitalAliases = [];

      if (Array.isArray(hospitalInput)) {
        hospitalAliases = hospitalInput
          .map((x) => String(x || '').trim().toLowerCase())
          .filter(Boolean);
      } else if (typeof hospitalInput === 'string') {
        const s = hospitalInput.trim();
        hospitalAliases = s ? [s.toLowerCase()] : [];
      } else if (hospitalInput != null) {
        const s = String(hospitalInput).trim();
        hospitalAliases = s ? [s.toLowerCase()] : [];
      }

      patch.hospital_name_norm = hospitalAliases;
    }

    // Treat empty string as null for optional fields
    if ('ward_hint' in patch && (patch.ward_hint === '' || patch.ward_hint == null)) {
      patch.ward_hint = null;
    }

    // Prevent updates to immutable/owner fields
    delete patch.id;
    delete patch.client_id;
    delete patch.created_at;

    patch.updated_at = new Date().toISOString();

    const url =
      `${env.SUPABASE_URL}/rest/v1/client_hospitals` +
      `?id=eq.${encodeURIComponent(hospitalId)}` +
      `&client_id=eq.${encodeURIComponent(clientId)}`;

    const res = await fetch(url, {
      method: "PATCH",
      headers: { ...sbHeaders(env), "Prefer": "return=representation" },
      body: JSON.stringify(patch)
    });

    if (!res.ok) {
      const err = await res.text();
      return withCORS(env, req, badRequest(`Hospital update failed: ${err}`));
    }

    const json = await res.json().catch(() => []);
    const hospital = Array.isArray(json) ? json[0] : json;

    if (!hospital) {
      return withCORS(env, req, notFound("Hospital not found"));
    }

    return withCORS(env, req, ok({ hospital }));
  } catch {
    return withCORS(env, req, serverError("Failed to update client hospital"));
  }
}


async function handleDeleteHospital(env, req, clientId, hospitalId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  try {
    const url = `${env.SUPABASE_URL}/rest/v1/client_hospitals` +
      `?id=eq.${encodeURIComponent(hospitalId)}` +
      `&client_id=eq.${encodeURIComponent(clientId)}`;

    const res = await fetch(url, {
      method: "DELETE",
      headers: { ...sbHeaders(env), "Prefer": "return=representation" }
    });

    if (!res.ok) {
      const err = await res.text();
      return withCORS(env, req, badRequest(`Hospital delete failed: ${err}`));
    }

    // With Prefer:return=representation PostgREST returns the deleted row(s)
    const json = await res.json().catch(() => []);
    if (!Array.isArray(json) || json.length === 0) {
      return withCORS(env, req, notFound("Hospital not found"));
    }

    return withCORS(env, req, ok({ deleted: true, hospital: json[0] }));
  } catch {
    return withCORS(env, req, serverError("Failed to delete client hospital"));
  }
}

// ====================== UMBRELLAS ======================
/**
 * @openapi
 * /api/umbrellas:
 *   get:
 *     summary: List umbrella companies
 *     tags: [Umbrellas]
 *     security:
 *       - bearerAuth: []
 *   post:
 *     summary: Create umbrella
 *     tags: [Umbrellas]
 *     security:
 *       - bearerAuth: []
 * /api/umbrellas/{umbrella_id}:
 *   get:
 *     summary: Get umbrella
 *     tags: [Umbrellas]
 *     security:
 *       - bearerAuth: []
 *   put:
 *     summary: Update umbrella
 *     tags: [Umbrellas]
 *     security:
 *       - bearerAuth: []
 */

async function handleListUmbrellas(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const params = new URL(req.url).searchParams;
  const includeCount = params.get('include_count') === 'true';

  // ✅ NEW: enabled filter (supports enabled=true|false)
  const enabledRaw = params.get('enabled');
  const enabledNorm = (enabledRaw == null) ? '' : String(enabledRaw).trim().toLowerCase();
  const hasEnabled =
    (enabledNorm === 'true'  || enabledNorm === '1' || enabledNorm === 'yes' || enabledNorm === 'y' || enabledNorm === 'on') ||
    (enabledNorm === 'false' || enabledNorm === '0' || enabledNorm === 'no'  || enabledNorm === 'n' || enabledNorm === 'off');

  const enabledBool =
    (enabledNorm === 'true'  || enabledNorm === '1' || enabledNorm === 'yes' || enabledNorm === 'y' || enabledNorm === 'on')
      ? true
      : (enabledNorm === 'false' || enabledNorm === '0' || enabledNorm === 'no' || enabledNorm === 'n' || enabledNorm === 'off')
        ? false
        : null;

  // Prefer page/page_size; fall back to limit/offset
  const pageRaw      = parseInt(params.get('page') || '1', 10);
  const pageSizeRaw  = params.get('page_size');
  const legacyLimit  = parseInt(params.get('limit')  || '50', 10);
  const legacyOffset = parseInt(params.get('offset') || '0',  10);

  const page     = Math.max(1, isNaN(pageRaw) ? 1 : pageRaw);
  const pageSize = pageSizeRaw != null ? Math.max(1, Math.min(200, parseInt(pageSizeRaw, 10) || 50)) : null;
  const limit    = pageSize != null ? pageSize : Math.max(1, Math.min(200, isNaN(legacyLimit) ? 50 : legacyLimit));
  const offset   = pageSize != null ? (page - 1) * limit : Math.max(0, isNaN(legacyOffset) ? 0 : legacyOffset);

  const url = new URL(`${env.SUPABASE_URL}/rest/v1/umbrellas`);
  url.searchParams.set('select', '*');
  url.searchParams.set('order',  'name.asc');
  url.searchParams.set('limit',  String(limit));
  url.searchParams.set('offset', String(offset));

  // ✅ Apply filter to Supabase REST (public.umbrellas.enabled boolean column)
  if (hasEnabled && enabledBool !== null) {
    url.searchParams.set('enabled', enabledBool ? 'eq.true' : 'eq.false');
  }

  try {
    const { rows, total } = await sbFetch(env, url.toString(), includeCount);
    const resp = includeCount ? { items: rows, count: total ?? undefined } : { items: rows };
    return withCORS(env, req, ok(resp));
  } catch {
    return withCORS(env, req, serverError('Failed to list umbrellas'));
  }
}


async function handleCreateUmbrella(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const data = await parseJSONBody(req);
  if (!data) return withCORS(env, req, badRequest("Invalid JSON"));

  // ✅ NEW: normalise remittance override booleans on create (accept 'on'/'true'/1, empty => false)
  const normalizeBoolish = (v) => {
    if (typeof v === 'boolean') return v;
    if (v === null || v === undefined) return false;
    if (typeof v === 'number') return v === 1;
    const s = String(v).trim().toLowerCase();
    if (!s) return false;
    if (['true','1','yes','y','on'].includes(s)) return true;
    if (['false','0','no','n','off'].includes(s)) return false;
    return false;
  };
  const normalizeBoolField = (obj, key) => {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) return;
    obj[key] = normalizeBoolish(obj[key]);
  };
  normalizeBoolField(data, 'remittance_overrides_enabled');
  normalizeBoolField(data, 'remittances_detailed_breakdown');

  try {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/umbrellas`, {
      method: "POST",
      headers: { ...sbHeaders(env), "Prefer": "return=representation" },
      body: JSON.stringify({ ...data, created_at: new Date().toISOString() })
    });
    if (!res.ok) {
      const err = await res.text();
      return withCORS(env, req, badRequest(`Umbrella creation failed: ${err}`));
    }
    const json = await res.json().catch(() => ({}));
    const umbrella = Array.isArray(json) ? json[0] : json;
    return withCORS(env, req, ok({ umbrella }));
  } catch {
    return withCORS(env, req, serverError("Failed to create umbrella"));
  }
}

async function handleGetUmbrella(env, req, umbrellaId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/umbrellas?id=eq.${encodeURIComponent(umbrellaId)}&select=*`
    );
    if (!rows.length) return withCORS(env, req, notFound("Umbrella not found"));
    return withCORS(env, req, ok({ umbrella: rows[0] }));
  } catch {
    return withCORS(env, req, serverError("Failed to fetch umbrella"));
  }
}
async function handleUpdateUmbrella(env, req, umbrellaId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const data = await parseJSONBody(req);
  if (!data) return withCORS(env, req, badRequest("Invalid JSON"));

  // Normalise boolean fields on update (accept 'on'/'true'/'yes'/1, empty => false)
  const normalizeBoolish = (v) => {
    if (typeof v === 'boolean') return v;
    if (v === null || v === undefined) return false;
    if (typeof v === 'number') return v === 1;
    const s = String(v).trim().toLowerCase();
    if (!s) return false;
    if (['true','1','yes','y','on'].includes(s)) return true;
    if (['false','0','no','n','off'].includes(s)) return false;
    return false;
  };
  const normalizeBoolField = (obj, key) => {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) return;
    obj[key] = normalizeBoolish(obj[key]);
  };

  normalizeBoolField(data, 'vat_chargeable');
  normalizeBoolField(data, 'enabled');
  normalizeBoolField(data, 'remittance_overrides_enabled');
  normalizeBoolField(data, 'remittances_detailed_breakdown');

  const umbrellaBankClearFields = ['bank_name', 'sort_code', 'account_number'];
  for (const field of umbrellaBankClearFields) {
    if (!Object.prototype.hasOwnProperty.call(data, field)) continue;
    if (data[field] === null || data[field] === undefined) {
      data[field] = null;
      continue;
    }
    if (typeof data[field] === 'string') {
      const trimmedBankValue = data[field].trim();
      data[field] = trimmedBankValue ? trimmedBankValue : null;
    }
  }

  try {
    // 1) Load current umbrella (for change detection)
    const { rows: beforeRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/umbrellas?id=eq.${encodeURIComponent(umbrellaId)}&select=name,bank_name,sort_code,account_number,bank_details_hash,vat_chargeable,enabled`
    );
    const before = beforeRows?.[0] || {};

    // 2) Update
    const url = `${env.SUPABASE_URL}/rest/v1/umbrellas?id=eq.${encodeURIComponent(umbrellaId)}`;
    const res = await fetch(url, {
      method: "PATCH",
      headers: { ...sbHeaders(env), "Prefer": "return=representation" },
      body: JSON.stringify({ ...data, updated_at: new Date().toISOString() })
    });
    if (!res.ok) {
      const err = await res.text();
      return withCORS(env, req, badRequest(`Umbrella update failed: ${err}`));
    }
    const json = await res.json().catch(() => ({}));
    const umbrella = Array.isArray(json) ? json[0] : json;

    const oldHash = (before && before.bank_details_hash != null) ? String(before.bank_details_hash).trim() : '';
    const newHash = (umbrella && umbrella.bank_details_hash != null) ? String(umbrella.bank_details_hash).trim() : '';

    // 3) Detect pay-channel / TSFIN-impacting changes.
    // VAT chargeability must be included because umbrella payment inc-VAT is frozen from this setting.
    const watched = ['name','bank_name','sort_code','account_number','vat_chargeable','enabled'];
    const changed = watched.some((k) => {
      if (k === 'vat_chargeable' || k === 'enabled') {
        return normalizeBoolish(umbrella?.[k]) !== normalizeBoolish(before?.[k]);
      }
      return (umbrella?.[k] ?? null) !== (before?.[k] ?? null);
    });

    if (changed) {
      // Enqueue recompute for all candidates on this umbrella (current & unlocked TSFIN only)
      const { rows: candidateRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/candidates` +
          `?select=id` +
          `&umbrella_id=eq.${encodeURIComponent(umbrellaId)}` +
          `&pay_method=eq.UMBRELLA`
      );
      const candIds = (candidateRows || []).map(r => r.id).filter(Boolean);
      if (candIds.length) {
        for (const candId of candIds) {
          try {
            await sbRpc(env, '_change_bump', { p_entity_key: `pay_candidate:${candId}` });
          } catch (changeErr) {
            console.warn('[BANKING_PAY] umbrella candidate change counter bump failed (non-fatal)', {
              umbrella_id: umbrellaId,
              candidate_id: candId,
              err: changeErr?.message || String(changeErr)
            });
          }
        }

        const idsParam = candIds.map(encodeURIComponent).join(',');
        const { rows: tsfins } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
            `?select=timesheet_id` +
            `&candidate_id=in.(${idsParam})` +
            `&is_current=eq.true` +
            `&locked_by_invoice_id=is.null`
        );
        const toEnqueue = (tsfins || []).map(r => ({ timesheet_id: r.timesheet_id, reason: 'CONTEXT_CHANGED' }));
        if (toEnqueue.length) {
          await fetch(
            `${env.SUPABASE_URL}/rest/v1/ts_financials_outbox?on_conflict=timesheet_id,reason`,
            {
              method: "POST",
              headers: { ...sbHeaders(env), "Prefer": "resolution=ignore-duplicates" },
              body: JSON.stringify(toEnqueue)
            }
          );
        }
      }
    }

    if (oldHash && oldHash !== newHash) {
      try {
        await cleanupStaleRailPayeeMappingsForHash(env, {
          entity_kind: 'UMBRELLA',
          entity_id: umbrellaId,
          old_bank_details_hash: oldHash,
          new_bank_details_hash: newHash || null,
          actor_user_id: user.id
        });
      } catch (cleanupErr) {
        console.warn('[BANK_PAYEE_CLEANUP] umbrella cleanup failed (non-fatal)', cleanupErr?.message || cleanupErr);
      }
    }

    return withCORS(env, req, ok({ umbrella }));
  } catch {
    return withCORS(env, req, serverError("Failed to update umbrella"));
  }
}



