// ====================== RATES (FIVE-WAY) ======================
/**
 * @openapi
 * /api/rates/client-defaults:
 *   get:
 *     summary: List client default rates
 *     tags: [Rates]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: query
 *         name: client_id
 *         required: true
 *         schema: { type: string }
 *   post:
 *     summary: Upsert client default rates (five-way)
 *     tags: [Rates]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               client_id: { type: string }
 *               role: { type: string }
 *               band: { type: string }
 *               date_from: { type: string, format: date }
 *               date_to: { type: string, format: date, nullable: true }
 *               charge_day: { type: number }
 *               charge_night: { type: number }
 *               charge_sat: { type: number }
 *               charge_sun: { type: number }
 *               charge_bh: { type: number }
 *               pay_day: { type: number, nullable: true }
 *               pay_night: { type: number, nullable: true }
 *               pay_sat: { type: number, nullable: true }
 *               pay_sun: { type: number, nullable: true }
 *               pay_bh: { type: number, nullable: true }
 * /api/rates/candidate-overrides:
 *   get:
 *     summary: List candidate override rates
 *     tags: [Rates]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: query
 *         name: candidate_id
 *         required: true
 *         schema: { type: string }
 *   post:
 *     summary: Create candidate override (five-way)
 *     tags: [Rates]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               candidate_id: { type: string }
 *               client_id: { type: string, nullable: true }
 *               role: { type: string }
 *               band: { type: string }
 *               date_from: { type: string, format: date }
 *               date_to: { type: string, format: date, nullable: true }
 *               pay_day: { type: number }
 *               pay_night: { type: number }
 *               pay_sat: { type: number }
 *               pay_sun: { type: number }
 *               pay_bh: { type: number }
 * /api/rates/resolve-preview:
 *   post:
 *     summary: Resolve five-way pay/charge for a candidate/client/date/role/band
 *     tags: [Rates]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [candidate_id, client_id, date]
 *             properties:
 *               candidate_id: { type: string }
 *               client_id: { type: string }
 *               role: { type: string }
 *               band: { type: string }
 *               date: { type: string, format: date }
 *     responses:
 *       200:
 *         description: Resolved five-way snapshot
 */

// ─────────────────────────────────────────────────────────────────────────────
// Client defaults: list with optional role/band + active_on filters,
// and correct NULL/default semantics. Supports pagination.
// ─────────────────────────────────────────────────────────────────────────────
// ======================================
// BACKEND — handleSearchCandidates (UPDATED)
// Add pass-through support for PostgREST 'id=in.(...)' filter
// ======================================

async function handleSearchCandidates(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const enc = encodeURIComponent;

  const urlObj = new URL(req.url);
  const q = (k) => urlObj.searchParams.get(k);

  const page = Math.max(1, parseInt(q('page') || '1', 10));
  const pageSize = Math.max(1, Math.min(200, parseInt(q('page_size') || '50', 10)));
  const format = (q('format') || 'json').toLowerCase();

  const includeCount = String(q('include_count') || 'false').toLowerCase() === 'true';

  const orderByParam = (q('order_by') || '').toLowerCase();
  const orderDirParam = (q('order_dir') || '').toLowerCase();

  const allowedSort = {
    display_name: 'display_name',
    first_name: 'first_name',
    last_name: 'last_name',
    email: 'email',
    phone: 'phone',
    pay_method: 'pay_method',
    active: 'active',
    created_at: 'created_at',
    primary_job_title: 'primary_job_title',
    job_titles_display: 'job_titles_display',
    tms_ref: '__tms_ref',
    tms_ref_num: 'tms_ref_num'
  };

  const defaultOrderCol = 'display_name';
  const orderCol = allowedSort[orderByParam] || defaultOrderCol;
  const orderDir = (orderDirParam === 'desc') ? 'desc' : 'asc';
  const useDerivedSecondaryJobTitlesSort = (orderByParam === 'job_titles_display');

  const spec = buildCandidateSummaryFilterSpec(urlObj.searchParams);

  const firstName = spec.first_name || null;
  const lastName = spec.last_name || null;
  const email = spec.email || null;
  const phone = spec.phone || null;
  const payMethod = spec.pay_method || null;
  const active = spec.active || null;
  const createdFrom = spec.created_from || null;
  const createdTo = spec.created_to || null;
  const notesExact = spec.notes || null;
  const jobTitleIncludeNodeIds = Array.isArray(spec.job_title_include_node_ids) ? spec.job_title_include_node_ids.map(String).map((s) => s.trim()).filter(Boolean) : [];
  const jobTitleExcludeNodeIds = Array.isArray(spec.job_title_exclude_node_ids) ? spec.job_title_exclude_node_ids.map(String).map((s) => s.trim()).filter(Boolean) : [];
  const jobTitleRoleIds = Array.isArray(spec.job_title_role_ids) ? spec.job_title_role_ids.map(String).map((s) => s.trim()).filter(Boolean) : [];
  const jobTitlePrimaryOnly = !!spec.job_title_primary_only;
  const profRegNumber = spec.prof_reg_number || null;
  const profRegType = spec.prof_reg_type || null;
  const dobExact = spec.dob || null;
  const gender = spec.gender || null;
  const townCity = spec.town_city || null;
  const postcode = spec.postcode || null;
  const updatedFrom = spec.updated_from || null;
  const updatedTo = spec.updated_to || null;
  const sortCode = spec.sort_code || null;
  const accountNumber = spec.account_number || null;
  const umbrellaName = spec.umbrella_name || null;
  const tmsRef = spec.tms_ref || null;
  const text = spec.q || null;
  const workStatus = spec.work_status || null;
  const recentMonthsRaw = spec.recent_months || null;
  const rolesAny = Array.isArray(spec.roles_any) ? spec.roles_any.map(String) : [];
  const rolesAll = Array.isArray(spec.roles_all) ? spec.roles_all.map(String) : [];
  const ids = Array.isArray(spec.ids) ? spec.ids.map(String) : [];

  let idFilterExpr = null;
  if (ids.length) {
    idFilterExpr = `in.(${ids.join(',')})`;
  }

  const recentAll = (workStatus === 'RECENT') && (String(recentMonthsRaw || '').trim().toUpperCase() === 'ALL');

  const recentMonths =
    (!recentAll && Number.isFinite(parseInt(recentMonthsRaw || '', 10)))
      ? Math.max(1, Math.min(120, parseInt(recentMonthsRaw, 10)))
      : 3;

  const londonYMDNow = () => {
    const parts = new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Europe/London',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).formatToParts(new Date());
    const get = (type) => (parts.find((p) => p.type === type)?.value || '');
    return `${get('year')}-${get('month')}-${get('day')}`;
  };

  const subtractMonthsYMD = (ymd, months) => {
    const y0 = Number(String(ymd).slice(0, 4));
    const m0 = Number(String(ymd).slice(5, 7));
    const d0 = Number(String(ymd).slice(8, 10));
    const mm = Math.max(0, Math.trunc(Number(months) || 0));

    let total = (y0 * 12 + (m0 - 1)) - mm;
    let y1 = Math.floor(total / 12);
    let m1 = total % 12;
    if (m1 < 0) { m1 += 12; y1 -= 1; }

    const daysInTargetMonth = new Date(Date.UTC(y1, m1 + 1, 0)).getUTCDate();
    const d1 = Math.min(d0, daysInTargetMonth);

    return `${String(y1).padStart(4, '0')}-${String(m1 + 1).padStart(2, '0')}-${String(d1).padStart(2, '0')}`;
  };

  const addDaysYMD = (ymd, days) => {
    const s = String(ymd || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
    const d = new Date(`${s}T00:00:00Z`);
    if (Number.isNaN(d.getTime())) return null;
    d.setUTCDate(d.getUTCDate() + (Number(days) || 0));
    const yyyy = d.getUTCFullYear();
    const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(d.getUTCDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  };

  const cutoffYMD = ((workStatus === 'RECENT' && !recentAll) || workStatus === 'NOT')
    ? subtractMonthsYMD(londonYMDNow(), recentMonths)
    : null;

  const normalizePickerRows = (value) => {
    const arr = Array.isArray(value)
      ? value
      : ((value && typeof value === 'object' && Array.isArray(value.rows)) ? value.rows : (value == null ? [] : [value]));

    return arr
      .filter((row) => row && typeof row === 'object')
      .map((row) => ({
        id: row.id == null ? null : String(row.id),
        display_name: row.display_name == null ? '' : String(row.display_name),
        first_name: row.first_name == null ? '' : String(row.first_name),
        last_name: row.last_name == null ? '' : String(row.last_name),
        email: row.email == null ? '' : String(row.email),
        phone: row.phone == null ? '' : String(row.phone),
        tms_ref: row.tms_ref == null ? '' : String(row.tms_ref),
        roles: row.roles == null ? null : row.roles,
        primary_job_title: row.primary_job_title == null ? '' : String(row.primary_job_title),
        job_titles_display: row.job_titles_display == null ? '' : String(row.job_titles_display),
        active: !!row.active,
        match_rank: Number.isFinite(Number(row.match_rank)) ? Number(row.match_rank) : null
      }));
  };

  const normalizeTextForSort = (value) => String(value == null ? '' : value).trim().toLowerCase();

  const deriveSecondaryJobTitlesSortValue = (row) => {
    const primaryTitle = String(row && row.primary_job_title == null ? '' : row && row.primary_job_title || '').trim();
    const primaryTitleNorm = normalizeTextForSort(primaryTitle);

    const parts = String(row && row.job_titles_display == null ? '' : row && row.job_titles_display || '')
      .split(';')
      .map((part) => String(part || '').trim())
      .filter(Boolean);

    const seen = new Set();
    const secondary = [];

    for (const part of parts) {
      const norm = normalizeTextForSort(part);
      if (!norm) continue;
      if (primaryTitleNorm && norm === primaryTitleNorm) continue;
      if (seen.has(norm)) continue;
      seen.add(norm);
      secondary.push(part);
    }

    secondary.sort((a, b) => {
      const aa = normalizeTextForSort(a);
      const bb = normalizeTextForSort(b);
      if (aa < bb) return -1;
      if (aa > bb) return 1;
      return 0;
    });

    return secondary.join('; ');
  };

  const compareNullableText = (leftValue, rightValue, dir) => {
    const leftNorm = normalizeTextForSort(leftValue);
    const rightNorm = normalizeTextForSort(rightValue);

    const leftBlank = !leftNorm;
    const rightBlank = !rightNorm;

    if (leftBlank && rightBlank) return 0;
    if (leftBlank) return 1;
    if (rightBlank) return -1;

    if (leftNorm < rightNorm) return dir === 'desc' ? 1 : -1;
    if (leftNorm > rightNorm) return dir === 'desc' ? -1 : 1;
    return 0;
  };

  const compareNullableBoolean = (leftValue, rightValue, dir) => {
    const leftNorm = leftValue === true ? 1 : (leftValue === false ? 0 : null);
    const rightNorm = rightValue === true ? 1 : (rightValue === false ? 0 : null);

    const leftBlank = leftNorm == null;
    const rightBlank = rightNorm == null;

    if (leftBlank && rightBlank) return 0;
    if (leftBlank) return 1;
    if (rightBlank) return -1;

    if (leftNorm < rightNorm) return dir === 'desc' ? 1 : -1;
    if (leftNorm > rightNorm) return dir === 'desc' ? -1 : 1;
    return 0;
  };

  const compareCandidateRows = (leftRow, rightRow) => {
    let cmp = 0;

    if (useDerivedSecondaryJobTitlesSort) {
      cmp = compareNullableText(
        deriveSecondaryJobTitlesSortValue(leftRow),
        deriveSecondaryJobTitlesSortValue(rightRow),
        orderDir
      );
      if (cmp !== 0) return cmp;

      cmp = compareNullableText(leftRow && leftRow.last_name, rightRow && rightRow.last_name, 'asc');
      if (cmp !== 0) return cmp;

      cmp = compareNullableText(leftRow && leftRow.first_name, rightRow && rightRow.first_name, 'asc');
      if (cmp !== 0) return cmp;

      cmp = compareNullableText(leftRow && leftRow.display_name, rightRow && rightRow.display_name, 'asc');
      if (cmp !== 0) return cmp;

      return compareNullableText(leftRow && leftRow.id, rightRow && rightRow.id, 'asc');
    }

    if (orderCol === 'primary_job_title') {
      cmp = compareNullableText(
        leftRow && leftRow.primary_job_title,
        rightRow && rightRow.primary_job_title,
        orderDir
      );
      if (cmp !== 0) return cmp;

      cmp = compareNullableText(leftRow && leftRow.last_name, rightRow && rightRow.last_name, 'asc');
      if (cmp !== 0) return cmp;

      cmp = compareNullableText(leftRow && leftRow.first_name, rightRow && rightRow.first_name, 'asc');
      if (cmp !== 0) return cmp;

      cmp = compareNullableText(leftRow && leftRow.display_name, rightRow && rightRow.display_name, 'asc');
      if (cmp !== 0) return cmp;

      return compareNullableText(leftRow && leftRow.id, rightRow && rightRow.id, 'asc');
    }

    if (orderCol === '__tms_ref') {
      const leftRefNum = Number(leftRow && leftRow.tms_ref_num);
      const rightRefNum = Number(rightRow && rightRow.tms_ref_num);
      const leftHasRefNum = Number.isFinite(leftRefNum);
      const rightHasRefNum = Number.isFinite(rightRefNum);

      if (leftHasRefNum && rightHasRefNum && leftRefNum !== rightRefNum) {
        cmp = orderDir === 'desc' ? (rightRefNum - leftRefNum) : (leftRefNum - rightRefNum);
      } else if (leftHasRefNum && !rightHasRefNum) {
        cmp = -1;
      } else if (!leftHasRefNum && rightHasRefNum) {
        cmp = 1;
      } else {
        cmp = compareNullableText(
          leftRow && leftRow.tms_ref,
          rightRow && rightRow.tms_ref,
          orderDir
        );
      }

      if (cmp !== 0) return cmp;
      return compareNullableText(leftRow && leftRow.id, rightRow && rightRow.id, 'asc');
    }

    if (orderCol === 'active') {
      cmp = compareNullableBoolean(
        leftRow && leftRow.active,
        rightRow && rightRow.active,
        orderDir
      );
      if (cmp !== 0) return cmp;
      return compareNullableText(leftRow && leftRow.id, rightRow && rightRow.id, 'asc');
    }

    cmp = compareNullableText(
      leftRow && leftRow[orderCol],
      rightRow && rightRow[orderCol],
      orderDir
    );
    if (cmp !== 0) return cmp;

    return compareNullableText(leftRow && leftRow.id, rightRow && rightRow.id, 'asc');
  };

   const hasCanonicalJobTitleFilter =
    jobTitleIncludeNodeIds.length > 0 ||
    jobTitleExcludeNodeIds.length > 0 ||
    jobTitleRoleIds.length > 0;

  // ✅ Date-semantics alignment:
  // If any created/updated date filters are present, force the canonical (RPC-driven) path
  // so we inherit the DB's date semantics (and avoid timestamp boundary drift).
  const hasCanonicalRpcFilter =
    hasCanonicalJobTitleFilter ||
    !!createdFrom ||
    !!createdTo ||
    !!updatedFrom ||
    !!updatedTo;

  let canonicalCandidateIdsPromise = null;

  const loadCanonicalCandidateIds = async () => {
    if (!hasCanonicalRpcFilter) return [];

    if (!canonicalCandidateIdsPromise) {
      canonicalCandidateIdsPromise = (async () => {
        const rpcFilters = (() => {
          try {
            return JSON.parse(JSON.stringify(spec || {}));
          } catch {
            return { ...(spec || {}) };
          }
        })();

        const rpcRows = await sbRpcAllRows(env, 'candidate_list_ids', {
          p_filters: rpcFilters
        }, {
          pageSize: 1000
        });

        const rows = Array.isArray(rpcRows)
          ? rpcRows
          : ((rpcRows && typeof rpcRows === 'object' && Array.isArray(rpcRows.rows)) ? rpcRows.rows : []);

        const outIds = [];
        const seenIds = new Set();

        for (const row of rows) {
          const id = String(
            (row && typeof row === 'object')
              ? (row.id ?? row.candidate_id ?? '')
              : (row == null ? '' : row)
          ).trim();

          if (!id || seenIds.has(id)) continue;
          seenIds.add(id);
          outIds.push(id);
        }

        return outIds;
      })();
    }

    return canonicalCandidateIdsPromise;
  };

  const canonicalCandidateSortSelectClause = 'id,display_name,first_name,last_name,email,phone,pay_method,active,created_at,primary_job_title,job_titles_display,tms_ref,tms_ref_num,roles';

  const fetchCanonicalCandidateRows = async ({ selectClause = '*' } = {}) => {
    const canonicalIds = await loadCanonicalCandidateIds();
    if (!Array.isArray(canonicalIds) || !canonicalIds.length) return [];

    const outRows = [];
    const seenRowIds = new Set();
    const chunkSize = 100;

    for (let index = 0; index < canonicalIds.length; index += chunkSize) {
      const chunkIds = canonicalIds.slice(index, index + chunkSize).map((value) => String(value || '').trim()).filter(Boolean);
      if (!chunkIds.length) continue;

      const api =
        `${env.SUPABASE_URL}/rest/v1/candidates_summary_activity` +
        `?select=${selectClause}` +
        `&id=${enc(`in.(${chunkIds.join(',')})`)}`;

      const res = await sbFetch(env, api, false);
      const batchRows = Array.isArray(res && res.rows) ? res.rows : [];

      for (const row of batchRows) {
        const rowId = String(row && row.id ? row.id : '').trim();
        if (!rowId || seenRowIds.has(rowId)) continue;
        seenRowIds.add(rowId);
        outRows.push(row);
      }
    }

    return outRows;
  };

  const fetchAllCandidateRows = async ({
    selectClause = '*',
    withJobTitleFilters = true
  } = {}) => {
    const outRows = [];
    let offsetValue = 0;
    const batchSize = 1000;

    while (true) {
      const api = buildCandidatesApi({
        selectClause,
        withPaging: true,
        limitValue: batchSize,
        offsetValue,
        withOrder: false,
        withJobTitleFilters
      });

      const res = await sbFetch(env, api, false);
      const batch = Array.isArray(res && res.rows) ? res.rows : [];
      outRows.push(...batch);

      if (batch.length < batchSize) break;
      offsetValue += batchSize;
    }

    return outRows;
  };

  const buildCandidatesApi = ({
    selectClause = '*',
    withPaging = true,
    limitValue = pageSize,
    offsetValue = (page - 1) * pageSize,
    withOrder = true,
    withJobTitleFilters = true
  }) => {
    const orderExpr =
      (orderCol === '__tms_ref')
        ? `${enc('tms_ref_num')}.${orderDir},${enc('tms_ref')}.${orderDir},id.asc`
        : (
            orderCol === 'primary_job_title'
              ? `${enc('primary_job_title')}.${orderDir},${enc('last_name')}.asc,${enc('first_name')}.asc,id.asc`
              : `${enc(orderCol)}.${orderDir},id.asc`
          );

    let api =
      `${env.SUPABASE_URL}/rest/v1/candidates_summary_activity` +
      `?select=${selectClause}`;

    if (withOrder) {
      api += `&order=${orderExpr}`;
    }

    if (withPaging) {
      api += `&limit=${limitValue}&offset=${offsetValue}`;
    }

    let orParts = null;

    if (text) {
      const esc = enc(text);
      orParts = [
        `first_name.ilike.*${esc}*`,
        `last_name.ilike.*${esc}*`,
        `display_name.ilike.*${esc}*`,
        `email.ilike.*${esc}*`,
        `phone.ilike.*${esc}*`,
        `tms_ref.ilike.*${esc}*`,
        `job_titles_display.ilike.*${esc}*`
      ];
    }

    if (rolesAny.length) {
      const parts = rolesAny.map((code) => {
        const val = enc(JSON.stringify([{ code }]));
        return `roles.cs.${val}`;
      });
      orParts = parts;
    }

    if (firstName) api += `&first_name=ilike.*${enc(firstName)}*`;
    if (lastName) api += `&last_name=ilike.*${enc(lastName)}*`;
    if (email) api += `&email=ilike.*${enc(email)}*`;
    if (phone) api += `&phone=ilike.*${enc(phone)}*`;

    if (notesExact) {
      const escMid = String(notesExact)
        .replace(/\\/g, '\\\\')
        .replace(/\*/g, '\\*')
        .replace(/%/g, '\\%')
        .replace(/_/g, '\\_');
      api += `&notes=ilike.*${enc(escMid)}*`;
    }

    if (payMethod === 'BLANK') {
      api += `&pay_method=is.null`;
    } else if (payMethod) {
      api += `&pay_method=eq.${enc(payMethod)}`;
    }

    if (active === 'true') api += `&active=eq.true`;
    if (active === 'false') api += `&active=eq.false`;

     if (createdFrom) api += `&created_at=gte.${enc(createdFrom)}`;
    if (createdTo) {
      const next = addDaysYMD(createdTo, 1);
      if (next) api += `&created_at=lt.${enc(next)}`;
      else api += `&created_at=lte.${enc(createdTo)}`;
    }
    if (withJobTitleFilters && jobTitleRoleIds.length) {
      if (jobTitlePrimaryOnly) {
        api += `&primary_job_title_id=${enc(`in.(${jobTitleRoleIds.join(',')})`)}`;
      } else {
        api += `&job_title_ids=${enc(`ov.{${jobTitleRoleIds.join(',')}}`)}`;
      }
    }

    if (profRegNumber) {
      api += `&prof_reg_number=ilike.*${enc(profRegNumber)}*`;
    }
    if (profRegType) {
      api += `&prof_reg_type=eq.${enc(profRegType)}`;
    }

    if (dobExact) api += `&date_of_birth=eq.${enc(dobExact)}`;

    if (gender) api += `&gender=eq.${enc(gender)}`;
    if (townCity) api += `&town_city=ilike.*${enc(townCity)}*`;
    if (postcode) api += `&postcode=ilike.*${enc(postcode)}*`;

     if (updatedFrom) api += `&updated_at=gte.${enc(updatedFrom)}`;
    if (updatedTo) {
      const next = addDaysYMD(updatedTo, 1);
      if (next) api += `&updated_at=lt.${enc(next)}`;
      else api += `&updated_at=lte.${enc(updatedTo)}`;
    }

    if (sortCode) api += `&sort_code=ilike.*${enc(sortCode)}*`;
    if (accountNumber) api += `&account_number=ilike.*${enc(accountNumber)}*`;
    if (umbrellaName) api += `&umbrella_name=ilike.*${enc(umbrellaName)}*`;
    if (tmsRef) api += `&tms_ref=ilike.*${enc(tmsRef)}*`;

    if (idFilterExpr) api += `&id=${enc(idFilterExpr)}`;

    if (rolesAll.length) {
      for (const code of rolesAll) {
        const val = JSON.stringify([{ code }]);
        api += `&roles=cs.${enc(val)}`;
      }
    }

    if (workStatus === 'CURRENT') {
      api += `&is_currently_working=eq.true`;
    } else if (workStatus === 'RECENT') {
      const d1 = `is_currently_working.eq.true`;
      const d2 = recentAll
        ? `and(is_currently_working.eq.false,last_timesheet_week_ending.not.is.null)`
        : (cutoffYMD
            ? `and(is_currently_working.eq.false,last_timesheet_week_ending.gte.${enc(cutoffYMD)})`
            : `is_currently_working.eq.true`);

      if (Array.isArray(orParts) && orParts.length) {
        const combined = [];
        for (const p of orParts) {
          combined.push(`and(${p},${d1})`);
          combined.push(`and(${p},${d2})`);
        }
        orParts = combined;
      } else {
        orParts = [d1, d2];
      }
    } else if (workStatus === 'NOT') {
      api += `&is_currently_working=eq.false`;
      const d1 = `last_timesheet_week_ending.is.null`;
      const d2 = cutoffYMD ? `last_timesheet_week_ending.lt.${enc(cutoffYMD)}` : `last_timesheet_week_ending.is.null`;

      if (Array.isArray(orParts) && orParts.length) {
        const combined = [];
        for (const p of orParts) {
          combined.push(`and(${p},${d1})`);
          combined.push(`and(${p},${d2})`);
        }
        orParts = combined;
      } else {
        orParts = [d1, d2];
      }
    }

    if (Array.isArray(orParts) && orParts.length) {
      api += `&or=(${orParts.join(',')})`;
    }

    return api;
  };

  if (format === 'picker') {
    const pickerQuery = String(
      text ||
      tmsRef ||
      email ||
      phone ||
      [firstName, lastName].filter(Boolean).join(' ')
    ).trim();

    const pickerPage = Math.max(1, parseInt(q('page') || '1', 10));
    const pickerPageSize = Math.max(1, Math.min(50, parseInt(q('page_size') || '25', 10)));

    if (!pickerQuery || pickerQuery.length < 2) {
      return withCORS(env, req, ok({
        rows: [],
        page: pickerPage,
        page_size: pickerPageSize,
        count: 0,
        has_more: false
      }));
    }

    try {
      let pickerRows = [];

         if (hasCanonicalRpcFilter) {
        const allPickerRows = await fetchCanonicalCandidateRows({
          selectClause: canonicalCandidateSortSelectClause
        });
        pickerRows = normalizePickerRows(allPickerRows).sort(compareCandidateRows);
      } else if (useDerivedSecondaryJobTitlesSort) {
        const allPickerRows = await fetchAllCandidateRows({
          selectClause: 'id,display_name,first_name,last_name,email,phone,tms_ref,roles,primary_job_title,job_titles_display,active'
        });
        pickerRows = normalizePickerRows(allPickerRows).sort(compareCandidateRows);
      } else {
        const pickerApi = buildCandidatesApi({
          selectClause: 'id,display_name,first_name,last_name,email,phone,tms_ref,roles,primary_job_title,job_titles_display,active',
          withPaging: true,
          limitValue: pickerPageSize + 1,
          offsetValue: (pickerPage - 1) * pickerPageSize,
          withOrder: true,
          withJobTitleFilters: true
        });

        const { rows } = await sbFetch(env, pickerApi, false);
        pickerRows = normalizePickerRows(rows);
      }

      if (hasCanonicalRpcFilter || useDerivedSecondaryJobTitlesSort) {
        const start = (pickerPage - 1) * pickerPageSize;
        const outRows = pickerRows.slice(start, start + pickerPageSize);
        const hasMore = (start + pickerPageSize) < pickerRows.length;

        return withCORS(env, req, ok({
          rows: outRows,
          page: pickerPage,
          page_size: pickerPageSize,
          count: outRows.length,
          has_more: hasMore
        }));
      }

      const hasMore = pickerRows.length > pickerPageSize;
      const outRows = pickerRows.slice(0, pickerPageSize);

      return withCORS(env, req, ok({
        rows: outRows,
        page: pickerPage,
        page_size: pickerPageSize,
        count: outRows.length,
        has_more: hasMore
      }));
    } catch (err) {
      const msg = String(err?.message || err || 'Candidate picker search failed');
      return withCORS(env, req, serverError(msg));
    }
  }
  if (format === 'membership') {
    const idsOut = [];
    const seen = new Set();
    let offset = 0;
    const batchSize = 1000;

    try {
      if (hasCanonicalRpcFilter) {
        const membershipRows = await fetchCanonicalCandidateRows({
          selectClause: canonicalCandidateSortSelectClause
        });
        membershipRows.sort(compareCandidateRows);

        for (const row of membershipRows) {
          const id = row && row.id ? String(row.id).trim() : '';
          if (!id || seen.has(id)) continue;
          seen.add(id);
          idsOut.push(id);
        }
      } else {
        while (true) {
          const api = buildCandidatesApi({
            selectClause: 'id',
            withPaging: true,
            limitValue: batchSize,
            offsetValue: offset,
            withOrder: true,
            withJobTitleFilters: true
          });

          const { rows } = await sbFetch(env, api, false);
          const batch = Array.isArray(rows) ? rows : [];

          for (const row of batch) {
            const id = row && row.id ? String(row.id).trim() : '';
            if (!id || seen.has(id)) continue;
            seen.add(id);
            idsOut.push(id);
          }

          if (batch.length < batchSize) break;
          offset += batchSize;
        }
      }
    } catch (err) {
      const msg = String(err?.message || err || 'Supabase fetch failed');
      if (/\b400\b/.test(msg)) {
        return withCORS(env, req, badRequest(`Supabase fetch failed: ${msg}`));
      }
      return withCORS(env, req, serverError(`Supabase fetch failed: ${msg}`));
    }

    return withCORS(env, req, ok({ ids: idsOut, count: idsOut.length }));
  }

  let rows = [];
  let total = undefined;

  try {
    if (hasCanonicalRpcFilter) {
      const allRows = await fetchCanonicalCandidateRows({ selectClause: '*' });
      allRows.sort(compareCandidateRows);

      const start = (page - 1) * pageSize;
      rows = allRows.slice(start, start + pageSize);
      total = allRows.length;
    } else if (useDerivedSecondaryJobTitlesSort) {
      const allRows = await fetchAllCandidateRows({ selectClause: '*' });
      allRows.sort(compareCandidateRows);

      const start = (page - 1) * pageSize;
      rows = allRows.slice(start, start + pageSize);
      total = allRows.length;
    } else {
      const api = buildCandidatesApi({
        selectClause: '*',
        withPaging: true,
        limitValue: pageSize,
        offsetValue: (page - 1) * pageSize,
        withOrder: true,
        withJobTitleFilters: true
      });

      const res = await sbFetch(env, api, includeCount);
      rows = res?.rows || [];
      total = res?.total;
    }
  } catch (err) {
    const msg = String(err?.message || err || 'Supabase fetch failed');

    if (/\b400\b/.test(msg)) {
      return withCORS(
        env,
        req,
        badRequest(
          `Supabase fetch failed: ${msg}`,
          {
            order_by: (orderByParam || null),
            order_dir: orderDir,
            use_derived_secondary_job_titles_sort: useDerivedSecondaryJobTitlesSort,
            job_title_include_node_ids: jobTitleIncludeNodeIds,
            job_title_exclude_node_ids: jobTitleExcludeNodeIds,
            job_title_role_ids: jobTitleRoleIds,
            job_title_primary_only: jobTitlePrimaryOnly
          }
        )
      );
    }

    return withCORS(env, req, serverError(`Supabase fetch failed: ${msg}`));
  }

  const respCount = includeCount ? (typeof total === 'number' ? total : (rows?.length || 0)) : (rows?.length || 0);

  if (format === 'csv') {
    const header = [
      'CandidateId',
      'DisplayName',
      'Email',
      'Phone',
      'PayMethod',
      'Active',
      'CreatedAt',
      'RotaRoles',
      'JobTitles'
    ];
    const out = [csvJoin(header)];
    for (const r of rows || []) {
      const rotaRoles = Array.isArray(r.roles) ? formatRolesSummary(r.roles) : '';
      const jobTitles = (typeof r.job_titles_display === 'string' && r.job_titles_display.trim())
        ? r.job_titles_display.trim()
        : '';
      out.push(csvJoin([
        r.id,
        r.display_name || [r.first_name, r.last_name].filter(Boolean).join(' '),
        r.email || '',
        r.phone || '',
        (r.pay_method || '').toUpperCase(),
        r.active ? 'Y' : 'N',
        r.created_at || '',
        rotaRoles,
        jobTitles
      ]));
    }
    return withCORS(env, req, ok({
      csv: out.join('\n'),
      count: respCount,
      page,
      page_size: pageSize
    }));
  }

  if (format === 'print') {
    const rowsHtml = (rows || []).map((r) => `
      <tr>
        <td>${r.display_name || [r.first_name, r.last_name].filter(Boolean).join(' ')}</td>
        <td>${r.email || ''}</td>
        <td>${r.phone || ''}</td>
        <td>${(r.pay_method || '').toUpperCase()}</td>
        <td>${r.active ? 'Y' : 'N'}</td>
        <td>${r.created_at || ''}</td>
      </tr>`).join('');
    const html = `
      <div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif">
        <h3>Candidates — Search Results</h3>
        <table width="100%" cellspacing="0" cellpadding="6" style="border-collapse:collapse">
          <thead><tr style="background:#f5f5f5">
            <th>Candidate</th><th>Email</th><th>Phone</th><th>Pay Method</th><th>Active</th><th>Created At</th>
          </tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>`;
    return withCORS(env, req, ok({
      html,
      count: respCount,
      page,
      page_size: pageSize
    }));
  }

  return withCORS(env, req, ok({
    rows,
    page,
    page_size: pageSize,
    count: respCount
  }));
}

async function handleListCandidates(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  try {
    const incomingUrl = new URL(req.url);
    const forwardUrl = new URL(incomingUrl.toString());
    forwardUrl.pathname = '/api/search/candidates';

    const internalReq = new Request(forwardUrl.toString(), {
      method: 'GET',
      headers: req.headers
    });

    const resp = await handleSearchCandidates(env, internalReq);
    if (!resp) return withCORS(env, req, serverError('Failed to list candidates'));

    let payload = null;
    try { payload = await resp.clone().json(); } catch { payload = null; }

    if (!resp.ok) {
      return withCORS(env, req, resp);
    }

    if (payload && typeof payload === 'object' && Array.isArray(payload.rows)) {
      return withCORS(env, req, ok({
        items: payload.rows,
        count: (typeof payload.count === 'number') ? payload.count : undefined,
        page: payload.page,
        page_size: payload.page_size
      }));
    }

    if (payload && typeof payload === 'object' && Array.isArray(payload.items)) {
      return withCORS(env, req, ok(payload));
    }

    return withCORS(env, req, ok({
      items: [],
      count: 0
    }));
  } catch {
    return withCORS(env, req, serverError('Failed to list candidates'));
  }
}


// ======================= NEW: Job titles list ==========================
 async function handleListJobTitles(env, req) {
  const user = await requireUser(env, req);
  if (!user) return unauthorized(); // you could optionally wrap this with withCORS if you want

  const url = new URL(req.url);
  const search = (url.searchParams.get('search') || url.searchParams.get('q') || '').trim();
  const activeOnly = (url.searchParams.get('activeOnly') ?? 'true').toLowerCase() !== 'false';

  let qs = 'select=*';

  if (activeOnly) {
    qs += '&active=eq.true';
  }

  if (search) {
    const safe = search.replace(/\s+/g, ' ').trim();
    const pattern = `*${safe}*`;
    qs += `&label=ilike.${encodeURIComponent(pattern)}`;
  }

  // Optional: sort by depth then label
  qs += '&order=depth.asc&order=label.asc';

  const base = `${env.SUPABASE_URL}/rest/v1/default_job_titles`;
  const urlStr = `${base}?${qs}`;

  try {
    const { rows } = await sbFetch(env, urlStr);
    return withCORS(env, req, ok({ items: rows || [] }));
  } catch (err) {
    console.error('handleListJobTitles failed', err);
    return withCORS(env, req, serverError('job_titles_list_failed'));
  }
}
// ======================= NEW: Job title create ==========================
 async function handleCreateJobTitle(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const body = await parseJSONBody(req).catch(() => null);
  if (!body || typeof body !== 'object') {
    return withCORS(env, req, badRequest('Invalid JSON'));
  }

  const rawLabel = (body.label || '').trim();
  if (!rawLabel) {
    return withCORS(env, req, badRequest('Label is required'));
  }

  const parentId = body.parent_id || null;
  const isRole = !!body.is_role;

  let requiresProfReg = !!body.requires_prof_reg;
  let profRegType = body.prof_reg_type || null;

  const allowedRegTypes = ['NMC', 'GMC', 'HCPC'];

  if (!isRole) {
    // Groups/categories can never require registration
    requiresProfReg = false;
    profRegType = null;
  } else {
    if (requiresProfReg) {
      const t = String(profRegType || '').toUpperCase();
      if (!allowedRegTypes.includes(t)) {
        return withCORS(env, req, badRequest('Invalid professional registration type'));
      }
      profRegType = t;
    } else {
      profRegType = null;
    }
  }

  // Compute depth from parent if provided
  let depth = 0;
  if (parentId) {
    try {
      const parentUrl =
        `${env.SUPABASE_URL}/rest/v1/default_job_titles` +
        `?select=depth&id=eq.${enc(parentId)}&limit=1`;
      const { rows: parents } = await sbFetch(env, parentUrl);
      const parent = (parents && parents[0]) || null;
      if (!parent) {
        return withCORS(env, req, badRequest('Parent job title not found'));
      }
      depth = (Number(parent.depth) || 0) + 1;
    } catch (e) {
      console.error('handleCreateJobTitle parent lookup failed', e);
      return withCORS(env, req, serverError('job_title_parent_lookup_failed'));
    }
  }

  const insertRow = {
    label: rawLabel,
    parent_id: parentId,
    depth,
    is_role: isRole,
    requires_prof_reg: requiresProfReg,
    prof_reg_type: profRegType,
    active: body.active === false ? false : true,
    updated_at: new Date().toISOString()
  };

  const urlStr = `${env.SUPABASE_URL}/rest/v1/default_job_titles`;

  try {
    const { rows } = await sbFetch(env, urlStr, {
      method: 'POST',
      headers: {
        Prefer: 'return=representation'
      },
      body: JSON.stringify(insertRow)
    });

    const created = (rows && rows[0]) || null;
    if (!created) {
      return withCORS(env, req, serverError('job_title_create_failed'));
    }

    return withCORS(env, req, ok({ item: created }, 201));
  } catch (err) {
    console.error('handleCreateJobTitle failed', err);
    return withCORS(env, req, serverError('job_title_create_failed'));
  }
}


// ======================= NEW: Job title update ==========================
 async function handleUpdateJobTitle(env, req, jobTitleId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  if (!jobTitleId) {
    return withCORS(env, req, badRequest('Missing job title id'));
  }

  const body = await parseJSONBody(req).catch(() => null);
  if (!body || typeof body !== 'object') {
    return withCORS(env, req, badRequest('Invalid JSON'));
  }

  // Load existing row so we can reason about is_role / reg settings / depth
  let existing;
  try {
    const existingUrl =
      `${env.SUPABASE_URL}/rest/v1/default_job_titles` +
      `?select=id,label,parent_id,depth,is_role,requires_prof_reg,prof_reg_type,active` +
      `&id=eq.${enc(jobTitleId)}&limit=1`;
    const { rows } = await sbFetch(env, existingUrl);
    existing = (rows && rows[0]) || null;
    if (!existing) {
      return withCORS(env, req, notFound());
    }
  } catch (e) {
    console.error('handleUpdateJobTitle existing lookup failed', e);
    return withCORS(env, req, serverError('job_title_existing_lookup_failed'));
  }

  const patch = {};
  let newParentId = undefined;

  if (body.label != null) {
    const rawLabel = String(body.label || '').trim();
    if (!rawLabel) {
      return withCORS(env, req, badRequest('Label cannot be empty'));
    }
    patch.label = rawLabel;
  }

  if (Object.prototype.hasOwnProperty.call(body, 'parent_id')) {
    newParentId = body.parent_id || null;
    if (newParentId === jobTitleId) {
      return withCORS(env, req, badRequest('parent_id cannot be the same as id'));
    }
    patch.parent_id = newParentId;
  }

  if (Object.prototype.hasOwnProperty.call(body, 'is_role')) {
    patch.is_role = !!body.is_role;
  }

  if (Object.prototype.hasOwnProperty.call(body, 'requires_prof_reg')) {
    patch.requires_prof_reg = !!body.requires_prof_reg;
  }

  if (Object.prototype.hasOwnProperty.call(body, 'prof_reg_type')) {
    if (body.prof_reg_type == null || body.prof_reg_type === '') {
      patch.prof_reg_type = null;
    } else {
      const allowed = ['NMC', 'GMC', 'HCPC'];
      const t = String(body.prof_reg_type).toUpperCase();
      if (!allowed.includes(t)) {
        return withCORS(env, req, badRequest('Invalid professional registration type'));
      }
      patch.prof_reg_type = t;
    }
  }

  if (Object.prototype.hasOwnProperty.call(body, 'active')) {
    patch.active = !!body.active;
  }

  // If parent changed, recompute depth
  if (newParentId !== undefined) {
    let depth = 0;
    if (newParentId) {
      try {
        const parentUrl =
          `${env.SUPABASE_URL}/rest/v1/default_job_titles` +
          `?select=depth&id=eq.${enc(newParentId)}&limit=1`;
        const { rows: parents } = await sbFetch(env, parentUrl);
        const parent = (parents && parents[0]) || null;
        if (!parent) {
          return withCORS(env, req, badRequest('Parent job title not found'));
        }
        depth = (Number(parent.depth) || 0) + 1;
      } catch (e) {
        console.error('handleUpdateJobTitle parent lookup failed', e);
        return withCORS(env, req, serverError('job_title_parent_lookup_failed'));
      }
    }
    patch.depth = depth;
  }

  // Enforce group vs role rules for registration
  const finalIsRole =
    Object.prototype.hasOwnProperty.call(patch, 'is_role') ? !!patch.is_role : !!existing.is_role;

  const finalRequiresProf =
    Object.prototype.hasOwnProperty.call(patch, 'requires_prof_reg')
      ? !!patch.requires_prof_reg
      : !!existing.requires_prof_reg;

  const finalProfType =
    Object.prototype.hasOwnProperty.call(patch, 'prof_reg_type') && patch.prof_reg_type !== undefined
      ? patch.prof_reg_type
      : existing.prof_reg_type;

  if (!finalIsRole) {
    // Groups/categories cannot have registration requirements
    patch.requires_prof_reg = false;
    patch.prof_reg_type = null;
  } else if (finalRequiresProf && !finalProfType) {
    return withCORS(env, req, badRequest('Professional registration type required when registration is required'));
  }

  // Block Role → Group change when in use
  const isRoleToGroup = !!existing.is_role && !finalIsRole;
  if (isRoleToGroup) {
    try {
      const usageUrl =
        `${env.SUPABASE_URL}/rest/v1/candidate_job_titles` +
        `?select=candidate_id&job_title_id=eq.${enc(jobTitleId)}&limit=200`;
      const { rows: used } = await sbFetch(env, usageUrl);
      const candidateIds = Array.from(new Set((used || []).map(r => r.candidate_id).filter(Boolean)));
      if (candidateIds.length) {
        return withCORS(env, req, ok({
          error: 'JOB_TITLE_IN_USE',
          message: `This role is assigned to ${candidateIds.length} candidates.`,
          candidate_ids: candidateIds
        }));
      }
    } catch (e) {
      console.error('handleUpdateJobTitle usage check failed', e);
      // fall through – if the check fails, we still try to apply patch, but log it
    }
  }

  patch.updated_at = new Date().toISOString();

  const urlStr =
    `${env.SUPABASE_URL}/rest/v1/default_job_titles` +
    `?id=eq.${enc(jobTitleId)}&select=*`;

  try {
    const { rows } = await sbFetch(env, urlStr, {
      method: 'PATCH',
      headers: {
        Prefer: 'return=representation'
      },
      body: JSON.stringify(patch)
    });

    const updated = (rows && rows[0]) || null;
    if (!updated) {
      return withCORS(env, req, notFound());
    }

    return withCORS(env, req, ok({ item: updated }));
  } catch (err) {
    console.error('handleUpdateJobTitle failed', err);
    return withCORS(env, req, serverError('job_title_update_failed'));
  }
}

// ======================= NEW: Job title delete ==========================
async function handleDeleteJobTitle(env, req, jobTitleId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  if (!jobTitleId) {
    return withCORS(env, req, badRequest('Missing job title id'));
  }

  const enc = encodeURIComponent;

  const pickErrMsg = (err) => {
    try {
      if (err && typeof err === 'object') {
        if (err.json && typeof err.json === 'object') {
          if (err.json.message) return String(err.json.message || '');
          if (err.json.error) return String(err.json.error || '');
        }
        if (typeof err.body === 'string' && err.body.trim()) {
          try {
            const j = JSON.parse(err.body);
            if (j && typeof j === 'object') {
              if (j.message) return String(j.message || '');
              if (j.error) return String(j.error || '');
            }
          } catch {}
          return String(err.body || '');
        }
        if (typeof err.message === 'string' && err.message.trim()) {
          const m = String(err.message || '');
          const idx = m.indexOf(':');
          const tail = (idx >= 0) ? m.slice(idx + 1).trim() : m.trim();
          if (tail) {
            try {
              const j = JSON.parse(tail);
              if (j && typeof j === 'object') {
                if (j.message) return String(j.message || '');
                if (j.error) return String(j.error || '');
              }
            } catch {}
          }
          return m;
        }
      }
    } catch {}
    return '';
  };

  try {
    const payload = {
      p_job_title_id: jobTitleId,
      p_actor_user_id: user.id,
      p_reason: null
    };

    const rpc = await sbRpc(env, 'job_titles_delete_apply', payload);

    // Keep response flexible; RPC returns { deleted:true, kind:'role'|'category', id:'...' }
    return withCORS(env, req, ok(rpc && typeof rpc === 'object' ? rpc : { deleted: true, id: String(jobTitleId) }));
  } catch (err) {
    const msgRaw = pickErrMsg(err);

    const msg = String(msgRaw || '').trim();

    // Required user-facing messages (surface exactly)
    if (msg.includes('Candidates have been assigned to this role.')) {
      return withCORS(env, req, badRequest(msg));
    }
    if (msg.includes('Candidates have been assigned to roles in this category.')) {
      return withCORS(env, req, badRequest(msg));
    }

    if (msg.includes('Job title not found')) {
      return withCORS(env, req, badRequest('Job title not found'));
    }

    console.error('handleDeleteJobTitle failed', { jobTitleId: enc(jobTitleId), msg, err });
    return withCORS(env, req, serverError('job_title_delete_failed'));
  }
}

// ======================= NEW: Postcode lookup (EasyPostcodes) ==========================
 async function handlePostcodeLookup(env, req) {
  const user = await requireUser(env, req);
  if (!user) return unauthorized();

  const url = new URL(req.url);
  const rawPostcode = (url.searchParams.get('postcode') || '').trim();
  const rawHouse = (url.searchParams.get('house') || '').trim();

  if (!rawPostcode) {
    return withCORS(env, req, badRequest('postcode is required'));
  }

  const apiKey = env.EASYPOSTCODES_API_KEY;
  if (!apiKey) {
    console.error('EASYPOSTCODES_API_KEY missing in env');
    return withCORS(env, req, serverError('postcode_lookup_not_configured'));
  }

  // Normalise postcode by stripping extra spaces
  const cleanedPostcode = rawPostcode.replace(/\s+/g, '');
  const epUrl = `https://api.easypostcodes.com/addresses/${encodeURIComponent(
    cleanedPostcode
  )}?includeGeo=false`;

  let resp;
  try {
    resp = await fetch(epUrl, {
      method: 'GET',
      headers: {
        Key: apiKey
      }
    });
  } catch (err) {
    console.error('EasyPostcodes network error', err);
    return withCORS(env, req, serverError('postcode_lookup_failed'));
  }

  if (!resp.ok) {
    console.error('EasyPostcodes non-OK', resp.status);
    return withCORS(env, req, serverError('postcode_lookup_failed'));
  }

  let raw;
  try {
    raw = await resp.json();
  } catch (err) {
    console.error('EasyPostcodes JSON parse error', err);
    return withCORS(env, req, serverError('postcode_lookup_failed'));
  }

  if (!Array.isArray(raw)) {
    return withCORS(env, req, ok({ addresses: [] }));
  }

  // Optional filter by house number / name
  let candidates = raw;
  const house = rawHouse.trim();
  if (house) {
    const needle = house.replace(/\s+/g, '').toLowerCase();

    const filtered = raw.filter((a) => {
      const bn = String(a.buildingNumber || '')
        .replace(/\s+/g, '')
        .toLowerCase();
      const sub = String(a.subBuildingName || '').toLowerCase();
      const addr1 = String(a.envelopeAddress?.addressLine1 || '').toLowerCase();

      if (bn && bn === needle) return true;
      if (addr1 && addr1.includes(needle)) return true;
      if (sub && sub.includes(needle)) return true;
      return false;
    });

    if (filtered.length > 0) {
      candidates = filtered;
    }
  }

  const mapped = candidates.map((a, idx) => {
    const envAddr = a.envelopeAddress || {};

    const line1 =
      envAddr.addressLine1 ||
      [a.subBuildingName, a.buildingNumber, a.thoroughfareAndDescriptor]
        .filter(Boolean)
        .join(' ')
        .trim();

    const line2 =
      envAddr.addressLine2 ||
      a.dependentLocality ||
      a.doubleDependentLocality ||
      '';

    const city = envAddr.town || a.postTown || '';
    const postcode = envAddr.postCode || a.postCode || rawPostcode;

    return {
      id: envAddr.summaryLine || `${idx}:${postcode}`,
      line1,
      line2,
      line3: '',
      city,
      postcode
    };
  });

  return withCORS(env, req, ok({ addresses: mapped }));
}





















// ================== BROKER: handleCreateCandidate (UPDATED to strip CCR fields) ==================
async function handleCreateCandidate(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const dataRaw = await parseJSONBody(req);
  if (!dataRaw) return withCORS(env, req, badRequest("Invalid JSON"));

  // Strip any accidental CCR fields (immutable/minted by DB)
  const { tms_ref, ccr_num, job_titles, ...data } = dataRaw;

  const enc = encodeURIComponent;

  // ✅ NEW: normalise remittance override booleans on create (accept 'on'/'true'/1, empty => false)
  const normalizeBoolish = (v) => {
    if (typeof v === 'boolean') return v;
    if (v === null || v === undefined) return false;
    if (typeof v === 'number') return v === 1;
    const s = String(v).trim().toLowerCase();
    if (!s) return false;
    if (['true','1','yes','y','on'].includes(s)) return true;
    if (['false','0','no','n','off'].includes(s)) return false;
    return false;
  };
  const normalizeBoolField = (obj, key) => {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) return;
    obj[key] = normalizeBoolish(obj[key]);
  };
  normalizeBoolField(data, 'remittance_overrides_enabled');
  normalizeBoolField(data, 'remittance_receive_enabled');
  normalizeBoolField(data, 'remittances_detailed_breakdown');
  normalizeBoolField(data, 'remittance_receive_when_umbrella_paid');

  // Normalise NHSP/HR name aliases (JSONB) if provided
  if (Object.prototype.hasOwnProperty.call(data, 'nhsp_hr_name_aliases')) {
    const rawAliases = data.nhsp_hr_name_aliases;
    let aliases = [];

    if (Array.isArray(rawAliases)) {
      aliases = rawAliases
        .map((x) => String(x || '').trim().toLowerCase())
        .filter(Boolean);
    } else if (typeof rawAliases === 'string') {
      const s = rawAliases.trim();
      if (s) {
        if (s.startsWith('[')) {
          try {
            const arr = JSON.parse(s);
            if (Array.isArray(arr)) {
              aliases = arr
                .map((x) => String(x || '').trim().toLowerCase())
                .filter(Boolean);
            }
          } catch {
            aliases = s
              .split(',')
              .map((x) => x.trim().toLowerCase())
              .filter(Boolean);
          }
        } else {
          aliases = s
            .split(',')
            .map((x) => x.trim().toLowerCase())
            .filter(Boolean);
        }
      }
    } else if (rawAliases != null) {
      const s = String(rawAliases).trim();
      if (s) aliases = [s.toLowerCase()];
    }

    data.nhsp_hr_name_aliases = Array.from(new Set(aliases));
  }

  // ✅ Normalise key_norm (GCK) and allow empty -> null
  if (Object.prototype.hasOwnProperty.call(data, 'key_norm')) {
    const v = String(data.key_norm ?? '').trim();
    data.key_norm = v ? v.toLowerCase() : null;
  }

  // ✅ Enforce key_norm uniqueness if provided
  if (data.key_norm) {
    const other = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?key_norm=eq.${enc(data.key_norm)}` +
        `&select=id` +
        `&limit=1`
    ).catch(() => null);

    if (other?.id) {
      return withCORS(env, req, badRequest('Global Candidate Key (key_norm) is already assigned to another candidate.'));
    }
  }

  // Normalise pay_method: only PAYE/UMBRELLA; Unknown/other -> "use DB default" (do not send)
  if (Object.prototype.hasOwnProperty.call(data, 'pay_method')) {
    let pm = (data.pay_method == null ? '' : String(data.pay_method)).trim().toUpperCase();
    if (pm === 'UNKNOWN' || pm === '') {
      delete data.pay_method;
    } else if (pm === 'PAYE' || pm === 'UMBRELLA') {
      data.pay_method = pm;
    } else {
      delete data.pay_method;
    }
  }

  // Normalise job_titles array -> list of UUID strings
  const jtArray = Array.isArray(job_titles)
    ? job_titles.map((x) => String(x)).filter(Boolean)
    : [];

  const primaryJobTitleId = jtArray[0] || null;

  const enqueueTsfinOutbox = async (items) => {
    if (!Array.isArray(items) || !items.length) return { enqueued: 0 };
    try {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/ts_financials_outbox?on_conflict=timesheet_id,reason`,
        {
          method: "POST",
          headers: { ...sbHeaders(env), "Prefer": "resolution=ignore-duplicates" },
          body: JSON.stringify(items)
        }
      );
      return { enqueued: items.length };
    } catch (e) {
      console.warn('[TSFIN] enqueue outbox failed', e?.message || e);
      return { enqueued: 0 };
    }
  };

  const runTsfinImmediate = async (limitHint) => {
    try {
      if (typeof runTsfinWorkerOnce !== 'function') {
        return { ran: false, picked: 0, ok: 0, fail: 0 };
      }
      const limit = Math.min(Math.max(parseInt(limitHint || '50', 10) || 50, 1), 200);
      const res = await runTsfinWorkerOnce(env, { limit });
      return { ran: true, ...(res || {}) };
    } catch (e) {
      console.warn('[TSFIN] immediate run failed', e?.message || e);
      return { ran: false, picked: 0, ok: 0, fail: 0 };
    }
  };

 const assignTimesheetsByOccKey = async (occKeyLower, candId) => {
  // candId is kept as a guard so callers don’t accidentally call with null,
  // but we do NOT write candidate_id into timesheets (column does not exist).
  if (!occKeyLower || !candId) return [];
  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?is_current=eq.true` +
        `&occupant_key_norm=eq.${enc(occKeyLower)}` +
        `&select=timesheet_id` +
        `&limit=500`
    );

    const ids = (rows || []).map(r => r?.timesheet_id).filter(Boolean);

    // ✅ Do NOT PATCH timesheets here (timesheets.candidate_id does not exist).
    // TSFIN rebuild will populate candidate_id/client_id in timesheets_financials / v_timesheets_summary.
    return ids;
  } catch (e) {
    console.warn('[CAND] assignTimesheetsByOccKey failed', e?.message || e);
    return [];
  }
};

  try {
    // Insert candidate; set job_title_id to primary (or null)
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/candidates`, {
      method: "POST",
      headers: { ...sbHeaders(env), "Prefer": "return=representation" },
      body: JSON.stringify({
        ...data,
        job_title_id: primaryJobTitleId,
        created_at: new Date().toISOString()
      })
    });
    if (!res.ok) {
      const err = await res.text();
      return withCORS(env, req, badRequest(`Candidate creation failed: ${err}`));
    }

    const json = await res.json().catch(() => ({}));
    const candidate = Array.isArray(json) ? json[0] : json;
    const candidateId = candidate?.id;

    // Insert candidate_job_titles join rows if provided
    if (candidateId && jtArray.length) {
      const nowIso = new Date().toISOString();
      const rows = jtArray.map((jobTitleId, idx) => ({
        candidate_id: candidateId,
        job_title_id: jobTitleId,
        is_primary: idx === 0,
        created_at: nowIso,
        updated_at: nowIso
      }));

      const jtRes = await fetch(`${env.SUPABASE_URL}/rest/v1/candidate_job_titles`, {
        method: "POST",
        headers: { ...sbHeaders(env), "Prefer": "resolution=ignore-duplicates" },
        body: JSON.stringify(rows)
      });

      if (!jtRes.ok) {
        const err = await jtRes.text().catch(() => 'insert candidate_job_titles failed');
        console.error('candidate_job_titles insert failed', err);
      }
    }

    // ✅ NEW: on candidate create, try to resolve any unassigned timesheets by key_norm
    let autoAssignedTimesheets = [];
    if (candidateId && candidate?.key_norm) {
      const k = String(candidate.key_norm || '').trim().toLowerCase();
      if (k) {
        autoAssignedTimesheets = await assignTimesheetsByOccKey(k, candidateId);
      }
    }

// ✅ Priority enqueue + targeted drain for any auto-assigned timesheets
const tsfinRun = await tsfinTargetedDrainNow(env, {
  timesheetIds: autoAssignedTimesheets,
  reason: 'CONTEXT_CHANGED',
  chunkSize: 50
});

return withCORS(env, req, ok({
  candidate,
  tsfin: {
    enqueued: tsfinRun.enqueued || 0,
    ran_now: tsfinRun.ran || 0,
    picked: tsfinRun.picked || 0,
    ok: tsfinRun.ok || 0,
    fail: tsfinRun.fail || 0,
    auto_assigned_timesheets: autoAssignedTimesheets.length
  }
}));

  } catch (e) {
    console.error('handleCreateCandidate failed', e);
    return withCORS(env, req, serverError("Failed to create candidate"));
  }
}



async function handleUpdateCandidate(env, req, candidateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const raw = await parseJSONBody(req);
  if (!raw) return withCORS(env, req, badRequest("Invalid JSON"));

  // Strip any accidental CCR fields (immutable/minted by DB)
  const { tms_ref, ccr_num, job_titles, ...data } = raw;

  // ✅ NEW: normalise remittance override booleans (accept 'on'/'true'/1, empty => false)
  const normalizeBoolish = (v) => {
    if (typeof v === 'boolean') return v;
    if (v === null || v === undefined) return false;
    if (typeof v === 'number') return v === 1;
    const s = String(v).trim().toLowerCase();
    if (!s) return false;
    if (['true','1','yes','y','on'].includes(s)) return true;
    if (['false','0','no','n','off'].includes(s)) return false;
    return false;
  };
  const normalizeBoolField = (obj, key) => {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) return;
    obj[key] = normalizeBoolish(obj[key]);
  };
  normalizeBoolField(data, 'remittance_overrides_enabled');
  normalizeBoolField(data, 'remittance_receive_enabled');
  normalizeBoolField(data, 'remittances_detailed_breakdown');
  normalizeBoolField(data, 'remittance_receive_when_umbrella_paid');

  const candidateBankClearFields = ['account_holder', 'bank_name', 'sort_code', 'account_number'];
  for (const field of candidateBankClearFields) {
    if (!Object.prototype.hasOwnProperty.call(data, field)) continue;
    if (data[field] === null || data[field] === undefined) {
      data[field] = null;
      continue;
    }
    if (typeof data[field] === 'string') {
      const trimmedBankValue = data[field].trim();
      data[field] = trimmedBankValue ? trimmedBankValue : null;
    }
  }

  // Normalise NHSP/HR name aliases (JSONB) if provided
  let aliasesChanged = false;
  if (Object.prototype.hasOwnProperty.call(data, 'nhsp_hr_name_aliases')) {
    const rawAliases = data.nhsp_hr_name_aliases;
    let aliases = [];

    if (Array.isArray(rawAliases)) {
      aliases = rawAliases
        .map((x) => String(x || '').trim().toLowerCase())
        .filter(Boolean);
    } else if (typeof rawAliases === 'string') {
      const s = rawAliases.trim();
      if (s) {
        if (s.startsWith('[')) {
          try {
            const arr = JSON.parse(s);
            if (Array.isArray(arr)) {
              aliases = arr
                .map((x) => String(x || '').trim().toLowerCase())
                .filter(Boolean);
            }
          } catch {
            aliases = s
              .split(',')
              .map((x) => x.trim().toLowerCase())
              .filter(Boolean);
          }
        } else {
          aliases = s
            .split(',')
            .map((x) => x.trim().toLowerCase())
            .filter(Boolean);
        }
      }
    } else if (rawAliases != null) {
      const s = String(rawAliases).trim();
      if (s) aliases = [s.toLowerCase()];
    }

    // de-dupe
    aliases = Array.from(new Set(aliases));
    data.nhsp_hr_name_aliases = aliases;
    aliasesChanged = true; // we’ll compute exact diff after loading "before"
  }

  // ✅ Normalise key_norm (GCK): allow clear -> null
  let keyNormTouched = false;
  if (Object.prototype.hasOwnProperty.call(data, 'key_norm')) {
    keyNormTouched = true;
    const v = String(data.key_norm ?? '').trim();
    data.key_norm = v ? v.toLowerCase() : null;
  }

  // Normalise pay_method:
  // - only PAYE/UMBRELLA are allowed
  // - Unknown/empty/other => "no change" (do NOT PATCH null because DB is NOT NULL)
  let payMethodAttemptedUnknown = false;
  if (Object.prototype.hasOwnProperty.call(data, 'pay_method')) {
    let pm = (data.pay_method == null ? '' : String(data.pay_method)).trim().toUpperCase();
    if (pm === 'UNKNOWN' || pm === '') {
      payMethodAttemptedUnknown = true;
      delete data.pay_method;
    } else if (pm === 'PAYE' || pm === 'UMBRELLA') {
      data.pay_method = pm;
    } else {
      payMethodAttemptedUnknown = true;
      delete data.pay_method;
    }
  }

  // Normalise job_titles array if present; undefined => "no change"
  let jtArray = null;
  if (Array.isArray(job_titles)) {
    jtArray = job_titles.map((x) => String(x)).filter(Boolean);
    data.job_title_id = jtArray[0] || null; // primary is first
  }

  // helpers
  const enc = encodeURIComponent;

  const arraysEqual = (a, b) => {
    const aa = Array.isArray(a) ? a.slice() : [];
    const bb = Array.isArray(b) ? b.slice() : [];
    if (aa.length !== bb.length) return false;
    for (let i = 0; i < aa.length; i++) if (String(aa[i]) !== String(bb[i])) return false;
    return true;
  };

  const normaliseAliasArr = (v) => {
    try {
      let out = [];
      if (Array.isArray(v)) out = v;
      else if (typeof v === 'string') {
        const s = v.trim();
        if (s.startsWith('[')) {
          try {
            const arr = JSON.parse(s);
            out = Array.isArray(arr) ? arr : [];
          } catch {
            out = s.split(',');
          }
        } else {
          out = s.split(',');
        }
      } else if (v != null) out = [v];
      return Array.from(
        new Set(
          out
            .map(x => String(x || '').trim().toLowerCase())
            .filter(Boolean)
        )
      ).sort();
    } catch {
      return [];
    }
  };

  const enqueueTsfinOutbox = async (items) => {
    if (!Array.isArray(items) || !items.length) return { enqueued: 0 };
    try {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/ts_financials_outbox?on_conflict=timesheet_id,reason`,
        {
          method: "POST",
          headers: { ...sbHeaders(env), "Prefer": "resolution=ignore-duplicates" },
          body: JSON.stringify(items)
        }
      );
      return { enqueued: items.length };
    } catch (e) {
      console.warn('[TSFIN] enqueue outbox failed', e?.message || e);
      return { enqueued: 0 };
    }
  };

  const runTsfinImmediate = async (limitHint) => {
    try {
      if (typeof runTsfinWorkerOnce !== 'function') {
        return { ran: false, picked: 0, ok: 0, fail: 0 };
      }
      const limit = Math.min(Math.max(parseInt(limitHint || '50', 10) || 50, 1), 200);
      const res = await runTsfinWorkerOnce(env, { limit });
      return { ran: true, ...(res || {}) };
    } catch (e) {
      console.warn('[TSFIN] immediate run failed', e?.message || e);
      return { ran: false, picked: 0, ok: 0, fail: 0 };
    }
  };

 const assignTimesheetsByOccKey = async (occKeyLower, candId) => {
  // candId is kept as a guard so callers don’t accidentally call with null,
  // but we do NOT write candidate_id into timesheets (column does not exist).
  if (!occKeyLower || !candId) return [];
  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?is_current=eq.true` +
        `&occupant_key_norm=eq.${enc(occKeyLower)}` +
        `&select=timesheet_id` +
        `&limit=500`
    );

    const ids = (rows || []).map(r => r?.timesheet_id).filter(Boolean);

    // ✅ Do NOT PATCH timesheets here (timesheets.candidate_id does not exist).
    // TSFIN rebuild will populate candidate_id/client_id in timesheets_financials / v_timesheets_summary.
    return ids;
  } catch (e) {
    console.warn('[CAND] assignTimesheetsByOccKey failed', e?.message || e);
    return [];
  }
};


  try {
    // 1) Load current candidate (include key_norm + aliases for diff + uniqueness)
    const sel = [
      'pay_method',
      'mileage_pay_rate',
      'umbrella_id',
      'account_holder',
      'bank_name',
      'sort_code',
      'account_number',
      'bank_details_hash',
      'key_norm',
      'nhsp_hr_name_aliases'
    ].join(',');

    const { rows: beforeRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?id=eq.${enc(candidateId)}` +
        `&select=${sel}` +
        `&limit=1`
    );
    const before = beforeRows?.[0] || {};

    const originalPayMethod = (before.pay_method == null)
      ? null
      : String(before.pay_method).toUpperCase();

    if (Object.prototype.hasOwnProperty.call(data, 'pay_method')) {
      const requestedPayMethod = String(data.pay_method || '').trim().toUpperCase();
      if ((requestedPayMethod === 'PAYE' || requestedPayMethod === 'UMBRELLA') && requestedPayMethod !== originalPayMethod) {
        return withCORS(
          env,
          req,
          new Response(JSON.stringify({
            error: 'PAYE and UMBRELLA changes must use the dedicated prospective-only pay-method change flow.',
            code: 'PAY_METHOD_CHANGE_ENDPOINT_REQUIRED',
            candidate_id: candidateId,
            current_method: originalPayMethod,
            requested_method: requestedPayMethod,
            dedicated_endpoint: `/api/candidates/${encodeURIComponent(candidateId)}/pay-method-change`
          }), {
            status: 409,
            headers: { 'content-type': 'application/json' }
          })
        );
      }

      if (requestedPayMethod === originalPayMethod) {
        delete data.pay_method;
      }
    }

    // If user attempted to set Unknown, enforce your rule (only allowed if NO contracts)
    if (payMethodAttemptedUnknown && (originalPayMethod === 'PAYE' || originalPayMethod === 'UMBRELLA')) {
      const { rows: conRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/contracts` +
          `?candidate_id=eq.${enc(candidateId)}` +
          `&select=id&limit=1`
      );
      const hasAnyContract = Array.isArray(conRows) && conRows.length > 0;
      if (hasAnyContract) {
        return withCORS(
          env,
          req,
          badRequest(
            'Cannot change pay method to Unknown while this candidate has contracts. ' +
            'Set pay method to PAYE or UMBRELLA instead.'
          )
        );
      }
      // If no contracts, "Unknown" just means "no change" (we already deleted pay_method)
    }

    // ✅ Enforce key_norm uniqueness if it’s being set (non-null)
    const beforeKey = (before.key_norm == null) ? null : String(before.key_norm).trim().toLowerCase();
    const nextKey   = keyNormTouched ? (data.key_norm == null ? null : String(data.key_norm)) : beforeKey;

    const keyNormChanged = keyNormTouched && (String(beforeKey || '') !== String(nextKey || ''));

    if (keyNormTouched && nextKey) {
      const other = await sbGetOne(
        env,
        `${env.SUPABASE_URL}/rest/v1/candidates` +
          `?key_norm=eq.${enc(nextKey)}` +
          `&id=neq.${enc(candidateId)}` +
          `&select=id` +
          `&limit=1`
      ).catch(() => null);

      if (other?.id) {
        return withCORS(env, req, badRequest('Global Candidate Key (key_norm) is already assigned to another candidate.'));
      }
    }

    // Compute alias exact diff only if field was touched
    let aliasesActuallyChanged = false;
    if (aliasesChanged) {
      const beforeAliases = normaliseAliasArr(before.nhsp_hr_name_aliases).sort();
      const afterAliases  = normaliseAliasArr(data.nhsp_hr_name_aliases).sort();
      aliasesActuallyChanged = !arraysEqual(beforeAliases, afterAliases);
    }

    // 2) Update candidate
    const url =
      `${env.SUPABASE_URL}/rest/v1/candidates` +
      `?id=eq.${enc(candidateId)}`;

    const res = await fetch(url, {
      method: "PATCH",
      headers: { ...sbHeaders(env), "Prefer": "return=representation" },
      body: JSON.stringify({ ...data, updated_at: new Date().toISOString() })
    });
    if (!res.ok) {
      const err = await res.text();
      return withCORS(env, req, badRequest(`Candidate update failed: ${err}`));
    }
    const json = await res.json().catch(() => ({}));
    const candidate = Array.isArray(json) ? json[0] : json;

    const oldHash = (before && before.bank_details_hash != null) ? String(before.bank_details_hash).trim() : '';
    const newHash = (candidate && candidate.bank_details_hash != null) ? String(candidate.bank_details_hash).trim() : '';

    // 2b) Upsert candidate_job_titles if job_titles were explicitly provided
    if (jtArray !== null) {
      try {
        const { rows: existingRows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/candidate_job_titles` +
            `?candidate_id=eq.${enc(candidateId)}` +
            `&select=job_title_id`
        );
        const existingIds = new Set((existingRows || []).map((r) => String(r.job_title_id)));
        const newIds = new Set(jtArray.map(String));

        const toDelete = [];
        for (const r of existingRows || []) {
          const id = String(r.job_title_id);
          if (!newIds.has(id)) toDelete.push(id);
        }
        const toInsert = [];
        for (const id of jtArray.map(String)) {
          if (!existingIds.has(id)) toInsert.push(id);
        }

        for (const jobTitleId of toDelete) {
          const delUrl =
            `${env.SUPABASE_URL}/rest/v1/candidate_job_titles` +
            `?candidate_id=eq.${enc(candidateId)}` +
            `&job_title_id=eq.${enc(jobTitleId)}`;
          await fetch(delUrl, { method: 'DELETE', headers: sbHeaders(env) }).catch(() => {});
        }

        if (toInsert.length) {
          const nowIso = new Date().toISOString();
          const rows = toInsert.map((jobTitleId) => ({
            candidate_id: candidateId,
            job_title_id: jobTitleId,
            is_primary: false,
            created_at: nowIso,
            updated_at: nowIso
          }));
          await fetch(`${env.SUPABASE_URL}/rest/v1/candidate_job_titles`, {
            method: 'POST',
            headers: { ...sbHeaders(env), "Prefer": "resolution=ignore-duplicates" },
            body: JSON.stringify(rows)
          }).catch(() => {});
        }

        const clearPrimaryUrl =
          `${env.SUPABASE_URL}/rest/v1/candidate_job_titles` +
          `?candidate_id=eq.${enc(candidateId)}`;
        await fetch(clearPrimaryUrl, {
          method: 'PATCH',
          headers: { ...sbHeaders(env), "Prefer": "return=minimal" },
          body: JSON.stringify({ is_primary: false, updated_at: new Date().toISOString() })
        }).catch(() => {});

        const primaryId = jtArray[0] || null;
        if (primaryId) {
          const setPrimaryUrl =
            `${env.SUPABASE_URL}/rest/v1/candidate_job_titles` +
            `?candidate_id=eq.${enc(candidateId)}` +
            `&job_title_id=eq.${enc(primaryId)}`;
          await fetch(setPrimaryUrl, {
            method: 'PATCH',
            headers: { ...sbHeaders(env), "Prefer": "return=minimal" },
            body: JSON.stringify({ is_primary: true, updated_at: new Date().toISOString() })
          }).catch(() => {});
        }
      } catch (jtErr) {
        console.error('handleUpdateCandidate: candidate_job_titles upsert failed', jtErr);
      }
    }

    // 3) Change detection (existing + NEW key_norm/aliases)
    const umbrellaChanged   = (data.umbrella_id !== undefined) && data.umbrella_id !== before.umbrella_id;
    const mileagePayChanged = (data.mileage_pay_rate != null) && Number(data.mileage_pay_rate) !== Number(before.mileage_pay_rate);

    const bankKeys = ['account_holder','bank_name','sort_code','account_number'];
    const bankChanged = bankKeys.some(k => Object.prototype.hasOwnProperty.call(data, k) && data[k] !== before[k]);

    // 4A) If key_norm changed, try to auto-assign matching unassigned timesheets now
    let autoAssignedTimesheets = [];
    if (keyNormChanged && nextKey) {
      autoAssignedTimesheets = await assignTimesheetsByOccKey(nextKey, candidateId);
    }

    // 4B) Build TSFIN outbox items
    const outboxItems = [];

    // Existing behaviour: recompute for current TSFIN rows for this candidate
    if (umbrellaChanged || bankChanged || mileagePayChanged || keyNormChanged || aliasesActuallyChanged) {
      const { rows: tsfins } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
          `?select=timesheet_id` +
          `&candidate_id=eq.${enc(candidateId)}` +
          `&is_current=eq.true` +
          `&locked_by_invoice_id=is.null`
      );

      for (const r of (tsfins || [])) {
        if (umbrellaChanged || bankChanged || keyNormChanged || aliasesActuallyChanged) {
          outboxItems.push({ timesheet_id: r.timesheet_id, reason: 'CONTEXT_CHANGED' });
        }
        if (mileagePayChanged) {
          outboxItems.push({ timesheet_id: r.timesheet_id, reason: 'RATE_CHANGED' });
        }
      }
    }

    // Also enqueue for any newly auto-assigned timesheets (so they become “resolved” immediately)
    for (const tsid of autoAssignedTimesheets) {
      outboxItems.push({ timesheet_id: tsid, reason: 'GCK_ASSIGNED' });
    }

 // 4C) Priority enqueue + targeted drain
const ids = Array.from(
  new Set(outboxItems.map(x => x?.timesheet_id).filter(Boolean).map(String))
);

const tsfinRun = await tsfinTargetedDrainNow(env, {
  timesheetIds: ids,
  reason: 'CONTEXT_CHANGED',
  chunkSize: 50
});

    if (oldHash && oldHash !== newHash) {
      try {
        await cleanupStaleRailPayeeMappingsForHash(env, {
          entity_kind: 'CANDIDATE',
          entity_id: candidateId,
          old_bank_details_hash: oldHash,
          new_bank_details_hash: newHash || null,
          actor_user_id: user.id
        });
      } catch (cleanupErr) {
        console.warn('[BANK_PAYEE_CLEANUP] candidate cleanup failed (non-fatal)', cleanupErr?.message || cleanupErr);
      }
    }

return withCORS(env, req, ok({
  candidate,
  tsfin: {
    enqueued: tsfinRun.enqueued || 0,
    ran_now: tsfinRun.ran || 0,
    picked: tsfinRun.picked || 0,
    ok: tsfinRun.ok || 0,
    fail: tsfinRun.fail || 0,
    auto_assigned_timesheets: autoAssignedTimesheets.length
  }
}));

  } catch (e) {
    console.error('handleUpdateCandidate failed', e);
    return withCORS(env, req, serverError("Failed to update candidate"));
  }
}

function normaliseRemittanceTimingGateResult(result) {
  const unwrapRpcPayload = (value) => {
    let payload = value;
    for (let i = 0; i < 4; i += 1) {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') {
        payload = payload[0];
        continue;
      }
      if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
        const wrapperKeys = [
          'pay_remittance_maybe_queue_for_trigger',
          'pay_batch_schedule',
          'pay_remittance_queue_commit_stage',
          'pay_finance_payout_notice_queue_commit_stage'
        ];
        let unwrapped = false;
        for (const key of wrapperKeys) {
          if (Object.prototype.hasOwnProperty.call(payload, key)) {
            payload = payload[key];
            unwrapped = true;
            break;
          }
        }
        if (unwrapped) continue;
      }
      break;
    }
    return (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : {};
  };

  const raw = unwrapRpcPayload(result);

  const getPath = (source, path) => {
    if (!source || typeof source !== 'object') return undefined;
    let cursor = source;
    for (const part of path) {
      if (!cursor || typeof cursor !== 'object' || !Object.prototype.hasOwnProperty.call(cursor, part)) return undefined;
      cursor = cursor[part];
    }
    return cursor;
  };

  function firstValue() {
    for (const value of Array.from(arguments)) {
      if (value === null || value === undefined) continue;
      if (typeof value === 'string' && value.trim() === '') continue;
      return value;
    }
    return undefined;
  }

  const textOrNull = (value) => {
    if (value === null || value === undefined) return null;
    const text = String(value).trim();
    return text ? text : null;
  };

  const upperTextOrNull = (value) => {
    const text = textOrNull(value);
    return text ? text.toUpperCase() : null;
  };

  const readBool = (value, fallback = false) => {
    if (typeof value === 'boolean') return value;
    if (typeof value === 'number') return value !== 0;
    if (value === null || value === undefined) return !!fallback;
    const text = String(value).trim().toLowerCase();
    if (['true', '1', 'yes', 'y', 'on'].includes(text)) return true;
    if (['false', '0', 'no', 'n', 'off'].includes(text)) return false;
    return !!fallback;
  };

  const nestedRemittanceStage = firstValue(
    getPath(raw, ['remittance_queue_stage_result']),
    getPath(raw, ['worker_communications', 'remittance_queue_stage_result'])
  );

  const nestedWorkerCommunications = firstValue(
    getPath(raw, ['worker_communications']),
    getPath(raw, ['workerCommunications'])
  );

  const queueResultRaw = firstValue(
    getPath(raw, ['queue_result']),
    getPath(raw, ['queueResult']),
    getPath(raw, ['remittance', 'queue_result']),
    getPath(raw, ['remittance', 'queueResult']),
    getPath(raw, ['payout_notice', 'queue_result']),
    getPath(raw, ['payout_notice', 'queueResult']),
    getPath(raw, ['remittance_queue_stage_result', 'queue_result']),
    getPath(raw, ['remittance_queue_stage_result', 'queueResult']),
    getPath(raw, ['worker_communications', 'remittance_queue_stage_result', 'queue_result']),
    getPath(raw, ['worker_communications', 'remittance_queue_stage_result', 'queueResult'])
  );

  const queueResult = unwrapRpcPayload(queueResultRaw);
  const remittanceStage = unwrapRpcPayload(nestedRemittanceStage);
  const workerCommunications = unwrapRpcPayload(nestedWorkerCommunications);

  const childOperationId = textOrNull(firstValue(
    getPath(raw, ['child_operation_id']),
    getPath(raw, ['childOperationId']),
    getPath(raw, ['operation_id']),
    getPath(raw, ['operationId']),
    getPath(raw, ['queue_result', 'operation_id']),
    getPath(raw, ['queueResult', 'operationId']),
    getPath(raw, ['queueResult', 'operation_id']),
    getPath(raw, ['remittance', 'operation_id']),
    getPath(raw, ['remittance', 'operationId']),
    getPath(raw, ['remittance', 'queue_result', 'operation_id']),
    getPath(raw, ['remittance', 'queueResult', 'operationId']),
    getPath(raw, ['payout_notice', 'operation_id']),
    getPath(raw, ['payout_notice', 'operationId']),
    getPath(raw, ['payout_notice', 'queue_result', 'operation_id']),
    getPath(raw, ['payout_notice', 'queueResult', 'operationId']),
    getPath(raw, ['remittance_queue_stage_result', 'operation_id']),
    getPath(raw, ['remittance_queue_stage_result', 'operationId']),
    getPath(raw, ['remittance_queue_stage_result', 'queue_result', 'operation_id']),
    getPath(raw, ['remittance_queue_stage_result', 'queueResult', 'operationId']),
    getPath(raw, ['worker_communications', 'remittance_queue_stage_result', 'operation_id']),
    getPath(raw, ['worker_communications', 'remittance_queue_stage_result', 'operationId']),
    getPath(raw, ['worker_communications', 'remittance_queue_stage_result', 'queue_result', 'operation_id']),
    getPath(raw, ['worker_communications', 'remittance_queue_stage_result', 'queueResult', 'operationId'])
  ));

  const trigger = upperTextOrNull(firstValue(
    getPath(raw, ['trigger']),
    getPath(raw, ['remittance_trigger']),
    getPath(raw, ['remittanceTrigger']),
    getPath(queueResult, ['trigger']),
    getPath(remittanceStage, ['trigger']),
    getPath(workerCommunications, ['trigger'])
  ));

  const configuredTiming = upperTextOrNull(firstValue(
    getPath(raw, ['configured_timing']),
    getPath(raw, ['configuredTiming']),
    getPath(raw, ['remittance_configured_timing']),
    getPath(raw, ['remittanceConfiguredTiming']),
    getPath(queueResult, ['configured_timing']),
    getPath(queueResult, ['configuredTiming']),
    getPath(remittanceStage, ['configured_timing']),
    getPath(remittanceStage, ['configuredTiming']),
    getPath(workerCommunications, ['configured_timing']),
    getPath(workerCommunications, ['configuredTiming'])
  ));

  const deferred = readBool(firstValue(
    getPath(raw, ['deferred']),
    getPath(raw, ['remittance_deferred']),
    getPath(raw, ['remittanceDeferred']),
    getPath(queueResult, ['deferred']),
    getPath(remittanceStage, ['deferred']),
    getPath(workerCommunications, ['deferred'])
  ), false);

  const suppressed = readBool(firstValue(
    getPath(raw, ['suppressed']),
    getPath(raw, ['suppress_remittances']),
    getPath(raw, ['remittance_suppressed']),
    getPath(raw, ['remittanceSuppressed']),
    getPath(queueResult, ['suppressed']),
    getPath(queueResult, ['suppress_remittances']),
    getPath(remittanceStage, ['suppressed']),
    getPath(remittanceStage, ['suppress_remittances']),
    getPath(workerCommunications, ['suppressed']),
    getPath(workerCommunications, ['suppress_remittances'])
  ), false);

  const dispatchRequired = readBool(firstValue(
    getPath(raw, ['dispatch_required']),
    getPath(raw, ['dispatchRequired']),
    getPath(queueResult, ['dispatch_required']),
    getPath(queueResult, ['dispatchRequired']),
    getPath(remittanceStage, ['dispatch_required']),
    getPath(remittanceStage, ['dispatchRequired'])
  ), false);

  const explicitOperationQueued = readBool(firstValue(
    getPath(raw, ['operation_queued']),
    getPath(raw, ['operationQueued']),
    getPath(raw, ['queued']),
    getPath(raw, ['remittance_operation_queued']),
    getPath(raw, ['remittanceOperationQueued']),
    getPath(queueResult, ['operation_queued']),
    getPath(queueResult, ['operationQueued']),
    getPath(queueResult, ['queued']),
    getPath(remittanceStage, ['operation_queued']),
    getPath(remittanceStage, ['operationQueued']),
    getPath(remittanceStage, ['queued'])
  ), false);

  const operationQueued = explicitOperationQueued || (!!childOperationId && !deferred && !suppressed);

  const requiresRemittanceOperation = readBool(firstValue(
    getPath(raw, ['requires_remittance_operation']),
    getPath(raw, ['requiresRemittanceOperation']),
    getPath(raw, ['operation_started']),
    getPath(raw, ['operationStarted']),
    getPath(queueResult, ['requires_remittance_operation']),
    getPath(queueResult, ['requiresRemittanceOperation']),
    getPath(queueResult, ['operation_started']),
    getPath(remittanceStage, ['requires_remittance_operation']),
    getPath(remittanceStage, ['requiresRemittanceOperation'])
  ), operationQueued || !!childOperationId);

  const operationStatus = upperTextOrNull(firstValue(
    getPath(raw, ['operation_status']),
    getPath(raw, ['operationStatus']),
    getPath(queueResult, ['operation_status']),
    getPath(queueResult, ['operationStatus']),
    getPath(remittanceStage, ['operation_status']),
    getPath(remittanceStage, ['operationStatus'])
  ));

  const operationPhase = upperTextOrNull(firstValue(
    getPath(raw, ['operation_phase']),
    getPath(raw, ['operationPhase']),
    getPath(queueResult, ['operation_phase']),
    getPath(queueResult, ['operationPhase']),
    getPath(remittanceStage, ['operation_phase']),
    getPath(remittanceStage, ['operationPhase'])
  ));

  const triggerStatus = upperTextOrNull(firstValue(
    getPath(raw, ['trigger_status']),
    getPath(raw, ['triggerStatus']),
    getPath(raw, ['remittance_trigger_status']),
    getPath(raw, ['remittanceTriggerStatus']),
    getPath(queueResult, ['trigger_status']),
    getPath(queueResult, ['triggerStatus']),
    getPath(remittanceStage, ['trigger_status']),
    getPath(remittanceStage, ['triggerStatus']),
    getPath(workerCommunications, ['trigger_status']),
    getPath(workerCommunications, ['triggerStatus'])
  ));

  const messageKind = upperTextOrNull(firstValue(
    getPath(raw, ['message_kind']),
    getPath(raw, ['messageKind']),
    getPath(raw, ['remittance_message_kind']),
    getPath(raw, ['remittanceMessageKind']),
    getPath(queueResult, ['message_kind']),
    getPath(queueResult, ['messageKind']),
    getPath(remittanceStage, ['message_kind']),
    getPath(remittanceStage, ['messageKind']),
    getPath(workerCommunications, ['message_kind']),
    getPath(workerCommunications, ['messageKind'])
  ));

  const ok = readBool(firstValue(
    getPath(raw, ['ok']),
    getPath(queueResult, ['ok']),
    getPath(remittanceStage, ['ok'])
  ), true);

  return {
    ok,
    trigger,
    configuredTiming,
    deferred,
    suppressed,
    dispatchRequired,
    operationQueued,
    requiresRemittanceOperation,
    childOperationId,
    operationStatus,
    operationPhase,
    triggerStatus,
    messageKind,
    queueResult,
    raw
  };
}


async function findExistingRemittanceChildOperation(env, options = {}) {
  const trimStr = (value) => String(value == null ? '' : value).trim();
  const upperTrim = (value) => trimStr(value).toUpperCase();
  const readBool = (value, fallback = false) => {
    if (typeof value === 'boolean') return value;
    if (typeof value === 'number') return value !== 0;
    if (value === null || value === undefined) return !!fallback;
    const text = String(value).trim().toLowerCase();
    if (['true', '1', 'yes', 'y', 'on'].includes(text)) return true;
    if (['false', '0', 'no', 'n', 'off'].includes(text)) return false;
    return !!fallback;
  };

  const getInputJson = (row) => {
    const input = row && row.input_json;
    return (input && typeof input === 'object' && !Array.isArray(input)) ? input : {};
  };

  const normaliseTrigger = (value, onlyConfirmed) => {
    const trigger = upperTrim(value) || (onlyConfirmed ? 'ON_PAYMENT_CONFIRMED' : 'ON_EXECUTION');
    return trigger === 'ON_PAYMENT_CONFIRMED' ? 'ON_PAYMENT_CONFIRMED' : 'ON_EXECUTION';
  };

  const normaliseScope = (value) => {
    const scope = upperTrim(value) || 'ALL';
    return ['ALL', 'PAYE', 'UMBRELLA'].includes(scope) ? scope : 'ALL';
  };

  const requestedOnlyConfirmed = readBool(options.onlyConfirmed ?? options.only_confirmed, false);
  const payBatchId = trimStr(options.payBatchId ?? options.pay_batch_id);
  const rootOperationId = trimStr(options.rootOperationId ?? options.root_operation_id);
  const trigger = normaliseTrigger(options.trigger, requestedOnlyConfirmed);
  const scope = normaliseScope(options.scope);
  const onlyConfirmed = requestedOnlyConfirmed;
  const messageKind = upperTrim(options.messageKind ?? options.message_kind);

  const emptyResult = {
    found: false,
    operationId: null,
    status: null,
    phase: null,
    terminal: false,
    row: null
  };

  if (!payBatchId || !rootOperationId) return emptyResult;

  const enc = encodeURIComponent;
  const select = [
    'id',
    'operation_type',
    'status',
    'phase',
    'actor_user_id',
    'pay_batch_id',
    'root_operation_id',
    'idempotency_key',
    'input_json',
    'result_json',
    'error_json',
    'created_at_utc',
    'started_at_utc',
    'updated_at_utc',
    'completed_at_utc',
    'failed_at_utc'
  ].join(',');

  const url = `${env.SUPABASE_URL}/rest/v1/banking_pay_operations` +
    `?operation_type=eq.REMITTANCE_QUEUE` +
    `&pay_batch_id=eq.${enc(payBatchId)}` +
    `&root_operation_id=eq.${enc(rootOperationId)}` +
    `&select=${enc(select)}` +
    `&order=updated_at_utc.desc` +
    `&limit=25`;

  const { rows } = await sbFetch(env, url);
  const sourceRows = Array.isArray(rows) ? rows : [];

  const matches = sourceRows.filter((row) => {
    const input = getInputJson(row);
    const rowOnlyConfirmed = readBool(input.only_confirmed ?? input.onlyConfirmed, false);
    const rowTrigger = normaliseTrigger(input.trigger ?? input.remittance_trigger ?? input.remittanceTrigger, rowOnlyConfirmed);
    const rowScope = normaliseScope(input.scope ?? input.pay_channel_scope ?? input.payChannelScope);
    const rowMessageKind = upperTrim(input.message_kind ?? input.messageKind);

    if (rowTrigger !== trigger) return false;
    if (rowScope !== scope) return false;
    if (rowOnlyConfirmed !== onlyConfirmed) return false;
    if (messageKind && rowMessageKind && rowMessageKind !== messageKind) return false;
    return true;
  });

  if (!matches.length) return emptyResult;

  const activeStatuses = new Set(['QUEUED', 'RUNNING', 'WAITING']);
  const successTerminalStatuses = new Set(['COMPLETE', 'COMPLETED', 'SUCCEEDED', 'SUCCESS']);
  const terminalStatuses = new Set(['COMPLETE', 'COMPLETED', 'SUCCEEDED', 'SUCCESS', 'FAILED', 'CANCELLED', 'CANCELED']);

  const activeRow = matches.find((row) => activeStatuses.has(upperTrim(row.status)));
  const completedRow = matches.find((row) => successTerminalStatuses.has(upperTrim(row.status)));
  const diagnosticRow = activeRow || completedRow || matches[0];
  const diagnosticStatus = upperTrim(diagnosticRow && diagnosticRow.status);
  const diagnosticPhase = upperTrim(diagnosticRow && diagnosticRow.phase);

  if (activeRow) {
    return {
      found: true,
      operationId: trimStr(activeRow.id) || null,
      status: upperTrim(activeRow.status) || null,
      phase: upperTrim(activeRow.phase) || null,
      terminal: terminalStatuses.has(upperTrim(activeRow.status)),
      row: activeRow
    };
  }

  if (completedRow) {
    return {
      found: true,
      operationId: trimStr(completedRow.id) || null,
      status: upperTrim(completedRow.status) || null,
      phase: upperTrim(completedRow.phase) || null,
      terminal: true,
      row: completedRow
    };
  }

  return {
    found: false,
    operationId: trimStr(diagnosticRow && diagnosticRow.id) || null,
    status: diagnosticStatus || null,
    phase: diagnosticPhase || null,
    terminal: terminalStatuses.has(diagnosticStatus),
    row: diagnosticRow || null
  };
}
async function queueRemittanceViaTimingGate(env, options = {}) {
  const trimStr = (value) => String(value == null ? '' : value).trim();
  const upperTrim = (value) => trimStr(value).toUpperCase();
  const readBool = (value, fallback = false) => {
    if (typeof value === 'boolean') return value;
    if (typeof value === 'number') return value !== 0;
    if (value === null || value === undefined) return !!fallback;
    const text = String(value).trim().toLowerCase();
    if (['true', '1', 'yes', 'y', 'on'].includes(text)) return true;
    if (['false', '0', 'no', 'n', 'off'].includes(text)) return false;
    return !!fallback;
  };

  const normaliseTrigger = (value, onlyConfirmed) => {
    const trigger = upperTrim(value) || (onlyConfirmed ? 'ON_PAYMENT_CONFIRMED' : 'ON_EXECUTION');
    return trigger === 'ON_PAYMENT_CONFIRMED' ? 'ON_PAYMENT_CONFIRMED' : 'ON_EXECUTION';
  };

  const normaliseScope = (value) => {
    const scope = upperTrim(value) || 'ALL';
    return ['ALL', 'PAYE', 'UMBRELLA'].includes(scope) ? scope : 'ALL';
  };

  const unwrapRpcPayload = (value, key) => {
    let payload = value;
    for (let i = 0; i < 4; i += 1) {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') {
        payload = payload[0];
        continue;
      }
      if (payload && typeof payload === 'object' && !Array.isArray(payload) && key && Object.prototype.hasOwnProperty.call(payload, key)) {
        payload = payload[key];
        continue;
      }
      break;
    }
    return (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : {};
  };

  const onlyConfirmed = readBool(options.onlyConfirmed ?? options.only_confirmed, false);
  const payBatchId = trimStr(options.payBatchId ?? options.pay_batch_id);
  const actorUserId = trimStr(options.actorUserId ?? options.actor_user_id ?? options.user_id);
  const rootOperationId = trimStr(options.rootOperationId ?? options.root_operation_id);
  const trigger = normaliseTrigger(options.trigger, onlyConfirmed);
  const scope = normaliseScope(options.scope);
  const source = trimStr(options.source) || 'queueRemittanceViaTimingGate';
  const messageKind = upperTrim(options.messageKind ?? options.message_kind);

  if (!payBatchId) throw new Error('queueRemittanceViaTimingGate: pay_batch_id is required');
  if (!actorUserId) throw new Error('queueRemittanceViaTimingGate: actor_user_id is required');
  if (!rootOperationId) throw new Error('queueRemittanceViaTimingGate: root_operation_id is required');

  const existing = await findExistingRemittanceChildOperation(env, {
    payBatchId,
    rootOperationId,
    actorUserId,
    trigger,
    scope,
    onlyConfirmed,
    messageKind
  });

  if (existing && existing.found && existing.operationId) {
    return normaliseRemittanceTimingGateResult({
      ok: true,
      trigger,
      configured_timing: null,
      deferred: false,
      suppressed: false,
      dispatch_required: false,
      operation_queued: true,
      requires_remittance_operation: true,
      operation_id: existing.operationId,
      operation_status: existing.status,
      operation_phase: existing.phase,
      trigger_status: existing.terminal ? 'REMITTANCE_OPERATION_ALREADY_COMPLETED' : 'REMITTANCE_OPERATION_ALREADY_EXISTS',
      message_kind: messageKind || null,
      already_exists: true,
      operation_created: false,
      operation_reused: true,
      source,
      existing_operation: {
        id: existing.operationId,
        status: existing.status,
        phase: existing.phase,
        terminal: existing.terminal
      },
      queue_result: {
        ok: true,
        operation_id: existing.operationId,
        operation_status: existing.status,
        operation_phase: existing.phase,
        trigger,
        scope,
        only_confirmed: onlyConfirmed,
        already_exists: true,
        operation_created: false,
        operation_reused: true
      }
    });
  }

  const rpcPayload = unwrapRpcPayload(await sbRpc(env, 'pay_remittance_maybe_queue_for_trigger', {
    p_pay_batch_id: payBatchId,
    p_trigger: trigger,
    p_scope: scope,
    p_actor_user_id: actorUserId,
    p_only_confirmed: onlyConfirmed,
    p_root_operation_id: rootOperationId,
    p_operation_mode: true
  }), 'pay_remittance_maybe_queue_for_trigger');

  const timingGatePayload = Object.assign({}, rpcPayload, {
    trigger: rpcPayload.trigger || trigger,
    scope: rpcPayload.scope || scope,
    only_confirmed: Object.prototype.hasOwnProperty.call(rpcPayload, 'only_confirmed') ? rpcPayload.only_confirmed : onlyConfirmed,
    source,
    queue_result: rpcPayload.queue_result || rpcPayload.queueResult || rpcPayload
  });

  const normalised = normaliseRemittanceTimingGateResult(timingGatePayload);
  const finalRaw = Object.assign({}, normalised.raw || {}, {
    source,
    pay_batch_id: payBatchId,
    root_operation_id: rootOperationId,
    scope,
    only_confirmed: onlyConfirmed,
    trigger
  });

  return Object.assign({}, normalised, { raw: finalRaw });
}




async function handleGetCandidate(env, req, candidateId) {
  const enc  = encodeURIComponent;
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  // ---- local helpers (kept inside function for safety + no external deps) ----
  const londonYMDNow = () => {
    // Build YYYY-MM-DD in Europe/London reliably (no DST bugs)
    const parts = new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Europe/London',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).formatToParts(new Date());

    const get = (type) => (parts.find(p => p.type === type)?.value || '');
    const y = get('year');
    const m = get('month');
    const d = get('day');
    return `${y}-${m}-${d}`;
  };

  const subtractMonthsYMD = (ymd, months) => {
    // ymd is YYYY-MM-DD. Subtract calendar months with end-of-month clamping.
    const y0 = Number(String(ymd).slice(0, 4));
    const m0 = Number(String(ymd).slice(5, 7));
    const d0 = Number(String(ymd).slice(8, 10));
    const mm = Math.max(0, Math.trunc(Number(months) || 0));

    let total = (y0 * 12 + (m0 - 1)) - mm;
    let y1 = Math.floor(total / 12);
    let m1 = total % 12;
    if (m1 < 0) { m1 += 12; y1 -= 1; } // defensive

    const daysInTargetMonth = new Date(Date.UTC(y1, m1 + 1, 0)).getUTCDate();
    const d1 = Math.min(d0, daysInTargetMonth);

    const yy = String(y1).padStart(4, '0');
    const mo = String(m1 + 1).padStart(2, '0');
    const dd = String(d1).padStart(2, '0');
    return `${yy}-${mo}-${dd}`;
  };

  try {
    // Fetch candidate
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?id=eq.${enc(candidateId)}` +
        `&select=*`
    );
    if (!rows.length) {
      return withCORS(env, req, notFound("Candidate not found"));
    }
    const candidate = rows[0];

    // Fetch joined job titles for this candidate
    let job_titles = [];
    try {
      const { rows: jtRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/candidate_job_titles` +
          `?candidate_id=eq.${enc(candidateId)}` +
          `&select=job_title_id,is_primary`
      );
      job_titles = Array.isArray(jtRows) ? jtRows : [];
    } catch (e) {
      console.error('handleGetCandidate: candidate_job_titles lookup failed', e);
      job_titles = [];
    }

    // If umbrella, fetch umbrella minimal fields
    let umbrella = undefined;
    if (candidate.pay_method === 'UMBRELLA' && candidate.umbrella_id) {
      const { rows: umbRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/umbrellas` +
          `?id=eq.${enc(candidate.umbrella_id)}` +
          `&select=id,name,bank_name,sort_code,account_number`
      );
      umbrella = umbRows?.[0];
    }

    const effective_pay_channel = resolveEffectivePayChannel({
      pay_method: candidate.pay_method,
      candidate,
      umbrella
    });

    // fetch hr_name_mappings aliases for this candidate
    let hr_aliases = [];
    try {
      const { rows: aliasRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/hr_name_mappings` +
          `?candidate_id=eq.${enc(candidateId)}` +
          `&select=id,hr_name_norm,hospital_or_trust,last_used_at`
      );
      hr_aliases = Array.isArray(aliasRows) ? aliasRows : [];
    } catch (e) {
      console.error('handleGetCandidate: hr_name_mappings lookup failed', {
        candidate_id: candidateId,
        err: e?.message || String(e)
      });
      hr_aliases = [];
    }

    // ---------------------------------------------------------------------
    // has_e_history (existence check via v_legacy_candidate_contract_summary)
    // ---------------------------------------------------------------------
    let has_e_history = false;
    try {
      const { rows: histRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_legacy_candidate_contract_summary` +
          `?candidate_id=eq.${enc(candidateId)}` +
          `&select=candidate_id` +
          `&limit=1`
      );
      has_e_history = Array.isArray(histRows) && histRows.length > 0;
    } catch (e) {
      console.error('handleGetCandidate: legacy history existence check failed', {
        candidate_id: candidateId,
        err: e?.message || String(e)
      });
      has_e_history = false;
    }

    // ---------------------------------------------------------------------
    // work_status (via candidate_activity_rollup)
    // ---------------------------------------------------------------------
    const RECENT_MONTHS_DEFAULT = 3;

    let is_currently_working = false;
    let last_timesheet_week_ending = null;

    try {
      const { rows: actRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/candidate_activity_rollup` +
          `?candidate_id=eq.${enc(candidateId)}` +
          `&select=is_currently_working,last_timesheet_week_ending` +
          `&limit=1`
      );

      const act = Array.isArray(actRows) ? actRows[0] : null;
      is_currently_working = !!(act && act.is_currently_working);
      last_timesheet_week_ending = (act && act.last_timesheet_week_ending) ? String(act.last_timesheet_week_ending) : null;
    } catch (e) {
      console.error('handleGetCandidate: candidate_activity_rollup lookup failed', {
        candidate_id: candidateId,
        err: e?.message || String(e)
      });
      is_currently_working = false;
      last_timesheet_week_ending = null;
    }

    const anchorYMD = londonYMDNow();
    const cutoffYMD = subtractMonthsYMD(anchorYMD, RECENT_MONTHS_DEFAULT);

    const is_recently_worked =
      (!is_currently_working) &&
      !!last_timesheet_week_ending &&
      (String(last_timesheet_week_ending) >= String(cutoffYMD));

    const work_status = {
      is_currently_working: !!is_currently_working,
      is_recently_worked: !!is_recently_worked,
      last_timesheet_week_ending: last_timesheet_week_ending
    };

    return withCORS(
      env,
      req,
      ok({
        candidate,
        effective_pay_channel,
        job_titles,
        hr_aliases,
        has_e_history,
        work_status
      })
    );
  } catch (e) {
    console.error('handleGetCandidate failed', e);
    return withCORS(env, req, serverError("Failed to fetch candidate"));
  }
}


async function handleChangesPing(env, req, user) {
  const currentUser = user || await requireUser(env, req, ['admin']);
  if (!currentUser) return withCORS(env, req, unauthorized());
  const safeObject = (value) => (value && typeof value === 'object' && !Array.isArray(value)) ? value : {};
  const unwrapRpc = (rpcRes, key) => {
    let payload = rpcRes;
    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && key && Object.prototype.hasOwnProperty.call(payload, key)) payload = payload[key];
    } catch {}
    return (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : {};
  };
  const normaliseCount = (value, fallback = 0) => {
    const numeric = Number(value);
    return Number.isFinite(numeric) && numeric >= 0 ? Math.trunc(numeric) : fallback;
  };
  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }
  body = safeObject(body);
  const lastSeen = safeObject(body.last_seen || body.lastSeen);
  const watchedBatchIds = [];
  const addWatched = (value) => {
    if (Array.isArray(value)) { for (const item of value) addWatched(item); return; }
    const text = String(value || '').trim();
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text) && !watchedBatchIds.includes(text) && watchedBatchIds.length < 20) watchedBatchIds.push(text);
  };
  addWatched(body.watched_pay_batch_ids || body.watchedPayBatchIds || body.open_pay_batch_ids || body.openPayBatchIds || body.open_batch_ids || body.openBatchIds);
  const watchedInvoiceOperationIds = [];
  const addWatchedInvoiceOperation = (value) => {
    if (Array.isArray(value)) {
      for (const item of value) addWatchedInvoiceOperation(item);
      return;
    }
    const text = String(value || '').trim();
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text)
        && !watchedInvoiceOperationIds.includes(text)
        && watchedInvoiceOperationIds.length < 100) {
      watchedInvoiceOperationIds.push(text);
    }
  };
  addWatchedInvoiceOperation(
    body.watched_invoice_operation_ids
    || body.watchedInvoiceOperationIds
    || lastSeen.watched_invoice_operation_ids
  );
  const previousBankingAlertHash = String(body.banking_alert_hash || body.bankingAlertHash || body.last_banking_alert_hash || body.lastBankingAlertHash || body.banking_alert_summary_signature || '').trim();
  try {
    const payload = unwrapRpc(await sbRpc(env, 'rpc_changes_ping', {
      p_last_seen: {
        ...lastSeen,
        __banking_actor_user_id: currentUser.id,
        __banking_alert_hash: previousBankingAlertHash || '',
        __watched_pay_batch_ids: watchedBatchIds,
        __watched_invoice_operation_ids: watchedInvoiceOperationIds
      }
    }), 'rpc_changes_ping');
    const responsePayload = { ...payload };
    const count = normaliseCount(responsePayload.banking_unacknowledged_alert_count, 0);
    responsePayload.banking_alert_hash = String(responsePayload.banking_alert_hash || responsePayload.banking_alert_summary_signature || '').trim();
    responsePayload.banking_alert_summary_signature = responsePayload.banking_alert_hash;
    responsePayload.banking_alert_summary_changed = responsePayload.banking_alert_summary_changed === true;
    responsePayload.banking_unacknowledged_alert_count = count;
    responsePayload.banking_highest_alert_label = count > 0 ? String(responsePayload.banking_highest_alert_label || '').trim() : '';
    responsePayload.banking_highest_alert_severity = count > 0 ? String(responsePayload.banking_highest_alert_severity || '').trim().toLowerCase() : '';
    responsePayload.banking_alert_summary_included = false;
    responsePayload.banking_alert_summary_deferred = count > 0;
    if (watchedBatchIds.length) {
      responsePayload.watched_batch_signals = [];
      for (const payBatchId of watchedBatchIds) {
        try {
          const signal = unwrapRpc(await sbRpc(env, 'banking_pay_batch_watch_signal', {
            p_pay_batch_id: payBatchId,
            p_actor_user_id: currentUser.id,
            p_known_version: null,
            p_known_payment_status_version: null,
            p_known_correction_progress_version: null,
            p_known_alert_version: null,
            p_known_overview_version: null,
            p_current_tab: 'AUTO',
            p_current_section_json: { source: 'handleChangesPing' }
          }), 'banking_pay_batch_watch_signal');
          responsePayload.watched_batch_signals.push(signal);
        } catch {}
      }
    }
    return withCORS(env, req, ok(responsePayload));
  } catch (e) {
    console.error('[CHANGES_PING] rpc_changes_ping failed', { err: e?.message || String(e), status: e?.status, body: e?.body });
    return withCORS(env, req, ok({ ok: true, degraded: true, changes_ping_degraded: true, changed: [], seqs: {}, server_utc: new Date().toISOString(), banking_alert_hash: previousBankingAlertHash || '', banking_alert_summary_signature: previousBankingAlertHash || '', banking_alert_summary_changed: false, banking_alert_summary_included: false, banking_alert_summary_deferred: false, banking_unacknowledged_alert_count: 0, banking_highest_alert_label: '', banking_highest_alert_severity: '', warning_code: 'CHANGES_PING_DEGRADED' }));
  }
}





async function handleRolesGlobal(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  // Small in-memory cache (worker instance) to make repeated opens instant.
  // TTL default: 10 minutes (within your requested 5–15 min window).
  const TTL_MS = 10 * 60 * 1000;

  try {
    const g = (typeof globalThis !== 'undefined') ? globalThis : {};
    g.__ROLES_GLOBAL_CACHE__ = g.__ROLES_GLOBAL_CACHE__ || { ts: 0, roles: [] };

    const cache = g.__ROLES_GLOBAL_CACHE__;
    const now = Date.now();

    if (Array.isArray(cache.roles) && (now - (cache.ts || 0) < TTL_MS)) {
      return withCORS(env, req, ok({ roles: cache.roles }));
    }

    const limit = 100000;

    const collectRoles = (rows) => {
      const set = new Set();
      for (const r of (Array.isArray(rows) ? rows : [])) {
        const s = String(r?.role || '').trim();
        if (!s) continue;
        set.add(s);
      }
      return Array.from(set).sort((a, b) => a.localeCompare(b));
    };

    const trimLogBody = (value, maxLen = 1200) => {
      const s = String(value == null ? '' : value);
      return s.length > maxLen ? `${s.slice(0, maxLen)}…` : s;
    };

    const fetchRolesRows = async (url, sourceLabel) => {
      try {
        const res = await sbFetch(env, url);
        return Array.isArray(res?.rows) ? res.rows : [];
      } catch (err) {
        const wrapped = new Error(err?.message || String(err) || `Failed to fetch roles from ${sourceLabel}`);
        wrapped.sourceLabel = sourceLabel;
        wrapped.url = url;
        wrapped.status = err?.status;
        wrapped.body = err?.body;
        throw wrapped;
      }
    };

    const viewUrl =
      `${env.SUPABASE_URL}/rest/v1/v_rates_client_defaults_enabled` +
      `?select=role` +
      `&role=not.is.null` +
      `&order=role.asc` +
      `&limit=${limit}`;

    const tableUrl =
      `${env.SUPABASE_URL}/rest/v1/rates_client_defaults` +
      `?select=role` +
      `&disabled_at_utc=is.null` +
      `&role=not.is.null` +
      `&order=role.asc` +
      `&limit=${limit}`;

    let rows = null;
    let primaryErr = null;

    try {
      rows = await fetchRolesRows(viewUrl, 'v_rates_client_defaults_enabled');
    } catch (err) {
      primaryErr = err;
      console.error('[ROLES_GLOBAL] primary source failed', {
        source: err?.sourceLabel || 'v_rates_client_defaults_enabled',
        url: err?.url || viewUrl,
        status: err?.status ?? null,
        body: trimLogBody(err?.body),
        err: err?.message || String(err)
      });
    }

    if (!Array.isArray(rows) || rows.length === 0) {
      try {
        const fallbackRows = await fetchRolesRows(tableUrl, 'rates_client_defaults');
        if (!Array.isArray(rows) || fallbackRows.length > 0) {
          rows = fallbackRows;
        } else if (!Array.isArray(rows)) {
          rows = fallbackRows;
        }
      } catch (fallbackErr) {
        console.error('[ROLES_GLOBAL] fallback source failed', {
          source: fallbackErr?.sourceLabel || 'rates_client_defaults',
          url: fallbackErr?.url || tableUrl,
          status: fallbackErr?.status ?? null,
          body: trimLogBody(fallbackErr?.body),
          err: fallbackErr?.message || String(fallbackErr)
        });

        if (!Array.isArray(rows)) {
          console.error('[ROLES_GLOBAL] failed', {
            primary_source: primaryErr?.sourceLabel || 'v_rates_client_defaults_enabled',
            primary_url: primaryErr?.url || viewUrl,
            primary_status: primaryErr?.status ?? null,
            primary_body: trimLogBody(primaryErr?.body),
            primary_err: primaryErr?.message || String(primaryErr || ''),
            fallback_source: fallbackErr?.sourceLabel || 'rates_client_defaults',
            fallback_url: fallbackErr?.url || tableUrl,
            fallback_status: fallbackErr?.status ?? null,
            fallback_body: trimLogBody(fallbackErr?.body),
            fallback_err: fallbackErr?.message || String(fallbackErr)
          });

          return withCORS(env, req, serverError('Failed to load global roles'));
        }
      }
    }

    const roles = collectRoles(rows);

    cache.ts = now;
    cache.roles = roles;

    return withCORS(env, req, ok({ roles }));
  } catch (e) {
    console.error('[ROLES_GLOBAL] failed', {
      err: e?.message || String(e),
      status: e?.status ?? null,
      body: String(e?.body == null ? '' : e.body).slice(0, 1200)
    });
    return withCORS(env, req, serverError('Failed to load global roles'));
  }
}
async function handleCandidateAliasesDelete(env, req, candidateId) {
  const enc  = encodeURIComponent;
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!candidateId) {
    return withCORS(env, req, badRequest('candidate_id required'));
  }

  let body;
  try {
    body = await parseJSONBody(req);
  } catch (e) {
    return withCORS(env, req, badRequest('Invalid JSON body'));
  }

  const mappingIds = Array.isArray(body?.mapping_ids)
    ? body.mapping_ids.map(String).filter(Boolean)
    : [];

  if (!mappingIds.length) {
    return withCORS(env, req, badRequest('mapping_ids (array) is required'));
  }

  try {
    // Delete only mappings that belong to this candidate
    const filter =
      `id=in.(${mappingIds.map((id) => enc(id)).join(',')})` +
      `&candidate_id=eq.${enc(candidateId)}`;

    const url =
      `${env.SUPABASE_URL}/rest/v1/hr_name_mappings?${filter}`;

    const res = await fetch(url, {
      method: 'DELETE',
      headers: { ...sbHeaders(env), Prefer: 'return=minimal' }
    });

    if (!res.ok) {
      const txt = await res.text().catch(() => '');
      return withCORS(env, req, serverError(
        txt || 'Failed to delete candidate alias mappings'
      ));
    }

    return withCORS(env, req, ok({
      candidate_id: candidateId,
      deleted: mappingIds.length
    }));
  } catch (e) {
    console.error('handleCandidateAliasesDelete failed', {
      candidate_id: candidateId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to delete candidate aliases'));
  }
}

async function handleClientAliasesDelete(env, req, clientId) {
  const enc  = encodeURIComponent;
  const norm = (s) => String(s || '').trim().toLowerCase();

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!clientId) {
    return withCORS(env, req, badRequest('client_id required'));
  }

  let body;
  try {
    body = await parseJSONBody(req);
  } catch (e) {
    return withCORS(env, req, badRequest('Invalid JSON body'));
  }

  // Allow either a single alias or an array of aliases
  let aliasesToDelete = [];
  if (Array.isArray(body?.aliases)) {
    aliasesToDelete = body.aliases.map(norm).filter(Boolean);
  } else if (body?.alias) {
    aliasesToDelete = [norm(body.alias)];
  }

  if (!aliasesToDelete.length) {
    return withCORS(env, req, badRequest('alias or aliases (array) is required'));
  }

  const deleteSet = new Set(aliasesToDelete);

  // Helper copied from applyWeeklyMappingsOnly
  const normAliasList = (val) => {
    if (!val) return [];
    if (Array.isArray(val)) return val;
    if (typeof val === 'string') {
      try {
        const parsed = JSON.parse(val);
        return Array.isArray(parsed) ? parsed : [val];
      } catch {
        return [val];
      }
    }
    return [];
  };

  try {
    // There is typically a single client_hospitals row per client
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/client_hospitals` +
        `?client_id=eq.${enc(clientId)}` +
        `&select=id,display_name,hospital_name_norm`
    );

    if (!Array.isArray(rows) || !rows.length) {
      return withCORS(env, req, ok({
        client_id: clientId,
        deleted: 0
      }));
    }

    let totalRemoved = 0;

    for (const r of rows) {
      const existing = normAliasList(r.hospital_name_norm);
      if (!existing.length) continue;

      const kept = [];
      let removedHere = 0;

      for (const alias of existing) {
        const canonical = norm(alias);
        if (deleteSet.has(canonical)) {
          removedHere++;
        } else {
          kept.push(alias);
        }
      }

      if (!removedHere) continue;
      totalRemoved += removedHere;

      // Patch this row with the pruned alias list
      const patchUrl =
        `${env.SUPABASE_URL}/rest/v1/client_hospitals` +
        `?id=eq.${enc(r.id)}`;

      const res = await fetch(patchUrl, {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
        body: JSON.stringify({ hospital_name_norm: kept })
      });

      if (!res.ok) {
        const txt = await res.text().catch(() => '');
        console.warn('handleClientAliasesDelete: PATCH failed', {
          id: r.id,
          client_id: clientId,
          err: txt
        });
      }
    }

    return withCORS(env, req, ok({
      client_id: clientId,
      deleted: totalRemoved
    }));
  } catch (e) {
    console.error('handleClientAliasesDelete failed', {
      client_id: clientId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to delete client aliases'));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Files: secure download via short-lived token
// GET /api/files/download?key=...&token=...[&filename=...]
// ─────────────────────────────────────────────────────────────────────────────



// ====================== HEALTHROSTER ======================
/**
 * @openapi
 * /api/healthroster/import:
 *   post:
 *     summary: Register an HR import (file already in R2)
 *     tags: [HealthRoster]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [file_key]
 *             properties:
 *               file_key: { type: string, description: "R2 key of uploaded file" }
 *     responses:
 *       200:
 *         description: import_id returned
 * /api/healthroster/{import_id}/rows:
 *   get:
 *     summary: List parsed rows for an import
 *     tags: [HealthRoster]
 *     security:
 *       - bearerAuth: []
 * /api/healthroster/{import_id}/mapping:
 *   get:
 *     summary: List active HR name mappings (global)
 *     tags: [HealthRoster]
 *     security:
 *       - bearerAuth: []
 *   post:
 *     summary: Upsert HR name mappings (global)
 *     tags: [HealthRoster]
 *     security:
 *       - bearerAuth: []
 * /api/healthroster/{import_id}/validate:
 *   post:
 *     summary: Trigger validation run (delegates to Flow if configured)
 *     tags: [HealthRoster]
 *     security:
 *       - bearerAuth: []
 */
async function handleHRRows(env, req, importId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!importId) {
    return withCORS(env, req, badRequest("import_id is required"));
  }

  try {
    const { searchParams } = new URL(req.url);
    const limit  = Math.min(Math.max(parseInt(searchParams.get('limit')  || '500', 10) || 500, 1), 5000);
    const offset = Math.max(parseInt(searchParams.get('offset') || '0',   10) || 0, 0);
    const order  = searchParams.get('order') || 'id.asc';

    const url =
      `${env.SUPABASE_URL}/rest/v1/hr_rows` +
      `?import_id=eq.${encodeURIComponent(importId)}` +
      `&select=*` +
      `&order=${encodeURIComponent(order)}` +
      `&limit=${limit}` +
      `&offset=${offset}`;

    const { rows } = await sbFetch(env, url, false);
    return withCORS(env, req, ok({ rows }));
  } catch {
    return withCORS(env, req, serverError("Failed to fetch HR rows"));
  }
}

async function handleFilesDownload(env, req) {
  const LOG = true; // set false if you want to reduce console noise

  try {
    const url = new URL(req.url);
    const keyParam = url.searchParams.get('key');
    const token = url.searchParams.get('token');
    const overrideName = url.searchParams.get('filename') || null;

    if (!keyParam || !token) {
      if (LOG) console.warn('[FILES][DL] deny: missing_params', {
        hasKey: !!keyParam,
        hasToken: !!token
      });
      return withCORS(env, req, badRequest("key and token are required"));
    }

    // Normalize incoming key to a bare R2 key (no leading slash)
    const key = String(keyParam || '').replace(/^\/+/, '').trim();

    if (key.includes('..')) {
      if (LOG) console.warn('[FILES][DL] deny: dotdot', { key });
      return withCORS(env, req, unauthorized());
    }

    // Allow uploaded evidence + other doc prefixes
    const ALLOWED_PREFIXES = [
      'files/',                     // evidence uploads
      'invoices/', 'remittances/', 'paper_ts/', 'signatures/', 'docs/',
      'docs-pdf/',
      'Assets/', 'assets/',
      'mailshot-template-attachments/'
    ];
    if (!ALLOWED_PREFIXES.some(p => key.startsWith(p))) {
      if (LOG) console.warn('[FILES][DL] deny: prefix', { key });
      return withCORS(env, req, unauthorized());
    }

    const secret = env.UPLOAD_TOKEN_SECRET;
    if (!secret) {
      if (LOG) console.warn('[FILES][DL] deny: missing_secret');
      return withCORS(env, req, serverError("Server not configured"));
    }

    // ✅ FIX: verifyToken returns { ok, payload } (NOT the payload itself)
    let ver;
    try {
      ver = await verifyToken(secret, token);
    } catch (e) {
      if (LOG) console.warn('[FILES][DL] deny: verify_throw', {
        key,
        err: e?.message || String(e)
      });
      await writeAudit(env, null, 'FILE_DOWNLOAD_DENIED', { key, reason: 'invalid_token_throw' }, { entity: 'r2', subject_id: key, req });
      return withCORS(env, req, unauthorized());
    }

    if (!ver || !ver.ok) {
      if (LOG) console.warn('[FILES][DL] deny: invalid_token', { key });
      await writeAudit(env, null, 'FILE_DOWNLOAD_DENIED', { key, reason: 'invalid_token' }, { entity: 'r2', subject_id: key, req });
      return withCORS(env, req, unauthorized());
    }

    const p = ver.payload || {};
    const payloadKey = (typeof p.key === 'string') ? p.key.replace(/^\/+/, '').trim() : '';
    const typ = (p.typ != null) ? String(p.typ) : null;
    const exp = (typeof p.exp === 'number') ? p.exp : null;

    // Accept both token types (backwards compatible)
    const typOk = (typ === 'dl' || typ === 'file_dl');

    if (!typOk || !payloadKey || payloadKey !== key) {
      if (LOG) console.warn('[FILES][DL] deny: claims_mismatch', {
        key,
        payloadKey: payloadKey || null,
        typ
      });
      await writeAudit(
        env,
        null,
        'FILE_DOWNLOAD_DENIED',
        { key, reason: 'claims_mismatch', payload_key: payloadKey || null, typ },
        { entity: 'r2', subject_id: key, req }
      );
      return withCORS(env, req, unauthorized());
    }

    // Expiry check (unix seconds)
    const now = Math.floor(Date.now() / 1000);
    if (!exp || now >= exp) {
      if (LOG) console.warn('[FILES][DL] deny: expired', { key, exp, now });
      await writeAudit(env, null, 'FILE_DOWNLOAD_DENIED', { key, reason: 'expired', exp }, { entity: 'r2', subject_id: key, req });
      return withCORS(env, req, new Response("Link expired", { status: 410 }));
    }

    const bucket = env.R2_BUCKET || env.R2;
    if (!bucket || !bucket.get) {
      if (LOG) console.warn('[FILES][DL] deny: no_bucket');
      return withCORS(env, req, serverError("Storage not configured"));
    }

    const obj = await bucket.get(key);
    if (!obj) {
      if (LOG) console.warn('[FILES][DL] not_found', { key });
      await writeAudit(env, null, 'FILE_DOWNLOAD_NOT_FOUND', { key }, { entity: 'r2', subject_id: key, req });
      return withCORS(env, req, notFound("File not found"));
    }

    const headers = new Headers();
    const ct = obj.httpMetadata?.contentType || 'application/octet-stream';
    headers.set('Content-Type', ct);
    if (typeof obj.size === 'number') headers.set('Content-Length', String(obj.size));
    headers.set('X-Content-Type-Options', 'nosniff');
    headers.set('Cache-Control', 'no-store');

    const metaName = obj.customMetadata?.originalName || null;
    const baseName = key.split('/').pop() || 'download.bin';
    const chosen = (overrideName || metaName || baseName)
      .replace(/[/\\]/g, '_')
      .replace(/[\r\n"]/g, '');

    // ✅ inline so iframe preview works
    headers.set('Content-Disposition', `inline; filename="${chosen}"`);

    await writeAudit(env, null, 'FILE_DOWNLOAD_OK', { key, size: obj.size || null }, { entity: 'r2', subject_id: key, req });
    return withCORS(env, req, new Response(obj.body, { status: 200, headers }));
  } catch (e) {
    try {
      console.warn('[FILES][DL] fatal', { err: e?.message || String(e) });
    } catch {}
    return withCORS(env, req, serverError("Failed to download file"));
  }
}

