// ====================== RELATED: COUNTS (generic) ======================
/**
 * @openapi
 * /api/related/{entity}/{id}/counts:
 *   get:
 *     summary: Get counts of related records for an entity (candidate, timesheet, invoice, remittance)
 *     tags: [Related]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: path
 *         name: entity
 *         required: true
 *         schema:
 *           type: string
 *           enum: [candidate, timesheet, invoice, remittance]
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *           description: The entity identifier (UUID for candidate/timesheet/invoice; mail_outbox.id for remittance)
 *     responses:
 *       200:
 *         description: Counts keyed by related type for the given entity.
 *         content:
 *           application/json:
 *             schema:
 *               oneOf:
 *                 - type: object
 *                   properties:
 *                     timesheets: { type: integer }
 *                     invoices:   { type: integer }
 *                     remittances:{ type: integer }
 *                 - type: object
 *                   properties:
 *                     candidate:  { type: integer }
 *                     invoice:    { type: integer }
 *                     remittances:{ type: integer }
 *                 - type: object
 *                   properties:
 *                     timesheets:     { type: integer }
 *                     candidates:     { type: integer }
 *                     correspondence: { type: integer }
 *                 - type: object
 *                   properties:
 *                     timesheets: { type: integer }
 *                     candidate:  { type: integer }
 */


// ─────────────────────────────────────────────────────────────────────────────
// Rates: LIST CLIENT DEFAULTS (UNIFIED WINDOW)
// GET /api/rates/client-defaults
// Supports: client_id, role, band, active_on, limit, offset, only_enabled
// - only_enabled=true → adds disabled_at_utc=is.null to the query
// ─────────────────────────────────────────────────────────────────────────────

async function handleListClientRates(env, req, clientId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const sp         = new URL(req.url).searchParams;
  const cid        = clientId || sp.get("client_id");
  const role       = sp.get("role");
  const bandRaw    = sp.get("band");
  const on         = sp.get("active_on");
  const onlyEnabled= sp.get("only_enabled") === 'true';

  const limit   = Math.min(Math.max(parseInt(sp.get('limit')  || '100', 10) || 100, 1), 500);
  const offset  = Math.max(parseInt(sp.get('offset') || '0',   10) || 0, 0);

  try {
    // Base query
    let q = `${env.SUPABASE_URL}/rest/v1/rates_client_defaults?select=*`;

    if (cid)  q += `&client_id=eq.${encodeURIComponent(cid)}`;
    if (role) q += `&role=eq.${encodeURIComponent(role)}`;

    // Band filter: explicit '' or 'null' → IS NULL; otherwise exact match.
    if (bandRaw !== null) {
      if (bandRaw === '' || String(bandRaw).toLowerCase() === 'null') q += `&band=is.null`;
      else q += `&band=eq.${encodeURIComponent(bandRaw)}`;
    }

    // Active-on-date filter
    if (on) {
      q += `&date_from=lte.${encodeURIComponent(on)}`;
      q += `&or=(date_to.gte.${encodeURIComponent(on)},date_to.is.null)`;
    }

    // Enabled-only filter
    if (onlyEnabled) q += `&disabled_at_utc=is.null`;

    // Order & pagination
    q += `&order=date_from.desc,role.asc,band.nullsfirst&limit=${limit}&offset=${offset}`;

    const { rows } = await sbFetch(env, q);

    // Enrich with disabled_by_name (email local-part), and strip disabled_by
    const ids = Array.from(
      new Set(
        (rows || [])
          .filter(r => r && r.disabled_by)
          .map(r => String(r.disabled_by))
      )
    );

    const idToName = new Map();

    if (ids.length) {
      // Build IN list WITHOUT URL-encoding the parentheses; PostgREST expects raw "(id1,id2,...)"
      const inList = `(${ids.join(',')})`;

      const ures = await fetch(
        `${env.SUPABASE_URL}/rest/v1/tms_users?select=id,email&id=in.${inList}`,
        { method:'GET', headers: { ...sbHeaders(env) } }
      );

      if (ures.ok) {
        const urows = await ures.json().catch(()=>[]);
        for (const u of (urows || [])) {
          const em = (u && typeof u.email === 'string') ? u.email : '';
          const short = em && em.includes('@') ? em.split('@')[0] : null;
          if (u?.id) idToName.set(String(u.id), short);
        }
      } else {
        // If lookup fails, leave map empty; FE will render blank (no "unknown")
      }
    }

    const enriched = (rows || []).map(r => {
      const out = { ...r };
      if (out.disabled_by) {
        out.disabled_by_name = idToName.get(String(out.disabled_by)) ?? null;
        delete out.disabled_by; // do not leak UUID
      }
      return out;
    });

    return withCORS(env, req, ok({ items: enriched }));
  } catch (e) {
    return withCORS(env, req, serverError("Failed to fetch client default rates"));
  }
}


// ─────────────────────────────────────────────────────────────────────────────
// Rates: upsert client default (now requires rate_type; uniqueness includes it)
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Rates: upsert client default (require rate_type; enqueue RATE_CHANGED by rate_type)
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// Rates: CLIENT DEFAULTS (UNIFIED WINDOW)
// POST /api/rates/client-defaults
// - Unified payload: one row holds 5×charge + 5×PAYE + 5×Umbrella
// - No rate_type in API
// - On insert with start N: truncate incumbent window (same category) to N−1
// - If a later window exists and new.date_to is null or overlaps, clamp new.date_to to (nextStart−1)
// - Unique key: (client_id, role, band|null, date_from)
// - Enqueue TSFIN recompute for current, unlocked rows for this client (all pay methods)
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// Rates: CLIENT DEFAULTS (UNIFIED WINDOW) UPSERT
// POST /api/rates/client-defaults
// - Unified payload: one row holds 5×charge + 5×PAYE + 5×Umbrella
// - No rate_type in API
// - Insert with start N: truncate incumbent (enabled-only) to N−1
// - If a later (enabled) window exists and new.date_to is null/overlaps, clamp new.date_to to (nextStart−1)
// - Unique key: (client_id, role, band|null, date_from) — DB enforces only for enabled rows
// - Enqueue TSFIN recompute **only if today is within [date_from, date_to] inclusive**
// ─────────────────────────────────────────────────────────────────────────────
async function handleUpsertClientRate(env, req, clientId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const body = await parseJSONBody(req);
  if (!body) return withCORS(env, req, badRequest("Invalid JSON"));

  // Expect unified fields in the body
  const rec = {
    client_id: body.client_id || clientId,
    role:      body.role ?? null,
    band:      (body.band === '' ? null : body.band ?? null),
    date_from: body.date_from ?? null,
    date_to:   (body.date_to === '' ? null : body.date_to ?? null),

    // charge (5)
    charge_day:   body.charge_day   ?? null,
    charge_night: body.charge_night ?? null,
    charge_sat:   body.charge_sat   ?? null,
    charge_sun:   body.charge_sun   ?? null,
    charge_bh:    body.charge_bh    ?? null,

    // PAYE (5)
    paye_day:   body.paye_day   ?? null,
    paye_night: body.paye_night ?? null,
    paye_sat:   body.paye_sat   ?? null,
    paye_sun:   body.paye_sun   ?? null,
    paye_bh:    body.paye_bh    ?? null,

    // Umbrella (5)
    umb_day:    body.umb_day    ?? null,
    umb_night:  body.umb_night  ?? null,
    umb_sat:    body.umb_sat    ?? null,
    umb_sun:    body.umb_sun    ?? null,
    umb_bh:     body.umb_bh     ?? null
  };

  if (!rec.client_id) return withCORS(env, req, badRequest("client_id required"));
  if (!rec.role)       return withCORS(env, req, badRequest("role required"));
  if (!rec.date_from)  return withCORS(env, req, badRequest("date_from required"));

  const client_id = rec.client_id;
  const role      = rec.role;
  const band      = rec.band;
  const dateFrom  = rec.date_from;

  // Helper: encode "(band is null)" vs "band = value"
  const bandFilter = (b) => (b == null ? 'band=is.null' : `band=eq.${encodeURIComponent(b)}`);

  // Helper: YMD day before
  function dayBeforeYmd(ymd) {
    if (!ymd) return null;
    const d = new Date(`${ymd}T00:00:00Z`);
    d.setUTCDate(d.getUTCDate() - 1);
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(d.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${dd}`;
  }

  // Helper: is today within [from, to] inclusive (to may be null = open)
  function todayWithinWindow(fromYmd, toYmd) {
    if (!fromYmd) return false;
    const today = new Date().toISOString().slice(0, 10);
    if (today < String(fromYmd)) return false;
    if (toYmd && today > String(toYmd)) return false;
    return true;
  }

  try {
    // 0) UPDATE path? (exact unique key exists among ENABLED rows)
    {
      let q = `${env.SUPABASE_URL}/rest/v1/rates_client_defaults` +
              `?client_id=eq.${encodeURIComponent(client_id)}` +
              `&role=eq.${encodeURIComponent(role)}` +
              `&${bandFilter(band)}` +
              `&date_from=eq.${encodeURIComponent(dateFrom)}` +
              `&disabled_at_utc=is.null` +                 // ← ignore disabled rows
              `&select=id`;
      const { rows: exactRows } = await sbFetch(env, q);
      if (Array.isArray(exactRows) && exactRows.length === 1) {
        const id = exactRows[0].id;
        const res = await fetch(
          `${env.SUPABASE_URL}/rest/v1/rates_client_defaults?id=eq.${encodeURIComponent(id)}`,
          { method: "PATCH", headers: { ...sbHeaders(env), "Prefer": "return=representation" }, body: JSON.stringify({ ...rec, updated_at: nowIso() }) }
        );
        if (!res.ok) {
          const err = await res.text();
          return withCORS(env, req, badRequest(`Rate update failed: ${err}`));
        }
        const json = await res.json().catch(() => ({}));
        const result = Array.isArray(json) ? json[0] : json;

        // Enqueue recompute ONLY if window is currently effective (inclusive)
        if (todayWithinWindow(rec.date_from, rec.date_to)) {
          await enqueueTsfinRecomputeForClient(env, client_id);
        }

        return withCORS(env, req, ok({ rate: result }));
      }
    }

    // 1) INSERT path — rollover behavior & no overlaps (consider ENABLED rows only)
    // 1a) Find incumbent window (same category) active at new start N = dateFrom
    {
      let qInc = `${env.SUPABASE_URL}/rest/v1/rates_client_defaults` +
                 `?client_id=eq.${encodeURIComponent(client_id)}` +
                 `&role=eq.${encodeURIComponent(role)}` +
                 `&${bandFilter(band)}` +
                 `&date_from=lte.${encodeURIComponent(dateFrom)}` +
                 `&or=(date_to.gte.${encodeURIComponent(dateFrom)},date_to.is.null)` +
                 `&disabled_at_utc=is.null` +               // ← ignore disabled rows
                 `&select=id,date_from,date_to` +
                 `&order=date_from.desc&limit=2`;
      const { rows: incumbents } = await sbFetch(env, qInc);

      if (incumbents.length > 1) {
        return withCORS(env, req, badRequest("Multiple incumbent windows found at the proposed start date. Please tidy overlaps first."));
      }
      if (incumbents.length === 1) {
        const inc = incumbents[0];
        if (String(inc.date_from) === String(dateFrom)) {
          return withCORS(env, req, badRequest("A window for this role/band already starts on the same date. Edit that window instead or choose a different start."));
        }
        const cut = dayBeforeYmd(dateFrom);
        if (inc.date_from && cut < inc.date_from) {
          return withCORS(env, req, badRequest("Proposed start would back-cut before the incumbent's start. Adjust dates."));
        }
        // Truncate incumbent to N−1
        const p = await fetch(
          `${env.SUPABASE_URL}/rest/v1/rates_client_defaults?id=eq.${encodeURIComponent(inc.id)}`,
          { method: "PATCH", headers: { ...sbHeaders(env), "Prefer": "return=representation" }, body: JSON.stringify({ date_to: cut, updated_at: nowIso() }) }
        );
        if (!p.ok) {
          const err = await p.text();
          return withCORS(env, req, badRequest(`Failed to truncate incumbent: ${err}`));
        }
      }
    }

    // 1b) If a later ENABLED window exists, clamp new.date_to to the day before the next start
    {
      let qNext = `${env.SUPABASE_URL}/rest/v1/rates_client_defaults` +
                  `?client_id=eq.${encodeURIComponent(client_id)}` +
                  `&role=eq.${encodeURIComponent(role)}` +
                  `&${bandFilter(band)}` +
                  `&date_from=gt.${encodeURIComponent(dateFrom)}` +
                  `&disabled_at_utc=is.null` +             // ← ignore disabled rows
                  `&select=date_from` +
                  `&order=date_from.asc&limit=1`;
      const { rows: nexts } = await sbFetch(env, qNext);
      if (Array.isArray(nexts) && nexts.length === 1) {
        const nextStart = nexts[0].date_from;
        const clampTo = dayBeforeYmd(nextStart);
        if (!rec.date_to || rec.date_to > clampTo) {
          rec.date_to = clampTo;
        }
      }
    }

    // 2) Insert the new unified window
    {
      const res = await fetch(`${env.SUPABASE_URL}/rest/v1/rates_client_defaults`, {
        method: "POST",
        headers: { ...sbHeaders(env), "Prefer": "return=representation" },
        body: JSON.stringify({ ...rec, created_at: nowIso() })
      });
      if (!res.ok) {
        const err = await res.text();
        return withCORS(env, req, badRequest(`Rate insert failed: ${err}`));
      }
      const json = await res.json().catch(() => ({}));
      const result = Array.isArray(json) ? json[0] : json;

      // Enqueue recompute ONLY if window is currently effective (inclusive)
      if (todayWithinWindow(rec.date_from, rec.date_to)) {
        await enqueueTsfinRecomputeForClient(env, client_id);
      }

      return withCORS(env, req, ok({ rate: result }));
    }
  } catch (e) {
    return withCORS(env, req, serverError("Failed to upsert client default window"));
  }
}

// Toggle enable/disable for a client default rate window
// PATCH /api/rates/client-defaults/:id
// Body: { "disabled": true|false }

async function handlePatchClientDefault(env, req, rateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const body = await parseJSONBody(req);
  if (!body || typeof body.disabled !== 'boolean') {
    return withCORS(env, req, badRequest('Field "disabled" (boolean) is required.'));
  }

  const now = nowIso();
  const patch = body.disabled
    ? { disabled_at_utc: now, disabled_by: user.id, updated_at: now }
    : { disabled_at_utc: null, disabled_by: null,     updated_at: now };

  // Apply patch and return the updated row
  const url = `${env.SUPABASE_URL}/rest/v1/rates_client_defaults?id=eq.${encodeURIComponent(rateId)}`;
  const res = await fetch(url, {
    method: 'PATCH',
    headers: { ...sbHeaders(env), 'Prefer': 'return=representation' },
    body: JSON.stringify(patch),
  });

  if (!res.ok) {
    const msg = await res.text().catch(() => '');
    return withCORS(env, req, badRequest(msg || `Failed to toggle rate window (status ${res.status})`));
  }

  const rows = await res.json().catch(() => []);
  const updated = Array.isArray(rows) ? rows[0] : rows;
  if (!updated) return withCORS(env, req, serverError('Toggle succeeded but no row returned.'));

  // Compute short name from tms_users.email (left-of-@), fallback to auth user email if needed.
  let disabled_by_name = null;
  if (updated.disabled_by) {
    try {
      const ures = await fetch(
        `${env.SUPABASE_URL}/rest/v1/tms_users?select=id,email&id=eq.${encodeURIComponent(updated.disabled_by)}`,
        { method: 'GET', headers: { ...sbHeaders(env) } }
      );
      if (ures.ok) {
        const arr = await ures.json().catch(()=>[]);
        if (Array.isArray(arr) && arr[0]) {
          const em = (arr[0].email || '');
          disabled_by_name = (typeof em === 'string' && em.includes('@')) ? em.split('@')[0] : null;
        }
      }
    } catch (_) {
      // fall through to auth user fallback
    }
  }
  if (!disabled_by_name) {
    const em = (user && typeof user.email === 'string') ? user.email : '';
    disabled_by_name = (em && em.includes('@')) ? em.split('@')[0] : null;
  }

  // enqueue TSFIN recompute only if window is currently effective
  const today = new Date().toISOString().slice(0,10);
  const fromYmd = String(updated.date_from || '');
  const toYmd   = updated.date_to ? String(updated.date_to) : null;
  const inWindow = fromYmd && (fromYmd <= today) && (!toYmd || today <= toYmd);
  if (updated?.client_id && inWindow) {
    try { await enqueueTsfinRecomputeForClient(env, updated.client_id); } catch (_) {}
  }

  const { disabled_by, ...rest } = updated;
  return withCORS(env, req, ok({ rate: { ...rest, disabled_by_name: disabled_by_name || null } }));
}

























const normaliseAdditionalRates = (raw) => {
  if (!raw) return null;
  const arr = Array.isArray(raw) ? raw : [];
  const out = [];
  const seen = new Set();
  const ALLOWED = new Set(['ONE_PER_WEEK','ONE_PER_DAY','WEEKENDS_AND_BH_ONLY','WEEKDAYS_EXCL_BH_ONLY']);

  const ensureCode = (code, idx) => {
    const c = String(code || '').toUpperCase();
    if (/^EX[1-5]$/.test(c)) return c;
    return `EX${idx + 1}`;
  };

  arr.slice(0, 5).forEach((row, idx) => {
    if (!row || typeof row !== 'object') return;
    const code = ensureCode(row.code, idx);
    if (seen.has(code)) return;
    seen.add(code);

    let bucketName = (row.bucket_name || '').trim();
    const unitName   = (row.unit_name != null && String(row.unit_name).trim())
      ? String(row.unit_name).trim()
      : null;

    let freq = String(row.frequency || 'ONE_PER_WEEK').toUpperCase();
    if (!ALLOWED.has(freq)) freq = 'ONE_PER_WEEK';

    let pay    = (row.pay_rate    !== undefined && row.pay_rate    !== null) ? Number(row.pay_rate)    : null;
    let charge = (row.charge_rate !== undefined && row.charge_rate !== null) ? Number(row.charge_rate) : null;
    if (pay != null && (!Number.isFinite(pay) || pay < 0)) pay = null;
    if (charge != null && (!Number.isFinite(charge) || charge < 0)) charge = null;

    const hasAny = bucketName || pay != null || charge != null || unitName;
    if (!hasAny) return;

    // ✅ Ensure bucket_name is never blank for a persisted row
    if (!bucketName) bucketName = code;

    out.push({
      code,
      bucket_name: bucketName,
      unit_name: unitName,
      frequency: freq,
      pay_rate: pay,
      charge_rate: charge
    });
  });

  out.sort((a, b) => String(a.code).localeCompare(String(b.code)));
  return out.length ? out : null;
};


async function migrateOutstandingWeeksToNewContract(env, originalId, newId, weekRows) {
  const weeks = Array.isArray(weekRows) ? weekRows : [];
  if (!weeks.length) {
    return { week_ids: [], timesheet_ids: [] };
  }

  const now = nowIso();

  const weekIds = weeks
    .map(w => w && w.id)
    .filter(Boolean)
    .map(String);

  const tsIds = Array.from(
    new Set(
      weeks
        .map(w => w && w.timesheet_id)
        .filter(Boolean)
        .map(String)
    )
  );

  // 1) Move contract_weeks to the new contract
  if (weekIds.length) {
    const inList = weekIds.map(enc).join(',');
    const url =
      `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
      `?id=in.(${inList})`;
    const res = await fetch(url, {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
      body: JSON.stringify({ contract_id: newId, updated_at: now })
    });
    if (!res.ok) {
      const txt = await res.text().catch(() => '');
      throw new Error(`migrateOutstandingWeeksToNewContract: PATCH contract_weeks failed (${res.status}): ${txt}`);
    }
  }

  // 2) Move timesheets (current rows only) to the new contract
  if (tsIds.length) {
    const inList = tsIds.map(enc).join(',');
    const url =
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=in.(${inList})` +
      `&is_current=eq.true`;
    const res = await fetch(url, {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
      body: JSON.stringify({ contract_id: newId, updated_at: now })
    });
    if (!res.ok) {
      const txt = await res.text().catch(() => '');
      throw new Error(`migrateOutstandingWeeksToNewContract: PATCH timesheets failed (${res.status}): ${txt}`);
    }
  }

  // 3) Enqueue TSFIN recompute for moved timesheets with reason = RATE_CHANGED
  if (tsIds.length) {
    const items = tsIds.map(tsid => ({
      timesheet_id: tsid,
      reason: 'RATE_CHANGED',
      attempt_count: 0,
      next_attempt_at: now,
      last_error: null,
      created_at: now
    }));

    const outboxUrl =
      `${env.SUPABASE_URL}/rest/v1/ts_financials_outbox` +
      `?on_conflict=timesheet_id,reason`;

    await fetch(outboxUrl, {
      method: 'POST',
      headers: { ...sbHeaders(env), Prefer: 'resolution=ignore-duplicates' },
      body: JSON.stringify(items)
    }).catch(() => {
      // Best-effort; failures here shouldn't abort the migration, but will show up in logs.
    });
  }

  return { week_ids: weekIds, timesheet_ids: tsIds };
}


async function collectOutstandingWeeklyContractsForCandidate(env, candidateId, newMethod, originalMethod) {
  if (!candidateId) return [];

  const orig = (originalMethod || '').toUpperCase();
  const target = (newMethod || '').toUpperCase();

  if (!orig || (orig !== 'PAYE' && orig !== 'UMBRELLA')) return [];
  if (!target || (target !== 'PAYE' && target !== 'UMBRELLA')) return [];

  // 1) Load contracts for this candidate with pay_method_snapshot = originalMethod
  const url =
    `${env.SUPABASE_URL}/rest/v1/contracts` +
    `?candidate_id=eq.${enc(candidateId)}` +
    `&pay_method_snapshot=eq.${enc(orig)}` +
    `&select=id,client_id,role,band,start_date,end_date,pay_method_snapshot`;

  const { rows: conRows } = await sbFetch(env, url);
  const contracts = Array.isArray(conRows) ? conRows : [];
  if (!contracts.length) return [];

  const contractIds = contracts.map(c => c && c.id).filter(Boolean).map(String);
  if (!contractIds.length) return [];

  // 2) Bulk outstanding weeks for these contracts
  const outstandingByContract = await collectOutstandingWeeksByContract(env, contractIds, null);

  const summaries = [];
  const clientIds = new Set();

  for (const c of contracts) {
    if (!c || !c.id) continue;
    const cid = String(c.id);
    const weeks = outstandingByContract.get(cid) || [];
    if (!weeks.length) continue;

    const dates = weeks
      .map(w => w.week_ending_date)
      .filter(Boolean)
      .sort();
    if (!dates.length) continue;

    clientIds.add(c.client_id);

    summaries.push({
      contract_id: c.id,
      client_id: c.client_id || null,
      client_name: null, // filled in below
      role: c.role || null,
      band: c.band ?? null,
      date_range: { start_date: c.start_date || null, end_date: c.end_date || null },
      pay_method_snapshot: c.pay_method_snapshot || null,
      outstanding_weeks: weeks.length,
      first_outstanding_we: dates[0],
      last_outstanding_we: dates[dates.length - 1]
    });
  }

  if (!summaries.length) return [];

  // 3) Load client names in one go
  if (clientIds.size) {
    const idsList = Array.from(clientIds).filter(Boolean).map(String);
    if (idsList.length) {
      const clientsUrl =
        `${env.SUPABASE_URL}/rest/v1/clients` +
        `?id=in.(${idsList.map(enc).join(',')})` +
        `&select=id,name`;
      const { rows: cliRows } = await sbFetch(env, clientsUrl);
      const byId = new Map((cliRows || []).map(r => [String(r.id), r.name || null]));

      for (const s of summaries) {
        if (s.client_id) {
          s.client_name = byId.get(String(s.client_id)) || null;
        }
      }
    }
  }

  return summaries;
}

// ─────────────────────────────────────────────────────────────────────────────
// Helper: collectOutstandingWeeklyContractsForCandidate
// Used by both preview + mutate handlers for PAYE↔UMBRELLA flips.
// Returns an array of:
// {
//   contract_id, client_id, client_name, role, band,
//   date_range: { start_date, end_date },
//   pay_method_snapshot,
//   outstanding_weeks, first_outstanding_we, last_outstanding_we
// }
// ─────────────────────────────────────────────────────────────────────────────




async function collectOutstandingWeeksByContract(env, contractIds, cutoffYmd = null) {
  const outMap = new Map();
  const ids = (contractIds || []).map(String).filter(Boolean);
  if (!ids.length) return outMap;

  // 1) Load contract_weeks for all contracts in one go
  let cwUrl =
    `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
    `?contract_id=in.(${ids.map(enc).join(',')})` +
    `&additional_seq=eq.0` +
    `&select=id,contract_id,week_ending_date,additional_seq,status,timesheet_id`;

  if (cutoffYmd) {
    cwUrl += `&week_ending_date=gte.${enc(cutoffYmd)}`;
  }

  cwUrl += `&order=contract_id.asc,week_ending_date.asc,additional_seq.asc`;

  const { rows: weekRows } = await sbFetch(env, cwUrl);
  const weeks = Array.isArray(weekRows) ? weekRows : [];
  if (!weeks.length) return outMap;

  // 2) Load current TSFIN rows for all attached timesheets in one go
  const tsIds = Array.from(
    new Set(
      weeks
        .map(w => w.timesheet_id)
        .filter(Boolean)
        .map(String)
    )
  );

  const finByTsId = new Map();
  if (tsIds.length) {
    const inList = tsIds.map(enc).join(',');
    const finQ =
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?is_current=eq.true` +
      `&timesheet_id=in.(${inList})` +
      `&select=timesheet_id,locked_by_invoice_id,paid_at_utc`;
    const { rows: finRows } = await sbFetch(env, finQ);
    for (const r of (finRows || [])) {
      if (r && r.timesheet_id) {
        finByTsId.set(String(r.timesheet_id), r);
      }
    }
  }

  // 3) Compute outstanding weeks and group by contract_id
  for (const w of weeks) {
    if (!w || !w.contract_id) continue;
    const cid = String(w.contract_id);
    const tsId = w.timesheet_id ? String(w.timesheet_id) : null;
    const fin = tsId ? (finByTsId.get(tsId) || null) : null;

    const isInvoiced = !!(fin && fin.locked_by_invoice_id);
    const isPaid     = !!(fin && fin.paid_at_utc);
    const isOutstanding = !tsId || (!isInvoiced && !isPaid);

    if (!isOutstanding) continue;

    const arr = outMap.get(cid) || [];
    arr.push({
      id: w.id,
      week_ending_date: w.week_ending_date,
      additional_seq: w.additional_seq,
      status: w.status,
      timesheet_id: w.timesheet_id || null,
      is_invoiced: isInvoiced,
      is_paid: isPaid
    });
    outMap.set(cid, arr);
  }

  return outMap;
}


// ─────────────────────────────────────────────────────────────────────────────
// Endpoint: GET /api/candidates/:id/pay-method-change-preview
// Preview which contracts would be affected by PAYE↔UMBRELLA flip.
// ─────────────────────────────────────────────────────────────────────────────


async function handleCandidatePayMethodChangePreview(env, req, candidateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));
  if (!candidateId) return withCORS(env, req, badRequest('candidate_id required'));

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const isoDateRe = /^\d{4}-\d{2}-\d{2}$/;
  const invalidScope = (message, context = null) => {
    const error = new Error(message);
    error.code = 'CANDIDATE_PAY_METHOD_CHANGE_SCOPE_INVALID';
    if (context) error.context = context;
    throw error;
  };
  const canonicalUuidArray = (value, fieldName, requireCanonicalOrder = true) => {
    if (!Array.isArray(value)) invalidScope(`Pay-method preview did not return ${fieldName} as an array.`);
    const raw = value.map((entry) => String(entry == null ? '' : entry).trim());
    if (raw.some((entry) => !uuidRe.test(entry))) {
      invalidScope(`Pay-method preview returned an invalid UUID in ${fieldName}.`, { field: fieldName, value });
    }
    const canonical = Array.from(new Set(raw)).sort();
    const hasDuplicates = canonical.length !== raw.length;
    const orderMismatch = raw.some((entry, index) => entry !== canonical[index]);
    if (hasDuplicates || (requireCanonicalOrder && orderMismatch)) {
      invalidScope(`Pay-method preview returned non-canonical ${fieldName}.`, { field: fieldName, value });
    }
    return canonical;
  };
  const arraysEqual = (left, right) => left.length === right.length && left.every((entry, index) => entry === right[index]);
  const nonNegativeInteger = (value, fieldName) => {
    const parsed = Number(value);
    if (!Number.isInteger(parsed) || parsed < 0) {
      invalidScope(`Pay-method preview returned an invalid ${fieldName}.`, { field: fieldName, value });
    }
    return parsed;
  };
  if (!uuidRe.test(String(candidateId))) return withCORS(env, req, badRequest('candidate_id must be a valid UUID'));
  const urlObj = new URL(req.url);
  const rawNewMethod = String(urlObj.searchParams.get('new_method') || '').trim().toUpperCase();
  const newMethod = (rawNewMethod === 'PAYE' || rawNewMethod === 'UMBRELLA') ? rawNewMethod : null;
  const requestedUmbrellaId = String(urlObj.searchParams.get('umbrella_id') || '').trim();

  if (!newMethod) {
    return withCORS(env, req, badRequest('new_method must be PAYE or UMBRELLA'));
  }
  if (requestedUmbrellaId && !uuidRe.test(requestedUmbrellaId)) {
    return withCORS(env, req, badRequest('umbrella_id must be a valid UUID'));
  }

  try {
    const candidate = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?id=eq.${enc(candidateId)}` +
        `&select=id,pay_method,umbrella_id,account_holder,bank_name,sort_code,account_number,updated_at,rev`
    );
    if (!candidate) {
      return withCORS(env, req, notFound('Candidate not found'));
    }

    const originalMethod = String(candidate.pay_method || '').trim().toUpperCase();
    if (originalMethod !== 'PAYE' && originalMethod !== 'UMBRELLA') {
      return withCORS(env, req, badRequest('Candidate pay_method must be PAYE or UMBRELLA for this operation'));
    }
    if (originalMethod === newMethod) {
      return withCORS(env, req, conflict('Candidate already has this pay method'));
    }

    const blockers = [];
    const effectiveUmbrellaId = newMethod === 'UMBRELLA'
      ? (requestedUmbrellaId || String(candidate.umbrella_id || '').trim() || null)
      : null;

    if (newMethod === 'UMBRELLA') {
      if (!effectiveUmbrellaId) {
        blockers.push({
          code: 'MISSING_UMBRELLA_ID',
          message: 'Select an enabled umbrella company before changing the candidate to UMBRELLA.'
        });
      } else {
        const umbrella = await sbGetOne(
          env,
          `${env.SUPABASE_URL}/rest/v1/umbrellas` +
            `?id=eq.${enc(effectiveUmbrellaId)}` +
            `&enabled=eq.true` +
            `&select=id,name,enabled`
        ).catch(() => null);
        if (!umbrella) {
          blockers.push({
            code: 'UMBRELLA_NOT_FOUND_OR_DISABLED',
            message: 'The selected umbrella company is unavailable or disabled.'
          });
        }
      }
    }

    const rpcResultRaw = await sbRpc(
      env,
      'candidate_pay_method_change_refresh_scope_v1',
      {
        p_candidate_id: candidate.id,
        p_source_method: originalMethod,
        p_target_method: newMethod
      },
      {
        routeClass: 'PREVIEW_PROGRESS',
        purpose: 'CANDIDATE_PAY_METHOD_CHANGE_PREVIEW',
        timeoutMs: 8000
      }
    );
    const scope = Array.isArray(rpcResultRaw) ? (rpcResultRaw[0] || {}) : (rpcResultRaw || {});

    if (
      !scope ||
      typeof scope !== 'object' ||
      Array.isArray(scope) ||
      scope.ok !== true ||
      String(scope.candidate_id || '').trim() !== String(candidate.id) ||
      String(scope.candidate_current_method || '').trim().toUpperCase() !== originalMethod ||
      String(scope.source_method || '').trim().toUpperCase() !== originalMethod ||
      String(scope.target_method || '').trim().toUpperCase() !== newMethod ||
      String(scope.coverage_basis || '').trim().toUpperCase() !== 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY' ||
      scope.coverage_complete !== true ||
      scope.exact_scope !== true
    ) {
      invalidScope('Pay-method preview did not return complete canonical coverage.', scope);
    }

    const targetedTimesheetIds = canonicalUuidArray(scope.targeted_timesheet_ids, 'targeted_timesheet_ids');
    const authorisedTimesheetIds = canonicalUuidArray(scope.authorised_timesheet_ids, 'authorised_timesheet_ids');
    const activeAdvanceTimesheetIds = canonicalUuidArray(scope.active_advance_timesheet_ids, 'active_advance_timesheet_ids');
    const retainedFinanceTimesheetIds = canonicalUuidArray(
      scope.retained_finance_timesheet_ids,
      'retained_finance_timesheet_ids'
    );
    const representedTimesheetIds = canonicalUuidArray(scope.represented_timesheet_ids, 'represented_timesheet_ids');
    const replacedSourceSessionIds = canonicalUuidArray(
      scope.replaced_source_session_ids,
      'replaced_source_session_ids',
      false
    );
    const expectedTargetIds = Array.from(new Set([
      ...authorisedTimesheetIds,
      ...activeAdvanceTimesheetIds,
      ...retainedFinanceTimesheetIds
    ])).sort();

    if (!arraysEqual(targetedTimesheetIds, expectedTargetIds)) {
      invalidScope('Pay-method preview target set does not equal the canonical authorised, active-Advance or retained-finance set.', {
        targeted_timesheet_ids: targetedTimesheetIds,
        expected_timesheet_ids: expectedTargetIds
      });
    }

    const sourceChangeSeq = nonNegativeInteger(
      scope.latest_source_change_seq ?? scope.source_change_seq ?? 0,
      'source_change_seq'
    );
    const authoritativeSessionCount = nonNegativeInteger(
      scope.authoritative_session_count ?? 0,
      'authoritative_session_count'
    );
    const previewRowCount = nonNegativeInteger(scope.preview_row_count ?? 0, 'preview_row_count');
    const representedTimesheetCount = nonNegativeInteger(scope.represented_timesheet_count ?? 0, 'represented_timesheet_count');
    const authorisedTimesheetCount = nonNegativeInteger(scope.authorised_timesheet_count ?? 0, 'authorised_timesheet_count');
    const activeAdvanceTimesheetCount = nonNegativeInteger(scope.active_advance_timesheet_count ?? 0, 'active_advance_timesheet_count');
    const retainedFinanceTimesheetCount = nonNegativeInteger(
      scope.retained_finance_timesheet_count ?? 0,
      'retained_finance_timesheet_count'
    );
    const targetedTimesheetCount = nonNegativeInteger(scope.targeted_timesheet_count ?? 0, 'targeted_timesheet_count');
    const sourceTargetMismatchCount = nonNegativeInteger(scope.source_target_mismatch_count ?? 0, 'source_target_mismatch_count');

    if (
      representedTimesheetCount !== representedTimesheetIds.length ||
      authorisedTimesheetCount !== authorisedTimesheetIds.length ||
      activeAdvanceTimesheetCount !== activeAdvanceTimesheetIds.length ||
      retainedFinanceTimesheetCount !== retainedFinanceTimesheetIds.length ||
      targetedTimesheetCount !== targetedTimesheetIds.length ||
      sourceTargetMismatchCount > targetedTimesheetIds.length ||
      Boolean(scope.targeted_scope_is_empty) !== (targetedTimesheetIds.length === 0)
    ) {
      invalidScope('Pay-method preview counts do not match the canonical UUID sets.', scope);
    }

    if (!Array.isArray(scope.authoritative_sessions)) {
      invalidScope('Pay-method preview did not return authoritative_sessions as an array.', scope);
    }
    const authoritativeSessions = scope.authoritative_sessions.map((session, index) => {
      if (!session || typeof session !== 'object' || Array.isArray(session)) {
        invalidScope('Pay-method preview returned an invalid authoritative session.', { index, session });
      }
      const sessionId = String(session.session_id || '').trim();
      const actorUserId = String(session.actor_user_id || '').trim();
      const payDate = String(session.pay_date || '').trim();
      const weekEndingCutoff = String(session.week_ending_cutoff || '').trim();
      const sessionVersion = Number(session.session_version);
      const sessionRepresentedIds = canonicalUuidArray(session.represented_timesheet_ids, `authoritative_sessions[${index}].represented_timesheet_ids`);
      const sessionQualifyingIds = canonicalUuidArray(session.qualifying_timesheet_ids, `authoritative_sessions[${index}].qualifying_timesheet_ids`);
      if (
        !uuidRe.test(sessionId) ||
        !uuidRe.test(actorUserId) ||
        !isoDateRe.test(payDate) ||
        !isoDateRe.test(weekEndingCutoff) ||
        !Number.isInteger(sessionVersion) ||
        sessionVersion < 1 ||
        !arraysEqual(sessionQualifyingIds, targetedTimesheetIds)
      ) {
        invalidScope('Pay-method preview returned inconsistent authoritative-session evidence.', { index, session });
      }
      return {
        ...session,
        session_id: sessionId,
        actor_user_id: actorUserId,
        pay_date: payDate,
        week_ending_cutoff: weekEndingCutoff,
        session_version: sessionVersion,
        represented_timesheet_ids: sessionRepresentedIds,
        qualifying_timesheet_ids: sessionQualifyingIds
      };
    });

    if (authoritativeSessionCount !== authoritativeSessions.length) {
      invalidScope('Pay-method preview authoritative-session count does not match its session evidence.', scope);
    }

    if (!Array.isArray(scope.target_details)) {
      invalidScope('Pay-method preview did not return target_details as an array.', scope);
    }
    const targetDetails = scope.target_details.map((detail, index) => {
      if (!detail || typeof detail !== 'object' || Array.isArray(detail)) {
        invalidScope('Pay-method preview returned an invalid target detail.', { index, detail });
      }
      const timesheetId = String(detail.timesheet_id || '').trim();
      if (!uuidRe.test(timesheetId)) {
        invalidScope('Pay-method preview returned an invalid target-detail Timesheet ID.', { index, detail });
      }
      return { ...detail, timesheet_id: timesheetId };
    });
    const targetDetailIds = Array.from(new Set(targetDetails.map((detail) => detail.timesheet_id))).sort();
    if (targetDetails.length !== targetedTimesheetIds.length || !arraysEqual(targetDetailIds, targetedTimesheetIds)) {
      invalidScope('Pay-method preview target details do not match its exact target set.', scope);
    }

    return withCORS(env, req, ok({
      ok: true,
      candidate_id: candidate.id,
      original_method: originalMethod,
      new_method: newMethod,
      expected_old_method: originalMethod,
      preview_source_change_seq: sourceChangeSeq,
      destination_patch: newMethod === 'UMBRELLA'
        ? { umbrella_id: effectiveUmbrellaId }
        : {},
      can_apply: blockers.length === 0,
      blockers,
      coverage_basis: 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY',
      coverage_complete: true,
      exact_scope: true,
      authoritative_sessions: authoritativeSessions,
      authoritative_session_count: authoritativeSessionCount,
      replaced_source_session_ids: replacedSourceSessionIds,
      represented_timesheet_ids: representedTimesheetIds,
      represented_timesheet_count: representedTimesheetCount,
      authorised_timesheet_ids: authorisedTimesheetIds,
      authorised_timesheet_count: authorisedTimesheetCount,
      active_advance_timesheet_ids: activeAdvanceTimesheetIds,
      active_advance_timesheet_count: activeAdvanceTimesheetCount,
      retained_finance_timesheet_ids: retainedFinanceTimesheetIds,
      retained_finance_timesheet_count: retainedFinanceTimesheetCount,
      targeted_timesheet_ids: targetedTimesheetIds,
      canonical_qualifying_timesheet_ids: targetedTimesheetIds,
      targeted_timesheet_count: targetedTimesheetCount,
      targeted_scope_is_empty: targetedTimesheetIds.length === 0,
      potential_case_resolution_timesheet_count: sourceTargetMismatchCount,
      target_details: targetDetails,
      preview_row_count: previewRowCount,
      contracts_changed: 0,
      contract_weeks_changed: 0,
      timesheets_changed: 0,
      rates_changed: 0,
      tsfin_repricing_rows: 0,
      prospective_only: true,
      source_records_mutated: false,
      policy_x_authority_scope: 'PRE_DRAFT_LIVE_TRUTH',
      policy_x_dirtying_only: true
    }));
  } catch (error) {
    console.error('[CAND][PAY-METHOD] preview failed', error);
    return withCORS(env, req, serverError('Failed to preview the candidate pay-method change'));
  }
}


// ─────────────────────────────────────────────────────────────────────────────
// Endpoint: POST /api/candidates/:id/pay-method-change
// ✅ NEW BEHAVIOUR (atomic):
// - Build a deterministic migration plan
// - Call DB RPC: candidate_pay_method_change_apply(...)
// - No direct PATCH/INSERT/DELETE to contracts/contract_weeks/timesheets/candidates here
// ─────────────────────────────────────────────────────────────────────────────

async function handleCandidatePayMethodChange(env, req, candidateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));
  if (!candidateId) return withCORS(env, req, badRequest('candidate_id required'));

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (!uuidRe.test(String(candidateId))) return withCORS(env, req, badRequest('candidate_id must be a valid UUID'));
  const jsonResponse = (status, payload) => withCORS(
    env,
    req,
    new Response(JSON.stringify(payload), {
      status,
      headers: { 'content-type': 'application/json' }
    })
  );
  const parseRpcCode = (error) => {
    const candidates = [
      error?.json?.message,
      error?.json?.details,
      error?.json?.hint,
      error?.body,
      error?.message
    ];
    const known = [
      'LEGACY_CONTRACT_MIGRATION_PLAN_REJECTED',
      'CANDIDATE_PAY_METHOD_CHANGE_ALREADY_APPLIED_OR_STALE',
      'CANDIDATE_PAY_METHOD_CHANGE_STALE_EXPECTED_METHOD',
      'CANDIDATE_PAY_METHOD_CHANGE_PREVIEW_STALE',
      'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_REQUIRED',
      'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_NOT_FOUND_OR_DISABLED',
      'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING',
      'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH',
      'CANDIDATE_PAY_METHOD_CHANGE_ADMIN_REQUIRED',
      'CANDIDATE_PAY_METHOD_CHANGE_PLAN_FIELDS_UNSUPPORTED',
      'CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_PATCH_INVALID',
      'CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_FIELDS_UNSUPPORTED',
      'CANDIDATE_PAY_METHOD_CHANGE_PAYE_BANK_FIELDS_NOT_ALLOWED_FOR_UMBRELLA',
      'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_ID_NOT_ALLOWED_FOR_PAYE',
      'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_ID_INVALID',
      'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_CONFLICT',
      'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_AUDIT_INVALID',
      'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_EXACT_SCOPE_PROOF_MISSING',
      'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_QUEUE_AUTHORITY_MISMATCH',
      'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_EXPECTED_SCOPE_INVALID',
      'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_QUEUE_SET_MISMATCH',
      'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_AUTHORITY_MISMATCH',
      'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE',
      'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID',
      'CANDIDATE_PAY_METHOD_CHANGE_POST_COMMIT_SCOPE_UNAVAILABLE',
      'CANDIDATE_PAY_METHOD_CHANGE_CANONICAL_SCOPE_CHANGED'
    ];
    const text = candidates.filter(Boolean).map(String).join(' ');
    return known.find((code) => text.includes(code)) || null;
  };
  const committedReplayProofCodes = new Set([
    'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_EXACT_SCOPE_PROOF_MISSING',
    'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_QUEUE_AUTHORITY_MISMATCH',
    'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_EXPECTED_SCOPE_INVALID',
    'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_QUEUE_SET_MISMATCH'
  ]);
  const canonicalUuidArray = (value, fieldName) => {
    if (!Array.isArray(value)) {
      const error = new Error(`${fieldName} must be an array.`);
      error.code = 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH';
      throw error;
    }
    const raw = value.map((entry) => String(entry == null ? '' : entry).trim());
    if (raw.some((entry) => !uuidRe.test(entry))) {
      const error = new Error(`${fieldName} contains an invalid UUID.`);
      error.code = 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH';
      throw error;
    }
    const canonical = Array.from(new Set(raw)).sort();
    if (canonical.length !== raw.length || raw.some((entry, index) => entry !== canonical[index])) {
      const error = new Error(`${fieldName} is not an exact sorted UUID set.`);
      error.code = 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH';
      throw error;
    }
    return canonical;
  };
  const arraysEqual = (left, right) => left.length === right.length && left.every((entry, index) => entry === right[index]);
  const nonNegativeInteger = (value, fieldName) => {
    if (
      typeof value !== 'number'
      || !Number.isFinite(value)
      || !Number.isInteger(value)
      || value < 0
    ) {
      const error = new Error(`${fieldName} must be a non-negative integer.`);
      error.code = 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH';
      throw error;
    }
    return value;
  };
  const readExactDurableProof = (result, options = {}) => {
    const superseded = options.superseded === true;
    const jobId = String(result.job_id || '').trim().toLowerCase();
    const jobStatus = String(result.job_status || '').trim().toUpperCase();
    const expectedIds = canonicalUuidArray(result.expected_targeted_timesheet_ids, 'expected_targeted_timesheet_ids');
    const persistedIds = canonicalUuidArray(result.persisted_targeted_timesheet_ids, 'persisted_targeted_timesheet_ids');
    const targetedIds = canonicalUuidArray(result.targeted_timesheet_ids, 'targeted_timesheet_ids');
    const missingIds = canonicalUuidArray(result.missing_targeted_timesheet_ids, 'missing_targeted_timesheet_ids');
    const extraIds = canonicalUuidArray(result.extra_targeted_timesheet_ids, 'extra_targeted_timesheet_ids');
    const authorisedIds = canonicalUuidArray(result.authorised_timesheet_ids, 'authorised_timesheet_ids');
    const activeAdvanceIds = canonicalUuidArray(result.active_advance_timesheet_ids, 'active_advance_timesheet_ids');
    const retainedFinanceIds = canonicalUuidArray(
      result.retained_finance_timesheet_ids,
      'retained_finance_timesheet_ids'
    );
    const canonicalQualifyingIds = Array.from(new Set([
      ...authorisedIds,
      ...activeAdvanceIds,
      ...retainedFinanceIds
    ])).sort();
    const targetedCount = nonNegativeInteger(result.targeted_timesheet_count, 'targeted_timesheet_count');
    const effectiveDuplicateCount = nonNegativeInteger(result.effective_duplicate_count, 'effective_duplicate_count');
    const invalidTargetCount = nonNegativeInteger(result.invalid_target_count, 'invalid_target_count');
    const sourceChangeSeq = nonNegativeInteger(result.source_change_seq, 'source_change_seq');
    const resultPreviewSourceChangeSeq = nonNegativeInteger(
      result.preview_source_change_seq,
      'preview_source_change_seq'
    );
    const currentJobStatuses = new Set(['QUEUED', 'RUNNING', 'SUCCEEDED']);
    const supersededJobStatuses = new Set(['QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'DEAD']);
    const refreshCompleted = result.refresh_completed === true;

    if (
      !uuidRe.test(jobId) ||
      !(superseded ? supersededJobStatuses : currentJobStatuses).has(jobStatus) ||
      String(result.coverage_basis || '').trim().toUpperCase() !== 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY' ||
      result.coverage_complete !== true ||
      result.exact_target_scope !== true ||
      result.exact_set_equality !== true ||
      result.refresh_accepted !== true ||
      effectiveDuplicateCount !== 0 ||
      invalidTargetCount !== 0 ||
      missingIds.length !== 0 ||
      extraIds.length !== 0 ||
      targetedCount !== targetedIds.length ||
      !arraysEqual(expectedIds, persistedIds) ||
      !arraysEqual(expectedIds, targetedIds) ||
      !arraysEqual(targetedIds, canonicalQualifyingIds) ||
      resultPreviewSourceChangeSeq !== previewSourceChangeSeq ||
      sourceChangeSeq <= previewSourceChangeSeq ||
      !Array.isArray(result.authoritative_sessions) ||
      (superseded ? refreshCompleted !== false : (jobStatus === 'SUCCEEDED') !== refreshCompleted)
    ) {
      const error = new Error('The committed candidate pay-method change did not return complete exact durable queue proof.');
      error.code = 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH';
      throw error;
    }

    return {
      operation_committed: true,
      operation_superseded_by_later_change: superseded,
      job_id: jobId,
      job_status: jobStatus,
      targeted_timesheet_ids: targetedIds,
      expected_targeted_timesheet_ids: expectedIds,
      persisted_targeted_timesheet_ids: persistedIds,
      authorised_timesheet_ids: authorisedIds,
      active_advance_timesheet_ids: activeAdvanceIds,
      retained_finance_timesheet_ids: retainedFinanceIds,
      source_change_seq: sourceChangeSeq,
      preview_source_change_seq: resultPreviewSourceChangeSeq,
      refresh_completed: refreshCompleted
    };
  };
  const isUncertainRpcFailure = (error, code) => {
    if (code) return false;

    const status = Number(error?.status);
    if (!Number.isFinite(status) || status <= 0) return true;
    if ([408, 425, 429, 499, 500, 502, 503, 504].includes(status)) return true;
    if (status >= 520 && status <= 526) return true;
    if (status >= 400 && status < 500) return false;

    const name = String(error?.name || '').trim().toLowerCase();
    const message = [
      error?.message,
      error?.body,
      error?.json?.message,
      error?.json?.details
    ].filter(Boolean).map(String).join(' ').toLowerCase();

    return name === 'aborterror'
      || name === 'timeouterror'
      || name === 'typeerror'
      || message.includes('timed out')
      || message.includes('timeout')
      || message.includes('network error')
      || message.includes('failed to fetch')
      || message.includes('fetch failed')
      || message.includes('connection reset')
      || message.includes('connection closed');
  };

  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    body = null;
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return withCORS(env, req, badRequest('Invalid JSON object'));
  }

  const legacyKeys = [
    'contract_ids',
    'contracts',
    'migrations',
    'successor_start',
    'successor_contract_id',
    'new_contract_id',
    'new_rates_json',
    'new_additional_rates_json',
    'rates_json',
    'timesheet_ids',
    'affected_timesheet_ids',
    'delete_old_contracts'
  ];
  const suppliedLegacyKeys = legacyKeys.filter((key) => Object.prototype.hasOwnProperty.call(body, key));
  if (suppliedLegacyKeys.length) {
    return jsonResponse(400, {
      error: 'Legacy contract-migration fields are not supported by the prospective-only pay-method change.',
      code: 'LEGACY_CONTRACT_MIGRATION_PLAN_REJECTED',
      unsupported_fields: suppliedLegacyKeys
    });
  }

  const allowedBodyKeys = new Set([
    'new_method',
    'expected_old_method',
    'operation_id',
    'preview_source_change_seq',
    'destination_patch',
    'reason'
  ]);
  const unsupportedBodyKeys = Object.keys(body).filter((key) => !allowedBodyKeys.has(key));
  if (unsupportedBodyKeys.length) {
    return jsonResponse(400, {
      error: 'The pay-method change request contains unsupported fields.',
      code: 'CANDIDATE_PAY_METHOD_CHANGE_PLAN_FIELDS_UNSUPPORTED',
      unsupported_fields: unsupportedBodyKeys
    });
  }

  const newMethod = String(body.new_method || '').trim().toUpperCase();
  const expectedOldMethod = String(body.expected_old_method || '').trim().toUpperCase();
  const operationId = String(body.operation_id || '').trim();
  const previewSourceChangeSeq = body.preview_source_change_seq;
  if (
    Object.prototype.hasOwnProperty.call(body, 'destination_patch')
    && (
      !body.destination_patch
      || typeof body.destination_patch !== 'object'
      || Array.isArray(body.destination_patch)
    )
  ) {
    return jsonResponse(400, {
      error: 'destination_patch must be a JSON object.',
      code: 'CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_PATCH_INVALID'
    });
  }
  const destinationPatch = body.destination_patch ? { ...body.destination_patch } : {};
  const reason = String(body.reason || 'PAY_METHOD_CHANGE').trim() || 'PAY_METHOD_CHANGE';

  if (newMethod !== 'PAYE' && newMethod !== 'UMBRELLA') {
    return withCORS(env, req, badRequest('new_method must be PAYE or UMBRELLA'));
  }
  if (expectedOldMethod !== 'PAYE' && expectedOldMethod !== 'UMBRELLA') {
    return withCORS(env, req, badRequest('expected_old_method must be PAYE or UMBRELLA'));
  }
  if (newMethod === expectedOldMethod) {
    return withCORS(env, req, badRequest('new_method must differ from expected_old_method'));
  }
  if (!uuidRe.test(operationId)) {
    return withCORS(env, req, badRequest('operation_id must be a valid UUID'));
  }
  if (
    typeof previewSourceChangeSeq !== 'number'
    || !Number.isFinite(previewSourceChangeSeq)
    || !Number.isInteger(previewSourceChangeSeq)
    || previewSourceChangeSeq < 0
  ) {
    return withCORS(env, req, badRequest('preview_source_change_seq must be a non-negative integer'));
  }

  const allowedDestinationKeys = new Set(['umbrella_id', 'account_holder', 'bank_name', 'sort_code', 'account_number']);
  const unsupportedDestinationKeys = Object.keys(destinationPatch).filter((key) => !allowedDestinationKeys.has(key));
  if (unsupportedDestinationKeys.length) {
    return jsonResponse(400, {
      error: 'destination_patch contains unsupported fields.',
      code: 'CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_FIELDS_UNSUPPORTED',
      unsupported_fields: unsupportedDestinationKeys
    });
  }
  if (newMethod === 'UMBRELLA') {
    const umbrellaId = String(destinationPatch.umbrella_id || '').trim();
    if (!uuidRe.test(umbrellaId)) {
      return withCORS(env, req, badRequest('A valid destination_patch.umbrella_id is required for UMBRELLA'));
    }
    if (['account_holder', 'bank_name', 'sort_code', 'account_number'].some((key) => Object.prototype.hasOwnProperty.call(destinationPatch, key))) {
      return withCORS(env, req, badRequest('PAYE bank fields cannot be changed as part of a switch to UMBRELLA'));
    }
  }

  let mutationAttempted = false;

  try {
    const currentCandidate = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?id=eq.${enc(candidateId)}` +
        `&select=id,pay_method,umbrella_id,updated_at,rev`
    );
    if (!currentCandidate) {
      return withCORS(env, req, notFound('Candidate not found'));
    }

    const currentMethod = String(currentCandidate.pay_method || '').trim().toUpperCase();
    if (currentMethod !== expectedOldMethod && currentMethod !== newMethod) {
      return jsonResponse(409, {
        error: 'The candidate payment method changed after the preview. Refresh and try again.',
        code: 'CANDIDATE_PAY_METHOD_CHANGE_STALE_EXPECTED_METHOD',
        expected_old_method: expectedOldMethod,
        current_method: currentMethod,
        operation_id: operationId
      });
    }

    let rpcResultRaw;
    try {
      mutationAttempted = true;
      rpcResultRaw = await sbRpc(
        env,
        'candidate_pay_method_change_apply',
        {
          p_candidate_id: currentCandidate.id,
          p_new_method: newMethod,
          p_plan: {
            operation_id: operationId,
            expected_old_method: expectedOldMethod,
            preview_source_change_seq: previewSourceChangeSeq,
            destination_patch: destinationPatch
          },
          p_actor_user_id: user.id,
          p_reason: reason
        },
        {
          routeClass: 'OPERATION_NUDGE',
          purpose: 'CANDIDATE_PAY_METHOD_CHANGE',
          timeoutMs: 8000
        }
      );
    } catch (rpcError) {
      const code = parseRpcCode(rpcError);
      if (isUncertainRpcFailure(rpcError, code)) {
        return jsonResponse(503, {
          error: 'The pay-method change outcome could not be confirmed. Do not submit a new operation; refresh using this operation ID.',
          code: 'CANDIDATE_PAY_METHOD_CHANGE_OUTCOME_UNKNOWN',
          candidate_id: currentCandidate.id,
          operation_id: operationId,
          refresh_required: true
        });
      }

      if (code === 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_AUDIT_INVALID') {
        return jsonResponse(503, {
          error: 'A previous operation audit exists, but its committed outcome cannot be reconciled safely. Do not submit a new operation; refresh using this operation ID.',
          code: 'CANDIDATE_PAY_METHOD_CHANGE_OUTCOME_UNKNOWN',
          candidate_id: currentCandidate.id,
          operation_id: operationId,
          refresh_required: true
        });
      }

      if (committedReplayProofCodes.has(code)) {
        return jsonResponse(503, {
          error: 'The operation committed previously, but its exact durable Banking Pay refresh proof cannot be reconciled safely. Do not submit a new operation; refresh using this operation ID.',
          code,
          candidate_id: currentCandidate.id,
          operation_id: operationId,
          operation_committed: true,
          original_method: expectedOldMethod,
          committed_method: newMethod,
          refresh_required: true
        });
      }

      const conflictCodes = new Set([
        'CANDIDATE_PAY_METHOD_CHANGE_ALREADY_APPLIED_OR_STALE',
        'CANDIDATE_PAY_METHOD_CHANGE_STALE_EXPECTED_METHOD',
        'CANDIDATE_PAY_METHOD_CHANGE_PREVIEW_STALE',
        'CANDIDATE_PAY_METHOD_CHANGE_CANONICAL_SCOPE_CHANGED',
        'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_CONFLICT'
      ]);
      const infrastructureCodes = new Set([
        'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING',
        'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_AUTHORITY_MISMATCH',
        'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH',
        'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE',
        'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID',
        'CANDIDATE_PAY_METHOD_CHANGE_POST_COMMIT_SCOPE_UNAVAILABLE'
      ]);
      const status = conflictCodes.has(code)
        ? 409
        : (code === 'CANDIDATE_PAY_METHOD_CHANGE_ADMIN_REQUIRED'
            ? 403
            : (infrastructureCodes.has(code) ? 503 : 400));
      const friendly = {
        LEGACY_CONTRACT_MIGRATION_PLAN_REJECTED: 'The client submitted an obsolete contract-migration request. Refresh the application and try again.',
        CANDIDATE_PAY_METHOD_CHANGE_ALREADY_APPLIED_OR_STALE: 'The candidate payment method has already changed under another operation. Refresh before continuing.',
        CANDIDATE_PAY_METHOD_CHANGE_STALE_EXPECTED_METHOD: 'The candidate payment method changed after the preview. Refresh and try again.',
        CANDIDATE_PAY_METHOD_CHANGE_PREVIEW_STALE: 'The Banking Pay preview changed after confirmation. Refresh the preview and confirm again.',
        CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_REQUIRED: 'Select an umbrella company before changing the candidate to UMBRELLA.',
        CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_NOT_FOUND_OR_DISABLED: 'The selected umbrella company is unavailable or disabled.',
        CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING: 'The candidate was not changed because durable Banking Pay refresh work could not be recorded.',
        CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH: 'The candidate was not changed because the exact Banking Pay refresh set could not be verified.',
        CANDIDATE_PAY_METHOD_CHANGE_ADMIN_REQUIRED: 'Administrator authority is required.',
        CANDIDATE_PAY_METHOD_CHANGE_PLAN_FIELDS_UNSUPPORTED: 'The request contains unsupported fields. Refresh the application and try again.',
        CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_PATCH_INVALID: 'The destination details must be supplied as a JSON object.',
        CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_FIELDS_UNSUPPORTED: 'The destination details contain unsupported fields.',
        CANDIDATE_PAY_METHOD_CHANGE_PAYE_BANK_FIELDS_NOT_ALLOWED_FOR_UMBRELLA: 'PAYE bank fields cannot be changed as part of a switch to UMBRELLA.',
        CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_ID_NOT_ALLOWED_FOR_PAYE: 'An umbrella company cannot be supplied when changing the candidate to PAYE.',
        CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_ID_INVALID: 'The selected umbrella company identifier is invalid.',
        CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_CONFLICT: 'This operation ID is already bound to a different pay-method change. Refresh and start a new confirmed operation.',
        CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_AUTHORITY_MISMATCH: 'The candidate was not changed because the durable Banking Pay job did not retain the required route-change authority.',
        CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE: 'The candidate was not changed because the canonical Banking Pay refresh scope could not be established.',
        CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID: 'The candidate was not changed because the canonical Banking Pay target scope was invalid.',
        CANDIDATE_PAY_METHOD_CHANGE_POST_COMMIT_SCOPE_UNAVAILABLE: 'The candidate was not changed because the canonical Banking Pay scope could not be revalidated.',
        CANDIDATE_PAY_METHOD_CHANGE_CANONICAL_SCOPE_CHANGED: 'The canonical Banking Pay scope changed after confirmation. Refresh the preview and confirm again.'
      };
      return jsonResponse(status, {
        error: friendly[code] || 'The pay-method change was rejected.',
        code: code || 'CANDIDATE_PAY_METHOD_CHANGE_FAILED',
        operation_id: operationId,
        refresh_required: status === 409 || status === 503
      });
    }

    const result = Array.isArray(rpcResultRaw) ? (rpcResultRaw[0] || null) : rpcResultRaw;
    if (!result || result.ok !== true) {
      return jsonResponse(503, {
        error: 'The pay-method change outcome could not be confirmed from the RPC response. Do not submit a new operation; refresh using this operation ID.',
        code: 'CANDIDATE_PAY_METHOD_CHANGE_OUTCOME_UNKNOWN',
        candidate_id: currentCandidate.id,
        operation_id: operationId,
        refresh_required: true
      });
    }

    const resultOperationId = String(result.operation_id || '').trim().toLowerCase();
    const resultCandidateId = String(result.candidate_id || '').trim().toLowerCase();
    const resultOriginalMethod = String(result.original_method || '').trim().toUpperCase();
    const resultNewMethod = String(result.new_method || '').trim().toUpperCase();
    const resultCurrentMethod = String(result.current_method || '').trim().toUpperCase();
    const committedOperationIdentityVerified = !!(
      result.operation_committed === true
      && resultOperationId === operationId.toLowerCase()
      && resultCandidateId === String(currentCandidate.id).trim().toLowerCase()
      && resultOriginalMethod === expectedOldMethod
      && resultNewMethod === newMethod
    );
    const committedCurrentOperationVerified = !!(
      committedOperationIdentityVerified
      && result.operation_superseded_by_later_change === false
      && resultCurrentMethod === newMethod
    );
    const committedSupersededOperationVerified = !!(
      committedOperationIdentityVerified
      && result.operation_superseded_by_later_change === true
      && (resultCurrentMethod === 'PAYE' || resultCurrentMethod === 'UMBRELLA')
    );

    const zeroMutationFields = ['contracts_changed', 'contract_weeks_changed', 'timesheets_changed', 'rates_changed', 'tsfin_repricing_rows'];
    const invalidMutationFields = zeroMutationFields.filter((key) => (
      !Object.prototype.hasOwnProperty.call(result, key)
      || typeof result[key] !== 'number'
      || !Number.isFinite(result[key])
      || result[key] !== 0
    ));
    if (invalidMutationFields.length) {
      console.error('[CAND][PAY-METHOD] prospective-only invariant failed', {
        candidateId,
        operationId,
        fields: invalidMutationFields,
        committedOperationIdentityVerified: committedCurrentOperationVerified
      });
      if (!committedCurrentOperationVerified) {
        return jsonResponse(503, {
          error: 'The pay-method change outcome could not be confirmed safely. Do not submit a new operation; refresh using this operation ID.',
          code: 'CANDIDATE_PAY_METHOD_CHANGE_OUTCOME_UNKNOWN',
          candidate_id: currentCandidate.id,
          operation_id: operationId,
          refresh_required: true
        });
      }
      return jsonResponse(500, {
        error: 'The committed operation returned an unsafe source-mutation result. The deployment must be reviewed; do not submit a new operation.',
        code: 'CANDIDATE_PAY_METHOD_CHANGE_SOURCE_MUTATION_ASSERTION_FAILED',
        candidate_id: currentCandidate.id,
        operation_id: operationId,
        operation_committed: true,
        operation_superseded_by_later_change: false,
        original_method: expectedOldMethod,
        committed_method: newMethod,
        fields: invalidMutationFields,
        refresh_required: true
      });
    }

    if (result.operation_superseded_by_later_change === true) {
      if (!committedSupersededOperationVerified) {
        return jsonResponse(503, {
          error: 'The pay-method change outcome could not be confirmed safely. Do not submit a new operation; refresh using this operation ID.',
          code: 'CANDIDATE_PAY_METHOD_CHANGE_OUTCOME_UNKNOWN',
          candidate_id: currentCandidate.id,
          operation_id: operationId,
          refresh_required: true
        });
      }
      try {
        readExactDurableProof(result, { superseded: true });
      } catch (proofError) {
        console.error('[CAND][PAY-METHOD] superseded operation proof failed', {
          candidateId,
          operationId,
          error: proofError?.message || proofError
        });
        return jsonResponse(503, {
          error: 'The superseded operation committed, but its exact durable Banking Pay proof could not be verified. Do not submit a new operation; refresh using this operation ID.',
          code: proofError?.code || 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH',
          candidate_id: currentCandidate.id,
          operation_id: operationId,
          operation_committed: true,
          original_method: expectedOldMethod,
          committed_method: newMethod,
          refresh_required: true
        });
      }
      return jsonResponse(409, {
        error: 'This operation committed previously, but a later pay-method change has superseded it. The earlier operation was not applied again.',
        code: 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_COMMITTED_SUPERSEDED',
        candidate_id: currentCandidate.id,
        operation_id: operationId,
        operation_committed: true,
        operation_superseded_by_later_change: true,
        original_method: expectedOldMethod,
        committed_method: newMethod,
        current_method: resultCurrentMethod,
        refresh_required: true
      });
    }

    let exactProof;
    try {
      if (!committedCurrentOperationVerified) {
        const identityError = new Error('The committed candidate pay-method change did not match the requested operation identity.');
        identityError.code = 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_PROOF_INVALID';
        throw identityError;
      }
      exactProof = readExactDurableProof(result, { superseded: false });
    } catch (proofError) {
      console.error('[CAND][PAY-METHOD] exact durable queue proof failed', {
        candidateId,
        operationId,
        error: proofError?.message || proofError,
        committedOperationIdentityVerified: committedCurrentOperationVerified
      });
      if (!committedCurrentOperationVerified) {
        return jsonResponse(503, {
          error: 'The pay-method change outcome could not be confirmed safely. Do not submit a new operation; refresh using this operation ID.',
          code: 'CANDIDATE_PAY_METHOD_CHANGE_OUTCOME_UNKNOWN',
          operation_id: operationId,
          refresh_required: true
        });
      }
      return jsonResponse(503, {
        error: 'The candidate pay-method change committed, but its exact durable Banking Pay refresh scope could not be verified. Do not submit a new operation; refresh using this operation ID.',
        code: proofError?.code || 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH',
        candidate_id: currentCandidate.id,
        operation_id: operationId,
        operation_committed: true,
        operation_superseded_by_later_change: false,
        original_method: expectedOldMethod,
        committed_method: newMethod,
        refresh_required: true
      });
    }

    let nudgeResult = null;
    if (exactProof.refresh_completed === true) {
      nudgeResult = {
        ok: true,
        scheduled: false,
        skipped: true,
        code: 'BANKING_PAY_WORKBENCH_ALREADY_COMPLETE'
      };
    } else {
      try {
        nudgeResult = nudgeBankingPayWorkbenchDrain(env, null, {
          origin: 'CANDIDATE_PAY_METHOD_CHANGE',
          candidateId: currentCandidate.id,
          candidate_id: currentCandidate.id,
          operationId,
          operation_id: operationId,
          priorityClass: 'DIRTY_TRIGGER_PRIORITY'
        });
      } catch (nudgeError) {
        console.warn('[CAND][PAY-METHOD] Workbench nudge failed; durable work remains queued', nudgeError?.message || nudgeError);
        nudgeResult = {
          ok: false,
          scheduled: false,
          code: 'BANKING_PAY_WORKBENCH_NUDGE_FAILED',
          message: String(nudgeError?.message || nudgeError || 'Workbench nudge failed')
        };
      }
    }

    return withCORS(env, req, ok({
      ...result,
      ...exactProof,
      current_method: newMethod,
      refresh_accepted: true,
      refresh_completed: exactProof.refresh_completed === true,
      refresh_pending: exactProof.refresh_completed !== true,
      refreshing: exactProof.refresh_completed !== true,
      nudge_result: nudgeResult,
      nudge_failed_non_fatal: nudgeResult?.ok === false,
      durable_queue_retained: true
    }));
  } catch (error) {
    console.error('[CAND][PAY-METHOD] apply failed', error);
    if (mutationAttempted) {
      return jsonResponse(503, {
        error: 'The pay-method change outcome could not be confirmed. Do not submit a new operation; refresh using this operation ID.',
        code: 'CANDIDATE_PAY_METHOD_CHANGE_OUTCOME_UNKNOWN',
        operation_id: operationId,
        refresh_required: true
      });
    }
    return withCORS(env, req, serverError('Failed to change the candidate payment method'));
  }
}



async function computeBucketRatesPreservingMargin(env, oldMethod, newMethod, oldRates) {
  const srcMethod = String(oldMethod || '').toUpperCase();
  const dstMethod = String(newMethod || '').toUpperCase();

  // Defensive clone + normalisation
  let base = oldRates || {};
  if (typeof base === 'string') {
    try { base = JSON.parse(base); } catch { base = {}; }
  }
  if (!base || typeof base !== 'object') base = {};

  const out = { ...base };

  // ─────────────────────────────────────────────────────────────
  // Fetch ERNI from finance windows (in-scope) via single RPC helper
  // (cached by loadFinanceGlobals to minimise subcalls)
  // ─────────────────────────────────────────────────────────────
  let erniMult = 1;
  try {
    const fin = await loadFinanceGlobals(env, null); // null => explicit "today London" in helper
    let pct = fin && fin.erni_pct != null ? Number(fin.erni_pct) : 0;

    // Support "15" vs "0.15" semantics like elsewhere:
    // if > 1 we treat as a percentage (e.g. 15 → 0.15)
    if (!Number.isFinite(pct)) pct = 0;
    if (pct > 1) pct = pct / 100;

    erniMult = 1 + pct;  // ERNI_MULT = 1 + erni_pct
    if (!Number.isFinite(erniMult) || erniMult <= 0) erniMult = 1;
  } catch (e) {
    try { console.warn('[RATES] computeBucketRatesPreservingMargin: failed to load ERNI from finance windows, defaulting to 1', e); } catch {}
    erniMult = 1;
  }

  const buckets = ['day', 'night', 'sat', 'sun', 'bh'];

  const toNumOrNull = (v) => {
    if (v === null || v === undefined || v === '') return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };

  for (const b of buckets) {
    const chargeKey  = `charge_${b}`;
    const payPayeKey = `paye_${b}`;
    const payUmbKey  = `umb_${b}`;

    const charge = toNumOrNull(base[chargeKey]);
    if (charge == null) continue;

    const payOld =
      (srcMethod === 'PAYE')
        ? toNumOrNull(base[payPayeKey])
        : (srcMethod === 'UMBRELLA')
          ? toNumOrNull(base[payUmbKey])
          : null;

    // If we don’t have a valid old pay, we can’t preserve margin for this bucket.
    if (payOld == null) continue;

    // Compute margin under the original method
    let margin;
    if (srcMethod === 'PAYE') {
      // Margin(PAYE) = charge - pay * ERNI_MULT
      margin = charge - (payOld * erniMult);
    } else {
      // Margin(Umbrella) = charge - pay
      margin = charge - payOld;
    }

    // Derive new pay keeping margin constant
    let payNew;
    if (dstMethod === 'PAYE') {
      // New PAYE pay = (charge - margin) / ERNI_MULT
      payNew = (charge - margin) / erniMult;
    } else {
      // New Umbrella pay = charge - margin
      payNew = charge - margin;
    }

    if (!Number.isFinite(payNew)) continue;

    // Round to 2dp like elsewhere in the system
    const rounded = +(+payNew).toFixed(2);

    if (dstMethod === 'PAYE') {
      out[payPayeKey] = rounded;
    } else {
      out[payUmbKey] = rounded;
    }
  }

  return out;
}
// ─────────────────────────────────────────────────────────────────────────────
// Helper: computeBucketRatesPreservingMargin
// Given an existing rates_json and a PAYE↔UMBRELLA flip, compute new pay buckets
// so that per-bucket margin is preserved.
//
// oldMethod: 'PAYE' | 'UMBRELLA'
// newMethod: 'PAYE' | 'UMBRELLA'
// oldRates:  the existing rates_json (object or JSON string) with:
//            charge_day/night/sat/sun/bh and paye_*/umb_*
// erniMult:  numeric ERNI multiplier (1 + erni_pct). If invalid, falls back to 1.
//
// Returns: a NEW object (cloned from oldRates) with updated paye_* or umb_* buckets
//          for the newMethod; charges and the other method’s buckets are left as-is.
// ─────────────────────────────────────────────────────────────────────────────
// Compute new PAYE/UMBRELLA pay buckets so that per-bucket margin is preserved,
// always using the current ERNI percentage from settings_defaults.
//
// - oldMethod: 'PAYE' | 'UMBRELLA'
// - newMethod: 'PAYE' | 'UMBRELLA'
// - oldRates:  the existing rates_json (object or JSON string) with
//              charge_day/night/sat/sun/bh and paye_*/umb_*
//
// Returns: a NEW object cloned from oldRates with updated paye_* or umb_*
//          buckets for the new method. Charges and the other method’s buckets
//          are left as-is.
//
// NOTE: This helper is async because it fetches erni_pct from settings_defaults.
//


// ─────────────────────────────────────────────────────────────────────────────
// Helper: enqueueTsfinRecomputeForTimesheets
// Bulk-enqueue TSFIN recomputes for a list of timesheet IDs into ts_financials_outbox.
//
// timesheetIds: array of timesheet_id values
// reason:       string reason, e.g. 'RATE_CHANGED' (default)
//
// Uses the same pattern as enqueueTsfinRecomputeForClient / enqueueManualTsfinRecalc:
// inserts into ts_financials_outbox with on_conflict=timesheet_id,reason and
// Prefer: resolution=ignore-duplicates.
// ─────────────────────────────────────────────────────────────────────────────
async function enqueueTsfinRecomputeForTimesheets(env, timesheetIds, reason = 'RATE_CHANGED') {
  const ids = Array.isArray(timesheetIds)
    ? Array.from(new Set(timesheetIds.map(String).filter(Boolean)))
    : [];
  if (!ids.length) return;

  const now = nowIso();
  const rows = ids.map(tsid => ({
    timesheet_id: tsid,
    reason,
    attempt_count: 0,
    next_attempt_at: now,
    last_error: null,
    created_at: now
  }));

  try {
    await fetch(
      `${env.SUPABASE_URL}/rest/v1/ts_financials_outbox?on_conflict=timesheet_id,reason`,
      {
        method: 'POST',
        headers: { ...sbHeaders(env), Prefer: 'resolution=ignore-duplicates' },
        body: JSON.stringify(rows)
      }
    );
  } catch (e) {
    // best-effort; log but don't throw
    try { console.warn('[TSFIN][enqueue] enqueueTsfinRecomputeForTimesheets failed', e); } catch {}
  }
}
























async function enqueueTsfinRecomputeForClient(env, client_id) {
  try {
    const urlList =
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?select=timesheet_id` +
      `&client_id=eq.${encodeURIComponent(client_id)}` +
      `&is_current=eq.true` +
      `&locked_by_invoice_id=is.null`;
    const { rows: tsfins } = await sbFetch(env, urlList);
    if (tsfins && tsfins.length) {
      const now = nowIso();
      const items = tsfins.map(r => ({
        timesheet_id: r.timesheet_id,
        reason: 'RATE_CHANGED',
        attempt_count: 0,
        next_attempt_at: now,
        last_error: null,
        created_at: now,
      }));
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/ts_financials_outbox?on_conflict=timesheet_id,reason`,
        {
          method: "POST",
          headers: { ...sbHeaders(env), "Prefer": "resolution=ignore-duplicates" },
          body: JSON.stringify(items)
        }
      );
    }
  } catch (_) { /* non-fatal */ }
}

// Finds READY_FOR_INVOICE snapshots for contracts with auto_invoice=true,
// groups by client, creates HOURS-only invoices and immediately issues them.
// Finds READY_FOR_INVOICE snapshots for contracts with auto_invoice=true,
// groups by client, creates HOURS-only invoices and immediately issues them.

async function runAutoInvoiceCycle(env) {
  try {
    // ENV defaults (may be overridden by DB-driven inv_effective)
    let invMaxBatches   = parseInt(env.INVOICE_MAX_BATCHES || '10', 10);
    let invBatchSize    = parseInt(env.INVOICE_BATCH_SIZE  || '10', 10);
    let groupEnqLimit   = parseInt(env.INVOICE_ENQUEUE_LIMIT || '500', 10);

    // Optional: allow caller to bypass enqueue step (default true)
    const invEnqueueFirst = String(env.INVOICE_ENQUEUE_FIRST || 'true').toLowerCase() !== 'false';

    // Actor for audit (optional)
    const invActorUserId  = (env.INVOICE_ACTOR_USER_ID && String(env.INVOICE_ACTOR_USER_ID).trim())
      ? String(env.INVOICE_ACTOR_USER_ID).trim()
      : null;

    const _rowsLocal = (v) => {
      if (Array.isArray(v)) return v;
      if (v && Array.isArray(v.rows)) return v.rows;
      if (v && Array.isArray(v.data)) return v.data;
      return [];
    };

    const _clampInt = (n, lo, hi, dflt) => {
      const x = Number(n);
      if (!Number.isFinite(x)) return dflt;
      const y = Math.trunc(x);
      if (y < lo) return lo;
      if (y > hi) return hi;
      return y;
    };

    // DB-driven throttles (import_config_json.inv_effective), with safe fallbacks
    try {
      const s = await loadSettingsDefaults(env);
      const invCfg = (s && s.importConfig && s.importConfig.inv_effective && typeof s.importConfig.inv_effective === 'object')
        ? s.importConfig.inv_effective
        : null;

      if (invCfg) {
        invMaxBatches = _clampInt(invCfg.worker?.max_batches, 1, 50, invMaxBatches);
        invBatchSize  = _clampInt(invCfg.worker?.dequeue_limit, 1, 500, invBatchSize);
        groupEnqLimit = _clampInt(invCfg.autoinvoice?.enqueue_group_limit, 1, 5000, groupEnqLimit);
      }
    } catch {
      // ignore; keep env defaults
    }

    const enqueueAutoInvoiceGroupsOnce = async () => {
      const runId = (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function')
        ? globalThis.crypto.randomUUID()
        : `${Date.now()}-${Math.random().toString(16).slice(2)}`;

      let groups = [];
      try {
        const gRes = await sbRpc(env, 'invoice_autoinvoice_candidate_groups', { p_limit: groupEnqLimit });
        groups = _rowsLocal(gRes);
      } catch (e) {
        console.warn('[runAutoInvoiceCycle] invoice_autoinvoice_candidate_groups failed:', e?.message || e);
        groups = [];
      }

      if (!groups.length) return;

      for (const g of groups) {
        const clientId = g?.client_id ? String(g.client_id) : null;
        const weekStart = g?.invoice_week_start ? String(g.invoice_week_start) : null;
        if (!clientId || !weekStart) continue;

        try {
          await sbRpc(env, 'invoice_outbox_enqueue_by_week', {
            p_client_id: clientId,
            p_invoice_week_start: weekStart,
            p_actor_user_id: invActorUserId,
            p_allow_early: false,            // ✅ enforced: auto-invoice never allow-early
            p_meta: {
              source: 'AUTO_INVOICE_CYCLE',
              run_id: runId,
              run_at_utc: new Date().toISOString()
            },
            p_timesheet_ids: null,           // ✅ cohort mode: canonical gate selects eligible ids
            p_auto_invoice_only: true        // ✅ auto-invoice only
          });
        } catch (e) {
          console.warn('[runAutoInvoiceCycle] invoice_outbox_enqueue_by_week failed:', {
            client_id: clientId,
            invoice_week_start: weekStart,
            err: e?.message || String(e)
          });
        }
      }
    };

    for (let i = 0; i < invMaxBatches; i++) {
      // 1) enqueue auto-invoice work using canonical gate (no selector RPC; no allow-early)
      if (invEnqueueFirst) {
        await enqueueAutoInvoiceGroupsOnce();
      }

      // 2) dequeue
      const dq = await sbRpc(env, 'invoice_dequeue_batch_ids', { p_limit: invBatchSize });
      const jobs = _rowsLocal(dq);
      if (!jobs.length) break;

      const outboxIds = jobs.map(r => r?.outbox_id).filter(Boolean);
      if (!outboxIds.length) break;

      // 3) generate (NO issuing here; issuing happens when emailing)
      await sbRpc(env, 'invoice_generate_from_outbox_batch', {
        p_outbox_ids: outboxIds,
        p_actor_user_id: invActorUserId
      });

      if (jobs.length < invBatchSize) break;
    }
  } catch (e) {
    console.warn('runAutoInvoiceCycle failed:', e?.message || e);
  }
}



// ─────────────────────────────────────────────────────────────────────────────
// Overrides: list by CLIENT (now supports optional rate_type filter)
// ─────────────────────────────────────────────────────────────────────────────
async function handleListOverridesByClient(env, req, clientId) {
  const user = await requireUser(env, req, ["admin"]);
  if (!user) return withCORS(env, req, unauthorized());

  const sp      = new URL(req.url).searchParams;
  const cid     = clientId || sp.get("client_id");
  const role    = sp.get("role");
  const band    = sp.get("band");
  const on      = sp.get("active_on");
  const rateType = sp.get("rate_type"); // optional filter
  const limit   = Math.min(Math.max(parseInt(sp.get('limit')  || '100', 10) || 100, 1), 500);
  const offset  = Math.max(parseInt(sp.get('offset') || '0',   10) || 0, 0);

  if (!cid) return withCORS(env, req, badRequest("client_id required"));

  try {
    let q = `${env.SUPABASE_URL}/rest/v1/rates_candidate_overrides` +
            `?select=*,candidate:candidates(id,display_name)` +
            `&client_id=eq.${encodeURIComponent(cid)}`;

    if (rateType) q += `&rate_type=eq.${encodeURIComponent(rateType)}`;

    const andParts = [];
    if (role) andParts.push(`or(role.eq.${encodeURIComponent(role)},role.is.null)`);
    if (band) andParts.push(`or(band.eq.${encodeURIComponent(band)},band.is.null)`);
    if (on) {
      andParts.push(`date_from=lte.${encodeURIComponent(on)}`);
      andParts.push(`or(date_to.gte.${encodeURIComponent(on)},date_to.is.null)`);
    }
    if (andParts.length) q += `&and=(${andParts.join(',')})`;

    q += `&order=date_from.desc,client_id.nullslast,role.nullslast,band.nullslast&limit=${limit}&offset=${offset}`;

    const { rows } = await sbFetch(env, q);

    const items = rows.map(r => ({
      ...r,
      candidate_name: r.candidate ? r.candidate.display_name : null
    }));

    return withCORS(env, req, ok({ items }));
  } catch {
    return withCORS(env, req, serverError("Failed to fetch candidate overrides for client"));
  }
}


