// ---------------------------
// Shared type mirrors
// ---------------------------
/** @typedef {'NEW_AUTHORISED'|'VERSION_ROTATED'|'REVOKED'|'RATE_CHANGED'|'POLICY_CHANGED'|'CONTEXT_CHANGED'|'MANUAL'} TsFinReason */
/** @typedef {'UNASSIGNED'|'ASSIGNED'} CandidateAssignment */
/** @typedef {'UNASSIGNED'|'CLIENT_UNRESOLVED'|'RATE_MISSING'|'PAY_CHANNEL_MISSING'|'READY_FOR_HR'|'READY_FOR_INVOICE'} ProcessingStatus */
/** @typedef {'PAYE'|'UMBRELLA'} PayMethod */

// ---------------------------
// Minimal helpers (reuse your base ones if present)
// ---------------------------

function asNumber(x, d = 0) {
  if (x === null || x === undefined) return d;
  const n = typeof x === 'number' ? x : Number(x);
  return Number.isFinite(n) ? n : d;
}

// Alias used throughout TSFIN maths
function asNumberLocal(x, d = 0) {
  return asNumber(x, d);
}


function ymd(iso) {
  const d = new Date(iso);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const da = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${da}`;
}

// --- Basic UK DST handling (same style as your base file) ---
function isBSTLocal(ymdStr) {
  const [y, m, d] = ymdStr.split('-').map(Number);
  const lastSunday = (year, month) => {
    const dt = new Date(Date.UTC(year, month, 0));
    const dow = dt.getUTCDay();
    dt.setUTCDate(dt.getUTCDate() - dow);
    return dt.getUTCDate();
  };
  const lastSunMar = lastSunday(y, 3);
  const lastSunOct = lastSunday(y, 10);
  const n = Date.UTC(y, m - 1, d);
  const bstStart = Date.UTC(y, 2, lastSunMar, 1);
  const bstEnd = Date.UTC(y, 9, lastSunOct, 1);
  return n >= bstStart && n < bstEnd;
}

function toLocalParts(iso, tz) {
  const tzRaw = (tz == null || String(tz).trim() === '') ? 'Europe/London' : String(tz).trim();
  const tzEff = (tzRaw === 'Europe/London') ? 'Europe/London' : 'UTC';

  const dt = new Date(iso);
  if (!Number.isFinite(dt.getTime())) {
    return {
      ymd: '',
      year: null,
      month: null,
      day: null,
      hh: 0,
      mm: 0,
      hm: '00:00',
      hhmm: '00:00',
      hhmm_local: '00:00',
      hm_local: '00:00',
      tz: tzEff
    };
  }

  if (tzEff !== 'Europe/London') {
    const year = dt.getUTCFullYear();
    const month = dt.getUTCMonth() + 1;
    const day = dt.getUTCDate();
    const hh = dt.getUTCHours();
    const mm = dt.getUTCMinutes();
    const hhStr = String(hh).padStart(2, '0');
    const mmStr = String(mm).padStart(2, '0');
    const hhmm = `${hhStr}:${mmStr}`;

    return {
      ymd: `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
      year,
      month,
      day,
      hh,
      mm,
      hm: hhmm,
      hhmm,
      hhmm_local: hhmm,
      hm_local: hhmm,
      tz: tzEff
    };
  }

  const formatter = toLocalParts._formatterLondon || (toLocalParts._formatterLondon = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    hourCycle: 'h23'
  }));

  const parts = formatter.formatToParts(dt);
  const year  = Number(parts.find((p) => p.type === 'year')?.value || NaN);
  const month = Number(parts.find((p) => p.type === 'month')?.value || NaN);
  const day   = Number(parts.find((p) => p.type === 'day')?.value || NaN);
  let hhStr   = parts.find((p) => p.type === 'hour')?.value || '00';
  const mmStr = parts.find((p) => p.type === 'minute')?.value || '00';

  if (hhStr === '24') hhStr = '00';

  const hh = Number(hhStr);
  const mm = Number(mmStr);
  const hhmm = `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;

  return {
    ymd: `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
    year,
    month,
    day,
    hh,
    mm,
    hm: hhmm,
    hhmm,
    hhmm_local: hhmm,
    hm_local: hhmm,
    tz: tzEff
  };
}
// ---------------------------
// Supabase helpers (RPC + REST)
// ---------------------------

// === REPLACE: sbFetch (supports GET + POST/PATCH/DELETE + optional exact count)
// BACKEND — UPDATED
// sbFetch: now supports init (POST/PATCH/DELETE) and optional exact count. (UPDATED, not new)
async function sbFetch(env, url, third, fourth) {
  let includeCount = false;
  let init = {};

  if (typeof third === 'boolean') {
    includeCount = third;
  } else if (third && typeof third === 'object') {
    const { preferExactCount, ...rest } = third;
    if (typeof preferExactCount === 'boolean') includeCount = preferExactCount;
    init = { ...rest };
  }

  if (fourth && typeof fourth === 'object') {
    init = { ...init, ...fourth };
  }

  const requestedTimeoutMs = Number.isFinite(Number(init.timeoutMs)) && Number(init.timeoutMs) > 0
    ? Math.trunc(Number(init.timeoutMs))
    : null;
  const callerSignal = init.signal;
  const controller = requestedTimeoutMs && !callerSignal ? new AbortController() : null;
  const timeoutHandle = controller
    ? setTimeout(() => {
        try { controller.abort(new Error(`Supabase fetch timed out after ${requestedTimeoutMs}ms`)); } catch {}
      }, requestedTimeoutMs)
    : null;
  delete init.timeoutMs;
  if (controller) init.signal = controller.signal;

  const callerPrefer = init.headers && (init.headers.Prefer || init.headers['Prefer']);
  const headers = {
    ...sbHeaders(env),
    ...(callerPrefer ? {} : (includeCount ? { Prefer: 'count=exact' } : {})),
    ...(init.headers || {})
  };

  let res;
  let text;
  try {
    res = await fetch(url, { ...init, headers });
    text = await res.text();
  } catch (error) {
    if (controller?.signal.aborted) {
      const timeoutError = new Error(`Supabase fetch timed out after ${requestedTimeoutMs}ms`);
      timeoutError.status = 408;
      timeoutError.code = 'SUPABASE_FETCH_TIMEOUT';
      throw timeoutError;
    }
    throw error;
  } finally {
    if (timeoutHandle) clearTimeout(timeoutHandle);
  }

  let json;
  try { json = text ? JSON.parse(text) : null; } catch { json = null; }

  if (!res.ok) throw new Error(`Supabase fetch failed ${res.status}: ${text}`);

  let rows;
  if (Array.isArray(json)) rows = json;
  else if (json === null) rows = [];
  else if (typeof json === 'object' && Array.isArray(json.rows)) rows = json.rows;
  else rows = [json];

  const cr = res.headers.get('content-range');
  const m = cr && /\/(\d+)$/.exec(cr);
  const total = m ? parseInt(m[1], 10) : undefined;

  return { rows, total };
}

async function sbRpc(env, fn, args, opts) {
  const options = (opts && typeof opts === 'object' && !Array.isArray(opts)) ? opts : {};
  const fnText = String(fn || '').trim();
  const routeClassRaw = String(options.routeClass || options.bankingPayRouteClass || options.payRouteClass || '').trim().toUpperCase();
  const purposeRaw = String(options.purpose || options.bankingPayPurpose || '').trim().toUpperCase();
  const bankingPayFunctionRouteClasses = new Map([
    ['pay_batches_list', 'DISPLAY'],
    ['pay_batch_get', 'BATCH_BOOTSTRAP'],
    ['pay_batch_get_section_page', 'OVERVIEW_SECTION'],
    ['rpc_changes_ping', 'CHANGES_PING'],
    ['banking_pay_batch_watch_signal', 'WATCH_SIGNAL'],
    ['pay_workbench_session_open', 'PREVIEW_OPEN'],
    ['pay_workbench_session_get_progress', 'PREVIEW_PROGRESS'],
    ['pay_workbench_session_get_preview', 'PREVIEW_PROGRESS'],
    ['pay_workbench_session_get_preview_page', 'PREVIEW_PAGE'],
    ['pay_workbench_session_get_candidate_preview', 'PREVIEW_PAGE'],
    ['pay_workbench_session_seed_scope_chunk', 'PREVIEW_CHUNK'],
    ['pay_workbench_candidate_line_work_seed', 'PREVIEW_CHUNK'],
    ['pay_workbench_candidate_line_work_process_chunk', 'PREVIEW_CHUNK'],
    ['pay_workbench_preview_rows_materialise_chunk', 'PREVIEW_CHUNK'],
    ['pay_workbench_preview_rows_materialize_chunk', 'PREVIEW_CHUNK'],
    ['pay_workbench_claim_due_jobs', 'PREVIEW_CHUNK'],
    ['pay_workbench_complete_job', 'PREVIEW_CHUNK'],
    ['pay_workbench_fail_job', 'PREVIEW_CHUNK'],
    ['pay_execute_bank', 'OPERATION_NUDGE'],
    ['banking_pay_operation_get', 'OPERATION_GET'],
    ['pay_execute_bank_transfer_scope_seed', 'OPERATION_WORKER_ADVANCE'],
    ['pay_execute_bank_transfer_scope_items_seed_chunk', 'OPERATION_WORKER_ADVANCE'],
    ['pay_execute_bank_transfer_scope_rollup_chunk', 'OPERATION_WORKER_ADVANCE'],
    ['banking_pay_operation_seed_chunks', 'OPERATION_WORKER_ADVANCE'],
    ['pay_execute_bank_transfer_chunk_prepare', 'OPERATION_WORKER_ADVANCE'],
    ['pay_bank_transfers_claim_provider_submit_chunk', 'OPERATION_WORKER_CLAIM'],
    ['pay_provider_submit_chunk_stage_record', 'OPERATION_PROGRESS_SAVE'],
    ['banking_pay_operation_provider_attempt_record', 'OPERATION_PROGRESS_SAVE'],
    ['pay_provider_submit_chunk_diagnostic_finalise', 'OPERATION_WORKER_ADVANCE'],
    ['pay_bank_transfers_apply_rail_updates', 'OPERATION_WORKER_ADVANCE'],
    ['pay_execute_operation_cleanup_failed_local_artifacts', 'OPERATION_WORKER_ADVANCE'],
    ['pay_execute_provider_submit_review_resolve', 'EXPLICIT_DIAGNOSTIC'],
    ['pay_batch_prepare', 'OPERATION_WORKER_ADVANCE'],
    ['pay_batch_auth_start', 'OPERATION_WORKER_ADVANCE'],
    ['pay_batch_schedule', 'OPERATION_WORKER_ADVANCE']
  ]);
  const inferredRouteClass = bankingPayFunctionRouteClasses.get(fnText) || '';
  const effectiveRouteClass = routeClassRaw || inferredRouteClass;
  const bankingPayRouteClasses = new Set([
    'DISPLAY',
    'PREVIEW_OPEN',
    'PREVIEW_PROGRESS',
    'PREVIEW_PAGE',
    'PREVIEW_CHUNK',
    'BATCH_BOOTSTRAP',
    'OVERVIEW_SECTION',
    'CHANGES_PING',
    'WATCH_SIGNAL',
    'OPERATION_PROGRESS',
    'OPERATION_GET',
    'OPERATION_NUDGE',
    'OPERATION_WORKER_CLAIM',
    'OPERATION_WORKER_ADVANCE',
    'OPERATION_PROGRESS_SAVE',
    'EXECUTION_COORDINATOR',
    'EXPLICIT_DIAGNOSTIC'
  ]);
  const shortRouteClasses = new Set([
    'DISPLAY',
    'PREVIEW_OPEN',
    'PREVIEW_PROGRESS',
    'PREVIEW_PAGE',
    'BATCH_BOOTSTRAP',
    'OVERVIEW_SECTION',
    'CHANGES_PING',
    'WATCH_SIGNAL',
    'OPERATION_PROGRESS',
    'OPERATION_GET',
    'OPERATION_NUDGE'
  ]);
  const workerRouteClasses = new Set([
    'PREVIEW_CHUNK',
    'OPERATION_WORKER_CLAIM',
    'OPERATION_WORKER_ADVANCE',
    'OPERATION_PROGRESS_SAVE',
    'EXECUTION_COORDINATOR'
  ]);
  const diagnosticRoute = effectiveRouteClass === 'EXPLICIT_DIAGNOSTIC' || purposeRaw === 'EXPLICIT_DIAGNOSTIC' || purposeRaw === 'DIAGNOSTIC';
  const isBankingPayRoute = bankingPayRouteClasses.has(effectiveRouteClass) || effectiveRouteClass.startsWith('BANKING_PAY_') || options.bankingPay === true || bankingPayFunctionRouteClasses.has(fnText);

  let defaultTimeoutMs = null;
  if (shortRouteClasses.has(effectiveRouteClass)) defaultTimeoutMs = 8000;
  else if (workerRouteClasses.has(effectiveRouteClass)) defaultTimeoutMs = 30000;
  else if (diagnosticRoute) defaultTimeoutMs = 60000;

  const requestedTimeoutMs =
    (Number.isFinite(Number(options.timeoutMs)) && Number(options.timeoutMs) > 0)
      ? Math.trunc(Number(options.timeoutMs))
      : null;
  const maxBankingPayTimeoutMs = shortRouteClasses.has(effectiveRouteClass)
    ? 8000
    : (workerRouteClasses.has(effectiveRouteClass) ? 30000 : (diagnosticRoute ? 60000 : null));
  let timeoutMs = requestedTimeoutMs ?? defaultTimeoutMs;
  if (isBankingPayRoute && maxBankingPayTimeoutMs != null && timeoutMs != null) {
    timeoutMs = Math.min(timeoutMs, maxBankingPayTimeoutMs);
  }

  const url = `${env.SUPABASE_URL}/rest/v1/rpc/${encodeURIComponent(fnText)}`;
  const controller = timeoutMs ? new AbortController() : null;
  const t = timeoutMs ? setTimeout(() => {
    try { controller.abort(new Error(`RPC ${fnText} timed out after ${timeoutMs}ms`)); } catch {}
  }, timeoutMs) : null;

  let res;
  let txt = '';
  let json = null;
  let authRefreshRetried = false;
  const maxAttempts = options.allowAuthRefreshRetry === true ? 2 : 1;

  try {
    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      res = await fetch(url, {
        method: 'POST',
        headers: {
          ...sbHeaders(env),
          ...(options.prefer ? { Prefer: String(options.prefer) } : {}),
          ...(isBankingPayRoute ? { 'X-CloudTMS-Banking-Pay-Route-Class': effectiveRouteClass || 'BANKING_PAY' } : {})
        },
        body: JSON.stringify(args || {}),
        signal: controller ? controller.signal : undefined
      });

      txt = await res.text().catch(() => '');
      try { json = txt ? JSON.parse(txt) : null; } catch { json = null; }

      if ((res.status === 401 || res.status === 403) && attempt < maxAttempts && typeof options.refreshAuth === 'function') {
        try {
          await options.refreshAuth(env, { fn: fnText, args, routeClass: effectiveRouteClass || null, purpose: purposeRaw || null, status: res.status });
          authRefreshRetried = true;
          continue;
        } catch {}
      }

      break;
    }

    if (!res.ok) {
      const err = new Error(`RPC ${fnText} failed ${res.status}: ${txt}`);
      err.status = res.status;
      err.body = txt;
      err.json = json;
      err.fn = fnText;
      err.routeClass = effectiveRouteClass || null;
      err.purpose = purposeRaw || null;
      err.authRefreshRetried = authRefreshRetried;
      throw err;
    }

    return json;
  } catch (e) {
    if (e && (e.name === 'AbortError' || /timed out|timeout/i.test(String(e.message || '')))) {
      const err = new Error(`RPC ${fnText} failed 408: ${timeoutMs ? `timeout after ${timeoutMs}ms` : 'timeout'}`);
      err.status = 408;
      err.body = '';
      err.json = null;
      err.fn = fnText;
      err.routeClass = effectiveRouteClass || null;
      err.purpose = purposeRaw || null;
      throw err;
    }
    throw e;
  } finally {
    if (t) clearTimeout(t);
  }
}


