                providerTransactionId && eventType === 'TransactionCreated'
                  ? `REVOLUT|${railEnv}|TransactionCreated|${providerTransactionId}|${stateForCreated || 'NO_STATE'}|${timestamp || 'NO_TIMESTAMP'}`
                  : ''
